def _runtime_resource_dir() -> Path:
    if getattr(sys, "frozen", False):
        meipass = getattr(sys, "_MEIPASS", None)
        if meipass:
            return Path(meipass)
    return Path(__file__).resolve().parent


def _runtime_app_dir() -> Path:
    if getattr(sys, "frozen", False):
        return Path(sys.executable).resolve().parent
    return Path(__file__).resolve().parent


def _instruction_image_candidates(base_dir: Path | str, filename: str, extra_names: list[str] | None = None) -> list[Path]:
    """Resolve instruction image paths for both source run and PyInstaller onefile run."""
    base = Path(base_dir) if base_dir else _runtime_app_dir()
    resource = _runtime_resource_dir()
    appdir = _runtime_app_dir()
    names = [str(filename or '').strip()]
    for x in (extra_names or []):
        x = str(x or '').strip()
        if x:
            names.append(x)

    out: list[Path] = []
    seen: set[str] = set()
    for name in names:
        for p in (
            resource / name,
            resource / 'assets' / name,
            appdir / name,
            appdir / 'assets' / name,
            base / name,
            base / 'assets' / name,
        ):
            key = str(p.resolve()) if p.exists() else str(p)
            if key in seen:
                continue
            seen.add(key)
            out.append(p)
    return out

