@dataclass
class SessionInfo:
    session_id: str
    name: str
    age: int
    gender: str
    started_at: datetime


class ParticipantsLogger:
    def __init__(self, base_dir: Path):
        self.base_dir = base_dir
        self.data_dir = self.base_dir / "data"
        self.archive_dir = self.data_dir / "archive"
        self.data_file = self.data_dir / "participants.csv"

    def rotate_weekly_file_if_needed(self):
        self.data_dir.mkdir(parents=True, exist_ok=True)
        self.archive_dir.mkdir(parents=True, exist_ok=True)

        if not self.data_file.exists():
            return

        modified_dt = datetime.fromtimestamp(self.data_file.stat().st_mtime)
        old_year, old_week, _ = modified_dt.isocalendar()
        current_dt = datetime.now()
        current_year, current_week, _ = current_dt.isocalendar()

        if (old_year, old_week) == (current_year, current_week):
            return

        archived_path = self.archive_dir / f"participants_{old_year}_week_{old_week:02d}.csv"
        if archived_path.exists():
            suffix = modified_dt.strftime("_%Y%m%d_%H%M%S")
            archived_path = self.archive_dir / f"participants_{old_year}_week_{old_week:02d}{suffix}.csv"

        shutil.move(str(self.data_file), str(archived_path))

    def _ensure_file(self):
        self.rotate_weekly_file_if_needed()
        self.data_dir.mkdir(parents=True, exist_ok=True)

        if self.data_file.exists() and self.data_file.stat().st_size > 0:
            return

        now = datetime.now()
        current_year, current_week, _ = now.isocalendar()
        with open(self.data_file, "w", newline="", encoding="utf-8-sig") as f:
            writer = csv.writer(f, delimiter=";")
            writer.writerow(["Неделя", f"{current_year}-W{current_week:02d}"])
            writer.writerow(CSV_HEADERS)

    def log_event(
        self,
        session: SessionInfo,
        event_type: str,
        screen: str = "",
        test_name: str = "",
        stage: str = "",
        action: str = "",
        elapsed_ms: str | int | float = "",
        x: str | int | float = "",
        y: str | int | float = "",
        angle: str | int | float = "",
        value: str | int | float = "",
        note: str = "",
    ):
        self._ensure_file()
        now = datetime.now()
        row = [
            now.strftime("%d.%m.%Y"),
            now.strftime("%H:%M:%S"),
            session.name,
            session.age,
            session.gender,
            session.session_id,
            event_type,
            screen,
            test_name,
            stage,
            action,
            elapsed_ms,
            x,
            y,
            angle,
            value,
            note,
        ]
        with open(self.data_file, "a", newline="", encoding="utf-8-sig") as f:
            writer = csv.writer(f, delimiter=";")
            writer.writerow(row)


@dataclass
class MethodAConfig:
    width: int = 1280
    height: int = 800
    fps: int = 60

    target_half_cm: float = 3.0
    work_extension_cm: float = 15.0
    crash_extension_cm: float = 1.0

    target_roll_deg: float = 18.0
    work_roll_deg: float = 90.0

    start_speed_xy_cm_s: float = 3.0
    step_speed_xy_cm_s: float = 0.5
    start_speed_z_deg_s: float = 10.0
    step_speed_z_deg_s: float = 2.0

    direction_change_min_s: float = 3.0
    direction_change_max_s: float = 20.0
    speedup_interval_s: float = 5.0

    stage_time_limit_s: float = 40.0
    stage_crash_limit: int = 3
    crash_penalty_ratio: float = 0.05

    auto_fit_to_screen: bool = True
    screen_side_margin_px: int = 90
    screen_vertical_margin_px: int = 70

    smax_stage_1: float = 100.0
    smax_stage_2: float = 200.0
    smax_stage_3: float = 300.0

    px_per_cm: float = 38.0

    mouse_gain_px: float = 1.15
    roll_step_per_wheel_notch_deg: float = 4.0
    # Safety switch: when false, joystick subsystem is fully bypassed.
    enable_joystick: bool = False

    error_gain: float = 5.0

    bg_color: tuple[int, int, int] = (232, 232, 232)
    target_color: tuple[int, int, int] = (133, 214, 136)
    work_color: tuple[int, int, int] = (139, 195, 220)
    crash_color: tuple[int, int, int] = (214, 16, 0)
    obj_color: tuple[int, int, int] = (15, 49, 64)
    text_color: tuple[int, int, int] = (18, 24, 30)
    grid_color: tuple[int, int, int] = (15, 49, 64)


@dataclass
class StageReport:
    stage_no: int
    active_axes: str
    crashes: int = 0
    real_time_s: float = 0.0
    sum_error: float = 0.0
    vmax_xy_cm_s: float = 0.0
    vmax_z_deg_s: float = 0.0
    inside_time_s: float = 0.0
    stability_pct: float = 0.0
    mean_abs_xy_cm: float = 0.0
    peak_abs_xy_cm: float = 0.0
    mean_abs_roll_deg: float = 0.0
    peak_abs_roll_deg: float = 0.0
    # Explicit axis bounds from settings (used in stage result cards).
    r_goal_x_cm: float = 0.0
    r_goal_y_cm: float = 0.0
    r_goal_z_deg: float = 0.0
    r_crash_x_cm: float = 0.0
    r_crash_y_cm: float = 0.0
    r_crash_z_deg: float = 0.0
    # Optional derived report fields used by newer calculation/render blocks.
    second_metrics_avg: dict | None = None
    calculation_version: str = ''

    def to_dict(self) -> dict:
        return asdict(self)


@dataclass
class DriftState:
    x_px: float = 0.0
    y_px: float = 0.0
    roll_deg: float = 0.0

    dir_x: int = 1
    dir_y: int = 1
    dir_z: int = 1

    speed_xy_cm_s: float = 0.0
    speed_z_deg_s: float = 0.0

    next_flip_x_s: float = 0.0
    next_flip_y_s: float = 0.0
    next_flip_z_s: float = 0.0

    outside_target_since_s: float | None = None
    was_outside_target: bool = False


def load_config(path: str | Path = "method_a_config.json", screen_w: int | None = None, screen_h: int | None = None) -> MethodAConfig:
    p = Path(path)
    if p.exists():
        data = json.loads(p.read_text(encoding="utf-8"))
        cfg = MethodAConfig(**data)
    else:
        cfg = MethodAConfig()

    if screen_w and screen_h:
        cfg.width = max(1000, int(screen_w))
        cfg.height = max(700, int(screen_h))
    return cfg


class MethodAApp:
    def __init__(self, cfg: MethodAConfig, session: SessionInfo, logger: ParticipantsLogger, base_dir: Path):
        _ensure_pygame()
        self.cfg = cfg
        self.session = session
        self.logger = logger
        self.base_dir = base_dir
        self.reports: list[StageReport] = []

        pygame.init()
        pygame.display.set_caption("СПР - Тест А: слежение за объектом")
        self.screen = pygame.display.set_mode((cfg.width, cfg.height))
        self.clock = pygame.time.Clock()
        self.font = pygame.font.SysFont("arial", 22)
        self.big_font = pygame.font.SysFont("arial", 42, bold=True)

        self.center = pygame.Vector2(cfg.width // 2, cfg.height // 2)
        self.target_half_px = cfg.target_half_cm * cfg.px_per_cm
        self.work_half_px = (cfg.target_half_cm + cfg.work_extension_cm) * cfg.px_per_cm
        self.crash_half_px = (
            cfg.target_half_cm + cfg.work_extension_cm + cfg.crash_extension_cm
        ) * cfg.px_per_cm

        self.stage_defs = {
            1: {"x": True, "y": False, "z": False, "label": "X"},
            2: {"x": True, "y": True, "z": False, "label": "X,Y"},
            3: {"x": True, "y": True, "z": True, "label": "X,Y,Z"},
        }

        self.assets_dir = _runtime_resource_dir() / "assets"
        if not self.assets_dir.exists():
            self.assets_dir = self.base_dir / "assets"
        self.background_surface = self.create_tracking_background()
        self.airplane_sprite = self.load_airplane_sprite_from_png()


    def load_airplane_sprite_from_png(self) -> pygame.Surface:
        candidate_paths = [
            self.assets_dir / "airplane_sprite.png",
            self.assets_dir / "airplane.png",
            self.base_dir / "airplane_sprite.png",
            self.base_dir / "airplane.png",
        ]
        for sprite_path in candidate_paths:
            if not sprite_path.exists():
                continue
            try:
                img = Image.open(sprite_path).convert("RGBA")
                bg_sample = img.getpixel((0, 0))
                pixels = img.load()
                tolerance = 18
                for y in range(img.height):
                    for x in range(img.width):
                        r, g, b, a = pixels[x, y]
                        if (
                            abs(r - bg_sample[0]) <= tolerance
                            and abs(g - bg_sample[1]) <= tolerance
                            and abs(b - bg_sample[2]) <= tolerance
                        ):
                            pixels[x, y] = (r, g, b, 0)
                bbox = img.getbbox()
                if bbox:
                    img = img.crop(bbox)
                max_w = int(self.cfg.width * 0.16)
                max_h = int(self.cfg.height * 0.13)
                scale = min(max_w / max(1, img.width), max_h / max(1, img.height))
                new_size = (
                    max(24, int(img.width * scale)),
                    max(24, int(img.height * scale)),
                )
                img = img.resize(new_size, Image.LANCZOS)
                return pygame.image.frombuffer(img.tobytes(), img.size, img.mode).convert_alpha()
            except Exception:
                pass
        return self.create_airplane_sprite()

    def load_tracking_background_from_doc(self) -> pygame.Surface | None:
        """Пытается взять готовый фон только если это действительно большой фон,
        а не маленькая иконка самолётика из документа."""
        candidate_paths = [
            self.assets_dir / "tracking_background_doc.png",
            self.assets_dir / "tracking_background.png",
            self.base_dir / "tracking_background_doc.png",
            self.base_dir / "tracking_background.png",
        ]
        for bg_path in candidate_paths:
            if not bg_path.exists():
                continue
            try:
                img = Image.open(bg_path).convert("RGBA")
                # В ранних версиях сюда случайно подхватывалась маленькая картинка самолёта.
                # Такие файлы игнорируем и рисуем фон сами по макету документа.
                if img.width < 500 or img.height < 300:
                    continue

                base = Image.new("RGBA", (self.cfg.width, self.cfg.height), (*self.cfg.bg_color, 255))
                scale = min(self.cfg.width / img.width, self.cfg.height / img.height)
                scaled = img.resize((max(1, int(img.width * scale)), max(1, int(img.height * scale))), Image.LANCZOS)
                left = (self.cfg.width - scaled.width) // 2
                top = (self.cfg.height - scaled.height) // 2
                base.alpha_composite(scaled, (left, top))
                return pygame.image.frombuffer(base.tobytes(), base.size, base.mode).convert()
            except Exception:
                pass
        return None

    def create_tracking_background(self) -> pygame.Surface:
        bg = self.load_tracking_background_from_doc()
        if bg is not None:
            return bg
        surf = pygame.Surface((self.cfg.width, self.cfg.height)).convert()
        surf.fill(self.cfg.bg_color)
        self.draw_tracking_zones(surf)
        return surf

    def create_airplane_sprite(self) -> pygame.Surface:
        size = 420
        img = Image.new("RGBA", (size, size), (0, 0, 0, 0))
        draw = ImageDraw.Draw(img)
        cx = size // 2
        cy = size // 2
        try:
            object_rgb = tuple(int(x) for x in tuple(self.cfg.obj_color)[:3])
        except Exception:
            object_rgb = (15, 49, 64)
        accent = (*object_rgb, 255)
        black = (*object_rgb, 255)

        draw.line((20, cy, size - 20, cy), fill=black, width=10)
        draw.line((cx, 20, cx, cy), fill=black, width=10)
        draw.arc((cx - 58, cy - 40, cx + 58, cy + 40), 165, 374, fill=accent, width=10)
        draw.line((cx - 92, cy + 6, cx - 8, cy + 48), fill=black, width=10)
        draw.line((cx + 92, cy + 6, cx + 8, cy + 48), fill=black, width=10)
        draw.line((cx - 92, cy + 6, cx - 92, cy + 66), fill=black, width=8)
        draw.line((cx + 92, cy + 6, cx + 92, cy + 66), fill=black, width=8)

        img = img.crop(img.getbbox())
        return pygame.image.frombuffer(img.tobytes(), img.size, img.mode).convert_alpha()

    def draw_background(self):
        self.screen.blit(self.background_surface, (0, 0))

    def draw_tracking_zones(self, surface: pygame.Surface | None = None):
        target_surface = surface or self.screen
        target_surface.fill(self.cfg.bg_color)

        c = self.center
        outer_radius = int(self.work_half_px)
        crash_outer = int(self.crash_half_px)
        target_radius = int(self.target_half_px)
        work_fill = self.cfg.work_color
        target_fill = self.cfg.target_color
        grid = self.cfg.grid_color
        red = self.cfg.crash_color

        cx = int(c.x)
        cy = int(c.y)
        pygame.draw.circle(target_surface, work_fill, c, outer_radius)
        # Подгон под образец: внешний красный пояс заметно толще.
        ring_width = max(16, int(crash_outer * 0.055), crash_outer - outer_radius + 6)
        pygame.draw.circle(target_surface, red, c, crash_outer, ring_width)

        # Концентрические окружности как в макете документа.
        for radius in (
            target_radius,
            int(target_radius + (outer_radius - target_radius) * 0.28),
            int(target_radius + (outer_radius - target_radius) * 0.56),
            int(target_radius + (outer_radius - target_radius) * 0.84),
        ):
            pygame.draw.circle(target_surface, grid, c, radius, 2)

        pygame.draw.circle(target_surface, target_fill, c, target_radius)
        pygame.draw.circle(target_surface, grid, c, target_radius, 2)

        axis_len = outer_radius + ring_width // 2
        pygame.draw.line(target_surface, grid, (cx - axis_len, cy), (cx + axis_len, cy), 3)
        pygame.draw.line(target_surface, grid, (cx, cy - axis_len), (cx, cy + axis_len), 3)

        # Плотная диагональная сетка как на образце из документа.
        overlay = pygame.Surface((self.cfg.width, self.cfg.height), pygame.SRCALPHA)
        step = max(16, int(outer_radius * 0.115))
        slope = 0.17
        xmin = cx - outer_radius
        xmax = cx + outer_radius

        def draw_family(sign: int):
            for offset in range(-outer_radius - step, outer_radius + step * 2, step):
                pts = []
                x = xmin
                while x <= xmax:
                    y = cy + sign * slope * (x - cx) + offset
                    if (x - cx) ** 2 + (y - cy) ** 2 <= outer_radius ** 2:
                        pts.append((int(x), int(y)))
                    elif len(pts) >= 2:
                        pygame.draw.aalines(overlay, (*grid, 125), False, pts)
                        pts = []
                    else:
                        pts = []
                    x += 6
                if len(pts) >= 2:
                    pygame.draw.aalines(overlay, (*grid, 125), False, pts)

        draw_family(1)
        draw_family(-1)
        target_surface.blit(overlay, (0, 0))

    def draw_panel(self, x: int, y: int, w: int, h: int, alpha: int = 150):
        panel = pygame.Surface((w, h), pygame.SRCALPHA)
        panel.fill((255, 255, 255, min(alpha, 180)))
        self.screen.blit(panel, (x, y))
        pygame.draw.rect(self.screen, (70, 90, 110), (x, y, w, h), 2, border_radius=10)

    def rand_flip_time(self) -> float:
        return random.uniform(
            self.cfg.direction_change_min_s,
            self.cfg.direction_change_max_s,
        )

    def init_stage_state(self) -> DriftState:
        return DriftState(
            speed_xy_cm_s=self.cfg.start_speed_xy_cm_s,
            speed_z_deg_s=self.cfg.start_speed_z_deg_s,
            dir_x=random.choice((-1, 1)),
            dir_y=random.choice((-1, 1)),
            dir_z=random.choice((-1, 1)),
            next_flip_x_s=self.rand_flip_time(),
            next_flip_y_s=self.rand_flip_time(),
            next_flip_z_s=self.rand_flip_time(),
        )

    def inside_target(self, state: DriftState, stage_no: int) -> bool:
        stage = self.stage_defs[stage_no]
        ok_x = (not stage["x"]) or abs(state.x_px) <= self.target_half_px
        ok_y = (not stage["y"]) or abs(state.y_px) <= self.target_half_px
        ok_z = (not stage["z"]) or abs(state.roll_deg) <= self.cfg.target_roll_deg
        return ok_x and ok_y and ok_z

    def in_crash_zone(self, state: DriftState, stage_no: int) -> bool:
        stage = self.stage_defs[stage_no]
        hit_x = stage["x"] and abs(state.x_px) > self.work_half_px
        hit_y = stage["y"] and abs(state.y_px) > self.work_half_px
        # Для крена срыв фиксируется по пределу допустимого крена,
        # который показывают наклонные направляющие линии на экране.
        hit_z = stage["z"] and abs(state.roll_deg) > self.cfg.target_roll_deg
        return hit_x or hit_y or hit_z

    def stage_smax(self, stage_no: int) -> float:
        return {
            1: self.cfg.smax_stage_1,
            2: self.cfg.smax_stage_2,
            3: self.cfg.smax_stage_3,
        }[stage_no]

    def current_error_increment(self, state: DriftState, stage_no: int, dt: float) -> float:
        stage = self.stage_defs[stage_no]
        err = 0.0

        if stage["x"]:
            dx = max(0.0, abs(state.x_px) - self.target_half_px)
            err += dx / max(1.0, self.target_half_px)

        if stage["y"]:
            dy = max(0.0, abs(state.y_px) - self.target_half_px)
            err += dy / max(1.0, self.target_half_px)

        if stage["z"]:
            dz = max(0.0, abs(state.roll_deg) - self.cfg.target_roll_deg)
            err += dz / max(1.0, self.cfg.target_roll_deg)

        return err * self.cfg.error_gain * dt

    def draw_zones(self):
        # Зоны уже нарисованы на фоновой поверхности в стиле схемы из DOCX.
        return

    def roll_limit_exceeded(self, state: DriftState, stage_no: int) -> bool:
        return self.stage_defs[stage_no]["z"] and abs(state.roll_deg) > self.cfg.target_roll_deg

    def draw_roll_limit_guides(self, state: DriftState, stage_no: int):
        """Рисует две наклонные линии-пределы допустимого крена.
        На 3 этапе линии становятся красными, если текущий крен вышел за норму.
        """
        if not self.stage_defs[stage_no]["z"]:
            return

        cx = int(self.center.x)
        cy = int(self.center.y)
        radius = int(self.target_half_px)
        color = self.cfg.crash_color if self.roll_limit_exceeded(state, stage_no) else self.cfg.grid_color

        line_len = max(44, int(radius * 0.95))
        side_shift = max(34, int(radius * 0.62))
        top_shift = max(78, int(radius * 1.45))
        guide_center_y = cy - top_shift
        half = line_len / 2.0
        ang = math.radians(max(8.0, float(self.cfg.target_roll_deg)))

        left_center = (cx - side_shift, guide_center_y)
        right_center = (cx + side_shift, guide_center_y)

        # Линии симметричны относительно центра и служат визуальной границей допустимого крена.
        left_dx = math.cos(ang) * half
        left_dy = math.sin(ang) * half
        right_dx = math.cos(-ang) * half
        right_dy = math.sin(-ang) * half

        p1 = (int(left_center[0] - left_dx), int(left_center[1] - left_dy))
        p2 = (int(left_center[0] + left_dx), int(left_center[1] + left_dy))
        p3 = (int(right_center[0] - right_dx), int(right_center[1] - right_dy))
        p4 = (int(right_center[0] + right_dx), int(right_center[1] + right_dy))

        pygame.draw.line(self.screen, color, p1, p2, 6)
        pygame.draw.line(self.screen, color, p3, p4, 6)

    def draw_object(self, state: DriftState):
        angle = -state.roll_deg
        cx = self.center.x + state.x_px
        cy = self.center.y + state.y_px

        shadow = pygame.Surface((180, 90), pygame.SRCALPHA)
        pygame.draw.ellipse(shadow, (40, 40, 40, 36), (10, 18, 160, 48))
        self.screen.blit(shadow, (cx - shadow.get_width() // 2, cy - shadow.get_height() // 2 + 12))

        rotated = pygame.transform.rotozoom(self.airplane_sprite, angle, 0.6)
        rect = rotated.get_rect(center=(cx, cy))
        self.screen.blit(rotated, rect)

    def draw_bar(self, x: int, y: int, w: int, h: int, ratio: float, title: str, color):
        ratio = max(0.0, min(1.0, ratio))
        pygame.draw.rect(self.screen, (216, 223, 230), (x, y, w, h))
        pygame.draw.rect(self.screen, color, (x, y + h * (1 - ratio), w, h * ratio))
        pygame.draw.rect(self.screen, self.cfg.text_color, (x, y, w, h), 2)
        txt = self.font.render(title, True, self.cfg.text_color)
        self.screen.blit(txt, (x, y - 26))

    def draw_hud(self, stage_no: int, elapsed_s: float, stage_error: float, report: StageReport, state: DriftState):
        time_ratio = elapsed_s / self.cfg.stage_time_limit_s
        err_ratio = stage_error / self.stage_smax(stage_no)

        # По запросу пользователя в рабочем экране теста А оставляем только
        # два столбика-индикатора без числовых подписей и диагностического текста.
        self.draw_bar(25, 60, 26, 250, time_ratio, "ВРЕМЯ", (70, 130, 255))
        self.draw_bar(
            self.cfg.width - 51,
            60,
            26,
            250,
            err_ratio,
            "ОШИБКА",
            (255, 140, 70),
        )

    def pump_message_events(self):
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                raise MethodAAbort
            if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
                raise MethodAAbort

    def read_runtime_events(self) -> int:
        wheel_delta = 0
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                raise MethodAAbort
            if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
                raise MethodAAbort
            if event.type == pygame.MOUSEWHEEL:
                wheel_delta += event.y
            elif event.type == pygame.MOUSEBUTTONDOWN:
                # запасной путь для некоторых старых сборок pygame / драйверов
                if event.button == 4:
                    wheel_delta += 1
                elif event.button == 5:
                    wheel_delta -= 1
        return wheel_delta

    def show_message(self, text: str, seconds: float = 1.0):
        timer = 0.0
        while timer < seconds:
            dt = self.clock.tick(self.cfg.fps) / 1000.0
            timer += dt
            self.pump_message_events()

            self.draw_background()
            msg = self.big_font.render(text, True, self.cfg.crash_color)
            rect = msg.get_rect(center=(self.cfg.width // 2, int(self.cfg.height * 0.16)))

            panel_w = min(self.cfg.width - 80, rect.width + 56)
            panel_h = rect.height + 28
            panel = pygame.Surface((panel_w, panel_h), pygame.SRCALPHA)
            panel.fill((255, 255, 255, 225))
            panel_rect = panel.get_rect(center=rect.center)

            self.screen.blit(panel, panel_rect)
            pygame.draw.rect(self.screen, self.cfg.grid_color, panel_rect, 2, border_radius=12)
            self.screen.blit(msg, rect)
            pygame.display.flip()

    def update_direction_timers(self, state: DriftState, stage_no: int, dt: float):
        stage = self.stage_defs[stage_no]

        if stage["x"]:
            state.next_flip_x_s -= dt
            if state.next_flip_x_s <= 0:
                state.dir_x *= -1
                state.next_flip_x_s = self.rand_flip_time()

        if stage["y"]:
            state.next_flip_y_s -= dt
            if state.next_flip_y_s <= 0:
                state.dir_y *= -1
                state.next_flip_y_s = self.rand_flip_time()

        if stage["z"]:
            state.next_flip_z_s -= dt
            if state.next_flip_z_s <= 0:
                state.dir_z *= -1
                state.next_flip_z_s = self.rand_flip_time()

    def handle_control(self, state: DriftState, stage_no: int, wheel_delta: int):
        stage = self.stage_defs[stage_no]
        rel_x, rel_y = pygame.mouse.get_rel()

        if stage["x"]:
            state.x_px -= rel_x * self.cfg.mouse_gain_px
        if stage["y"]:
            state.y_px -= rel_y * self.cfg.mouse_gain_px
        if stage["z"] and wheel_delta:
            state.roll_deg -= wheel_delta * self.cfg.roll_step_per_wheel_notch_deg

    def update_drift(self, state: DriftState, stage_no: int, dt: float):
        stage = self.stage_defs[stage_no]
        px_speed = self.cfg.px_per_cm * state.speed_xy_cm_s

        if stage["x"]:
            state.x_px += state.dir_x * px_speed * dt
        if stage["y"]:
            state.y_px += state.dir_y * px_speed * dt
        if stage["z"]:
            state.roll_deg += state.dir_z * state.speed_z_deg_s * dt

    def maybe_speedup(self, state: DriftState, stage_no: int, absolute_time_s: float):
        interval = max(1e-6, float(getattr(self.cfg, 'speedup_interval_s', 5.0) or 5.0))
        eps = 1e-6
        prev_steps = int(max(0.0, float(absolute_time_s) - eps) // interval)
        curr_steps = int(max(0.0, float(absolute_time_s)) // interval)
        if curr_steps > prev_steps:
            delta_steps = int(curr_steps - prev_steps)
            state.speed_xy_cm_s += float(self.cfg.step_speed_xy_cm_s) * delta_steps
            state.speed_z_deg_s += float(self.cfg.step_speed_z_deg_s) * delta_steps

    def maybe_register_return(self, state: DriftState, stage_no: int, report: StageReport):
        outside = not self.inside_target(state, stage_no)
        if state.was_outside_target and not outside:
            report.vmax_xy_cm_s = max(report.vmax_xy_cm_s, state.speed_xy_cm_s)
            if self.stage_defs[stage_no]["z"]:
                report.vmax_z_deg_s = max(report.vmax_z_deg_s, state.speed_z_deg_s)
        state.was_outside_target = outside

    def current_xy_deviation_cm(self, state: DriftState, stage_no: int) -> float:
        stage = self.stage_defs[stage_no]
        x_cm = (state.x_px / self.cfg.px_per_cm) if stage["x"] else 0.0
        y_cm = (state.y_px / self.cfg.px_per_cm) if stage["y"] else 0.0
        return (x_cm * x_cm + y_cm * y_cm) ** 0.5

    def current_roll_deviation_deg(self, state: DriftState, stage_no: int) -> float:
        return abs(state.roll_deg) if self.stage_defs[stage_no]["z"] else 0.0

    def finalize_stage_report(
        self,
        report: StageReport,
        elapsed_s: float,
        xy_integral: float,
        roll_integral: float,
    ) -> StageReport:
        total = max(elapsed_s, 1e-6)
        report.mean_abs_xy_cm = xy_integral / total
        report.mean_abs_roll_deg = roll_integral / total
        report.stability_pct = max(0.0, min(100.0, report.inside_time_s / total * 100.0))
        return report

    def reset_after_crash(self, state: DriftState):
        state.x_px = 0.0
        state.y_px = 0.0
        state.roll_deg = 0.0
        state.outside_target_since_s = None
        state.was_outside_target = False

        # By requirement: after crash, speed decreases by 1 unit per coordinate
        # instead of returning to initial speed.
        state.speed_xy_cm_s = max(0.0, float(state.speed_xy_cm_s) - 1.0)
        state.speed_z_deg_s = max(0.0, float(state.speed_z_deg_s) - 1.0)

    def log_stage_report(self, report: StageReport):
        self.logger.log_event(
            self.session,
            event_type="stage_report",
            screen="method_a",
            test_name="method_a_stage",
            stage=str(report.stage_no),
            action="stage_end",
            elapsed_ms=int(report.real_time_s * 1000),
            x=round(report.mean_abs_xy_cm, 3),
            y=round(report.peak_abs_xy_cm, 3),
            angle=round(report.peak_abs_roll_deg, 3),
            value=report.crashes,
            note=f"axes={report.active_axes}; stability={report.stability_pct:.1f}%",
        )

    def run_stage(self, stage_no: int) -> StageReport:
        report = StageReport(stage_no=stage_no, active_axes=self.stage_defs[stage_no]["label"])
        state = self.init_stage_state()
        stage_error = 0.0
        elapsed_s = 0.0
        xy_integral = 0.0
        roll_integral = 0.0

        pygame.event.set_grab(True)
        pygame.mouse.set_visible(False)
        pygame.mouse.get_rel()

        while True:
            dt = self.clock.tick(self.cfg.fps) / 1000.0
            elapsed_s += dt
            report.real_time_s = elapsed_s

            wheel_delta = self.read_runtime_events()
            self.update_direction_timers(state, stage_no, dt)
            self.handle_control(state, stage_no, wheel_delta)
            self.update_drift(state, stage_no, dt)
            self.maybe_speedup(state, stage_no, elapsed_s)

            stage_error += self.current_error_increment(state, stage_no, dt)
            report.sum_error = stage_error
            self.maybe_register_return(state, stage_no, report)

            inside_now = self.inside_target(state, stage_no)
            if inside_now:
                report.inside_time_s += dt

            xy_now = self.current_xy_deviation_cm(state, stage_no)
            roll_now = self.current_roll_deviation_deg(state, stage_no)
            xy_integral += xy_now * dt
            roll_integral += roll_now * dt
            report.peak_abs_xy_cm = max(report.peak_abs_xy_cm, xy_now)
            report.peak_abs_roll_deg = max(report.peak_abs_roll_deg, roll_now)

            crashed = self.in_crash_zone(state, stage_no) or stage_error >= self.stage_smax(stage_no)
            if crashed:
                report.crashes += 1
                self.logger.log_event(
                    self.session,
                    event_type="stage_event",
                    screen="method_a",
                    test_name="method_a_stage",
                    stage=str(stage_no),
                    action="crash",
                    elapsed_ms=int(elapsed_s * 1000),
                    x=round(state.x_px, 3),
                    y=round(stage_error, 3),
                    angle=round(state.roll_deg, 3),
                    value=report.crashes,
                    note=f"axes={report.active_axes}",
                )
                self.show_message("ОШИБКА", seconds=0.8)
                self.reset_after_crash(state)
                stage_error = 0.0
                report.sum_error = 0.0

                if report.crashes >= self.cfg.stage_crash_limit:
                    return self.finalize_stage_report(report, elapsed_s, xy_integral, roll_integral)

            if elapsed_s >= self.cfg.stage_time_limit_s:
                return self.finalize_stage_report(report, elapsed_s, xy_integral, roll_integral)

            self.draw_background()
            self.draw_zones()
            self.draw_roll_limit_guides(state, stage_no)
            self.draw_object(state)
            self.draw_hud(stage_no, elapsed_s, stage_error, report, state)
            pygame.display.flip()

    def run(self) -> dict:
        outcome = {"completed": False, "reports": [], "result_path": ""}
        try:
            self.logger.log_event(
                self.session,
                event_type="method_session",
                screen="method_a",
                test_name="method_a",
                action="launch",
                note="Крен управляется колесом мыши; фон неба и объект-самолёт активированы",
            )

            for stage_no in (1, 2, 3):
                self.logger.log_event(
                    self.session,
                    event_type="stage_event",
                    screen="method_a",
                    test_name="method_a_stage",
                    stage=str(stage_no),
                    action="stage_start",
                    note=f"axes={self.stage_defs[stage_no]['label']}",
                )
                self.show_message(f"Этап {stage_no}", seconds=1.0)
                report = self.run_stage(stage_no)
                self.reports.append(report)
                self.log_stage_report(report)

            result_path = self.base_dir / "data" / f"method_a_results_{self.session.session_id}.json"
            result_path.parent.mkdir(parents=True, exist_ok=True)
            result_path.write_text(
                json.dumps([r.to_dict() for r in self.reports], ensure_ascii=False, indent=2),
                encoding="utf-8",
            )
            self.logger.log_event(
                self.session,
                event_type="method_session",
                screen="method_a",
                test_name="method_a",
                action="completed",
                note=f"json={result_path.name}",
            )
            self.show_message("Тест завершен", seconds=1.5)
            outcome = {
                "completed": True,
                "reports": [r.to_dict() for r in self.reports],
                "result_path": str(result_path),
            }
        except MethodAAbort:
            self.logger.log_event(
                self.session,
                event_type="method_session",
                screen="method_a",
                test_name="method_a",
                action="aborted",
                value=len(self.reports),
                note="Пользователь закрыл методику или нажал ESC",
            )
            outcome = {
                "completed": False,
                "reports": [r.to_dict() for r in self.reports],
                "result_path": "",
            }
        finally:
            pygame.event.set_grab(False)
            pygame.mouse.set_visible(True)
            pygame.quit()
        return outcome



TEST_ORDER = ["A", "B", "C", "D"]
