def menu_card_text(code: str, state: str = "ready") -> str:
    if state == "done":
        return f"{TEST_LABELS[code]}\nПРОЙДЕН"
    if state == "locked":
        return f"{TEST_LABELS[code]}\nНедоступен\nдо предыдущих тестов"
    return MENU_CARD_TEXT.get(code, f"{TEST_LABELS[code]}\n{TEST_DESCRIPTIONS[code]}")
MENU_BG = "#c4bea0"
MENU_ACTIVE = "#a8d89f"
MENU_DISABLED = "#d8d2b5"
BACK_BG = "#d7cfaa"
BACK_ACTIVE = "#bfb585"
RESULT_BG = "#7ab6ff"
RESULT_ACTIVE = "#5a98e2"
RESULT_DISABLED = "#c7d6ea"


class UserProgressStore:
    def __init__(self, base_dir: Path):
        self.base_dir = base_dir
        self.progress_file = self.base_dir / "data" / "user_progress.json"

    def _load_method_a_reports(self, payload: dict) -> list[dict]:
        reports = payload.get("reports", [])
        if isinstance(reports, list) and reports:
            return [item for item in reports if isinstance(item, dict)]
        result_path = payload.get("result_path", "")
        if not result_path:
            return []
        try:
            rp = Path(result_path)
            if not rp.is_absolute():
                rp = self.base_dir / rp
            if rp.exists():
                loaded = json.loads(rp.read_text(encoding="utf-8"))
                if isinstance(loaded, list):
                    return [item for item in loaded if isinstance(item, dict)]
        except Exception:
            return []
        return []

    def _load_method_b_cycles(self, payload: dict) -> list[dict]:
        cycles = payload.get("cycles", [])
        if isinstance(cycles, list) and cycles:
            return [item for item in cycles if isinstance(item, dict)]
        result_path = payload.get("result_path", "")
        if not result_path:
            return []
        try:
            rp = Path(result_path)
            if not rp.is_absolute():
                rp = self.base_dir / rp
            if not rp.exists():
                return []
            loaded = json.loads(rp.read_text(encoding="utf-8"))
            if isinstance(loaded, dict):
                raw = loaded.get("cycles", [])
                if isinstance(raw, list):
                    return [item for item in raw if isinstance(item, dict)]
            if isinstance(loaded, list):
                return [item for item in loaded if isinstance(item, dict)]
        except Exception:
            return []
        return []

    def _rebuild_method_b_summary(self, cycles: list[dict], seed_summary: dict | None = None) -> dict:
        summary = dict(seed_summary) if isinstance(seed_summary, dict) else {}
        if not cycles:
            summary.setdefault("cycles_total", 0)
            summary.setdefault("successful_cycles", 0)
            summary.setdefault("accuracy_pct", 0.0)
            summary.setdefault("max_correct_count", 0)
            summary.setdefault("t_values", {})
            summary.setdefault("by_n", {})
            summary.setdefault("calculation_version", "fixed304_method_b_legacy_rebuild_v1")
            summary.setdefault("tmin_b", 0.0)
            summary.setdefault("tmedio_b", 0.0)
            summary.setdefault("tmax_b", 0.0)
            return summary

        try:
            cfg = load_method_b_config(self.base_dir)
            max_items = max(1, int(getattr(cfg, "max_items", 16) or 16))
            norms = list(getattr(cfg, "normative_times", []) or [])
        except Exception:
            max_items = 16
            norms = []
        if not norms:
            norms = [5.0 + 3.0 * (i - 1) for i in range(1, max_items + 1)]
        while len(norms) < max_items:
            norms.append(float(norms[-1]))

        grouped_total = {n: 0 for n in range(1, max_items + 1)}
        grouped_success = {n: 0 for n in range(1, max_items + 1)}
        cycle_times = {n: [] for n in range(1, max_items + 1)}
        max_correct = 0
        success_count = 0

        for cyc in cycles:
            n = int(cyc.get("n", 0) or 0)
            if not (1 <= n <= max_items):
                continue
            grouped_total[n] += 1
            cycle_times[n].append(float(cyc.get("elapsed_s", 0.0) or 0.0))
            if bool(cyc.get("success")):
                grouped_success[n] += 1
                success_count += 1
            max_correct = max(max_correct, int(cyc.get("correct_count", 0) or 0))

        t_values: dict[str, float] = {}
        by_n: dict[str, dict] = {}
        for n in range(1, max_items + 1):
            k_obsh = int(grouped_total[n])
            if k_obsh <= 0:
                continue
            k_usp = int(grouped_success[n])
            t_avg = sum(cycle_times[n]) / max(1, len(cycle_times[n]))
            gamma_n = float(k_usp) / float(k_obsh)
            t_norm = float(norms[n - 1] if (n - 1) < len(norms) else norms[-1])
            t_n_zap = (float(t_norm) * float(k_usp)) / max(0.0001, float(t_avg) * float(k_obsh))
            t_values[str(n)] = round(t_n_zap, 2)
            by_n[str(n)] = {
                "k_usp": k_usp,
                "k_obsh": k_obsh,
                "gamma_n": round(gamma_n, 2),
                "t_avg_s": round(t_avg, 2),
                "t_norm_s": round(t_norm, 2),
                "t_n_zap": round(t_n_zap, 2),
            }

        cycles_total = len([c for c in cycles if isinstance(c, dict)])
        summary["cycles_total"] = cycles_total
        summary["successful_cycles"] = success_count
        summary["accuracy_pct"] = round(100.0 * success_count / max(1, cycles_total), 2)
        summary["max_correct_count"] = max_correct
        summary["t_values"] = t_values
        summary["by_n"] = by_n
        summary["calculation_version"] = summary.get("calculation_version") or "fixed304_method_b_legacy_rebuild_v1"

        sorted_n = sorted(int(k) for k in t_values.keys() if str(k).isdigit())
        if sorted_n:
            n_low = sorted_n[0]
            n_mid = sorted_n[len(sorted_n) // 2]
            n_high = sorted_n[-1]
            summary["tmin_b"] = float(t_values.get(str(n_low), 0.0) or 0.0)
            summary["tmedio_b"] = float(t_values.get(str(n_mid), 0.0) or 0.0)
            summary["tmax_b"] = float(t_values.get(str(n_high), 0.0) or 0.0)
        else:
            summary["tmin_b"] = 0.0
            summary["tmedio_b"] = 0.0
            summary["tmax_b"] = 0.0
        return summary

    def _enrich_payload_for_storage(self, test_code: str, payload: dict) -> dict:
        normalized = dict(payload) if isinstance(payload, dict) else {}
        if test_code == "A":
            reports = self._load_method_a_reports(normalized)
            normalized["reports"] = reports
            summary = normalized.get("summary", {})
            if not isinstance(summary, dict):
                summary = {}
            if reports:
                if "total_time_s" not in summary:
                    summary["total_time_s"] = round(sum(float(r.get("real_time_s", 0.0)) for r in reports), 2)
                if "total_crashes" not in summary:
                    summary["total_crashes"] = int(sum(int(r.get("crashes", 0)) for r in reports))
                if "avg_stability_pct" not in summary:
                    summary["avg_stability_pct"] = round(sum(float(r.get("stability_pct", 0.0)) for r in reports) / max(1, len(reports)), 1)
                if "avg_mean_xy_cm" not in summary:
                    summary["avg_mean_xy_cm"] = round(sum(float(r.get("mean_abs_xy_cm", 0.0)) for r in reports) / max(1, len(reports)), 2)
                if summary.get("best_stage") in (None, "", 0):
                    best = max(
                        reports,
                        key=lambda r: (
                            float(r.get("stability_pct", 0.0)),
                            -int(r.get("crashes", 0)),
                            -float(r.get("mean_abs_xy_cm", 999.0)),
                            float(r.get("real_time_s", 0.0)),
                        ),
                    )
                    summary["best_stage"] = int(best.get("stage_no", 0))
            normalized["summary"] = summary
        elif test_code == "B":
            cycles = self._load_method_b_cycles(normalized)
            normalized["cycles"] = cycles
            summary = normalized.get("summary", {})
            if not isinstance(summary, dict):
                summary = {}

            has_tvals = isinstance(summary.get("t_values", {}), dict) and bool(summary.get("t_values", {}))
            has_by_n = isinstance(summary.get("by_n", {}), dict) and bool(summary.get("by_n", {}))
            needs_rebuild = (not has_tvals) or (not has_by_n) or ("cycles_total" not in summary)

            if needs_rebuild:
                summary = self._rebuild_method_b_summary(cycles, summary)
            else:
                summary.setdefault("cycles_total", len(cycles))
                summary.setdefault("successful_cycles", sum(1 for c in cycles if bool(c.get("success"))))
                summary.setdefault("accuracy_pct", round(100.0 * float(summary.get("successful_cycles", 0)) / max(1, int(summary.get("cycles_total", len(cycles)) or 0)), 2))
                summary.setdefault("max_correct_count", max((int(c.get("correct_count", 0) or 0) for c in cycles), default=0))

            normalized["summary"] = summary
        return normalized

    def _default_record(self, profile: UserProfile) -> dict:
        now = datetime.now().isoformat(timespec="seconds")
        return {
            "name": profile.name,
            "age": profile.age,
            "gender": profile.gender,
            "completed_tests": [],
            "results": {},
            "history": [],
            "created_at": now,
            "updated_at": now,
        }

    def _load(self) -> dict:
        if not self.progress_file.exists():
            return {}
        try:
            return json.loads(self.progress_file.read_text(encoding="utf-8"))
        except Exception:
            return {}

    def _save(self, data: dict):
        self.progress_file.parent.mkdir(parents=True, exist_ok=True)
        temp = self.progress_file.with_suffix('.tmp')
        temp.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
        temp.replace(self.progress_file)

    def get_progress(self, profile: UserProfile) -> dict:
        data = self._load()
        record = data.get(profile.key)
        if not isinstance(record, dict):
            return self._default_record(profile)
        completed = []
        for code in record.get("completed_tests", []):
            if code in TEST_ORDER and code not in completed:
                completed.append(code)
        record["completed_tests"] = completed
        record.setdefault("name", profile.name)
        record.setdefault("age", profile.age)
        record.setdefault("gender", profile.gender)
        record.setdefault("created_at", datetime.now().isoformat(timespec="seconds"))
        record.setdefault("updated_at", datetime.now().isoformat(timespec="seconds"))
        record.setdefault("results", {})
        record.setdefault("history", [])
        return record

    def ensure_user(self, profile: UserProfile) -> dict:
        data = self._load()
        if profile.key not in data:
            data[profile.key] = self._default_record(profile)
            self._save(data)
        return self.get_progress(profile)

    def reset_progress(self, profile: UserProfile) -> dict:
        data = self._load()
        old_record = data.get(profile.key, {}) if isinstance(data.get(profile.key, {}), dict) else {}
        new_record = self._default_record(profile)
        new_record["results"] = old_record.get("results", {}) if isinstance(old_record.get("results", {}), dict) else {}
        new_record["history"] = old_record.get("history", []) if isinstance(old_record.get("history", []), list) else []
        new_record["updated_at"] = datetime.now().isoformat(timespec="seconds")
        data[profile.key] = new_record
        self._save(data)
        return data[profile.key]

    def mark_completed(self, profile: UserProfile, test_code: str) -> dict:
        data = self._load()
        record = data.get(profile.key, self._default_record(profile))
        completed = [c for c in record.get("completed_tests", []) if c in TEST_ORDER]
        if test_code in TEST_ORDER and test_code not in completed:
            completed.append(test_code)
        record["completed_tests"] = [code for code in TEST_ORDER if code in completed]
        record["updated_at"] = datetime.now().isoformat(timespec="seconds")
        data[profile.key] = record
        self._save(data)
        return record

    def save_test_result(self, profile: UserProfile, test_code: str, payload: dict) -> dict:
        data = self._load()
        record = data.get(profile.key, self._default_record(profile))
        record.setdefault("results", {})
        record.setdefault("history", [])
        normalized_payload = self._enrich_payload_for_storage(test_code, payload)
        record["results"][test_code] = normalized_payload
        record["history"].append({
            "test_code": test_code,
            "saved_at": datetime.now().isoformat(timespec="seconds"),
            "session_id": normalized_payload.get("session_id", ""),
            "completed_at": normalized_payload.get("completed_at", ""),
        })
        record["updated_at"] = datetime.now().isoformat(timespec="seconds")
        data[profile.key] = record
        self._save(data)
        return record

    def get_test_result(self, profile: UserProfile, test_code: str) -> dict | None:
        data = self._load()
        record = data.get(profile.key)
        if not isinstance(record, dict):
            return None
        results = record.get("results", {})
        if isinstance(results, dict):
            item = results.get(test_code)
            if isinstance(item, dict):
                normalized_item = self._enrich_payload_for_storage(test_code, item)
                if normalized_item != item:
                    results[test_code] = normalized_item
                    record["results"] = results
                    record["updated_at"] = datetime.now().isoformat(timespec="seconds")
                    data[profile.key] = record
                    self._save(data)
                return normalized_item
        return None

    def repair_all_method_a_reports(self) -> int:
        data = self._load()
        if not isinstance(data, dict) or not data:
            return 0

        changed = 0
        stamp = datetime.now().isoformat(timespec="seconds")
        for user_key, record in data.items():
            if not isinstance(record, dict):
                continue
            results = record.get("results", {})
            if not isinstance(results, dict):
                continue
            payload = results.get("A")
            if not isinstance(payload, dict):
                continue
            normalized = self._enrich_payload_for_storage("A", payload)
            if normalized != payload:
                results["A"] = normalized
                record["results"] = results
                record["updated_at"] = stamp
                data[user_key] = record
                changed += 1

        if changed:
            self._save(data)
        return changed

    def next_test_code(self, profile: UserProfile) -> str | None:
        completed = set(self.get_progress(profile).get("completed_tests", []))
        for code in TEST_ORDER:
            if code not in completed:
                return code
        return None


