from dataclasses import field


@dataclass
class MethodBConfig:
    total_test_s: float = 300.0
    grid_size: int = 4
    max_items: int = 16
    normative_times: list[float] = field(default_factory=lambda: [5.0 + 3.0 * (i - 1) for i in range(1, 17)])
    normative_success_coef: float = 1.0


@dataclass
class MethodCConfig:
    total_test_s: float = 120.0
    stage_time_s: list[float] = field(default_factory=lambda: [40.0, 40.0, 40.0])
    exposure_start_s: list[float] = field(default_factory=lambda: [1.0, 2.0, 4.0])
    input_start_s: list[float] = field(default_factory=lambda: [3.0, 6.0, 12.0])
    time_step_s: list[float] = field(default_factory=lambda: [1.0, 1.0, 2.0])
    normative_cycle_times: list[float] = field(default_factory=lambda: [4.0, 8.0, 16.0])
    normative_success: list[float] = field(default_factory=lambda: [1.0, 1.0, 1.0])


@dataclass
class MethodDConfig:
    total_test_s: float = 540.0
    normative_success_coef: float = 1.0
    etap1_norm_cycle_time_s: float = 6.25
    etap2_norm_cycle_time_s: float = 8.75
    etap3_norm_cycle_time_s: float = 11.25
    etap1_norm_speed: float = 0.16
    etap2_norm_speed: float = 0.1143
    etap3_norm_speed: float = 0.0889

    @property
    def normative_cycle_times(self) -> dict:
        return {
            "min": float(self.etap1_norm_cycle_time_s),
            "medio": float(self.etap2_norm_cycle_time_s),
            "max": float(self.etap3_norm_cycle_time_s),
        }

    @normative_cycle_times.setter
    def normative_cycle_times(self, vals):
        raw = dict(vals or {}) if isinstance(vals, dict) else {}
        try:
            self.etap1_norm_cycle_time_s = float(raw.get("min", self.etap1_norm_cycle_time_s))
        except Exception:
            pass
        try:
            self.etap2_norm_cycle_time_s = float(raw.get("medio", self.etap2_norm_cycle_time_s))
        except Exception:
            pass
        try:
            self.etap3_norm_cycle_time_s = float(raw.get("max", self.etap3_norm_cycle_time_s))
        except Exception:
            pass

    @property
    def normative_stage_speed(self) -> dict:
        def _speed(time_value, fallback):
            try:
                time_value = float(time_value)
                if time_value > 0:
                    return 1.0 / time_value
            except Exception:
                pass
            return float(fallback)

        return {
            "min": _speed(self.etap1_norm_cycle_time_s, self.etap1_norm_speed),
            "medio": _speed(self.etap2_norm_cycle_time_s, self.etap2_norm_speed),
            "max": _speed(self.etap3_norm_cycle_time_s, self.etap3_norm_speed),
        }

    @normative_stage_speed.setter
    def normative_stage_speed(self, vals):
        raw = dict(vals or {}) if isinstance(vals, dict) else {}
        try:
            self.etap1_norm_speed = float(raw.get("min", self.etap1_norm_speed))
            if self.etap1_norm_speed > 0:
                self.etap1_norm_cycle_time_s = 1.0 / self.etap1_norm_speed
        except Exception:
            pass
        try:
            self.etap2_norm_speed = float(raw.get("medio", self.etap2_norm_speed))
            if self.etap2_norm_speed > 0:
                self.etap2_norm_cycle_time_s = 1.0 / self.etap2_norm_speed
        except Exception:
            pass
        try:
            self.etap3_norm_speed = float(raw.get("max", self.etap3_norm_speed))
            if self.etap3_norm_speed > 0:
                self.etap3_norm_cycle_time_s = 1.0 / self.etap3_norm_speed
        except Exception:
            pass




