def _run_method_d(self, session: SessionInfo) -> dict:
    cfg = load_method_d_config(self.base_dir)
    result = _run_modal_method(self, lambda: MethodDWindow(self.root, session, self.logger, self.base_dir, cfg).run())
    if result.get('completed'):
        payload = _build_method_d_payload(self, session, result)
        self.progress_store.save_test_result(self.current_profile, 'D', payload)
        self.logger.log_event(session, event_type='summary', screen='test_menu', test_name='method_d', action='session_finished', value=payload['summary'].get('tasks_correct', 0), note='Методика D завершена и сохранена')
        self.menu_status_var.set('Тест D завершён. Все четыре методики доступны в итоговой интегральной визуализации.')
        messagebox.showinfo('Готово', 'Тест D завершён. Теперь доступна интегральная визуализация результатов.')
    else:
        self.menu_status_var.set('Тест D был прерван. Уже записанные данные сохранены, прогресс не засчитан.')
        messagebox.showwarning('Остановлено', 'Тест D был прерван. Уже записанные данные сохранены, прогресс не засчитан.')
    return result


def _draw_summary_cards(parent: tk.Widget, cards: list[tuple[str, str, str, str]]):
    grid = tk.Frame(parent, bg=parent['bg'])
    for i, (title, value, subtitle, accent) in enumerate(cards):
        card = tk.Frame(grid, bg='white', bd=0, highlightbackground='#d8e1ec', highlightthickness=1)
        card.grid(row=0, column=i, padx=10, pady=10, sticky='nsew')
        tk.Frame(card, bg=accent, height=6).pack(fill='x')
        tk.Label(card, text=title, bg='white', fg='#425065', font=('Arial', 11, 'bold')).pack(anchor='w', padx=14, pady=(12, 4))
        tk.Label(card, text=value, bg='white', fg='#102744', font=('Arial', 22, 'bold')).pack(anchor='w', padx=14)
        tk.Label(card, text=subtitle, bg='white', fg='#657385', font=('Arial', 10), wraplength=200, justify='left').pack(anchor='w', padx=14, pady=(2, 12))
    return grid


def _open_results_top(self, title: str):
    top = tk.Toplevel(self.root)
    top.title(title)
    top.configure(bg='#eef3f8')
    top.transient(self.root)
    top.grab_set()
    try:
        top.attributes('-fullscreen', True)
    except tk.TclError:
        top.geometry(f"{self.root.winfo_screenwidth()}x{self.root.winfo_screenheight()}+0+0")
    top.bind('<Escape>', lambda _e: top.destroy())

    shell = tk.Frame(top, bg='#eef3f8')
    shell.pack(fill='both', expand=True)

    toolbar = tk.Frame(shell, bg='#eef3f8')
    toolbar.pack(fill='x', side='top')
    tk.Button(
        toolbar,
        text='Закрыть',
        command=top.destroy,
        bg=NEXT_BG,
        activebackground=NEXT_ACTIVE,
        relief='raised',
        bd=3,
        cursor='hand2',
        font=('Arial', 12, 'bold'),
        width=12,
    ).pack(side='right', padx=24, pady=(16, 4))

    content = tk.Frame(shell, bg='#eef3f8')
    content.pack(fill='both', expand=True)

    canvas = tk.Canvas(content, bg='#eef3f8', highlightthickness=0)
    scrollbar = tk.Scrollbar(content, orient='vertical', command=canvas.yview)
    canvas.configure(yscrollcommand=scrollbar.set)
    scrollbar.pack(side='right', fill='y')
    canvas.pack(side='left', fill='both', expand=True)

    body = tk.Frame(canvas, bg='#eef3f8')
    window_id = canvas.create_window((0, 0), window=body, anchor='nw')

    def _sync(_event=None):
        canvas.configure(scrollregion=canvas.bbox('all'))
        canvas.itemconfigure(window_id, width=canvas.winfo_width())

    def _on_mousewheel(event):
        delta = 0
        if getattr(event, 'delta', 0):
            delta = -int(event.delta / 120)
        elif getattr(event, 'num', None) == 4:
            delta = -1
        elif getattr(event, 'num', None) == 5:
            delta = 1
        if delta:
            canvas.yview_scroll(delta, 'units')
            return 'break'
        return None

    def _bind_mousewheel(_event=None):
        canvas.bind_all('<MouseWheel>', _on_mousewheel)
        canvas.bind_all('<Button-4>', _on_mousewheel)
        canvas.bind_all('<Button-5>', _on_mousewheel)

    def _unbind_mousewheel(_event=None):
        canvas.unbind_all('<MouseWheel>')
        canvas.unbind_all('<Button-4>')
        canvas.unbind_all('<Button-5>')

    body.bind('<Configure>', _sync)
    canvas.bind('<Configure>', _sync)
    top.bind('<Enter>', _bind_mousewheel)
    top.bind('<Leave>', _unbind_mousewheel)
    top.protocol('WM_DELETE_WINDOW', top.destroy)
    top.bind('<Destroy>', lambda _e: _unbind_mousewheel())
    return top, body


def _add_info_box(parent: tk.Widget, title: str, text: str, accent: str = '#6b7dff'):
    box = tk.Frame(parent, bg='white', highlightthickness=1, highlightbackground='#d8e1ec')
    tk.Frame(box, bg=accent, height=6).pack(fill='x')
    tk.Label(box, text=title, bg='white', fg='#102744', font=('Arial', 13, 'bold')).pack(anchor='w', padx=16, pady=(12, 4))
    tk.Label(box, text=text, bg='white', fg='#33455c', font=('Arial', 11), justify='left', wraplength=1080).pack(anchor='w', padx=16, pady=(0, 14))
    return box




def _interpret_method_a(summary: dict, reports: list[dict]) -> str:
    total_time = float(summary.get('total_time_s', 0.0))
    stability = float(summary.get('avg_stability_pct', 0.0))
    mean_xy = float(summary.get('avg_mean_xy_cm', 0.0))
    crashes = int(summary.get('total_crashes', 0))
    best_stage = summary.get('best_stage')

    if not reports:
        if total_time <= 0:
            return 'Пока нет данных для расшифровки этого теста.'
        parts = [
            f'Тест длился {total_time:.1f} с.',
            f'В среднем объект удерживался в зелёной зоне {stability:.0f}% времени.',
            f'Среднее отклонение от центра составило {mean_xy:.2f} см.',
        ]
        if crashes:
            parts.append(f'За весь тест было {crashes} выходов из зоны.')
        if best_stage:
            parts.append(f'Самым ровным получился этап {best_stage}.')
        return ' '.join(parts)

    stage_names = {1: 'по оси X', 2: 'по осям X и Y', 3: 'по осям X, Y и крену'}
    best_report = None
    if best_stage:
        for rep in reports:
            if int(rep.get('stage_no', 0)) == int(best_stage):
                best_report = rep
                break
    if best_report is None and reports:
        best_report = max(
            reports,
            key=lambda r: (
                float(r.get('stability_pct', 0.0)),
                -int(r.get('crashes', 0)),
                -float(r.get('mean_abs_xy_cm', 999.0)),
            ),
        )
        best_stage = int(best_report.get('stage_no', 0) or 0) or None

    worst_report = min(
        reports,
        key=lambda r: (
            float(r.get('stability_pct', 0.0)),
            int(r.get('crashes', 0)),
            float(r.get('mean_abs_xy_cm', 0.0)),
        ),
    )
    worst_stage = int(worst_report.get('stage_no', 0) or 0) or None

    if stability >= 65 and mean_xy <= 4.5 and crashes <= 1:
        overall = 'Контроль движения выглядит устойчивым: объект в целом удерживался близко к центру цели.'
    elif stability >= 35 and mean_xy <= 8.5 and crashes <= 4:
        overall = 'Контроль движения сохранён, но тест требовал заметной коррекции и постоянного подруливания.'
    else:
        overall = 'Тест шёл напряжённо: объект часто уходил от центра, а удержание в целевой зоне давалось трудно.'

    details = [
        f'За три этапа тест занял {total_time:.1f} с.',
        f'В среднем объект удерживался в зелёной зоне {stability:.0f}% времени, среднее отклонение от центра составило {mean_xy:.2f} см.',
        overall,
    ]

    if best_stage:
        details.append(
            f'Наиболее ровно прошёл этап {best_stage} ({stage_names.get(int(best_stage), "без уточнения осей")}).'
        )
    if worst_stage and worst_stage != best_stage:
        details.append(
            f'Больше всего трудностей было на этапе {worst_stage} ({stage_names.get(int(worst_stage), "без уточнения осей")}).'
        )

    if any(int(r.get('stage_no', 0)) == 3 for r in reports):
        roll = next((float(r.get('mean_abs_roll_deg', 0.0)) for r in reports if int(r.get('stage_no', 0)) == 3), 0.0)
        details.append(f'На третьем этапе дополнительно оценивался крен; среднее отклонение по крену составило {roll:.1f}°.')

    details.append('Ниже показаны отдельные карточки по этапам, где можно сравнить удержание в зоне, выходы из неё и величину отклонений.')
    return ' '.join(details)













def _show_method_d_results(self, payload: dict):
    top, outer = _open_results_top(self, 'Результаты - Тест D. Поиск закономерностей')
    participant = payload.get('participant', {})
    summary = dict(payload.get('summary', {}) or {})
    groups = summary.get('groups', {}) if isinstance(summary, dict) else {}

    completed_at = payload.get('completed_at', '')
    dt_label = completed_at.replace('T', ' ')[:19] if completed_at else 'не указано'

    stage_map = [
        ('min', 'Этап 1 - 2 элемента'),
        ('medio', 'Этап 2 - 3 элемента'),
        ('max', 'Этап 3 - 4 элемента'),
    ]

    def _group(key: str) -> dict:
        item = groups.get(key, {}) if isinstance(groups, dict) else {}
        return item if isinstance(item, dict) else {}

    def _f4(v) -> str:
        try:
            return f"{float(v or 0.0):.4f}"
        except Exception:
            return '0.0000'

    def _f2(v) -> str:
        try:
            return f"{float(v or 0.0):.2f}"
        except Exception:
            return '0.00'

    def _i(v) -> str:
        try:
            return str(int(v or 0))
        except Exception:
            return '0'

    def _draw_t_with_index(parent: tk.Widget, token: str, *, big_size: int, sub_size: int, fg: str = '#101010', bg: str = '#ffffff', centered: bool = False):
        txt = str(token or '')
        if not txt:
            tk.Label(parent, text='', bg=bg, fg=fg).pack()
            return
        first = txt[0]
        rest = txt[1:]
        row = tk.Frame(parent, bg=bg)
        if centered:
            row.pack(expand=True)
        else:
            row.pack(anchor='w')
        tk.Label(row, text=first, bg=bg, fg=fg, font=('Times New Roman', big_size, 'bold')).pack(side='left', anchor='n')
        if rest:
            tk.Label(row, text=rest, bg=bg, fg=fg, font=('Times New Roman', sub_size, 'bold')).pack(side='left', anchor='s', pady=(max(4, int(big_size * 0.36)), 0))

    norm_speed = {'min': 0.16, 'medio': 0.1143, 'max': 0.0889}
    try:
        cfg = load_method_d_config(self.base_dir)
        norm_speed = dict(getattr(cfg, 'normative_stage_speed', norm_speed) or norm_speed)
    except Exception:
        pass

    stage_colors = ['#67a9ff', '#53c26b', '#c98cff']
    stage_bottom_colors = ['#78d3e2', '#ffb35c', '#ef7070']
    stage_items = [_group('min'), _group('medio'), _group('max')]

    header = tk.Frame(outer, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec')
    header.pack(fill='x', padx=24, pady=(24, 10))
    tk.Frame(header, bg='#67a9ff', height=6).pack(fill='x')
    head_body = tk.Frame(header, bg='#ffffff')
    head_body.pack(fill='both', expand=True, padx=22, pady=(14, 12))
    tk.Label(head_body, text='Тест D   Поиск закономерностей', bg='#ffffff', fg='#102744', font=('Times New Roman', 30, 'bold')).pack(anchor='w')
    subtitle = f"{participant.get('name', '')}, {participant.get('age', '')} лет, {participant.get('gender', '')}. Последнее завершение: {dt_label}."
    tk.Label(head_body, text=subtitle, bg='#ffffff', fg='#5a6678', font=('Arial', 10, 'bold'), wraplength=1160, justify='left').pack(anchor='w', pady=(4, 0))

    cards_row = tk.Frame(outer, bg='#eef3f8')
    cards_row.pack(fill='x', padx=24, pady=(0, 4))
    for idx, item in enumerate(stage_items):
        cards_row.grid_columnconfigure(idx, weight=1, uniform='d_fixed365_cards')
        card = tk.Frame(cards_row, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec')
        card.grid(row=0, column=idx, sticky='nsew', padx=(0 if idx == 0 else 2, 0))
        tk.Frame(card, bg=stage_colors[idx], height=4).pack(fill='x')
        body = tk.Frame(card, bg='#ffffff')
        body.pack(fill='both', expand=True, padx=10, pady=(8, 8))
        top_line = tk.Frame(body, bg='#ffffff')
        top_line.pack(fill='x')
        tk.Label(top_line, text=_f2(item.get('t_value', 0.0)), bg='#ffffff', fg='#102744', font=('Arial', 26, 'bold')).pack(side='left')
        t_wrap = tk.Frame(top_line, bg='#ffffff')
        t_wrap.pack(side='left', padx=(18, 0))
        _draw_t_with_index(t_wrap, f'tзакон {idx + 1}', big_size=42, sub_size=20, fg='#101010', bg='#ffffff')
        tk.Label(body, text=stage_map[idx][1], bg='#ffffff', fg='#5a6678', font=('Arial', 9)).pack(anchor='center', pady=(6, 0))

    stage_row = tk.Frame(outer, bg='#eef3f8')
    stage_row.pack(fill='x', padx=24, pady=(0, 12))
    for idx, (_key, title) in enumerate(stage_map):
        stage_row.grid_columnconfigure(idx, weight=1, uniform='d_fixed365_stage')
        block = tk.Frame(stage_row, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec', height=116)
        block.grid(row=0, column=idx, sticky='nsew', padx=(0 if idx == 0 else 2, 0))
        block.grid_propagate(False)
        tk.Frame(block, bg=stage_bottom_colors[idx], height=3).pack(fill='x', side='top')
        center = tk.Frame(block, bg='#ffffff')
        center.pack(fill='both', expand=True)
        tk.Label(center, text=title, bg='#ffffff', fg='#111111', font=('Arial', 17, 'bold')).pack(expand=True, pady=(8, 8))

    table_shell = tk.Frame(outer, bg='#eef3f8')
    table_shell.pack(fill='x', padx=24, pady=(0, 8))
    table = tk.Frame(table_shell, bg='white', highlightthickness=1, highlightbackground='#9c9c9c')
    table.pack(fill='x')

    for grp in range(3):
        base = grp * 3
        table.grid_columnconfigure(base + 0, weight=2, uniform='d_fixed365_tbl')
        table.grid_columnconfigure(base + 1, weight=1, uniform='d_fixed365_tbl')
        table.grid_columnconfigure(base + 2, weight=1, uniform='d_fixed365_tbl')

    yellow = '#ffd400'
    head_labels = ('НАЗВАНИЕ\nПАРАМЕТРА', 'ПАРАМЕТР\nразмерность', 'величина')
    for grp in range(3):
        base = grp * 3
        for j, htxt in enumerate(head_labels):
            tk.Label(table, text=htxt, bg=yellow, fg='#1a1a1a', font=('Arial', 10, 'bold'), bd=1, relief='solid', padx=4, pady=6, justify='left' if j == 0 else 'center', anchor='w' if j == 0 else 'center').grid(row=0, column=base + j, sticky='nsew')

    def _presented_count(g: dict) -> int:
        try:
            return int(g.get('presented_count', g.get('total_count', g.get('attempted_count', g.get('correct_count', 0)))) or 0)
        except Exception:
            return 0

    def _success_ratio(g: dict) -> float:
        presented = _presented_count(g)
        try:
            correct = int(g.get('correct_count', 0) or 0)
        except Exception:
            correct = 0
        if presented <= 0:
            return float(g.get('success_ratio', 0.0) or 0.0)
        return float(correct) / float(presented)

    def _real_speed(g: dict) -> float:
        try:
            return float(g.get('real_speed', 0.0) or 0.0)
        except Exception:
            return 0.0

    def _t_reduced(g: dict, i: int) -> float:
        try:
            t_fact = float(g.get('t_fact_avg_s', 0.0) or 0.0)
            t_norm = float(g.get('t_norm_avg_s', 0.0) or 0.0)
            if t_fact > 0 and t_norm > 0:
                return t_norm / t_fact
            return float(g.get('t_reduced', 0.0) or 0.0)
        except Exception:
            return 0.0

    def _t_search(g: dict, i: int) -> float:
        try:
            return float(g.get('t_value', _t_reduced(g, i)) or 0.0)
        except Exception:
            return _t_reduced(g, i)

    row_defs = [
        ('предъявлено матриц за этап', lambda g, i: f'kпред {i}', lambda g, i: _i(_presented_count(g))),
        ('произведено ответов за этап', lambda g, i: f'kотв {i}', lambda g, i: _i(g.get('answered_count', _presented_count(g)))),
        ('верных ответов за этап', lambda g, i: f'kусп {i}', lambda g, i: _i(g.get('correct_count', 0))),
        ('коэффициент успешности', lambda g, i: f'γ{i}', lambda g, i: _f4(_success_ratio(g))),
        ('нормативный коэффициент успешности', lambda g, i: f'γнорм {i}', lambda g, i: _f4(g.get('gamma_norm', 1.0))),
        ('среднее реальное время цикла (с)', lambda g, i: f'Tфакт {i}', lambda g, i: _f2(g.get('t_fact_avg_s', 0.0))),
        ('нормативное время цикла (с)', lambda g, i: f'Tнорм {i}', lambda g, i: _f2(g.get('t_norm_avg_s', 0.0))),
        ('приведенное время цикла', lambda g, i: f'Tприв {i}', lambda g, i: _f2(_t_reduced(g, i))),
        (lambda g, i: f'темп закономерности {i}', lambda g, i: f'tзакон {i}', lambda g, i: _f2(_t_search(g, i))),
    ]

    for r_idx, (name_fn, sym_fn, val_fn) in enumerate(row_defs, start=1):
        for grp, stage_item in enumerate(stage_items, start=1):
            base = (grp - 1) * 3
            name_text = name_fn(stage_item, grp) if callable(name_fn) else name_fn
            values = (name_text, sym_fn(stage_item, grp), val_fn(stage_item, grp))
            for j, text in enumerate(values):
                bg = '#f8ffff' if j == 0 and r_idx % 2 == 0 else ('#effff4' if j == 0 else '#ffffff')
                if j == 1 and isinstance(text, str) and text and text[0].lower() == 't':
                    cell = tk.Frame(table, bg=bg, bd=1, relief='solid')
                    cell.grid(row=r_idx, column=base + j, sticky='nsew')
                    slot = tk.Frame(cell, bg=bg)
                    slot.pack(fill='both', expand=True, padx=4, pady=2)
                    _draw_t_with_index(slot, text, big_size=18, sub_size=11, fg='#20324d', bg=bg, centered=True)
                else:
                    tk.Label(table, text=text, bg=bg, fg='#102744' if j == 0 else '#20324d', font=('Arial', 9, 'bold' if j != 2 else 'normal'), bd=1, relief='solid', padx=4, pady=4, justify='left' if j == 0 else 'center', anchor='w' if j == 0 else 'center').grid(row=r_idx, column=base + j, sticky='nsew')


def _collect_integral_values(self, profile: UserProfile | None = None) -> dict:
    profile = profile or self.current_profile
    if not profile:
        return {}
    results = {}
    for code in TEST_ORDER:
        payload = self.progress_store.get_test_result(profile, code)
        if payload:
            results[code] = payload
    values = {
        'A': [0.0, 0.0, 0.0],
        'B': [0.0, 0.0, 0.0],
        'C': [0.0, 0.0, 0.0],
        'D': [0.0, 0.0, 0.0],
    }
    if 'A' in results:
        s = results['A'].get('summary', {})
        values['A'] = [float(s.get('tmin_a', s.get('tmin_A', s.get('t_values', {}).get('min', 0.0) if isinstance(s.get('t_values', {}), dict) else 0.0)) or 0.0), float(s.get('tmedio_a', s.get('tmedio_A', s.get('t_values', {}).get('medio', 0.0) if isinstance(s.get('t_values', {}), dict) else 0.0)) or 0.0), float(s.get('tmax_a', s.get('tmax_A', s.get('t_values', {}).get('max', 0.0) if isinstance(s.get('t_values', {}), dict) else 0.0)) or 0.0)]
        if values['A'] == [0.0, 0.0, 0.0]:
            reports = results['A'].get('reports', [])
            if reports:
                values['A'] = [
                    _round2(float(reports[0].get('stability_pct', 0)) / 100.0),
                    _round2(float(reports[1].get('stability_pct', 0)) / 100.0 if len(reports) > 1 else 0.0),
                    _round2(float(reports[2].get('stability_pct', 0)) / 100.0 if len(reports) > 2 else 0.0),
                ]
    if 'B' in results:
        s = results['B'].get('summary', {})
        values['B'] = [float(s.get('tmin_b', 0.0) or 0.0), float(s.get('tmedio_b', 0.0) or 0.0), float(s.get('tmax_b', 0.0) or 0.0)]
    if 'C' in results:
        s = results['C'].get('summary', {})
        values['C'] = [float(s.get('tmin_c', 0.0) or 0.0), float(s.get('tmedio_c', 0.0) or 0.0), float(s.get('tmax_c', 0.0) or 0.0)]
    if 'D' in results:
        s = results['D'].get('summary', {})
        values['D'] = [float(s.get('tmin_d', 0.0) or 0.0), float(s.get('tmedio_d', 0.0) or 0.0), float(s.get('tmax_d', 0.0) or 0.0)]
    return values





def _continue_next_test(self):
    if not self.current_profile:
        return
    next_code = self.progress_store.next_test_code(self.current_profile)
    if not next_code:
        _show_integral_results(self)
        return
    self.launch_test(next_code)


def _refresh_menu_state(self):
    if not self.current_profile:
        return
    progress = self.progress_store.ensure_user(self.current_profile)
    completed = progress.get('completed_tests', [])
    next_code = self.progress_store.next_test_code(self.current_profile)
    completed_text = ', '.join(TEST_LABELS[c] for c in completed) if completed else 'пока нет'
    if next_code:
        next_text = f'Следующий доступный тест: {TEST_LABELS[next_code]}'
    else:
        next_text = 'Все тесты пройдены. Ниже можно открыть результаты каждой методики и общий профиль СПР.'
    self.menu_intro_var.set(
        f'Пользователь: {self.current_profile.name}, {self.current_profile.age} лет, {self.current_profile.gender}.\n\n'
        'Тесты можно проходить не за один раз. Уже пройденные кнопки блокируются, '
        'а доступной остаётся только следующая методика по порядку.'
    )
    self.menu_status_var.set(f'Пройдено: {completed_text}.\n{next_text}')
    for code, btn in self.menu_buttons.items():
        if code in completed:
            btn.configure(state=tk.DISABLED, text=menu_card_text(code, "done"), bg='#bfc7ba', activebackground='#bfc7ba', disabledforeground='#4a5b47', relief='sunken')
        elif code == next_code:
            btn.configure(state=tk.NORMAL, text=menu_card_text(code), bg=NEXT_BG, activebackground=NEXT_ACTIVE, fg='#111111', relief='raised')
        else:
            btn.configure(state=tk.DISABLED, text=menu_card_text(code, "locked"), bg=MENU_DISABLED, activebackground=MENU_DISABLED, disabledforeground='#6d6955', relief='ridge')
    for code, btn in getattr(self, 'menu_result_buttons', {}).items():
        has_payload = bool(self.progress_store.get_test_result(self.current_profile, code))
        if has_payload:
            btn.configure(state=tk.NORMAL, text='ПОКАЗАТЬ\nРЕЗУЛЬТАТЫ', bg='#6b7dff', activebackground='#5b6de8', fg='white', relief='raised')
        else:
            btn.configure(state=tk.DISABLED, text='РЕЗУЛЬТАТОВ\nПОКА НЕТ', bg='#d6dbe5', activebackground='#d6dbe5', disabledforeground='#7f8897', relief='flat')
    if next_code:
        self.continue_btn.configure(state=tk.NORMAL, text='ПРОДОЛЖИТЬ', bg=NEXT_BG, activebackground=NEXT_ACTIVE, fg='#111111', width=14, relief='raised')
    else:
        self.continue_btn.configure(state=tk.NORMAL, text='ОБЩИЙ\nПРОФИЛЬ СПР', bg='#4f78ff', activebackground='#4269e0', fg='white', width=16, relief='raised')




def _launch_test(self, code: str):
    if not self.current_profile or not self.current_session:
        return
    next_code = self.progress_store.next_test_code(self.current_profile)
    completed = self.progress_store.get_progress(self.current_profile).get('completed_tests', [])
    if code in completed:
        messagebox.showinfo('Уже пройдено', f'{TEST_LABELS[code]} уже отмечен как пройденный.')
        return
    if code != next_code:
        messagebox.showwarning('Порядок тестов', f'Сейчас доступен только {TEST_LABELS[next_code]}.')
        return
    self.logger.log_event(self.current_session, event_type='menu_event', screen='test_menu', test_name=f'test_{code.lower()}', action='launch_requested', note=TEST_DESCRIPTIONS[code])
    if code == 'A':
        result = self.run_method_a(self.current_session)
    elif code == 'B':
        result = _run_method_b(self, self.current_session)
    elif code == 'C':
        result = _run_method_c(self, self.current_session)
    elif code == 'D':
        result = _run_method_d(self, self.current_session)
    else:
        return
    if result.get('completed'):
        self.progress_store.mark_completed(self.current_profile, code)
        self.logger.log_event(self.current_session, event_type='menu_event', screen='test_menu', test_name=f'test_{code.lower()}', action='marked_completed', note=f'{TEST_LABELS[code]} завершён и заблокирован как пройденный.')
        self.refresh_menu_state()
        self.show_test_completed_dialog(code)
    else:
        self.refresh_menu_state()


StartPageApp.run_method_b = _run_method_b
StartPageApp.run_method_c = _run_method_c
StartPageApp.run_method_d = _run_method_d
StartPageApp.continue_next_test = _continue_next_test
StartPageApp.refresh_menu_state = _refresh_menu_state
StartPageApp.show_method_d_results = _show_method_d_results
StartPageApp.launch_test = _launch_test



# ====== FIXED23 researcher mode / adaptive settings / all results ======



def _fixed285_csv_test_code(test_name: str) -> str | None:
    raw = str(test_name or '').strip().casefold()
    raw_compact = raw.replace('ё', 'е').replace('_', ' ').replace('-', ' ')
    raw_compact = ' '.join(raw_compact.split())
    if raw in ('method_a', 'test_a', 'a') or raw_compact in ('test a', 'тест a', 'тест а'):
        return 'A'
    if raw in ('method_b', 'test_b', 'b') or raw_compact in ('test b', 'тест b', 'тест в'):
        return 'B'
    if raw in ('method_c', 'test_c', 'c') or raw_compact in ('test c', 'тест c', 'тест с'):
        return 'C'
    if raw in ('method_d', 'test_d', 'd') or raw_compact in ('test d', 'тест d', 'тест д'):
        return 'D'
    return None


def _fixed285_csv_stamp_to_iso(date_raw: str, time_raw: str) -> str:
    d = str(date_raw or '').strip()
    t = str(time_raw or '').strip()
    if not d:
        return ''
    for fmt in ('%d.%m.%Y %H:%M:%S', '%Y-%m-%d %H:%M:%S', '%Y-%m-%dT%H:%M:%S'):
        try:
            return datetime.strptime(f'{d} {t}'.strip(), fmt).isoformat(timespec='seconds')
        except Exception:
            continue
    return ''


def _fixed285_parse_json_note_filename(note: str) -> str:
    txt = str(note or '')
    marker = 'json='
    pos = txt.find(marker)
    if pos < 0:
        return ''
    filename = txt[pos + len(marker):].strip().strip('"').strip("'")
    filename = filename.replace('\\', '/').split('/')[-1]
    return filename


def _fixed285_find_result_path(base_dir: Path, code: str, session_id: str, note: str = '') -> str:
    session = str(session_id or '').strip()
    if not session or code not in TEST_ORDER:
        return ''

    if code == 'A':
        note_name = _fixed285_parse_json_note_filename(note)
        if note_name:
            candidate = base_dir / 'data' / note_name
            if candidate.exists():
                return str(candidate)
        candidate = base_dir / 'data' / f'method_a_results_{session}.json'
        if candidate.exists():
            return str(candidate)
        # Fallback for technical/autotest files with non-standard naming.
        data_dir = base_dir / 'data'
        if data_dir.exists():
            def _norm(s: str) -> str:
                return ''.join(ch for ch in str(s).casefold() if ch.isalnum())
            key = _norm(session)
            if key:
                cand = []
                for p in data_dir.glob('*.json'):
                    if not p.is_file():
                        continue
                    if _norm(p.name).find(key) >= 0:
                        cand.append(p)
                if cand:
                    return str(max(cand, key=lambda p: p.stat().st_mtime))
        return ''

    results_dir = base_dir / 'data' / 'results'
    if not results_dir.exists():
        return ''
    pattern = f'method_{code.lower()}_{session}_*.json'
    files = [p for p in results_dir.glob(pattern) if p.is_file()]
    if not files:
        return ''
    latest = max(files, key=lambda p: p.stat().st_mtime)
    return str(latest)


def _fixed285_read_json_file(path_str: str):
    p = Path(path_str)
    if not p.exists():
        return None
    try:
        return json.loads(p.read_text(encoding='utf-8'))
    except Exception:
        return None


def _fixed285_build_payload_from_path(base_dir: Path, profile: UserProfile, code: str, session_id: str, completed_at: str, path_str: str) -> dict:
    result_path = str(path_str or '')
    payload = {
        'test_code': code,
        'test_label': TEST_LABELS.get(code, f'Тест {code}'),
        'completed_at': completed_at,
        'session_id': str(session_id or ''),
        'participant': {'name': profile.name, 'age': profile.age, 'gender': profile.gender},
        'result_path': result_path,
        'summary': {},
    }

    loaded = _fixed285_read_json_file(result_path) if result_path else None
    if code == 'A':
        reports = [item for item in loaded if isinstance(item, dict)] if isinstance(loaded, list) else []
        payload['reports'] = reports
        if reports:
            payload['summary'] = _fixed260_method_a_summary_from_reports(reports)
        return payload

    if isinstance(loaded, dict):
        merged = dict(loaded)
        merged.setdefault('test_code', code)
        merged.setdefault('test_label', TEST_LABELS.get(code, f'Тест {code}'))
        merged.setdefault('completed_at', completed_at)
        merged.setdefault('session_id', str(session_id or ''))
        participant = merged.get('participant', {})
        if not isinstance(participant, dict):
            participant = {}
        participant.setdefault('name', profile.name)
        participant.setdefault('age', profile.age)
        participant.setdefault('gender', profile.gender)
        merged['participant'] = participant
        merged.setdefault('result_path', result_path)
        return merged
    return payload


def _fixed285_merge_users_from_participants_csv(self, data: dict) -> tuple[dict, bool]:
    merged = dict(data) if isinstance(data, dict) else {}
    changed = False
    csv_path = self.base_dir / 'data' / 'participants.csv'
    if not csv_path.exists():
        return merged, changed

    users: dict[str, dict] = {}
    try:
        with open(csv_path, 'r', encoding='utf-8-sig', newline='') as f:
            reader = csv.reader(f, delimiter=';')
            header = None
            for row in reader:
                if not row:
                    continue
                first = str(row[0]).strip()
                if first == 'Неделя':
                    continue
                if first == 'Дата':
                    header = row
                    continue
                if not header:
                    continue
                if len(row) < len(header):
                    row = row + [''] * (len(header) - len(row))
                item = {str(header[i]).strip(): row[i] for i in range(min(len(header), len(row)))}

                name = str(item.get('ФИО') or item.get('Имя') or '').strip()
                if not name:
                    continue
                try:
                    age = int(str(item.get('Возраст', '0')).strip() or 0)
                except Exception:
                    age = 0
                gender = str(item.get('Пол', '')).strip() or 'Не указан'
                profile = UserProfile(name=name, age=age, gender=gender)
                key = profile.key

                user = users.get(key)
                if user is None:
                    user = {
                        'profile': profile,
                        'updated_at': '',
                        'completed': set(),
                        'tests': {},
                        'sessions': {},
                    }
                    users[key] = user

                iso_stamp = _fixed285_csv_stamp_to_iso(item.get('Дата', ''), item.get('Время', ''))
                if iso_stamp and (not user['updated_at'] or iso_stamp > user['updated_at']):
                    user['updated_at'] = iso_stamp

                code = _fixed285_csv_test_code(item.get('Тест', ''))
                if code is None:
                    continue

                event_type = str(item.get('Событие', '')).strip().casefold()
                action = str(item.get('Действие', '')).strip().casefold()
                session_id = str(item.get('SessionID', '')).strip()
                note = str(item.get('Примечание', '')).strip()

                sess_key = (code, session_id)
                sess = user['sessions'].get(sess_key)
                if sess is None:
                    sess = {
                        'code': code,
                        'session_id': session_id,
                        'stages': set(),
                        'has_completed': False,
                        'has_aborted': False,
                        'completed_at': '',
                        'note': '',
                    }
                    user['sessions'][sess_key] = sess
                stage_raw = str(item.get('Этап', '')).strip()
                try:
                    stage_no = int(stage_raw)
                except Exception:
                    stage_no = 0
                if stage_no > 0:
                    sess['stages'].add(stage_no)
                if iso_stamp and (not sess['completed_at'] or iso_stamp > sess['completed_at']):
                    sess['completed_at'] = iso_stamp
                if note and (not sess['note']):
                    sess['note'] = note

                completed = (
                    (event_type == 'summary' and action == 'session_finished')
                    or (event_type == 'method_session' and action in ('completed', 'finished'))
                )
                if completed:
                    sess['has_completed'] = True
                if event_type == 'method_session' and action == 'aborted':
                    sess['has_aborted'] = True
    except Exception:
        return merged, changed

    # Consolidate parsed sessions into completed tests/results.
    for user in users.values():
        for (_code, _session_id), sess in user.get('sessions', {}).items():
            code = str(sess.get('code', '') or '')
            session_id = str(sess.get('session_id', '') or '')
            completed_at = str(sess.get('completed_at', '') or '')
            stages = set(sess.get('stages', set()) or set())
            has_completed = bool(sess.get('has_completed'))
            has_aborted = bool(sess.get('has_aborted'))

            # Technical fallback: if Method A reached all stages and wasn't aborted,
            # treat it as completed even if summary rows were not written.
            synthetic_completed = (code == 'A' and not has_aborted and {1, 2, 3}.issubset(stages))
            if not (has_completed or synthetic_completed):
                continue

            user['completed'].add(code)
            path_from_note = _fixed285_find_result_path(self.base_dir, code, session_id, str(sess.get('note', '') or ''))
            info = user['tests'].get(code)
            if info is None or (completed_at and completed_at > str(info.get('completed_at', ''))):
                user['tests'][code] = {
                    'session_id': session_id,
                    'completed_at': completed_at,
                    'result_path': path_from_note,
                }

    for key, info in users.items():
        profile = info['profile']
        record = merged.get(key)
        if not isinstance(record, dict):
            record = self._default_record(profile)
            merged[key] = record
            changed = True

        if not str(record.get('name', '')).strip():
            record['name'] = profile.name
            changed = True
        if int(record.get('age', 0) or 0) != profile.age:
            record['age'] = profile.age
            changed = True
        if not str(record.get('gender', '')).strip():
            record['gender'] = profile.gender
            changed = True

        record.setdefault('results', {})
        record.setdefault('history', [])
        if info['updated_at'] and info['updated_at'] > str(record.get('updated_at', '') or ''):
            record['updated_at'] = info['updated_at']
            changed = True

        existing_completed = [c for c in record.get('completed_tests', []) if c in TEST_ORDER]
        merged_completed = [c for c in TEST_ORDER if (c in set(existing_completed)) or (c in info['completed'])]
        if merged_completed != existing_completed:
            record['completed_tests'] = merged_completed
            changed = True

        results = record.get('results', {})
        if not isinstance(results, dict):
            results = {}
            record['results'] = results
            changed = True

        for code, test_info in info['tests'].items():
            current_payload = results.get(code)
            csv_completed_at = str(test_info.get('completed_at', '') or '')
            current_completed_at = ''
            if isinstance(current_payload, dict):
                current_completed_at = str(current_payload.get('completed_at', '') or '')

            should_replace = (not isinstance(current_payload, dict)) or (csv_completed_at and csv_completed_at > current_completed_at)
            if not should_replace:
                continue

            result_path = str(test_info.get('result_path', '') or '')
            if not result_path:
                result_path = _fixed285_find_result_path(self.base_dir, code, str(test_info.get('session_id', '')), '')
            payload = _fixed285_build_payload_from_path(
                self.base_dir,
                profile,
                code,
                str(test_info.get('session_id', '')),
                csv_completed_at,
                result_path,
            )
            results[code] = self._enrich_payload_for_storage(code, payload)
            changed = True

        merged[key] = record
    return merged, changed


def _user_progress_all_user_records(self):
    data = self._load()
    merged, changed = _fixed285_merge_users_from_participants_csv(self, data if isinstance(data, dict) else {})
    if changed:
        self._save(merged)
    items = []
    for _key, record in merged.items():
        if not isinstance(record, dict):
            continue
        name = str(record.get('name', '')).strip()
        gender = str(record.get('gender', '')).strip()
        try:
            age = int(record.get('age', 0))
        except Exception:
            age = 0
        if not name:
            continue
        profile = UserProfile(name=name, age=age, gender=gender or 'Не указан')
        items.append((profile, record))
    # Default order for "All results": newest records first.
    items.sort(key=lambda item: (item[0].name.casefold(), item[0].age, item[0].gender.casefold()))
    items.sort(key=lambda item: str(item[1].get('updated_at', '') or ''), reverse=True)
    return items


UserProgressStore.all_user_records = _user_progress_all_user_records






