# ====== FIXED50: normalize bottom action rows on start and menu screens ======
def _fixed50_relayout_start_action_row(self):
    if not hasattr(self, 'btn_frame') or self.btn_frame is None or not self.btn_frame.winfo_exists():
        return
    scale = _fixed24_scale(self.root) if '_fixed24_scale' in globals() else 1.0
    gap = max(8, int(10 * scale))
    frame = self.btn_frame
    try:
        frame.grid_configure(sticky='ew', pady=(0, int(8 * scale)))
    except Exception:
        pass
    try:
        self.right.grid_columnconfigure(0, weight=1)
    except Exception:
        pass

    buttons = [
        getattr(self, 'back_to_settings_btn', None),
        getattr(self, 'next_btn', None),
        getattr(self, 'exit_btn', None),
    ]
    for btn in buttons:
        if btn is not None and btn.winfo_exists():
            try:
                btn.pack_forget()
            except Exception:
                pass
            try:
                btn.grid_forget()
            except Exception:
                pass

    for col, weight in enumerate((1.3, 1.0, 0.75)):
        try:
            frame.grid_columnconfigure(col, weight=weight, uniform='start_actions')
        except Exception:
            pass

    width = max(self.root.winfo_width(), 1100)
    height = max(self.root.winfo_height(), 760)
    scale2 = min(width / BASE_W, height / BASE_H)
    scale2 = max(0.72, min(scale2, 1.25))
    font_size = max(12, int(18 * scale2))
    pad_x = max(10, int(12 * scale2))
    pad_y = max(8, int(10 * scale2))

    common = dict(font=('Arial', font_size, 'bold'), height=2, bd=3, relief='raised', justify='center', anchor='center')
    labels = [
        (getattr(self, 'back_to_settings_btn', None), 'НАСТРОЙКИ'),
        (getattr(self, 'next_btn', None), 'ДАЛЕЕ'),
        (getattr(self, 'exit_btn', None), 'ВЫХОД'),
    ]
    for col, (btn, label) in enumerate(labels):
        if btn is None or not btn.winfo_exists():
            continue
        try:
            btn.configure(text=label, wraplength=0, padx=pad_x, pady=pad_y, **common)
        except Exception:
            pass
        try:
            btn.grid(row=0, column=col, sticky='ew', padx=(0, gap) if col < 2 else (0, 0), pady=0)
        except Exception:
            pass


def _fixed50_relayout_menu_action_row(self):
    if not hasattr(self, 'menu_btn_frame') or self.menu_btn_frame is None or not self.menu_btn_frame.winfo_exists():
        return
    scale = _fixed24_scale(self.root) if '_fixed24_scale' in globals() else 1.0
    gap = max(8, int(10 * scale))
    frame = self.menu_btn_frame
    try:
        frame.grid_configure(sticky='ew', pady=(0, int(10 * scale)))
    except Exception:
        pass
    try:
        self.right.grid_columnconfigure(0, weight=1)
    except Exception:
        pass

    buttons = [
        getattr(self, 'settings_btn', None),
        getattr(self, 'all_results_btn', None),
        getattr(self, 'continue_btn', None),
        getattr(self, 'restart_btn', None),
        getattr(self, 'exit_btn', None),
    ]
    for btn in buttons:
        if btn is not None and btn.winfo_exists():
            try:
                btn.pack_forget()
            except Exception:
                pass
            try:
                btn.grid_forget()
            except Exception:
                pass

    for col, weight in enumerate((1.15, 1.25, 1.3, 1.35, 0.75)):
        try:
            frame.grid_columnconfigure(col, weight=weight, uniform='menu_actions')
        except Exception:
            pass

    width = max(self.root.winfo_width(), 1200)
    height = max(self.root.winfo_height(), 780)
    scale2 = min(width / BASE_W, height / BASE_H)
    scale2 = max(0.72, min(scale2, 1.20))
    font_size = max(11, int(16 * scale2))
    pad_x = max(10, int(12 * scale2))
    pad_y = max(8, int(9 * scale2))

    common = dict(font=('Arial', font_size, 'bold'), height=2, bd=3, relief='raised', justify='center', anchor='center')
    order = [
        (getattr(self, 'settings_btn', None), 'НАСТРОЙКИ'),
        (getattr(self, 'all_results_btn', None), 'ВСЕ РЕЗУЛЬТАТЫ'),
        (getattr(self, 'continue_btn', None), None),
        (getattr(self, 'restart_btn', None), 'НАЧАТЬ СНАЧАЛА'),
        (getattr(self, 'exit_btn', None), 'ВЫХОД'),
    ]

    for col, (btn, forced_text) in enumerate(order):
        if btn is None or not btn.winfo_exists():
            continue
        text = forced_text if forced_text is not None else btn.cget('text')
        wrap = 0
        if text == 'ВСЕ РЕЗУЛЬТАТЫ':
            wrap = max(140, int(width * 0.12))
        elif text in ('ОБЩИЙ ПРОФИЛЬ СПР', 'СЛЕДУЮЩИЙ ТЕСТ', 'НАЧАТЬ СНАЧАЛА'):
            wrap = max(150, int(width * 0.14))
        try:
            btn.configure(text=text, wraplength=wrap, padx=pad_x, pady=pad_y, **common)
        except Exception:
            pass
        try:
            btn.grid(row=0, column=col, sticky='ew', padx=(0, gap) if col < 4 else (0, 0), pady=0)
        except Exception:
            pass


_FIXED50_PREV_APPLY_START_LAYOUT = StartPageApp.apply_start_layout
_FIXED50_PREV_APPLY_MENU_LAYOUT = StartPageApp.apply_menu_layout


def _fixed50_apply_start_layout(self):
    _FIXED50_PREV_APPLY_START_LAYOUT(self)
    if getattr(self, 'view_mode', '') == 'start':
        self.root.after_idle(lambda: _fixed50_relayout_start_action_row(self))




StartPageApp.apply_start_layout = _fixed50_apply_start_layout

