def _fixed57_build_menu_ui(self):
    self.view_mode = "menu"
    self.destroy_main()
    self.build_base_shell()

    self.title_small.configure(text="Меню")
    self.title_big.configure(text="ВЫБОР\nТЕСТА")

    self.body = tk.Label(
        self.right,
        textvariable=self.menu_intro_var,
        bg=BG_COLOR,
        fg=TEXT_COLOR,
        justify="left",
        anchor="nw",
    )
    self.body.grid(row=2, column=0, sticky="nsew")

    self.menu_panel = tk.Frame(self.right, bg=PANEL_COLOR, bd=2, relief="groove")
    self.menu_panel.grid(row=3, column=0, sticky="ew")
    self.menu_panel.grid_columnconfigure(0, weight=1)
    self.menu_panel.grid_columnconfigure(1, weight=1)

    self.menu_title = tk.Label(self.menu_panel, text="Доступные тесты", bg=PANEL_COLOR, fg=TITLE_COLOR, anchor="w")
    self.menu_title.grid(row=0, column=0, columnspan=2, sticky="ew")

    self.menu_status_label = tk.Label(
        self.menu_panel,
        textvariable=self.menu_status_var,
        bg=PANEL_COLOR,
        fg="#245a2a",
        justify="left",
        anchor="w",
    )
    self.menu_status_label.grid(row=1, column=0, columnspan=2, sticky="ew")

    self.tests_grid = tk.Frame(self.menu_panel, bg=PANEL_COLOR)
    self.tests_grid.grid(row=2, column=0, columnspan=2, sticky="ew")
    self.tests_grid.grid_columnconfigure(0, weight=1)
    self.tests_grid.grid_columnconfigure(1, weight=1)

    self.menu_buttons = {}
    self.menu_result_buttons = {}
    self.menu_cards = {}
    for idx, code in enumerate(TEST_ORDER):
        card = tk.Frame(self.tests_grid, bg="#e8e1bf", bd=2, relief="ridge")
        card.grid(row=idx // 2, column=idx % 2, sticky="nsew")
        card.grid_columnconfigure(0, weight=1)
        self.menu_cards[code] = card

        btn = tk.Button(
            card,
            text=menu_card_text(code),
            bg=MENU_BG,
            activebackground=MENU_ACTIVE,
            relief="raised",
            bd=3,
            cursor="hand2",
            command=lambda c=code: self.launch_test(c),
            justify="center",
            wraplength=340,
        )
        btn.grid(row=0, column=0, sticky="nsew")
        self.menu_buttons[code] = btn

        result_btn = tk.Button(
            card,
            text="РЕЗУЛЬТАТОВ\nПОКА НЕТ",
            bg=RESULT_BG,
            activebackground=RESULT_ACTIVE,
            relief="raised",
            bd=3,
            cursor="hand2",
            command=lambda c=code: self.view_results(c),
            justify="center",
            wraplength=340,
        )
        result_btn.grid(row=1, column=0, sticky="ew")
        self.menu_result_buttons[code] = result_btn

    self.menu_btn_frame = tk.Frame(self.right, bg=BG_COLOR)
    self.menu_btn_frame.grid(row=4, column=0, sticky="ew")

    self.settings_btn = tk.Button(
        self.menu_btn_frame, text='НАСТРОЙКИ', bg=BACK_BG, activebackground=BACK_ACTIVE,
        relief='raised', bd=3, command=lambda: _fixed46_open_researcher_settings(self), cursor='hand2')
    self.all_results_btn = tk.Button(
        self.menu_btn_frame, text='ВСЕ РЕЗУЛЬТАТЫ', bg='#6b7dff', activebackground='#5b6de8',
        relief='raised', bd=3, command=lambda: self.show_all_results_browser(), cursor='hand2')
    self.continue_btn = tk.Button(
        self.menu_btn_frame, text='СЛЕДУЮЩИЙ ТЕСТ', bg=NEXT_BG, activebackground=NEXT_ACTIVE,
        relief='raised', bd=3, command=self.continue_next_test, cursor='hand2')
    self.restart_btn = tk.Button(
        self.menu_btn_frame, text='НАЧАТЬ СНАЧАЛА', bg=BACK_BG, activebackground=BACK_ACTIVE,
        relief='raised', bd=3, command=self.restart_progress, cursor='hand2')
    self.exit_btn = tk.Button(
        self.menu_btn_frame, text='ВЫХОД', bg=EXIT_BG, activebackground=EXIT_ACTIVE,
        relief='raised', bd=3, command=self.exit_app, cursor='hand2')

    self.refresh_menu_state()
    self.apply_current_layout()


def _fixed57_apply_menu_layout(self):
    width = max(self.root.winfo_width(), 1100)
    height = max(self.root.winfo_height(), 760)
    scale = min(width / BASE_W, height / BASE_H)
    scale = max(0.72, min(scale, 1.35))
    self._apply_common_shell_layout(width, height, scale)

    panel_pad_x = int(16 * scale)
    panel_pad_y = int(10 * scale)
    button_gap = int(14 * scale)
    self.title_small.configure(font=("Times New Roman", max(20, int(28 * scale)), "bold"))
    self.title_big.configure(font=("Times New Roman", max(24, int(34 * scale)), "bold"))
    self.body.configure(font=("Arial", max(11, int(14 * scale)), "bold"), wraplength=int(width * 0.46))

    self.menu_panel.grid_configure(pady=(0, int(14 * scale)))
    self.menu_btn_frame.grid_configure(pady=(0, int(8 * scale)))
    for col in range(5):
        self.menu_btn_frame.grid_columnconfigure(col, weight=1, uniform='menu_buttons')

    title_size = max(14, int(20 * scale))
    status_size = max(11, int(14 * scale))
    menu_button_font_size = max(11, int(16 * scale))
    menu_result_font_size = max(10, int(14 * scale))
    card_wrap = max(220, int(width * 0.18))

    self.menu_title.configure(font=("Arial", title_size, "bold"))
    self.menu_status_label.configure(font=("Arial", status_size, "bold"), wraplength=int(width * 0.52))
    self.menu_title.grid_configure(padx=panel_pad_x, pady=(panel_pad_y, int(5 * scale)))
    self.menu_status_label.grid_configure(padx=panel_pad_x, pady=(0, int(8 * scale)))
    self.tests_grid.grid_configure(padx=panel_pad_x, pady=(0, panel_pad_y))

    for idx, code in enumerate(TEST_ORDER):
        card = self.menu_cards[code]
        card.grid_configure(
            padx=(0 if idx % 2 == 0 else int(8 * scale), 0),
            pady=(0 if idx < 2 else int(8 * scale), 0),
            ipadx=int(6 * scale),
            ipady=int(6 * scale),
        )
        btn = self.menu_buttons[code]
        res_btn = self.menu_result_buttons[code]
        btn.configure(font=("Arial", menu_button_font_size, "bold"), width=max(18, int(22 * scale)), height=max(3, int(4 * scale * 0.8)), wraplength=card_wrap)
        res_btn.configure(font=("Arial", menu_result_font_size, "bold"), width=max(18, int(22 * scale)), height=max(2, int(3 * scale * 0.8)), wraplength=card_wrap)
        btn.grid_configure(padx=int(6 * scale), pady=(int(6 * scale), int(4 * scale)), sticky='nsew')
        res_btn.grid_configure(padx=int(6 * scale), pady=(0, int(6 * scale)), sticky='ew')

    common = dict(font=("Arial", max(12, int(16 * scale)), "bold"), padx=max(10, int(12 * scale)), pady=max(8, int(10 * scale)), justify='center', anchor='center')
    self.settings_btn.configure(width=max(12, int(16 * scale)), **common)
    self.all_results_btn.configure(width=max(14, int(18 * scale)), **common)
    self.continue_btn.configure(width=max(14, int(18 * scale)), **common)
    self.restart_btn.configure(width=max(16, int(18 * scale)), **common)
    self.exit_btn.configure(width=max(10, int(12 * scale)), **common)

    self.settings_btn.grid(row=0, column=0, sticky='ew', padx=(0, button_gap))
    self.all_results_btn.grid(row=0, column=1, sticky='ew', padx=(0, button_gap))
    self.continue_btn.grid(row=0, column=2, sticky='ew', padx=(0, button_gap))
    self.restart_btn.grid(row=0, column=3, sticky='ew', padx=(0, button_gap))
    self.exit_btn.grid(row=0, column=4, sticky='ew')


def _fixed57_refresh_menu_state(self):
    if not self.current_profile:
        return
    progress = self.progress_store.ensure_user(self.current_profile)
    completed = progress.get('completed_tests', [])
    next_code = self.progress_store.next_test_code(self.current_profile)
    researcher = bool(getattr(self, 'researcher_mode_enabled', False))
    completed_text = ', '.join(TEST_LABELS[c] for c in completed) if completed else 'пока нет'

    self.menu_intro_var.set(_fixed57_menu_intro_text_researcher(self) if researcher else _fixed57_menu_intro_text_normal(self))
    self.menu_status_var.set(
        f"Пройдено: {completed_text}.\n"
        + (f"Следующий неполный тест: {TEST_LABELS[next_code] if next_code else 'все методики уже завершены'}." if researcher else (f"Следующий доступный тест: {TEST_LABELS[next_code]}" if next_code else "Все тесты пройдены. Можно начать сначала."))
    )

    for code, btn in self.menu_buttons.items():
        if researcher:
            if code in completed:
                text = f"{TEST_LABELS[code]}\n{TEST_DESCRIPTIONS[code]}\n(можно запустить снова)"
                btn.configure(state=tk.NORMAL, text=text, bg='#d8f0d7', activebackground='#c7e7c6', fg='#102744', relief='raised')
            else:
                btn.configure(state=tk.NORMAL, text=menu_card_text(code), bg=NEXT_BG if code == next_code else MENU_BG, activebackground=NEXT_ACTIVE if code == next_code else MENU_ACTIVE, fg='#111111', relief='raised')
        else:
            if code in completed:
                btn.configure(state=tk.DISABLED, text=menu_card_text(code, "done"), bg="#bfc7ba", activebackground="#bfc7ba", disabledforeground="#4a5b47", relief="sunken")
            elif code == next_code:
                btn.configure(state=tk.NORMAL, text=menu_card_text(code), bg=NEXT_BG, activebackground=NEXT_ACTIVE, fg="#111111", relief="raised")
            else:
                btn.configure(state=tk.DISABLED, text=menu_card_text(code, "locked"), bg=MENU_DISABLED, activebackground=MENU_DISABLED, disabledforeground="#6d6955", relief="ridge")

    for code, btn in getattr(self, 'menu_result_buttons', {}).items():
        has_payload = bool(self.progress_store.get_test_result(self.current_profile, code))
        if has_payload:
            btn.configure(state=tk.NORMAL, text='ПОКАЗАТЬ\nРЕЗУЛЬТАТЫ', bg='#6b7dff', activebackground='#5b6de8', fg='white', relief='raised')
        else:
            btn.configure(state=tk.DISABLED, text='РЕЗУЛЬТАТОВ\nПОКА НЕТ', bg='#d6dbe5', activebackground='#d6dbe5', disabledforeground='#7f8897', relief='flat')

    if next_code:
        self.continue_btn.configure(state=tk.NORMAL, text='СЛЕДУЮЩИЙ ТЕСТ', bg=NEXT_BG, activebackground=NEXT_ACTIVE, fg='#111111')
    else:
        if researcher:
            self.continue_btn.configure(state=tk.NORMAL, text='ОБЩИЙ ПРОФИЛЬ СПР', bg='#4f78ff', activebackground='#4269e0', fg='white')
        else:
            self.continue_btn.configure(state=tk.DISABLED, text='ПРОДОЛЖИТЬ', bg=NEXT_BG, activebackground=NEXT_ACTIVE, fg='#111111')

    self.settings_btn.configure(state=tk.NORMAL)
    self.restart_btn.configure(state=tk.NORMAL)
    self.exit_btn.configure(state=tk.NORMAL)
    self.all_results_btn.configure(state=tk.NORMAL if researcher else tk.DISABLED)

    # Применяем сеточную раскладку без вызова старых pack-патчей.
    if getattr(self, 'view_mode', '') == 'menu':
        self.apply_menu_layout()


