def _fixed57_normalize_method_a_cfg(cfg: MethodAConfig) -> MethodAConfig:
    try:
        if float(getattr(cfg, 'work_roll_deg', 0.0)) < float(getattr(cfg, 'target_roll_deg', 5.0)) + 6.0:
            cfg.work_roll_deg = float(getattr(cfg, 'target_roll_deg', 5.0)) + 12.0
        if float(getattr(cfg, 'start_speed_z_deg_s', 0.0)) > 8.0:
            cfg.start_speed_z_deg_s = 6.0
        if float(getattr(cfg, 'step_speed_z_deg_s', 0.0)) > 1.5:
            cfg.step_speed_z_deg_s = 1.0
        if float(getattr(cfg, 'roll_step_per_wheel_notch_deg', 0.0)) > 2.5:
            cfg.roll_step_per_wheel_notch_deg = 2.0
    except Exception:
        pass
    return cfg


