# ====== FIXED58: Method A red roll guides by target threshold, error after 3s, 90° only as real rollover ======

def _fixed58_roll_target_threshold(self):
    try:
        return max(1.0, float(getattr(self.cfg, 'target_roll_deg', 5.0)))
    except Exception:
        return 5.0


def _fixed58_roll_warning_exceeded(self, state: DriftState, stage_no: int) -> bool:
    if not self.stage_defs[stage_no].get('z'):
        return False
    return abs(float(getattr(state, 'roll_deg', 0.0))) > _fixed58_roll_target_threshold(self)


def _fixed58_method_a_init_stage_state(self):
    state = _FIXED57_PREV_INIT_STAGE_STATE(self) if '_FIXED57_PREV_INIT_STAGE_STATE' in globals() else MethodAApp.init_stage_state(self)
    state.roll_over_started = None
    return state


def _fixed58_method_a_roll_limit_exceeded(self, state: DriftState, stage_no: int) -> bool:
    if not self.stage_defs[stage_no].get('z'):
        setattr(state, 'roll_over_started', None)
        return False
    over = _fixed58_roll_warning_exceeded(self, state, stage_no)
    if over:
        if getattr(state, 'roll_over_started', None) is None:
            state.roll_over_started = _fixed57_time.monotonic() if '_fixed57_time' in globals() else __import__('time').monotonic()
    else:
        state.roll_over_started = None
    return over




def _fixed58_method_a_current_error_increment(self, state: DriftState, stage_no: int, dt: float) -> float:
    stage = self.stage_defs[stage_no]
    err = 0.0
    if stage['x']:
        dx = max(0.0, abs(state.x_px) - self.target_half_px)
        err += dx / max(1.0, self.target_half_px)
    if stage['y']:
        dy = max(0.0, abs(state.y_px) - self.target_half_px)
        err += dy / max(1.0, self.target_half_px)
    # Для крена ошибка считается отдельным событием после 3 секунд превышения порога,
    # поэтому не накапливаем её постоянно в столбике ошибки.
    return err * self.cfg.error_gain * dt






def _fixed58_method_a_draw_bar(self, x: int, y: int, w: int, h: int, ratio: float, title: str, color):
    ratio = max(0.0, min(1.0, ratio))
    bar_rect = pygame.Rect(int(x), int(y), int(w), int(h))
    pygame.draw.rect(self.screen, (230, 236, 244), bar_rect, border_radius=6)
    inner = bar_rect.inflate(-4, -4)
    fill_h = int(inner.height * ratio)
    if fill_h > 0:
        fill_rect = pygame.Rect(inner.left, inner.bottom - fill_h, inner.width, fill_h)
        pygame.draw.rect(self.screen, color, fill_rect, border_radius=4)
    pygame.draw.rect(self.screen, (35, 49, 66), bar_rect, 3, border_radius=6)
    font = pygame.font.SysFont('arial', 18, bold=True)
    txt = font.render(title, True, self.cfg.text_color)
    txt_rect = txt.get_rect(midbottom=(bar_rect.centerx, bar_rect.top - 8))
    txt_rect.left = max(6, txt_rect.left)
    txt_rect.right = min(self.cfg.width - 6, txt_rect.right)
    self.screen.blit(txt, txt_rect)




def _fixed58_metric_bar(self, canvas: tk.Canvas, x1: int, y: int, x2: int, title: str, value_text: str, ratio: float, color: str):
    if title == 'Выходы из зоны':
        title = 'Ошибки'
    elif title == 'Срывы':
        title = 'Ошибки'
    return _FIXED58_PREV_METRIC_BAR(self, canvas, x1, y, x2, title, value_text, ratio, color)


def _fixed58_draw_stage_report_canvas(self, canvas: tk.Canvas, report: dict):
    canvas.delete('all')
    w = int(canvas.cget('width'))
    h = int(canvas.cget('height'))
    canvas.create_rectangle(10, 10, w - 10, h - 10, outline='#d2dbe7', width=1, fill='#f8fbff')
    stage_no = int(report.get('stage_no', 0))
    crashes = int(report.get('crashes', 0))
    stability_pct = float(report.get('stability_pct', 0.0))
    mean_xy = float(report.get('mean_abs_xy_cm', 0.0))
    peak_xy = float(report.get('peak_abs_xy_cm', 0.0))
    mean_roll = float(report.get('mean_abs_roll_deg', 0.0))
    score = self.stage_visual_score(report)
    status_text, status_color = self.score_caption(score)
    cx, cy, r = 88, 88, 46
    canvas.create_oval(cx - r, cy - r, cx + r, cy + r, fill='#edf3fb', outline='')
    canvas.create_arc(cx - r, cy - r, cx + r, cy + r, start=90, extent=-360 * score / 100, style='arc', width=12, outline=status_color)
    canvas.create_text(cx, cy - 8, text=str(score), fill='#102744', font=('Arial', 24, 'bold'))
    canvas.create_text(cx, cy + 18, text='баллов', fill='#627286', font=('Arial', 10, 'bold'))
    text_x = 158
    text_w = max(150, w - text_x - 24)
    canvas.create_text(text_x, 36, anchor='nw', text=f'Этап {stage_no}', fill='#102744', font=('Arial', 16, 'bold'), width=text_w)
    canvas.create_text(text_x, 66, anchor='nw', text=f"Контролируемые оси: {report.get('active_axes', '')}", fill='#536275', font=('Arial', 10, 'bold'), width=text_w)
    canvas.create_text(text_x, 90, anchor='nw', text=f'Оценка: {status_text}', fill=status_color, font=('Arial', 11, 'bold'), width=text_w)
    x1 = 28
    x2 = w - 28
    base_y = 150
    self.metric_bar(canvas, x1, base_y, x2, 'Удержание в зелёной зоне', f'{stability_pct:.0f}% времени', stability_pct / 100.0, '#67a9ff')
    self.metric_bar(canvas, x1, base_y + 42, x2, 'Ошибки', f'{crashes} из 3 возможных', min(1.0, crashes / 3.0), '#e26565')
    self.metric_bar(canvas, x1, base_y + 84, x2, 'Среднее отклонение X/Y', f'в среднем {mean_xy:.2f} см', max(0.0, 1.0 - mean_xy / 18.0), '#ffb35c')
    if stage_no == 3:
        self.metric_bar(canvas, x1, base_y + 126, x2, 'Среднее отклонение по крену', f'в среднем {mean_roll:.1f}°', max(0.0, 1.0 - mean_roll / 90.0), '#c98cff')
    else:
        self.metric_bar(canvas, x1, base_y + 126, x2, 'Максимальное отклонение X/Y', f'до {peak_xy:.2f} см', max(0.0, 1.0 - peak_xy / 18.0), '#8dc0ff')






def _fixed58_normalize_method_a_cfg(cfg: MethodAConfig) -> MethodAConfig:
    cfg = _fixed57_normalize_method_a_cfg(cfg) if '_fixed57_normalize_method_a_cfg' in globals() else cfg
    try:
        if float(getattr(cfg, 'target_roll_deg', 0.0)) < 8.0:
            cfg.target_roll_deg = 10.0
        # 90° считаем именно реальным срывом, а не рабочим порогом.
        cfg.work_roll_deg = 90.0
        if float(getattr(cfg, 'roll_step_per_wheel_notch_deg', 0.0)) > 2.5:
            cfg.roll_step_per_wheel_notch_deg = 2.0
    except Exception:
        pass
    return cfg


def _fixed58_load_config(path: str | Path = 'method_a_config.json', screen_w: int | None = None, screen_h: int | None = None) -> MethodAConfig:
    cfg = _FIXED54_PREV_LOAD_CONFIG(path, screen_w, screen_h) if '_FIXED54_PREV_LOAD_CONFIG' in globals() else globals()['load_config'](path, screen_w, screen_h)
    return _fixed58_normalize_method_a_cfg(cfg)




