def _fixed72_make_help_button(parent, instruction_text: str, bg: str = UNIFORM_TEST_BG):
    btn = tk.Label(
        parent,
        text='?',
        bg='#ffffff',
        fg=UNIFORM_TEST_FG,
        font=('Arial', 30, 'bold'),
        width=3,
        height=1,
        relief='solid',
        bd=2,
        cursor='question_arrow',
        padx=8,
        pady=4,
    )
    _Fixed42HoverTip(btn, instruction_text)
    return btn


def _fixed72_create_bar(parent, label_text: str, bg: str, width: int = 280):
    if label_text.strip().lower() == 'задание':
        label_text = 'Прогресс выполнения'
    wrap = tk.Frame(parent, bg=bg)
    tk.Label(
        wrap,
        text=label_text,
        bg=bg,
        fg=UNIFORM_TEST_FG,
        font=('Arial', 13, 'bold'),
        anchor='center',
        justify='center',
    ).pack(fill='x', pady=(0, 4))
    canvas = tk.Canvas(wrap, width=max(width, 340), height=22, bg=bg, highlightthickness=0, bd=0)
    canvas.pack(fill='x', expand=True, pady=(2, 0))
    return wrap, canvas


def _fixed72_set_bar(canvas: tk.Canvas, ratio: float, fill: str):
    ratio = max(0.0, min(1.0, float(ratio)))
    try:
        width = max(60, int(canvas.winfo_width()))
        if width <= 1:
            width = int(canvas.cget('width'))
    except Exception:
        width = int(canvas.cget('width'))
    try:
        height = max(18, int(canvas.winfo_height()))
        if height <= 1:
            height = int(canvas.cget('height'))
    except Exception:
        height = int(canvas.cget('height'))
    canvas.delete('all')
    outer = 2
    canvas.create_rectangle(outer, outer, width - outer, height - outer, outline='#a99f87', fill='#fbf8ee', width=2)
    fill_w = int((width - outer * 2) * ratio)
    if fill_w > 0:
        canvas.create_rectangle(outer, outer, outer + fill_w, height - outer, outline='', fill=fill)


_fixed42_make_help_button = _fixed72_make_help_button
