def _fixed73d_populate_researcher_fields(self):
    for child in self.research_content.winfo_children():
        child.destroy()
    self.research_widgets = {}
    self.research_sections = {}

    self.research_content.grid_columnconfigure(0, weight=1)

    self.research_tabs = ttk.Notebook(self.research_content)
    self.research_tabs.grid(row=0, column=0, sticky='nsew', padx=10, pady=10)

    for code, title, cls, filename in RESEARCH_CONFIG_SPECS:
        tab = tk.Frame(self.research_tabs, bg=BG_COLOR)
        tab.grid_columnconfigure(0, weight=1)
        self.research_tabs.add(tab, text=f'Тест {code}')

        intro = tk.Label(
            tab,
            text=title,
            bg=BG_COLOR,
            fg=TITLE_COLOR,
            anchor='center',
            justify='center',
        )
        intro.grid(row=0, column=0, sticky='ew', padx=10, pady=(8, 10))

        cfg = _fixed73d_load_cfg(self, cls, filename)
        widgets = {}
        section_frames = []
        section_groups = _get_research_section_groups(code, cls)

        for section_index, (section_title, field_names) in enumerate(section_groups, start=1):
            section = tk.LabelFrame(
                tab,
                text=section_title,
                bg=PANEL_COLOR,
                fg=TITLE_COLOR,
                bd=2,
                relief='groove',
                padx=10,
                pady=8,
            )
            section.grid(row=section_index, column=0, sticky='ew', padx=10, pady=6)
            section.grid_columnconfigure(0, weight=0, minsize=300)
            section.grid_columnconfigure(1, weight=1)
            section_frames.append(section)

            row = 0
            for field_name in field_names:
                fld = next((item for item in fields(cls) if item.name == field_name), None)
                if fld is None:
                    continue
                meta = _get_research_field_meta(code, fld.name)
                default_value = getattr(cfg, fld.name)

                label_box = tk.Frame(section, bg=PANEL_COLOR)
                label_box.grid(row=row, column=0, sticky='nw', padx=(8, 16), pady=6)

                label = tk.Label(
                    label_box,
                    text=meta.get('label', fld.name),
                    bg=PANEL_COLOR,
                    fg=TITLE_COLOR,
                    anchor='w',
                    justify='left',
                    font=('Segoe UI', 10, 'bold'),
                    wraplength=280,
                )
                label.pack(anchor='w')

                help_text = meta.get('help', '')
                if help_text:
                    help_label = tk.Label(
                        label_box,
                        text=help_text,
                        bg=PANEL_COLOR,
                        fg='#5a5a5a',
                        anchor='w',
                        justify='left',
                        wraplength=280,
                    )
                    help_label.pack(anchor='w', pady=(2, 0))

                template_value = getattr(cls(), fld.name)
                is_bool_field = isinstance(template_value, bool)
                serialized = _serialize_config_value(default_value)
                is_multiline = (not is_bool_field) and (isinstance(default_value, (list, dict, tuple)) or len(serialized) > 52)

                widget_box = tk.Frame(section, bg=PANEL_COLOR)
                widget_box.grid(row=row, column=1, sticky='ew', padx=(0, 8), pady=6)
                widget_box.grid_columnconfigure(0, weight=1)

                bool_var = None
                if is_bool_field:
                    bool_var = tk.BooleanVar(value=_fixed275_to_bool(default_value))
                    bool_text_var = tk.StringVar()
                    def _sync_bool_caption(*_args, _var=bool_var, _text_var=bool_text_var):
                        _text_var.set('Включено' if bool(_var.get()) else 'Выключено')
                    _sync_bool_caption()
                    bool_var.trace_add('write', _sync_bool_caption)
                    widget = tk.Checkbutton(
                        widget_box,
                        textvariable=bool_text_var,
                        variable=bool_var,
                        onvalue=True,
                        offvalue=False,
                        bg=PANEL_COLOR,
                        activebackground=PANEL_COLOR,
                        fg=TITLE_COLOR,
                        selectcolor=FIELD_BG,
                        anchor='w',
                        justify='left',
                        font=('Segoe UI', 13, 'bold'),
                        indicatoron=False,
                        relief='raised',
                        padx=10,
                        pady=6,
                        width=12,
                        bd=2,
                        highlightthickness=0,
                    )
                    widget.grid(row=0, column=0, sticky='w')
                elif is_multiline:
                    widget = tk.Text(widget_box, height=max(3, min(6, serialized.count('\n') + 2)), wrap='word', bg=FIELD_BG, relief='sunken', bd=1)
                    widget.insert('1.0', serialized)
                    widget.grid(row=0, column=0, sticky='ew')
                else:
                    widget = tk.Entry(widget_box, bg=FIELD_BG)
                    widget.insert(0, serialized)
                    widget.grid(row=0, column=0, sticky='ew', ipady=4)

                if not is_bool_field:
                    default_hint = tk.Label(
                        widget_box,
                        text=f'По умолчанию: {serialized}',
                        bg=PANEL_COLOR,
                        fg='#6b7280',
                        anchor='w',
                        justify='left',
                        wraplength=620,
                    )
                    default_hint.grid(row=1, column=0, sticky='w', pady=(3, 0))

                widgets[fld.name] = {
                    'widget': widget,
                    'template': template_value,
                    'is_multiline': is_multiline,
                    'is_bool': is_bool_field,
                    'bool_var': bool_var,
                }
                row += 1

        self.research_widgets[code] = widgets
        self.research_sections[code] = section_frames

    self._on_research_canvas_configure()
    self._on_research_content_configure()


def _fixed73d_apply_researcher_layout(self):
    width = max(self.root.winfo_width(), 1100)
    height = max(self.root.winfo_height(), 760)
    scale = max(0.75, min(min(width / BASE_W, height / BASE_H), 1.25))

    pad_x = int(18 * scale)
    pad_y = int(14 * scale)
    gap = int(10 * scale)

    try:
        self.main.pack_configure(padx=pad_x, pady=pad_y)
    except Exception:
        pass

    self.research_header.grid_configure(pady=(0, int(8 * scale)))
    self.research_subtitle.grid_configure(pady=(0, int(8 * scale)))
    self.research_actions_top.grid_configure(pady=(0, int(8 * scale)))
    self.research_status.grid_configure(pady=(0, int(8 * scale)))

    self.research_title.configure(font=('Times New Roman', max(22, int(34 * scale)), 'bold'))
    self.research_subtitle.configure(font=('Arial', max(11, int(14 * scale)), 'bold'), wraplength=int(width * 0.82))
    self.research_status.configure(font=('Arial', max(11, int(13 * scale)), 'bold'), wraplength=int(width * 0.82))

    btn_font = ('Arial', max(11, int(14 * scale)), 'bold')
    for col, btn in enumerate([self.research_exit_btn, self.research_default_btn, self.research_all_results_btn, self.research_next_btn]):
        btn.configure(font=btn_font)
        btn.grid_configure(padx=(0, gap) if col < 3 else (0, 0), pady=0)

    for code, section_list in self.research_sections.items():
        for section in section_list:
            try:
                section.configure(font=('Arial', max(11, int(14 * scale)), 'bold'))
            except Exception:
                pass
            section.grid_columnconfigure(0, minsize=int(width * 0.24))
            for child in section.winfo_children():
                if isinstance(child, tk.Frame):
                    for nested in child.winfo_children():
                        if isinstance(nested, tk.Label):
                            is_title = 'bold' in str(nested.cget('font')).lower() or str(nested.cget('fg')) == TITLE_COLOR
                            nested.configure(font=('Arial', max(10, int(12 * scale)), 'bold' if is_title else 'normal'))
                        elif isinstance(nested, tk.Checkbutton):
                            nested.configure(
                                font=('Arial', max(12, int(15 * scale)), 'bold'),
                                padx=max(8, int(10 * scale)),
                                pady=max(4, int(6 * scale)),
                            )
                elif isinstance(child, tk.Entry):
                    child.configure(font=('Consolas', max(10, int(12 * scale))))
                elif isinstance(child, tk.Text):
                    child.configure(font=('Consolas', max(10, int(11 * scale))))
                elif isinstance(child, tk.Label):
                    child.configure(font=('Arial', max(9, int(11 * scale))), wraplength=int(width * 0.44))

    self._on_research_canvas_configure()
    self._on_research_content_configure()


def _fixed73d_apply_researcher_and_open_login(self):
    try:
        configs = self.collect_researcher_configs()
        for filename, cfg in configs:
            save_config_dataclass(self.base_dir, filename, cfg)
    except ValueError as exc:
        if getattr(self, 'research_status_var', None) is not None:
            self.research_status_var.set(str(exc))
        messagebox.showerror('Некорректные параметры', str(exc))
        return

    logged_in = getattr(self, 'current_profile', None) is not None and getattr(self, 'current_session', None) is not None
    if logged_in:
        if getattr(self, 'research_status_var', None) is not None:
            self.research_status_var.set('Параметры сохранены. Возвращаемся в главное меню.')
        self.build_menu_ui()
        try:
            self.refresh_menu_state()
        except Exception:
            pass
    else:
        if getattr(self, 'research_status_var', None) is not None:
            self.research_status_var.set('Параметры сохранены. Открывается регистрационная форма.')
        self.build_start_ui()


def _fixed73d_build_start_ui(self):
    self.view_mode = 'start'
    self.destroy_main()
    self.build_base_shell()

    text = (
        'Комплекс предназначен для оценки психической работоспособности.\n\n'
        'Перед началом заполните регистрационную форму, затем нажмите «ДАЛЕЕ».'
    )

    self.body = tk.Label(
        self.right,
        text=text,
        bg=BG_COLOR,
        fg=TEXT_COLOR,
        justify='left',
        anchor='nw',
    )
    self.body.grid(row=2, column=0, sticky='nsew')

    self.form_frame = tk.Frame(self.right, bg=PANEL_COLOR, bd=2, relief='groove')
    self.form_frame.grid(row=3, column=0, sticky='ew')
    self.form_frame.grid_columnconfigure(1, weight=1)

    self.form_title = tk.Label(self.form_frame, text='Регистрационная форма', bg=PANEL_COLOR, fg=TITLE_COLOR)
    self.form_title.grid(row=0, column=0, columnspan=2, sticky='w', padx=16, pady=(14, 6))

    self.name_label = tk.Label(self.form_frame, text='Имя:', bg=PANEL_COLOR, fg=TEXT_COLOR)
    self.name_label.grid(row=1, column=0, sticky='w', padx=16, pady=6)
    self.name_entry = tk.Entry(self.form_frame, textvariable=self.name_var, bg=FIELD_BG)
    self.name_entry.grid(row=1, column=1, sticky='ew', padx=(0, 16), pady=6, ipady=4)

    self.age_label = tk.Label(self.form_frame, text='Возраст (полных лет):', bg=PANEL_COLOR, fg=TEXT_COLOR)
    self.age_label.grid(row=2, column=0, sticky='w', padx=16, pady=6)
    self.age_entry = tk.Entry(self.form_frame, textvariable=self.age_var, bg=FIELD_BG)
    self.age_entry.grid(row=2, column=1, sticky='ew', padx=(0, 16), pady=6, ipady=4)

    self.gender_label = tk.Label(self.form_frame, text='Пол:', bg=PANEL_COLOR, fg=TEXT_COLOR)
    self.gender_label.grid(row=3, column=0, sticky='nw', padx=16, pady=6)
    self.gender_frame = tk.Frame(self.form_frame, bg=PANEL_COLOR)
    self.gender_frame.grid(row=3, column=1, sticky='w', padx=(0, 16), pady=6)

    self.gender_male = tk.Radiobutton(self.gender_frame, text='Мужской', variable=self.gender_var, value='Мужской', bg=PANEL_COLOR, activebackground=PANEL_COLOR, highlightthickness=0, anchor='w')
    self.gender_male.pack(side='left', padx=(0, 16))
    self.gender_female = tk.Radiobutton(self.gender_frame, text='Женский', variable=self.gender_var, value='Женский', bg=PANEL_COLOR, activebackground=PANEL_COLOR, highlightthickness=0, anchor='w')
    self.gender_female.pack(side='left')

    self.status_label = tk.Label(self.form_frame, textvariable=self.status_var, bg=PANEL_COLOR, fg='#245a2a', justify='left', anchor='w')
    self.status_label.grid(row=4, column=0, columnspan=2, sticky='ew', padx=16, pady=(8, 14))

    self.btn_frame = tk.Frame(self.right, bg=BG_COLOR)
    self.btn_frame.grid(row=4, column=0, sticky='ew')
    for i in range(3):
        self.btn_frame.grid_columnconfigure(i, weight=1)

    self.settings_btn = tk.Button(self.btn_frame, text='НАСТРОЙКИ', bg=BACK_BG, activebackground=BACK_ACTIVE, relief='raised', bd=3, cursor='hand2', command=self.build_researcher_ui)
    self.settings_btn.grid(row=0, column=1, sticky='ew')

    self.next_btn = tk.Button(self.btn_frame, text='ДАЛЕЕ', bg=NEXT_BG, activebackground=NEXT_ACTIVE, relief='raised', bd=3, cursor='hand2', command=self.submit_form)
    self.next_btn.grid(row=0, column=2, sticky='ew')

    self.exit_btn = tk.Button(self.btn_frame, text='ВЫХОД', bg=EXIT_BG, activebackground=EXIT_ACTIVE, relief='raised', bd=3, cursor='hand2', command=self.exit_app)
    self.exit_btn.grid(row=0, column=0, sticky='ew')

    self.name_entry.focus_set()
    self.apply_current_layout()


def _fixed73d_apply_start_layout(self):
    width = max(self.root.winfo_width(), 1100)
    height = max(self.root.winfo_height(), 760)
    scale = max(0.72, min(min(width / BASE_W, height / BASE_H), 1.25))
    self._apply_common_shell_layout(width, height, scale)

    self.title_small.configure(font=('Times New Roman', max(18, int(24 * scale)), 'bold'))
    self.title_big.configure(font=('Times New Roman', max(22, int(30 * scale)), 'bold'))
    self.body.configure(font=('Arial', max(11, int(14 * scale)), 'bold'), wraplength=int(width * 0.44), justify='left')

    self.form_title.configure(font=('Arial', max(13, int(18 * scale)), 'bold'))
    for widget in (self.name_label, self.age_label, self.gender_label, self.gender_male, self.gender_female):
        widget.configure(font=('Arial', max(11, int(14 * scale)), 'bold'))
    self.name_entry.configure(font=('Arial', max(11, int(14 * scale))))
    self.age_entry.configure(font=('Arial', max(11, int(14 * scale))))
    self.status_label.configure(font=('Arial', max(10, int(12 * scale)), 'bold'), wraplength=int(width * 0.42))

    gap = int(12 * scale)
    self.form_frame.grid_configure(pady=(0, int(14 * scale)))
    self.btn_frame.grid_configure(pady=(0, int(8 * scale)))
    btn_font = ('Arial', max(12, int(18 * scale)), 'bold')
    btn_w = max(10, int(12 * scale))
    for btn in [self.settings_btn, self.next_btn, self.exit_btn]:
        btn.configure(font=btn_font, width=btn_w)
    self.exit_btn.grid_configure(padx=(0, gap), sticky='ew')
    self.settings_btn.grid_configure(padx=(0, gap), sticky='ew')
    self.next_btn.grid_configure(padx=(0, 0), sticky='ew')


def _fixed73d_build_menu_ui(self):
    self.view_mode = 'menu'
    self.destroy_main()
    self.build_base_shell()

    self.title_small.configure(text='Меню')
    self.title_big.configure(text='ВЫБОР\nТЕСТОВ')

    self.body = tk.Label(self.right, textvariable=self.menu_intro_var, bg=BG_COLOR, fg=TEXT_COLOR, justify='left', anchor='nw')
    self.body.grid(row=2, column=0, sticky='nsew')

    self.menu_panel = tk.Frame(self.right, bg=PANEL_COLOR, bd=2, relief='groove')
    self.menu_panel.grid(row=3, column=0, sticky='ew')
    self.menu_panel.grid_columnconfigure(0, weight=1)

    self.menu_title = tk.Label(self.menu_panel, text='Доступные тесты', bg=PANEL_COLOR, fg=TITLE_COLOR, anchor='center', justify='center')
    self.menu_title.grid(row=0, column=0, sticky='ew', padx=14, pady=(12, 6))

    self.menu_status_label = tk.Label(self.menu_panel, textvariable=self.menu_status_var, bg=PANEL_COLOR, fg='#245a2a', justify='left', anchor='w')
    self.menu_status_label.grid(row=1, column=0, sticky='ew', padx=14, pady=(0, 8))

    self.tests_grid = tk.Frame(self.menu_panel, bg=PANEL_COLOR)
    self.tests_grid.grid(row=2, column=0, sticky='ew', padx=10, pady=(0, 10))
    self.tests_grid.grid_columnconfigure(0, weight=1)
    self.tests_grid.grid_columnconfigure(1, weight=1)

    self.menu_buttons = {}
    self.menu_result_buttons = {}
    self.menu_cards = {}
    for idx, code in enumerate(TEST_ORDER):
        card = tk.Frame(self.tests_grid, bg='#e8e1bf', bd=2, relief='ridge')
        card.grid(row=idx // 2, column=idx % 2, sticky='nsew', padx=8, pady=8)
        card.grid_columnconfigure(0, weight=1)
        self.menu_cards[code] = card

        btn = tk.Button(
            card,
            text=menu_card_text(code),
            bg=MENU_BG,
            activebackground=MENU_ACTIVE,
            relief='raised',
            bd=3,
            cursor='hand2',
            command=lambda c=code: self.launch_test(c),
            justify='center',
            wraplength=340,
        )
        btn.grid(row=0, column=0, sticky='nsew', padx=10, pady=(10, 6))
        self.menu_buttons[code] = btn

        result_btn = tk.Button(
            card,
            text='РЕЗУЛЬТАТОВ\nПОКА НЕТ',
            bg='#d6dbe5',
            activebackground='#d6dbe5',
            relief='flat',
            bd=1,
            cursor='hand2',
            command=lambda c=code: self.view_results(c),
            justify='center',
            wraplength=340,
        )
        result_btn.grid(row=1, column=0, sticky='ew', padx=10, pady=(0, 10))
        self.menu_result_buttons[code] = result_btn

    self.menu_btn_frame = tk.Frame(self.right, bg=BG_COLOR)
    self.menu_btn_frame.grid(row=4, column=0, sticky='ew')
    for i in range(5):
        self.menu_btn_frame.grid_columnconfigure(i, weight=1, uniform='fixed73d_menu_btn')

    self.settings_btn = tk.Button(self.menu_btn_frame, text='НАСТРОЙКИ', bg=BACK_BG, activebackground=BACK_ACTIVE, relief='raised', bd=3, cursor='hand2', command=self.build_researcher_ui)
    self.settings_btn.grid(row=0, column=1, sticky='ew')

    self.all_results_btn = tk.Button(self.menu_btn_frame, text='ВСЕ РЕЗУЛЬТАТЫ', bg='#6b7dff', activebackground='#5b6de8', fg='white', relief='raised', bd=3, cursor='hand2', command=lambda: self.show_all_results_browser())
    self.all_results_btn.grid(row=0, column=2, sticky='ew')

    self.continue_btn = tk.Button(self.menu_btn_frame, text='СЛЕДУЮЩИЙ ТЕСТ', bg=NEXT_BG, activebackground=NEXT_ACTIVE, relief='raised', bd=3, cursor='hand2', command=self.continue_next_test)
    self.continue_btn.grid(row=0, column=3, sticky='ew')

    self.restart_btn = tk.Button(self.menu_btn_frame, text='НАЧАТЬ СНАЧАЛА', bg=BACK_BG, activebackground=BACK_ACTIVE, relief='raised', bd=3, cursor='hand2', command=self.restart_progress)
    self.restart_btn.grid(row=0, column=4, sticky='ew')

    self.exit_btn = tk.Button(self.menu_btn_frame, text='ВЫХОД', bg=EXIT_BG, activebackground=EXIT_ACTIVE, relief='raised', bd=3, cursor='hand2', command=self.exit_app)
    self.exit_btn.grid(row=0, column=0, sticky='ew')

    self.refresh_menu_state()
    self.apply_current_layout()


def _fixed73d_apply_menu_layout(self):
    width = max(self.root.winfo_width(), 1100)
    height = max(self.root.winfo_height(), 760)
    scale = max(0.72, min(min(width / BASE_W, height / BASE_H), 1.08))
    self._apply_common_shell_layout(width, height, scale)

    self.title_small.configure(font=('Times New Roman', max(16, int(20 * scale)), 'bold'))
    self.title_big.configure(font=('Times New Roman', max(18, int(25 * scale)), 'bold'))
    self.body.configure(font=('Arial', max(10, int(12 * scale)), 'bold'), wraplength=int(width * 0.32), justify='left')
    self.body.grid_configure(pady=(int(6 * scale), int(8 * scale)), sticky='ew')

    self.menu_title.configure(font=('Arial', max(13, int(18 * scale)), 'bold'))
    self.menu_status_label.configure(font=('Arial', max(10, int(12 * scale)), 'bold'), wraplength=int(width * 0.42))

    self.root.update_idletasks()
    shared_card_btn_height = max(4, int(round(5 * scale)))
    shared_card_result_height = max(2, int(round(2 * scale)))
    for idx, code in enumerate(TEST_ORDER):
        card = self.menu_cards[code]
        btn = self.menu_buttons[code]
        result_btn = self.menu_result_buttons[code]
        card.grid_configure(padx=int(6 * scale), pady=int(6 * scale))
        card_w = max(260, int(card.winfo_width() or 0))
        card_wrap = max(220, card_w - max(24, int(28 * scale)))
        btn.configure(
            font=('Arial', max(10, int(13 * scale)), 'bold'),
            width=max(16, int(18 * scale)),
            height=shared_card_btn_height,
            wraplength=card_wrap,
            padx=max(6, int(8 * scale)),
            pady=max(2, int(4 * scale)),
            anchor='center',
            justify='center',
        )
        result_btn.configure(
            font=('Arial', max(9, int(11 * scale)), 'bold'),
            height=shared_card_result_height,
            wraplength=card_wrap,
            padx=max(6, int(8 * scale)),
            pady=max(2, int(3 * scale)),
            anchor='center',
            justify='center',
        )

    gap = int(10 * scale)
    btn_font = ('Arial', max(10, int(13 * scale)), 'bold')
    shared_width = max(14, int(16 * scale))
    shared_wrap = max(120, int(180 * scale))
    for btn in (self.exit_btn, self.settings_btn, self.all_results_btn, self.continue_btn, self.restart_btn):
        btn.configure(
            font=btn_font,
            width=shared_width,
            wraplength=shared_wrap,
            height=1,
            justify='center',
            anchor='center',
            padx=max(8, int(10 * scale)),
            pady=max(6, int(8 * scale)),
        )
    self.exit_btn.grid_configure(padx=(0, gap), sticky='ew')
    self.settings_btn.grid_configure(padx=(0, gap), sticky='ew')
    self.all_results_btn.grid_configure(padx=(0, gap), sticky='ew')
    self.continue_btn.grid_configure(padx=(0, gap), sticky='ew')
    self.restart_btn.grid_configure(padx=(0, 0), sticky='ew')


def _fixed73d_refresh_menu_state(self):
    if not self.current_profile:
        return
    progress = self.progress_store.ensure_user(self.current_profile)
    completed = progress.get('completed_tests', [])
    next_code = self.progress_store.next_test_code(self.current_profile)
    completed_text = ', '.join(TEST_LABELS[c] for c in completed) if completed else 'пока нет'
    researcher = bool(getattr(self, 'researcher_mode_enabled', False))

    self.menu_intro_var.set(f'Пользователь: {self.current_profile.name}, {self.current_profile.age} лет, {self.current_profile.gender}.')
    if researcher:
        next_text = f'Следующий неполный тест: {TEST_LABELS[next_code]}.' if next_code else 'Все методики уже завершены.'
    else:
        next_text = f'Следующий тест: {TEST_LABELS[next_code]}.' if next_code else 'Все тесты пройдены.'
    self.menu_status_var.set(f'Пройдено: {completed_text}.\n{next_text}')

    for code, btn in self.menu_buttons.items():
        has_result = bool(self.progress_store.get_test_result(self.current_profile, code))
        if researcher:
            if code in completed:
                repeat_text = f"{MENU_CARD_TEXT.get(code, menu_card_text(code))}\n(можно запустить снова)"
                btn.configure(state=tk.NORMAL, text=repeat_text, bg='#d8f0d7', activebackground='#c7e7c6', fg='#102744', relief='raised')
            else:
                btn.configure(state=tk.NORMAL, text=menu_card_text(code), bg=NEXT_BG if code == next_code else MENU_BG, activebackground=NEXT_ACTIVE if code == next_code else MENU_ACTIVE, fg='#111111', relief='raised')
        else:
            if code in completed:
                btn.configure(state=tk.DISABLED, text=menu_card_text(code, 'done'), bg='#bfc7ba', activebackground='#bfc7ba', disabledforeground='#4a5b47', relief='sunken')
            elif code == next_code:
                btn.configure(state=tk.NORMAL, text=menu_card_text(code), bg=NEXT_BG, activebackground=NEXT_ACTIVE, fg='#111111', relief='raised')
            else:
                btn.configure(state=tk.DISABLED, text=menu_card_text(code, 'locked'), bg=MENU_DISABLED, activebackground=MENU_DISABLED, disabledforeground='#6d6955', relief='ridge')

        result_btn = self.menu_result_buttons.get(code)
        if result_btn is not None:
            if has_result:
                result_btn.configure(state=tk.NORMAL, text='ПОКАЗАТЬ\nРЕЗУЛЬТАТ', bg='#6b7dff', activebackground='#5b6de8', fg='white', relief='raised')
            else:
                result_btn.configure(state=tk.DISABLED, text='РЕЗУЛЬТАТОВ\nПОКА НЕТ', bg='#d6dbe5', activebackground='#d6dbe5', disabledforeground='#7f8897', relief='flat')

    if next_code:
        self.continue_btn.configure(state=tk.NORMAL, text='СЛЕДУЮЩИЙ ТЕСТ', bg=NEXT_BG, activebackground=NEXT_ACTIVE, fg='#111111', relief='raised')
    else:
        self.continue_btn.configure(state=tk.NORMAL, text='ОБЩИЙ ПРОФИЛЬ СПР', bg='#4f78ff', activebackground='#4269e0', fg='white', relief='raised')

    if getattr(self, 'all_results_btn', None) is not None and self.all_results_btn.winfo_exists():
        self.all_results_btn.configure(state=tk.NORMAL)


StartPageApp.apply_researcher_layout = _fixed73d_apply_researcher_layout
StartPageApp.apply_researcher_and_open_login = _fixed73d_apply_researcher_and_open_login
StartPageApp.build_start_ui = _fixed73d_build_start_ui
StartPageApp.build_menu_ui = _fixed73d_build_menu_ui
StartPageApp.refresh_menu_state = _fixed73d_refresh_menu_state



# === FIXED73E: математика теста A по документу «Обработка данных в задаче Слежение» ===


def _fixed73e_clip(value, lo, hi):
    try:
        value = float(value)
    except Exception:
        value = lo
    return max(float(lo), min(float(hi), value))


def _fixed73e_stage_name(stage_no: int) -> str:
    return {1: 'X', 2: 'X+Y', 3: 'X+Y+крен'}.get(int(stage_no or 0), f'Этап {stage_no}')








def _fixed73e_stage_report_to_dict(self) -> dict:
    data = asdict(self)
    for key, value in self.__dict__.items():
        if key not in data:
            data[key] = value
    return data




def _fixed73e_log_stage_report(self, report: StageReport):
    self.logger.log_event(
        self.session,
        event_type='stage_report',
        screen='method_a',
        test_name='method_a_stage',
        stage=str(report.stage_no),
        action='stage_end',
        elapsed_ms=int(float(report.real_time_s) * 1000),
        x=round(float(getattr(report, 'v_avg', 0.0)), 4),
        y=round(float(getattr(report, 'avg_tracking_error', 0.0)), 4),
        angle=round(float(getattr(report, 'reduced_tempo_tr', 0.0)), 4),
        value=int(report.crashes),
        note=(
            f"axes={report.active_axes}; gamma={float(getattr(report, 'success_gamma', 0.0)):.4f}; "
            f"h={float(getattr(report, 'entropy_h', 0.0)):.4f}; tr={float(getattr(report, 'reduced_tempo_tr', 0.0)):.4f}"
        ),
    )




def _fixed73e_method_a_summary_from_reports(reports: list[dict]) -> dict:
    reports = [r for r in (reports or []) if isinstance(r, dict)]
    total_time_s = round(sum(float(r.get('real_time_s', 0.0) or 0.0) for r in reports), 2)
    total_crashes = int(sum(int(r.get('crashes', 0) or 0) for r in reports))
    avg_stability_pct = round(sum(float(r.get('stability_pct', 0.0) or 0.0) for r in reports) / max(1, len(reports)), 1) if reports else 0.0
    avg_mean_xy_cm = round(sum(float(r.get('mean_abs_xy_cm', 0.0) or 0.0) for r in reports) / max(1, len(reports)), 2) if reports else 0.0
    avg_v_avg = round(sum(float(r.get('v_avg', 0.0) or 0.0) for r in reports) / max(1, len(reports)), 4) if reports else 0.0
    avg_entropy_h = round(sum(float(r.get('entropy_h', 0.0) or 0.0) for r in reports) / max(1, len(reports)), 4) if reports else 0.0
    avg_success_gamma = round(sum(float(r.get('success_gamma', 0.0) or 0.0) for r in reports) / max(1, len(reports)), 4) if reports else 0.0
    avg_tracking_error = round(sum(float(r.get('avg_tracking_error', 0.0) or 0.0) for r in reports) / max(1, len(reports)), 4) if reports else 0.0
    avg_reduced_tempo_tr = round(sum(float(r.get('reduced_tempo_tr', 0.0) or 0.0) for r in reports) / max(1, len(reports)), 4) if reports else 0.0

    by_stage = {int(r.get('stage_no', 0) or 0): r for r in reports}
    t_values = {
        'min': round(float(by_stage.get(1, {}).get('reduced_tempo_tr', 0.0) or 0.0), 4),
        'medio': round(float(by_stage.get(2, {}).get('reduced_tempo_tr', 0.0) or 0.0), 4),
        'max': round(float(by_stage.get(3, {}).get('reduced_tempo_tr', 0.0) or 0.0), 4),
    }

    best_stage = None
    if reports:
        best = max(
            reports,
            key=lambda r: (
                float(r.get('reduced_tempo_tr', 0.0) or 0.0),
                float(r.get('success_gamma', 0.0) or 0.0),
                -int(r.get('crashes', 0) or 0),
                -float(r.get('avg_tracking_error', 0.0) or 0.0),
            ),
        )
        try:
            best_stage = int(best.get('stage_no', 0) or 0)
        except Exception:
            best_stage = None

    return {
        'total_time_s': total_time_s,
        'total_crashes': total_crashes,
        'avg_stability_pct': avg_stability_pct,
        'avg_mean_xy_cm': avg_mean_xy_cm,
        'avg_v_avg': avg_v_avg,
        'avg_entropy_h': avg_entropy_h,
        'avg_success_gamma': avg_success_gamma,
        'avg_tracking_error': avg_tracking_error,
        'avg_reduced_tempo_tr': avg_reduced_tempo_tr,
        'best_stage': best_stage,
        't_values': t_values,
        'tmin_a': t_values['min'],
        'tmedio_a': t_values['medio'],
        'tmax_a': t_values['max'],
    }


def _fixed73e_build_method_a_payload(self, session: SessionInfo, result: dict) -> dict:
    reports = [r for r in (result.get('reports', []) or []) if isinstance(r, dict)]
    summary = _fixed73e_method_a_summary_from_reports(reports)
    return {
        'test_code': 'A',
        'test_label': TEST_LABELS['A'],
        'completed_at': datetime.now().isoformat(timespec='seconds'),
        'session_id': session.session_id,
        'participant': {
            'name': session.name,
            'age': session.age,
            'gender': session.gender,
        },
        'result_path': result.get('result_path', ''),
        'reports': reports,
        'summary': summary,
    }


def _fixed73e_enrich_payload_for_storage(self, test_code: str, payload: dict) -> dict:
    normalized = dict(payload) if isinstance(payload, dict) else {}
    if test_code != 'A':
        return _FIXED73E_PREV_ENRICH_PAYLOAD(self, test_code, payload)

    reports = self._load_method_a_reports(normalized)
    normalized['reports'] = reports
    summary = normalized.get('summary', {})
    if not isinstance(summary, dict):
        summary = {}
    if reports:
        computed = _fixed73e_method_a_summary_from_reports(reports)
        for key, value in computed.items():
            if key == 't_values':
                if not isinstance(summary.get('t_values'), dict) or not summary.get('t_values'):
                    summary['t_values'] = value
                else:
                    merged = dict(value)
                    merged.update(summary.get('t_values', {}))
                    summary['t_values'] = merged
            elif key not in summary or summary.get(key) in (None, '', 0, 0.0):
                summary[key] = value
    normalized['summary'] = summary
    return normalized


def _fixed73e_method_a_stage_metric_rows(report: dict) -> list[tuple[str, str]]:
    stage_no = int(report.get('stage_no', 0) or 0)
    if stage_no == 3:
        v_label = 'Vср'
        v_value = f"{float(report.get('v_avg', 0.0) or 0.0):.4f} усл. ед./с"
        e_value = f"{float(report.get('avg_tracking_error', 0.0) or 0.0):.4f} норм. ед."
        bounds_value = 'цель = 0.0000, авария = 1.0000'
    else:
        v_label = 'Vср'
        v_value = f"{float(report.get('v_avg', 0.0) or 0.0):.4f} см/с"
        e_value = f"{float(report.get('avg_tracking_error', 0.0) or 0.0):.4f} см"
        bounds_value = (
            f"цель = {float(report.get('tracking_error_target', 0.0) or 0.0):.2f} см, "
            f"авария = {float(report.get('tracking_error_crash', 0.0) or 0.0):.2f} см"
        )


    rows = [
        ('Режим', _fixed73e_stage_name(stage_no)),
        ('Контролируемые оси', str(report.get('active_axes', ''))),
        ('Длительность', f"{float(report.get('real_time_s', 0.0) or 0.0):.1f} с"),
        ('Ошибки', f"{int(report.get('crashes', 0) or 0)} из 3"),
        (v_label, v_value),
        ('γ', f"{float(report.get('success_gamma', 0.0) or 0.0):.4f}"),
        ('Энтропия H', f"{float(report.get('entropy_h', 0.0) or 0.0):.4f}"),
        ('Yтек. ср.', e_value),
        ('tр = Vср × γ', f"{float(report.get('reduced_tempo_tr', 0.0) or 0.0):.4f}"),
        ('Границы расчёта ошибки', bounds_value),
    ]
    if stage_no == 3:
        rows.append(('Средний крен', f"{float(report.get('mean_abs_roll_deg', 0.0) or 0.0):.2f}°"))
    else:
        rows.append(('Среднее отклонение X/Y', f"{float(report.get('mean_abs_xy_cm', 0.0) or 0.0):.2f} см"))
    return rows


def _fixed73e_show_method_a_results(self, payload: dict):
    top, outer = _open_results_top(self, 'Результаты - Тест А. Слежение за объектом')
    participant = payload.get('participant', {})
    reports = payload.get('reports', [])
    if not reports:
        result_path = payload.get('result_path', '')
        if result_path:
            try:
                rp = Path(result_path)
                if not rp.is_absolute():
                    rp = self.base_dir / rp
                if rp.exists():
                    loaded = json.loads(rp.read_text(encoding='utf-8'))
                    if isinstance(loaded, list):
                        reports = [item for item in loaded if isinstance(item, dict)]
            except Exception:
                reports = []
    summary = dict(payload.get('summary', {}) or {})
    if reports:
        computed = _fixed73e_method_a_summary_from_reports(reports)
        for key, value in computed.items():
            if key == 't_values':
                merged = dict(value)
                merged.update(summary.get('t_values', {}) if isinstance(summary.get('t_values'), dict) else {})
                summary['t_values'] = merged
            else:
                summary.setdefault(key, value)
    t_values = summary.get('t_values', {}) if isinstance(summary.get('t_values'), dict) else {}

    completed_at = payload.get('completed_at', '')
    dt_label = completed_at.replace('T', ' ')[:19] if completed_at else 'не указано'

    header = tk.Frame(outer, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec')
    header.pack(fill='x', padx=24, pady=(24, 12))
    tk.Frame(header, bg='#67a9ff', height=8).pack(fill='x')
    head_body = tk.Frame(header, bg='#ffffff')
    head_body.pack(fill='both', expand=True, padx=22, pady=18)
    tk.Label(head_body, text='Тест А · Слежение за объектом', bg='#ffffff', fg='#102744', font=('Arial', 28, 'bold')).pack(anchor='w')
    subtitle = f"{participant.get('name', '')}, {participant.get('age', '')} лет, {participant.get('gender', '')}. Последнее завершение: {dt_label}."
    tk.Label(head_body, text=subtitle, bg='#ffffff', fg='#5a6678', font=('Arial', 12, 'bold'), wraplength=1180, justify='left').pack(anchor='w', pady=(8, 0))

    summary_shell = tk.Frame(outer, bg='#eef3f8')
    summary_shell.pack(fill='x', padx=24, pady=(0, 12))
    summary_grid = tk.Frame(summary_shell, bg='#eef3f8')
    summary_grid.pack(fill='x')
    for col in range(6):
        summary_grid.grid_columnconfigure(col, weight=1, uniform='a_summary73e')

    summary_cards = [
        ('tр · X', f"{float(t_values.get('min', 0.0) or 0.0):.4f}", 'Приведённый темп этапа слежения по одной координате', '#67a9ff', 0, 0),
        ('tр · X+Y', f"{float(t_values.get('medio', 0.0) or 0.0):.4f}", 'Приведённый темп этапа слежения по двум координатам', '#53c26b', 0, 2),
        ('tр · X+Y+крен', f"{float(t_values.get('max', 0.0) or 0.0):.4f}", 'Приведённый темп этапа слежения по трём параметрам', '#c98cff', 0, 4),
        ('Средний γ', f"{float(summary.get('avg_success_gamma', 0.0) or 0.0):.4f}", 'Коэффициент успешности, равный негэнтропии управления', '#7bd0d5', 1, 0),
        ('Средняя энтропия H', f"{float(summary.get('avg_entropy_h', 0.0) or 0.0):.4f}", 'Чем меньше H, тем ближе средняя ошибка к целевой зоне', '#ffb35c', 1, 2),
        ('Ошибки за тест', f"{int(summary.get('total_crashes', 0) or 0)} из 9", 'Суммарное число ошибок на трёх этапах', '#e26565', 1, 4),
    ]
    for title, value, subtitle, accent, row, col in summary_cards:
        card = self.draw_result_card(summary_grid, title, value, subtitle, accent)
        card.grid(row=row, column=col, columnspan=2, sticky='nsew', padx=8, pady=8)

    info_text = (
        'Основной показатель этапа рассчитывается как tр = Vср × γ. '
        'Коэффициент успешности γ получен через энтропию управления H, которая определяется средней текущей ошибкой слежения между целевой и аварийной границами. '
        'Для этапа X+Y+крен скорость и ошибка приведены к единой нормированной шкале, чтобы получить один скалярный показатель tр.'
    )
    info_box = _add_info_box(outer, 'Как читать результат', info_text, '#6b7dff')
    info_box.pack(fill='x', padx=24, pady=(0, 14))

    stages_title = tk.Frame(outer, bg='#eef3f8')
    stages_title.pack(fill='x', padx=24, pady=(0, 8))
    tk.Label(stages_title, text='Показатели по этапам', bg='#eef3f8', fg='#102744', font=('Arial', 18, 'bold')).pack(anchor='w')
    tk.Label(stages_title, text='На каждом этапе показаны Vср, γ, энтропия H, средняя текущая ошибка и приведённый темп tр.', bg='#eef3f8', fg='#607187', font=('Arial', 11)).pack(anchor='w', pady=(2, 0))

    if not reports:
        empty = tk.Frame(outer, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec')
        empty.pack(fill='x', padx=24, pady=(0, 14))
        tk.Label(empty, text='Подробные данные этапов не найдены.', bg='#ffffff', fg='#102744', font=('Arial', 16, 'bold')).pack(anchor='w', padx=18, pady=(16, 6))
        tk.Label(empty, text='Сводные карточки выше сохранены, но детальный список этапов для этого результата отсутствует.', bg='#ffffff', fg='#506176', font=('Arial', 11), wraplength=1120, justify='left').pack(anchor='w', padx=18, pady=(0, 18))
        return top

    ordered_reports = sorted(reports, key=lambda r: int(r.get('stage_no', 0) or 0))
    for report in ordered_reports:
        card = tk.Frame(outer, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec')
        card.pack(fill='x', padx=24, pady=(0, 14))

        head = tk.Frame(card, bg='#ffffff')
        head.pack(fill='x', padx=18, pady=(16, 8))
        stage_no = int(report.get('stage_no', 0) or 0)
        tk.Label(head, text=f"Этап {stage_no} · {_fixed73e_stage_name(stage_no)}", bg='#ffffff', fg='#102744', font=('Arial', 20, 'bold')).pack(anchor='w')
        tk.Label(head, text=f"tр = {float(report.get('reduced_tempo_tr', 0.0) or 0.0):.4f}", bg='#ffffff', fg='#4f78ff', font=('Arial', 12, 'bold')).pack(anchor='w', pady=(4, 0))

        grid = tk.Frame(card, bg='#ffffff')
        grid.pack(fill='x', padx=18, pady=(0, 16))
        rows = _fixed73e_method_a_stage_metric_rows(report)
        for idx, (label_text, value_text) in enumerate(rows):
            r = idx // 2
            c = (idx % 2) * 2
            tk.Label(grid, text=label_text, bg='#ffffff', fg='#617187', font=('Arial', 10, 'bold'), anchor='w').grid(row=r, column=c, sticky='w', padx=(0, 10), pady=4)
            tk.Label(grid, text=value_text, bg='#ffffff', fg='#102744', font=('Arial', 12, 'bold'), anchor='w').grid(row=r, column=c + 1, sticky='w', padx=(0, 26), pady=4)
        for col in range(4):
            grid.grid_columnconfigure(col, weight=1 if col % 2 else 0)

    return top


