# ====== FIXED74: Method B tray hides used figures, time bar matches Method A style ======

def _fixed74_draw_vertical_time_bar(canvas: tk.Canvas, ratio: float):
    ratio = max(0.0, min(1.0, float(ratio)))
    try:
        width = max(10, int(canvas.winfo_width()))
        if width <= 1:
            width = int(canvas.cget('width'))
    except Exception:
        width = int(canvas.cget('width'))
    try:
        height = max(10, int(canvas.winfo_height()))
        if height <= 1:
            height = int(canvas.cget('height'))
    except Exception:
        height = int(canvas.cget('height'))

    canvas.delete('all')
    bar_w = 58
    left = max(6, (width - bar_w) // 2)
    right = left + bar_w
    top = 34
    bottom = height - 12

    canvas.create_text(width / 2, 18, text='ВРЕМЯ', fill='#102744', font=('Arial', 10, 'bold'))
    canvas.create_rectangle(left, top, right, bottom, outline='#233142', fill='#e6ecf4', width=3)

    inner_left = left + 4
    inner_right = right - 4
    inner_top = top + 4
    inner_bottom = bottom - 4
    inner_h = max(0, inner_bottom - inner_top)
    fill_h = int(inner_h * ratio)

    if fill_h > 0:
        canvas.create_rectangle(
            inner_left,
            max(inner_top, inner_bottom - fill_h),
            inner_right,
            inner_bottom,
            outline='',
            fill='#3c82ff'
        )


def _fixed74_method_b_update_hud(self):
    if getattr(self, 'time_bar_canvas', None) is None:
        return
    total = max(1.0, float(self.cfg.total_test_s))
    time_ratio = min(1.0, self._elapsed_total() / total)
    _fixed180_draw_vertical_time_bar(self.time_bar_canvas, time_ratio)


def _fixed74_method_b_update_info_label(self):
    self.info_var.set('')
    _fixed74_method_b_update_hud(self)
    if self.phase in ('memorize', 'reproduce', 'message') and self.win and self.win.winfo_exists():
        self._track_after(self.win.after(160, self._update_info_label))








MethodBWindow._update_info_label = _fixed74_method_b_update_info_label



