# ====== FIXED78: Method C unified vertical time bar like tests A/B, no progress bar ======

def _fixed78_method_c_update_hud(self):
    canvas = getattr(self, 'time_bar_canvas', None)
    if canvas is None:
        return
    stage_total = 1.0
    if 1 <= int(getattr(self, 'stage_index', 0) or 1) <= 3:
        stage_total = float(self.cfg.stage_time_s[max(0, int(self.stage_index) - 1)])
    stage_left = self._stage_time_left() if getattr(self, 'stage_index', 0) else stage_total
    time_ratio = 1.0 - max(0.0, min(1.0, stage_left / max(1.0, stage_total)))
    _fixed74_draw_vertical_time_bar(canvas, time_ratio)


def _fixed78_method_c_tick_stage_clock(self):
    if not self.win or not self.win.winfo_exists() or self.phase == 'finished':
        return
    self.info_var.set('')
    _fixed78_method_c_update_hud(self)
    self._track_after(self.win.after(150, self._tick_stage_clock))




