def load_config(path: str | Path = 'method_a_config.json', screen_w: int | None = None, screen_h: int | None = None) -> MethodAConfig:
    cfg = _prev_load_config_fixed89(path=path, screen_w=screen_w, screen_h=screen_h)
    try:
        cfg.stage_time_limit_s = 120.0
    except Exception:
        pass
    return cfg

def load_method_b_config(base_dir: Path) -> MethodBConfig:
    cfg = _prev_load_method_b_config_fixed89(base_dir)
    try:
        cfg.total_test_s = 120.0
    except Exception:
        pass
    return cfg

def load_method_c_config(base_dir: Path) -> MethodCConfig:
    cfg = _prev_load_method_c_config_fixed89(base_dir)
    try:
        cfg.stage_time_s = [40.0, 40.0, 40.0]
    except Exception:
        pass
    return cfg

def load_method_d_config(base_dir: Path) -> MethodDConfig:
    cfg = _prev_load_method_d_config_fixed89(base_dir)
    raw = {}
    try:
        p = Path(base_dir) / 'method_d_config.json'
        if p.exists():
            loaded = json.loads(p.read_text(encoding='utf-8'))
            if isinstance(loaded, dict):
                raw = loaded
    except Exception:
        raw = {}

    # Backward compatibility: old config kept stage speed in one dict field.
    try:
        legacy = raw.get('normative_stage_speed', {})
        if isinstance(legacy, dict) and legacy:
            cfg.normative_stage_speed = legacy
    except Exception:
        pass

    try:
        cfg.total_test_s = max(10.0, float(getattr(cfg, 'total_test_s', 540.0) or 540.0))
    except Exception:
        cfg.total_test_s = 540.0
    try:
        cfg.normative_success_coef = max(1e-6, float(getattr(cfg, 'normative_success_coef', 1.0) or 1.0))
    except Exception:
        cfg.normative_success_coef = 1.0

    def _sync_norm_time(time_attr: str, speed_attr: str, raw_time_key: str, raw_speed_key: str, default_time: float):
        raw_has_time = raw_time_key in raw
        raw_has_speed = raw_speed_key in raw
        try:
            if raw_has_time:
                time_value = float(raw.get(raw_time_key))
            elif raw_has_speed:
                speed_value = float(raw.get(raw_speed_key) or 0.0)
                time_value = (1.0 / speed_value) if speed_value > 0 else default_time
            else:
                time_value = float(getattr(cfg, time_attr, default_time) or default_time)
        except Exception:
            time_value = default_time
        if time_value <= 0:
            time_value = default_time
        setattr(cfg, time_attr, float(time_value))
        try:
            setattr(cfg, speed_attr, 1.0 / float(time_value))
        except Exception:
            pass

    _sync_norm_time('etap1_norm_cycle_time_s', 'etap1_norm_speed', 'etap1_norm_cycle_time_s', 'etap1_norm_speed', 6.25)
    _sync_norm_time('etap2_norm_cycle_time_s', 'etap2_norm_speed', 'etap2_norm_cycle_time_s', 'etap2_norm_speed', 8.75)
    _sync_norm_time('etap3_norm_cycle_time_s', 'etap3_norm_speed', 'etap3_norm_cycle_time_s', 'etap3_norm_speed', 11.25)

    try:
        cfg.etap1_norm_speed = max(1e-6, float(getattr(cfg, 'etap1_norm_speed', 0.16) or 0.16))
    except Exception:
        cfg.etap1_norm_speed = 0.16
    try:
        cfg.etap2_norm_speed = max(1e-6, float(getattr(cfg, 'etap2_norm_speed', 0.1143) or 0.1143))
    except Exception:
        cfg.etap2_norm_speed = 0.1143
    try:
        cfg.etap3_norm_speed = max(1e-6, float(getattr(cfg, 'etap3_norm_speed', 0.0889) or 0.0889))
    except Exception:
        cfg.etap3_norm_speed = 0.0889
    return cfg



