_prev_reset_researcher_defaults_fixed89 = getattr(StartPageApp, 'reset_researcher_defaults', None)
def _fixed89_reset_researcher_defaults(self):
    if callable(_prev_reset_researcher_defaults_fixed89):
        _prev_reset_researcher_defaults_fixed89(self)
