def _fixed101_method_a_draw_hud(self, stage_no: int, elapsed_s: float, stage_error: float, report: StageReport, state: DriftState):
    self._exit_button_rect = None
    stage_limit = _fixed100_get_stage_time_limit(self.cfg, stage_no) if '_fixed100_get_stage_time_limit' in globals() else self.cfg.stage_time_limit_s
    time_ratio = elapsed_s / max(1e-6, stage_limit)
    err_limit = max(1e-6, float(getattr(report, 'error_limit_formula_value', self.stage_smax(stage_no)) or self.stage_smax(stage_no)))
    err_ratio = stage_error / err_limit
    self.draw_bar(16, 60, 64, 280, time_ratio, 'ВРЕМЯ', (60, 130, 255))
    self.draw_bar(self.cfg.width - 80, 60, 64, 280, err_ratio, 'ОШИБКА', (255, 118, 50))
    hud_font = pygame.font.SysFont('Arial', 22, bold=True)
    hud_text = f"YΣ={float(stage_error):.3f} / Yпредел={float(err_limit):.3f}"
    surf = hud_font.render(hud_text, True, (24, 40, 62))
    self.screen.blit(surf, (self.cfg.width - 420, 24))

