# ====== FIXED104: responsive layouts for all screens and safer button sizing ======



def _fixed104_screen_metrics(widget_or_parent):
    try:
        sw = int(widget_or_parent.winfo_screenwidth())
        sh = int(widget_or_parent.winfo_screenheight())
    except Exception:
        sw, sh = 1920, 1080
    scale = min(sw / 1920.0, sh / 1080.0)
    if sw < 1600 or sh < 920:
        scale *= 0.92
    if sw < 1366 or sh < 768:
        scale *= 0.90
    scale = max(0.58, min(scale, 1.18))
    return sw, sh, scale

# Make all later test windows use the more conservative scaling too.
globals()['_fixed88_screen_metrics'] = _fixed104_screen_metrics


def _fixed104_apply_common_shell_layout(self, width: int, height: int, scale: float):
    compact = width < 1500 or height < 900
    ultra_compact = width < 1280 or height < 780

    try:
        self.root.minsize(960, 680)
    except Exception:
        pass

    left_weight = 5 if compact else 7
    right_weight = 15 if compact else 13
    self.main.grid_columnconfigure(0, weight=left_weight, uniform="cols")
    self.main.grid_columnconfigure(1, weight=right_weight, uniform="cols")

    # Prevent the intro text row from greedily eating the entire center on laptops.
    try:
        self.right.grid_rowconfigure(2, weight=0)
        self.right.grid_rowconfigure(3, weight=0)
        self.right.grid_rowconfigure(4, weight=0)
    except Exception:
        pass

    pad_x = int((16 if compact else 24) * scale)
    pad_y = int((12 if compact else 18) * scale)
    left_right_gap = int((14 if compact else 24) * scale)
    image_gap = int((10 if compact else 18) * scale)

    self.main.pack_configure(padx=pad_x, pady=pad_y)
    self.left.grid_configure(padx=(0, left_right_gap))
    self.title_small.grid_configure(pady=(0, int((4 if compact else 8) * scale)))
    self.title_big.grid_configure(pady=(0, int((6 if compact else 8) * scale)))
    self.body.grid_configure(pady=(int((8 if compact else 16) * scale), int((8 if compact else 16) * scale)))
    self.image_gap.configure(height=image_gap)

    title_small_size = max(18, int((30 if compact else 42) * scale))
    title_big_size = max(22, int((34 if compact else 46) * scale))
    body_size = max(10, int((15 if compact else 21) * scale))
    body_wrap = int(width * (0.60 if compact else 0.54))

    self.title_small.configure(font=("Times New Roman", title_small_size, "bold"))
    self.title_big.configure(font=("Times New Roman", title_big_size, "bold"))
    self.body.configure(font=("Times New Roman", body_size, "bold"), wraplength=body_wrap)

    left_width = int(width * (0.22 if ultra_compact else (0.24 if compact else 0.29)))
    img_height_factor = 0.26 if ultra_compact else (0.30 if compact else 0.40)
    img_size = min(left_width, int(height * img_height_factor))
    img_size = max(160 if ultra_compact else (180 if compact else 220), img_size)

    self.set_image(self.circle_label, "circle.png", img_size)
    self.set_image(self.cockpit_label, "cockpit.png", img_size)

StartPageApp._apply_common_shell_layout = _fixed104_apply_common_shell_layout








def _fixed104_apply_research_layout(self):
    width = max(self.root.winfo_width(), 960)
    height = max(self.root.winfo_height(), 680)
    scale = min(width / BASE_W, height / BASE_H)
    scale = max(0.58, min(scale, 1.15))
    compact = width < 1500 or height < 900

    pad_x = int((14 if compact else 22) * scale)
    pad_y = int((10 if compact else 16) * scale)
    self.main.pack_configure(padx=pad_x, pady=pad_y)
    self.research_header.pack_configure(pady=(0, int((6 if compact else 10) * scale)))
    self.research_actions_top.pack_configure(pady=(0, int((6 if compact else 10) * scale)))
    self.research_status.pack_configure(pady=(0, int((6 if compact else 10) * scale)))

    title_size = max(18, int((28 if compact else 40) * scale))
    text_size = max(10, int((13 if compact else 16) * scale))
    section_label_size = max(10, int((12 if compact else 15) * scale))
    button_size = max(10, int((11 if compact else 16) * scale))

    self.research_title.configure(font=("Times New Roman", title_size, "bold"))
    self.research_subtitle.configure(font=("Arial", text_size, "bold"), wraplength=int(width * 0.86))
    self.research_status.configure(font=("Arial", text_size, "bold"), wraplength=int(width * 0.86))

    # Buttons sized by font only, width left automatic so long Russian labels fit.
    for btn in (self.research_default_btn, self.research_next_btn, self.research_exit_btn):
        btn.configure(font=("Arial", button_size, "bold"))
    self.research_default_btn.pack_configure(padx=(0, int(10 * scale)))
    self.research_exit_btn.pack_configure(padx=(int(10 * scale), 0))
    self.research_next_btn.pack_configure(padx=(int(10 * scale), 0))

    section_title_wrap = int(width * 0.20)
    field_help_wrap = int(width * 0.18)
    default_wrap = int(width * 0.26)

    for code, section_list in self.research_sections.items():
        for section in section_list:
            try:
                section.configure(font=("Arial", section_label_size, "bold"))
            except tk.TclError:
                pass
            section.grid_columnconfigure(0, minsize=int(width * (0.18 if compact else 0.16)))
            for child in section.winfo_children():
                if isinstance(child, tk.Frame):
                    for nested in child.winfo_children():
                        if isinstance(nested, tk.Label):
                            text_value = str(nested.cget("text") or "")
                            if "по умолчанию" in text_value.lower():
                                nested.configure(font=("Arial", max(9, text_size - 1), "bold"), wraplength=default_wrap)
                            elif text_value.endswith(":") or text_value.startswith("•"):
                                nested.configure(font=("Arial", text_size, "bold"), wraplength=section_title_wrap)
                            else:
                                nested.configure(font=("Arial", max(9, text_size - 1)), wraplength=field_help_wrap)
                        elif isinstance(nested, tk.Entry):
                            nested.configure(font=("Arial", text_size))
                        elif isinstance(nested, tk.Text):
                            nested.configure(font=("Arial", max(9, text_size - 1)), height=max(2, int(3 * scale)))
                        elif isinstance(nested, tk.Checkbutton):
                            nested.configure(font=("Arial", text_size, "bold"))

    try:
        style = ttk.Style(self.root)
        style.configure("TNotebook.Tab", padding=(int(10 * scale), int(5 * scale)), font=("Arial", max(9, text_size), "bold"))
    except Exception:
        pass

