def _fixed149_method_c_stage1_preview_value(self) -> int:
    preview = getattr(self, '_method_c_stage1_preview_value', None)
    if preview is None:
        lo, hi = self._stage_limits(1)
        lo = max(1, int(lo))
        hi = int(hi)
        preview = random.randint(lo, hi)
        self._method_c_stage1_preview_value = preview
    return int(preview)


def _fixed149_method_c_apply_stage1_preview(self):
    preview = _fixed149_method_c_stage1_preview_value(self)
    self.phase = 'idle'
    self.current_value = preview
    self.prompt_var.set('')
    self.entry_var.set('')
    self.big_var.set(str(preview))
    try:
        self.big_label.configure(
            fg='#228b22',
            font=self._fixed137_digit_font,
            justify='center',
            anchor='center',
            wraplength=self._display_wrap,
            width=16,
        )
    except Exception:
        try:
            self.big_label.configure(fg='#228b22')
        except Exception:
            pass
    try:
        _fixed137_method_c_set_input_enabled(self, False)
    except Exception:
        pass


def _fixed149_method_c_build_ui(self):
    _FIXED149_PREV_METHOD_C_BUILD_UI(self)
    if getattr(self, 'win', None) and self.win.winfo_exists():
        _fixed149_method_c_apply_stage1_preview(self)



def _fixed149_method_c_start_stage(self, stage_index: int):
    _FIXED149_PREV_METHOD_C_START_STAGE(self, stage_index)
    if stage_index == 1 and getattr(self, 'win', None) and self.win.winfo_exists():
        preview = getattr(self, '_method_c_stage1_preview_value', None)
        if preview is not None:
            self.current_value = int(preview)
            self._method_c_stage1_preview_value = None
            self.prompt_var.set('')
            self.entry_var.set('')
            self.big_var.set(str(self.current_value))
            try:
                self.big_label.configure(
                    fg='#228b22',
                    font=self._fixed137_digit_font,
                    justify='center',
                    anchor='center',
                    wraplength=self._display_wrap,
                    width=16,
                )
            except Exception:
                try:
                    self.big_label.configure(fg='#228b22')
                except Exception:
                    pass
            _fixed137_method_c_set_input_enabled(self, False)


MethodCWindow._build_ui = _fixed149_method_c_build_ui
