def _fixed157_method_c_build_ui(self):
    _FIXED157_PREV_METHOD_C_BUILD_UI(self)

    host = getattr(self, '_display_box', None)
    if host is None:
        return

    old_frame = getattr(self, '_method_c_feedback_frame', None)
    if old_frame is not None:
        try:
            old_frame.destroy()
        except Exception:
            pass

    self._method_c_feedback_text_var = tk.StringVar(value='')
    self._method_c_feedback_line1_var = tk.StringVar(value='')
    self._method_c_feedback_line2_var = tk.StringVar(value='')
    self._method_c_feedback_number_var = tk.StringVar(value='')

    text_font = _fixed152_method_c_text_font(self)
    try:
        text_size = int(text_font[1])
    except Exception:
        text_size = 28
    try:
        digit_size = int(self._fixed137_digit_font[1])
    except Exception:
        digit_size = 72

    feedback_w = max(520, int(self._display_wrap * 0.92))
    row_h = max(72, int(text_size * 2.0))
    row_gap = max(10, int(text_size * 0.28))
    number_pad = max(6, int(digit_size * 0.08))
    feedback_h = row_h * 2 + row_gap * 2 + max(110, int(digit_size * 1.22))
    self._method_c_feedback_place = {'width': feedback_w, 'height': feedback_h}

    try:
        current_h = int(host.cget('height'))
    except Exception:
        try:
            current_h = int(host.winfo_reqheight())
        except Exception:
            current_h = feedback_h
    try:
        host.configure(height=max(current_h, feedback_h + 32))
    except Exception:
        pass

    self._method_c_feedback_frame = tk.Frame(host, bg=PDF_TURQUOISE_BG, width=feedback_w, height=feedback_h)
    self._method_c_feedback_frame.pack_propagate(False)
    self._method_c_feedback_frame.grid_propagate(False)
    self._method_c_feedback_frame.grid_columnconfigure(0, weight=1)

    self._method_c_feedback_line1_row = tk.Frame(self._method_c_feedback_frame, bg=PDF_TURQUOISE_BG, width=feedback_w, height=row_h)
    self._method_c_feedback_line1_row.grid(row=0, column=0, sticky='ew', pady=(0, row_gap))
    self._method_c_feedback_line1_row.grid_propagate(False)
    self._method_c_feedback_line1_label = tk.Label(
        self._method_c_feedback_line1_row,
        textvariable=self._method_c_feedback_line1_var,
        bg=PDF_TURQUOISE_BG,
        fg='#8b1e1e',
        font=text_font,
        justify='center',
        anchor='center',
        padx=18,
    )
    self._method_c_feedback_line1_label.place(relx=0.5, rely=0.5, anchor='center')

    self._method_c_feedback_line2_row = tk.Frame(self._method_c_feedback_frame, bg=PDF_TURQUOISE_BG, width=feedback_w, height=row_h)
    self._method_c_feedback_line2_row.grid(row=1, column=0, sticky='ew', pady=(0, row_gap))
    self._method_c_feedback_line2_row.grid_propagate(False)
    self._method_c_feedback_line2_label = tk.Label(
        self._method_c_feedback_line2_row,
        textvariable=self._method_c_feedback_line2_var,
        bg=PDF_TURQUOISE_BG,
        fg='#8b1e1e',
        font=text_font,
        justify='center',
        anchor='center',
        padx=18,
    )
    self._method_c_feedback_line2_label.place(relx=0.5, rely=0.5, anchor='center')

    self._method_c_feedback_number_label = tk.Label(
        self._method_c_feedback_frame,
        textvariable=self._method_c_feedback_number_var,
        bg=PDF_TURQUOISE_BG,
        fg='#000000',
        font=self._fixed137_digit_font,
        justify='center',
        anchor='center',
        pady=number_pad,
    )
    self._method_c_feedback_number_label.grid(row=2, column=0, sticky='n')

    _fixed150_method_c_feedback_clear(self)


MethodCWindow._build_ui = _fixed157_method_c_build_ui


