# ====== FIXED163: Method C colors, error feedback, and buttons follow latest notes ======

_FIXED163_PREV_METHOD_C_BUILD_UI = MethodCWindow._build_ui
_FIXED163_GREEN = '#18a74a'
_FIXED163_RED = '#ff0000'


def _fixed163_method_c_feedback_font(self):
    base = getattr(self, '_fixed137_digit_font', ('Arial', 72, 'bold'))
    try:
        size = int(base[1])
    except Exception:
        size = 72
    return ('Arial', max(42, int(size * 0.88)), 'bold')












def _fixed163_method_c_build_ui(self):
    _FIXED163_PREV_METHOD_C_BUILD_UI(self)

    try:
        digit_size = int(self._fixed137_digit_font[1])
    except Exception:
        digit_size = 72

    # Bigger raised side buttons with a clear black outline.
    clear_old_w = self.clear_btn.winfo_reqwidth()
    clear_old_x = int(self.clear_btn.place_info().get('x', 0))
    answer_old_x = int(self.answer_btn.place_info().get('x', 0))

    button_font = ('Arial', max(16, int(digit_size * 0.22)), 'bold')
    for btn in (self.clear_btn, self.answer_btn):
        try:
            base_width = int(btn.cget('width'))
        except Exception:
            base_width = 10
        try:
            base_padx = int(btn.cget('padx'))
        except Exception:
            base_padx = 14
        try:
            base_pady = int(btn.cget('pady'))
        except Exception:
            base_pady = 8
        btn.configure(
            font=button_font,
            width=max(14, int(round(base_width * 1.5))),
            padx=max(18, int(round(base_padx * 1.5))),
            pady=max(12, int(round(base_pady * 1.5))),
            bd=3,
            relief='raised',
            highlightthickness=1,
            highlightbackground='#000000',
            highlightcolor='#000000',
            overrelief='raised',
        )

    # Smaller exit button so it does not clip on the right edge.
    try:
        exit_width = int(self.exit_btn.cget('width'))
    except Exception:
        exit_width = 18
    try:
        exit_padx = int(self.exit_btn.cget('padx'))
    except Exception:
        exit_padx = 14
    try:
        exit_pady = int(self.exit_btn.cget('pady'))
    except Exception:
        exit_pady = 8
    self.exit_btn.configure(
        font=('Arial', max(12, int(digit_size * 0.18)), 'bold'),
        width=max(12, int(exit_width * 0.78)),
        padx=max(10, int(exit_padx * 0.78)),
        pady=max(7, int(exit_pady * 0.88)),
        bd=2,
        relief='raised',
        highlightthickness=1,
        highlightbackground='#000000',
        highlightcolor='#000000',
    )
    self.exit_btn.grid_configure(padx=(0, 12))

    self.entry.configure(
        fg=_FIXED163_GREEN,
        disabledforeground=_FIXED163_GREEN,
        insertbackground=_FIXED163_GREEN,
    )

    # Keypad digits stay green as well.
    keypad = getattr(self, '_method_c_keypad', None)
    if keypad is not None:
        try:
            keypad.configure(highlightbackground='#000000')
        except Exception:
            pass
    for widget in getattr(self, '_method_c_input_widgets', [])[2:]:
        try:
            widget.configure(
                fg=_FIXED163_GREEN,
                activeforeground=_FIXED163_GREEN,
                highlightbackground='#000000',
                highlightcolor='#000000',
            )
        except Exception:
            pass

    self.win.update_idletasks()
    clear_new_w = self.clear_btn.winfo_reqwidth()
    self.clear_btn.place_configure(x=max(6, clear_old_x - max(0, clear_new_w - clear_old_w)))
    self.answer_btn.place_configure(x=answer_old_x)

    # Replace the old multi-row feedback block with a large red two-line message,
    # while the correct number is shown separately in the normal digit position.
    host = getattr(self, '_display_box', None)
    if host is not None:
        try:
            current_h = int(host.cget('height'))
        except Exception:
            try:
                current_h = int(host.winfo_reqheight())
            except Exception:
                current_h = 240
        try:
            host.configure(height=max(current_h, int(digit_size * 3.5)))
        except Exception:
            pass

    old_frame = getattr(self, '_method_c_feedback_frame', None)
    if old_frame is not None:
        try:
            old_frame.destroy()
        except Exception:
            pass

    self._method_c_feedback_text_var = tk.StringVar(value='')
    if host is not None:
        feedback_w = max(560, int(self._display_wrap * 0.96))
        feedback_h = max(170, int(digit_size * 1.85))
        self._method_c_feedback_place = {
            'relx': 0.5,
            'y': 0,
            'anchor': 'n',
            'width': feedback_w,
            'height': feedback_h,
        }
        self._method_c_feedback_frame = tk.Frame(host, bg=PDF_TURQUOISE_BG, width=feedback_w, height=feedback_h)
        self._method_c_feedback_frame.pack_propagate(False)
        self._method_c_feedback_text_label = tk.Label(
            self._method_c_feedback_frame,
            textvariable=self._method_c_feedback_text_var,
            bg=PDF_TURQUOISE_BG,
            fg=_FIXED163_RED,
            font=_fixed163_method_c_feedback_font(self),
            justify='center',
            anchor='center',
            wraplength=feedback_w - 24,
        )
        self._method_c_feedback_text_label.pack(expand=True, fill='both', padx=12, pady=(4, 0))
        _fixed150_method_c_feedback_clear(self)


MethodCWindow._build_ui = _fixed163_method_c_build_ui


# ====== FIXED164: Method C keeps one green tone for all non-negative digits ======

_FIXED164_PREV_METHOD_C_BUILD_UI = MethodCWindow._build_ui
_FIXED164_PREV_METHOD_C_START_STAGE = MethodCWindow._start_stage
_FIXED164_PREV_METHOD_C_START_OPERATION_CYCLE = MethodCWindow._start_operation_cycle
_FIXED164_GREEN = '#18a74a'
_FIXED164_NEGATIVE = '#c93232'


def _fixed164_method_c_apply_big_value(self, value, color):
    try:
        self.big_label.configure(
            fg=color,
            font=self._fixed137_digit_font,
            justify='center',
            anchor='center',
            wraplength=self._display_wrap,
            width=16,
        )
    except Exception:
        pass
    self.big_var.set('' if value is None else str(value))


def _fixed150_method_c_feedback_show(self, text: str, number: int | str | None = None):
    frame = getattr(self, '_method_c_feedback_frame', None)
    if frame is not None:
        text_var = getattr(self, '_method_c_feedback_text_var', None)
        if text_var is not None:
            text_var.set('' if text is None else str(text))
        place_cfg = getattr(self, '_method_c_feedback_place', {}) or {}
        try:
            frame.place(
                relx=place_cfg.get('relx', 0.5),
                y=place_cfg.get('y', 0),
                anchor=place_cfg.get('anchor', 'n'),
                width=place_cfg.get('width'),
                height=place_cfg.get('height'),
            )
            frame.lift()
        except Exception:
            pass
    if number is not None:
        _fixed164_method_c_apply_big_value(self, number, _FIXED164_GREEN)


def _fixed164_method_c_build_ui(self):
    _FIXED164_PREV_METHOD_C_BUILD_UI(self)

    if getattr(self, 'big_var', None) is not None and self.big_var.get():
        _fixed164_method_c_apply_big_value(self, self.big_var.get(), _FIXED164_GREEN)

    for btn in (getattr(self, 'clear_btn', None), getattr(self, 'answer_btn', None)):
        if btn is None:
            continue
        try:
            btn.configure(
                bd=4,
                relief='raised',
                overrelief='sunken',
                highlightthickness=1,
                highlightbackground='#000000',
                highlightcolor='#000000',
            )
        except Exception:
            pass

    exit_btn = getattr(self, 'exit_btn', None)
    if exit_btn is not None:
        try:
            exit_btn.configure(
                bd=2,
                relief='raised',
                overrelief='sunken',
                highlightthickness=1,
                highlightbackground='#000000',
                highlightcolor='#000000',
            )
        except Exception:
            pass

    for widget in getattr(self, '_method_c_input_widgets', [])[2:]:
        try:
            widget.configure(
                fg=_FIXED164_GREEN,
                activeforeground=_FIXED164_GREEN,
            )
        except Exception:
            pass


def _fixed164_method_c_start_stage(self, stage_index: int):
    _FIXED164_PREV_METHOD_C_START_STAGE(self, stage_index)
    if getattr(self, 'win', None) and self.win.winfo_exists():
        _fixed164_method_c_apply_big_value(self, self.current_value, _FIXED164_GREEN)


def _fixed164_method_c_start_operation_cycle(self):
    _FIXED164_PREV_METHOD_C_START_OPERATION_CYCLE(self)
    if not (getattr(self, 'win', None) and self.win.winfo_exists()):
        return
    if getattr(self, 'phase', '') != 'show_operand':
        return
    color = _FIXED164_GREEN if getattr(self, 'current_op', '+') == '+' else _FIXED164_NEGATIVE
