# ====== FIXED180: Method B time bar uses configured canvas size until geometry is realized ======

def _fixed180_draw_vertical_time_bar(canvas: tk.Canvas, ratio: float):
    ratio = max(0.0, min(1.0, float(ratio)))
    try:
        raw_width = int(canvas.winfo_width())
    except Exception:
        raw_width = 0
    try:
        raw_height = int(canvas.winfo_height())
    except Exception:
        raw_height = 0
    try:
        cfg_width = int(canvas.cget('width'))
    except Exception:
        cfg_width = 96
    try:
        cfg_height = int(canvas.cget('height'))
    except Exception:
        cfg_height = 320

    width = raw_width if raw_width > 1 else cfg_width
    height = raw_height if raw_height > 1 else cfg_height
    width = max(10, width)
    height = max(10, height)

    canvas.delete('all')
    bar_w = 58
    left = max(6, (width - bar_w) // 2)
    right = left + bar_w
    top = 34
    bottom = height - 12

    canvas.create_text(width / 2, 18, text='\u0412\u0420\u0415\u041c\u042f', fill='#102744', font=('Arial', 10, 'bold'))
    canvas.create_rectangle(left, top, right, bottom, outline='#233142', fill='#e6ecf4', width=3)

    inner_left = left + 4
    inner_right = right - 4
    inner_top = top + 4
    inner_bottom = bottom - 4
    inner_h = max(0, inner_bottom - inner_top)
    fill_h = int(inner_h * ratio)

    if fill_h > 0:
        canvas.create_rectangle(
            inner_left,
            max(inner_top, inner_bottom - fill_h),
            inner_right,
            inner_bottom,
            outline='',
            fill='#3c82ff'
        )


