# ====== FIXED207: Method A PDF includes ALL result pages (full scroll capture) ======
_FIXED207_METHOD_A_CALC_VERSION = 'fixed207_pdf_all_results_scroll_capture_v1'




def _fixed207_find_results_canvas(top: tk.Toplevel) -> tk.Canvas | None:
    try:
        shell = top.winfo_children()[0]
        content = shell.winfo_children()[1]
        canvas = next((w for w in content.winfo_children() if isinstance(w, tk.Canvas)), None)
        return canvas
    except Exception:
        return None


def _fixed207_collect_scrollbars(root: tk.Misc) -> list[tk.Misc]:
    found: list[tk.Misc] = []
    stack = [root]
    while stack:
        node = stack.pop()
        try:
            children = list(node.winfo_children())
        except Exception:
            children = []
        for child in children:
            if isinstance(child, (tk.Scrollbar, ttk.Scrollbar)):
                found.append(child)
            stack.append(child)
    return found


def _fixed207_hide_scrollbars_for_capture(top: tk.Toplevel) -> list[tuple[tk.Misc, str, dict]]:
    hidden: list[tuple[tk.Misc, str, dict]] = []
    for bar in _fixed207_collect_scrollbars(top):
        try:
            mgr = str(bar.winfo_manager() or '')
            if mgr == 'pack':
                hidden.append((bar, mgr, dict(bar.pack_info())))
                bar.pack_forget()
            elif mgr == 'grid':
                hidden.append((bar, mgr, dict(bar.grid_info())))
                bar.grid_remove()
            elif mgr == 'place':
                hidden.append((bar, mgr, dict(bar.place_info())))
                bar.place_forget()
        except Exception:
            continue
    return hidden


def _fixed207_restore_scrollbars(hidden: list[tuple[tk.Misc, str, dict]]) -> None:
    for bar, mgr, info in reversed(hidden):
        try:
            if mgr == 'pack':
                bar.pack(**info)
            elif mgr == 'grid':
                bar.grid(**info)
            elif mgr == 'place':
                bar.place(**info)
        except Exception:
            continue


def _fixed207_export_pdf_all_results(self, top: tk.Toplevel, payload: dict) -> str:
    try:
        from PIL import ImageGrab as _fixed207_imagegrab
    except Exception:
        return ''

    canvas = _fixed207_find_results_canvas(top)
    if canvas is None:
        return ''

    try:
        top.update_idletasks()
        top.update()
        hidden_scrollbars = _fixed207_hide_scrollbars_for_capture(top)
        top.update_idletasks()
        top.update()

        captured: list[Image.Image] = []
        try:
            region = str(canvas.cget('scrollregion') or '').strip()
            if region:
                parts = region.split()
                if len(parts) == 4:
                    _, y1s, _, y2s = parts
                    total_h = max(1, int(float(y2s) - float(y1s)))
                else:
                    total_h = max(1, int(canvas.bbox('all')[3] if canvas.bbox('all') else canvas.winfo_height()))
            else:
                box = canvas.bbox('all')
                total_h = max(1, int((box[3] - box[1]) if box else canvas.winfo_height()))

            vis_h = max(1, int(canvas.winfo_height()))
            max_offset = max(0, total_h - vis_h)

            offsets: list[int] = []
            current = 0
            while current < max_offset:
                offsets.append(current)
                current += vis_h
            offsets.append(max_offset)

            for off in offsets:
                frac = float(off) / float(max(1, max_offset))
                canvas.yview_moveto(frac)
                top.update_idletasks()
                top.update()

                x1 = int(canvas.winfo_rootx())
                y1 = int(canvas.winfo_rooty())
                x2 = x1 + int(canvas.winfo_width())
                y2 = y1 + int(canvas.winfo_height())
                if x2 <= x1 or y2 <= y1:
                    continue
                shot = _fixed207_imagegrab.grab(bbox=(x1, y1, x2, y2))
                if shot.mode != 'RGB':
                    shot = shot.convert('RGB')
                captured.append(shot)
        finally:
            canvas.yview_moveto(0.0)
            _fixed207_restore_scrollbars(hidden_scrollbars)
            top.update_idletasks()
            top.update()

        if not captured:
            return ''

        session_id = str(payload.get('session_id', 'session') or 'session')
        ts = datetime.now().strftime('%Y%m%d_%H%M%S')
        pdf_path = _results_dir(self.base_dir) / f'method_a_all_results_{session_id}_{ts}.pdf'
        captured[0].save(str(pdf_path), format='PDF', save_all=True, append_images=captured[1:], resolution=150.0)
        return str(pdf_path)
    except Exception:
        return ''




globals()['_fixed73e_method_a_summary_from_reports'] = _fixed204_method_a_summary_from_reports


