_FIXED208_METHOD_A_CALC_VERSION = 'fixed208_full_second_table_normalized_v1'


def _fixed208_inside_target_center(self, state: DriftState, stage_no: int) -> bool:
    """Target-zone decision strictly by object center (crosshair), not sprite edges."""
    stage = self.stage_defs[int(stage_no)]
    px_per_cm = max(1e-6, float(getattr(self.cfg, 'px_per_cm', 38.0) or 38.0))
    goal_x_px = max(1e-6, float(getattr(self.cfg, 'r_goal_x_cm', 3.0) or 3.0) * px_per_cm)
    goal_y_px = max(1e-6, float(getattr(self.cfg, 'r_goal_y_cm', 3.0) or 3.0) * px_per_cm)
    goal_z_deg = max(1e-6, float(getattr(self.cfg, 'r_goal_z_deg', 15.0) or 15.0))
    ok_x = (not stage.get('x')) or (abs(float(getattr(state, 'x_px', 0.0))) <= goal_x_px)
    ok_y = (not stage.get('y')) or (abs(float(getattr(state, 'y_px', 0.0))) <= goal_y_px)
    ok_z = (not stage.get('z')) or (abs(float(getattr(state, 'roll_deg', 0.0))) <= goal_z_deg)
    return bool(ok_x and ok_y and ok_z)










def _fixed254_stage_table_column_averages(rows: list[dict], stage_no: int) -> dict:
    if not isinstance(rows, list) or not rows:
        return {}
    cols = [
        't_s',
        'x_cm', 'y_cm', 'z_deg',
        'goal_x', 'goal_y', 'goal_z',
        'crash_x', 'crash_y', 'crash_z',
        'vx', 'vy', 'vz', 'v_current', 'v_control_x', 'v_control_y', 'v_control_z', 'v_control_total',
        'lambda_x', 'lambda_y', 'lambda_z', 'lambda_total',
        's_x', 's_y', 's_z',
        'h_current', 'h_sigma_x', 'h_sigma_y', 'h_sigma_z', 'h_sigma',
        'crashes', 'y_pred', 'n_dop_t',
    ]
    out = {}
    terminal_cols = {'h_sigma_x', 'h_sigma_y', 'h_sigma_z', 'h_sigma', 'crashes'}
    for c in cols:
        if c == 't_s':
            out[c] = 0.0
            continue
        if c in terminal_cols:
            v_last = float(rows[-1].get(c, 0.0) or 0.0)
            if c in ('h_sigma_x', 'h_sigma_y', 'h_sigma_z') and int(stage_no) in (2, 3):
                v_last = abs(v_last)
            out[c] = v_last
            continue
        vals = []
        for r in rows:
            v = float(r.get(c, 0.0) or 0.0)
            if c in ('s_x', 's_y', 's_z') and int(stage_no) in (2, 3):
                v = abs(v)
            vals.append(v)
        out[c] = float(sum(vals) / max(1, len(vals)))
    return out


