# ====== FIXED260: clean Method A formulas from "СЛЕЖЕНИЕ ОБРАБОТКА 07.05.2026.docx" ======
from dataclasses import dataclass as _fixed260_dataclass

_FIXED260_METHOD_A_CALC_VERSION = 'fixed427_method_a_doc_gamma_allowed_error_v1'
# Compatibility alias for legacy result renderers that still reference fixed209 name.
_FIXED209_METHOD_A_CALC_VERSION = _FIXED260_METHOD_A_CALC_VERSION


@_fixed260_dataclass
class MethodAConfigFixed260(MethodAConfig):
    # Axis thresholds from settings (defaults from document notes).
    r_goal_x_cm: float = 3.0
    r_crash_x_cm: float = 18.0
    r_goal_y_cm: float = 3.0
    r_crash_y_cm: float = 18.0
    r_goal_z_deg: float = 15.0
    r_crash_z_deg: float = 90.0
    # Normative control speeds by axis (document).
    v_norm_x_cm_s: float = 5.0
    v_norm_y_cm_s: float = 5.0
    v_norm_z_deg_s: float = 25.0
    # Sнорм bounds for stage completion / Yслеж (document).
    s_norm_x: float = 28.0
    s_norm_xy: float = 28.0
    s_norm_xyz: float = 28.0


MethodAConfig = MethodAConfigFixed260
globals()['MethodAConfig'] = MethodAConfigFixed260

_fixed260_prev_load_config = load_config


def _fixed260_read_raw_json(path: str | Path) -> dict:
    raw = {}
    p = Path(path)
    if p.exists():
        try:
            loaded = json.loads(p.read_text(encoding='utf-8'))
            if isinstance(loaded, dict):
                raw = dict(loaded)
        except Exception:
            raw = {}
    return raw


def _fixed260_clamp_cfg(cfg: MethodAConfigFixed260) -> MethodAConfigFixed260:
    cfg.r_goal_x_cm = max(1e-6, float(getattr(cfg, 'r_goal_x_cm', 3.0) or 3.0))
    cfg.r_goal_y_cm = max(1e-6, float(getattr(cfg, 'r_goal_y_cm', 3.0) or 3.0))
    cfg.r_goal_z_deg = max(1e-6, float(getattr(cfg, 'r_goal_z_deg', 15.0) or 15.0))
    cfg.r_crash_x_cm = max(cfg.r_goal_x_cm + 1e-6, float(getattr(cfg, 'r_crash_x_cm', 18.0) or 18.0))
    cfg.r_crash_y_cm = max(cfg.r_goal_y_cm + 1e-6, float(getattr(cfg, 'r_crash_y_cm', 18.0) or 18.0))
    cfg.r_crash_z_deg = max(cfg.r_goal_z_deg + 1e-6, float(getattr(cfg, 'r_crash_z_deg', 90.0) or 90.0))
    cfg.v_norm_x_cm_s = max(1e-6, float(getattr(cfg, 'v_norm_x_cm_s', 5.0) or 5.0))
    cfg.v_norm_y_cm_s = max(1e-6, float(getattr(cfg, 'v_norm_y_cm_s', 5.0) or 5.0))
    cfg.v_norm_z_deg_s = max(1e-6, float(getattr(cfg, 'v_norm_z_deg_s', 25.0) or 25.0))
    cfg.s_norm_x = max(1e-6, float(getattr(cfg, 's_norm_x', 28.0) or 28.0))
    cfg.s_norm_xy = max(1e-6, float(getattr(cfg, 's_norm_xy', 28.0) or 28.0))
    cfg.s_norm_xyz = max(1e-6, float(getattr(cfg, 's_norm_xyz', 28.0) or 28.0))
    # Keep geometry-compatible legacy fields synchronized.
    cfg.target_half_cm = float((cfg.r_goal_x_cm + cfg.r_goal_y_cm) * 0.5)
    cfg.work_extension_cm = float(max(cfg.r_crash_x_cm - cfg.r_goal_x_cm, cfg.r_crash_y_cm - cfg.r_goal_y_cm))
    cfg.target_roll_deg = float(cfg.r_goal_z_deg)
    cfg.work_roll_deg = float(cfg.r_crash_z_deg)
    return cfg


def load_config(path: str | Path = 'method_a_config.json', screen_w: int | None = None, screen_h: int | None = None) -> MethodAConfigFixed260:
    base_cfg = _fixed260_prev_load_config(path=path, screen_w=screen_w, screen_h=screen_h)
    raw = _fixed260_read_raw_json(path)

    inherited_kwargs = {}
    for fld in _fixed199_fields(MethodAConfigFixed260):
        if hasattr(base_cfg, fld.name):
            inherited_kwargs[fld.name] = getattr(base_cfg, fld.name)
        elif fld.name in raw:
            inherited_kwargs[fld.name] = raw.get(fld.name)
    cfg = MethodAConfigFixed260(**inherited_kwargs)

    for key in (
        'r_goal_x_cm', 'r_crash_x_cm', 'r_goal_y_cm', 'r_crash_y_cm', 'r_goal_z_deg', 'r_crash_z_deg',
        'v_norm_x_cm_s', 'v_norm_y_cm_s', 'v_norm_z_deg_s',
        's_norm_x', 's_norm_xy', 's_norm_xyz',
        # Keep roll dynamics fully configurable by user settings.
        'start_speed_z_deg_s', 'step_speed_z_deg_s', 'roll_step_per_wheel_notch_deg',
    ):
        if key in raw:
            try:
                setattr(cfg, key, float(raw.get(key)))
            except Exception:
                pass
    cfg = _fixed260_clamp_cfg(cfg)
    return cfg


globals()['load_config'] = load_config

