# ====== FIXED265: all-results browser with multi-filter search ======
def _fixed265_parse_age_filter(raw: str) -> tuple[int | None, int | None]:
    txt = str(raw or '').strip().replace(' ', '')
    if not txt:
        return None, None
    if '-' in txt:
        parts = txt.split('-', 1)
        try:
            lo = int(parts[0]) if parts[0] else None
        except Exception:
            lo = None
        try:
            hi = int(parts[1]) if parts[1] else None
        except Exception:
            hi = None
        return lo, hi
    try:
        exact = int(txt)
        return exact, exact
    except Exception:
        return None, None


_FIXED416_SUMMARY_KEY = '_fixed416_progress_key'


def _fixed416_norm_identity(name, age, gender) -> tuple[str, str, str]:
    name_text = ' '.join(str(name or '').strip().casefold().split())
    try:
        age_text = str(int(age or 0))
    except Exception:
        age_text = str(age or '').strip()
    gender_text = ' '.join(str(gender or '').strip().casefold().split())
    return name_text, age_text, gender_text


def _fixed416_record_identity(record: dict) -> tuple[str, str, str]:
    if not isinstance(record, dict):
        return '', '', ''
    participant = {}
    results = record.get('results') if isinstance(record.get('results'), dict) else {}
    for payload in results.values():
        if isinstance(payload, dict) and isinstance(payload.get('participant'), dict):
            participant = payload.get('participant')
            break
    return _fixed416_norm_identity(
        record.get('name', participant.get('name', '')),
        record.get('age', participant.get('age', '')),
        record.get('gender', participant.get('gender', '')),
    )


def _fixed416_profile_from_record(record: dict) -> UserProfile | None:
    if not isinstance(record, dict):
        return None
    name = str(record.get('name', '')).strip()
    gender = str(record.get('gender', '')).strip() or 'Не указан'
    try:
        age = int(record.get('age', 0) or 0)
    except Exception:
        age = 0
    if not name:
        return None
    return UserProfile(name=name, age=age, gender=gender)


def _fixed416_card_key(profile: UserProfile, record: dict) -> str:
    key = str(record.get(_FIXED416_SUMMARY_KEY, '') if isinstance(record, dict) else '').strip()
    return key or profile.key


def _fixed416_light_result_stub(code: str, session_id: str = '', completed_at: str = '') -> dict:
    return {
        'test_code': str(code or '').upper(),
        'session_id': str(session_id or ''),
        'completed_at': str(completed_at or ''),
        '_fixed416_summary_only': True,
    }


def _fixed416_all_user_summaries(store: UserProgressStore) -> list[tuple[UserProfile, dict]]:
    data = store._load()
    if not isinstance(data, dict):
        data = {}
    summaries: dict[str, dict] = {}
    identity_to_key: dict[tuple[str, str, str], str] = {}

    def _ensure_summary(profile: UserProfile, storage_key: str) -> dict:
        identity = _fixed416_norm_identity(profile.name, profile.age, profile.gender)
        key = identity_to_key.get(identity) or storage_key or profile.key
        item = summaries.get(key)
        if item is None:
            item = {
                'name': profile.name,
                'age': profile.age,
                'gender': profile.gender,
                'completed_tests': [],
                'results': {},
                'updated_at': '',
                _FIXED416_SUMMARY_KEY: key,
            }
            summaries[key] = item
            if identity[0]:
                identity_to_key[identity] = key
        return item

    for storage_key, record in data.items():
        if not isinstance(record, dict):
            continue
        profile = _fixed416_profile_from_record(record)
        if profile is None:
            continue
        item = _ensure_summary(profile, str(storage_key))
        item['updated_at'] = str(record.get('updated_at', '') or '')
        completed = []
        for code in record.get('completed_tests', []) if isinstance(record.get('completed_tests', []), list) else []:
            code = str(code).upper()
            if code in TEST_ORDER and code not in completed:
                completed.append(code)
        results = record.get('results') if isinstance(record.get('results'), dict) else {}
        for code in TEST_ORDER:
            payload = results.get(code)
            if isinstance(payload, dict):
                if code not in completed:
                    completed.append(code)
                item['results'][code] = _fixed416_light_result_stub(
                    code,
                    payload.get('session_id', ''),
                    payload.get('completed_at', ''),
                )
        item['completed_tests'] = [code for code in TEST_ORDER if code in completed]

    csv_path = store.base_dir / 'data' / 'participants.csv'
    if csv_path.exists():
        try:
            with open(csv_path, 'r', encoding='utf-8-sig', newline='') as f:
                reader = csv.reader(f, delimiter=';')
                header = None
                for row in reader:
                    if not row:
                        continue
                    first = str(row[0]).strip()
                    if first == 'Дата':
                        header = row
                        continue
                    if first == 'Неделя' or not header:
                        continue
                    if len(row) < len(header):
                        row = row + [''] * (len(header) - len(row))
                    item = {str(header[i]).strip(): row[i] for i in range(min(len(header), len(row)))}
                    name = str(item.get('ФИО') or item.get('Имя') or '').strip()
                    if not name:
                        continue
                    try:
                        age = int(str(item.get('Возраст', '0')).strip() or 0)
                    except Exception:
                        age = 0
                    gender = str(item.get('Пол', '')).strip() or 'Не указан'
                    profile = UserProfile(name=name, age=age, gender=gender)
                    summary = _ensure_summary(profile, profile.key)
                    stamp = _fixed285_csv_stamp_to_iso(item.get('Дата', ''), item.get('Время', ''))
                    if stamp and stamp > str(summary.get('updated_at', '') or ''):
                        summary['updated_at'] = stamp
                    code = _fixed285_csv_test_code(item.get('Тест', ''))
                    if code is None:
                        continue
                    event_type = str(item.get('Событие', '')).strip().casefold()
                    action = str(item.get('Действие', '')).strip().casefold()
                    completed = (
                        (event_type == 'summary' and action == 'session_finished')
                        or (event_type == 'method_session' and action in ('completed', 'finished'))
                    )
                    if completed:
                        completed_tests = list(summary.get('completed_tests', []) or [])
                        if code not in completed_tests:
                            completed_tests.append(code)
                        summary['completed_tests'] = [c for c in TEST_ORDER if c in completed_tests]
                        summary.setdefault('results', {})[code] = _fixed416_light_result_stub(
                            code,
                            item.get('SessionID', ''),
                            stamp,
                        )
        except Exception:
            pass

    items = []
    for record in summaries.values():
        profile = _fixed416_profile_from_record(record)
        if profile is not None:
            items.append((profile, record))
    items.sort(key=lambda item: (item[0].name.casefold(), item[0].age, item[0].gender.casefold()))
    items.sort(key=lambda item: str(item[1].get('updated_at', '') or ''), reverse=True)
    return items


def _fixed416_remove_participants_rows_for_records(base_dir: Path, records: list[dict]) -> int:
    identities = {_fixed416_record_identity(record) for record in records if isinstance(record, dict)}
    identities = {item for item in identities if item[0]}
    if not identities:
        return 0
    csv_path = Path(base_dir) / 'data' / 'participants.csv'
    if not csv_path.exists():
        return 0
    try:
        with open(csv_path, 'r', encoding='utf-8-sig', newline='') as f:
            rows = list(csv.reader(f, delimiter=';'))
    except Exception:
        return 0

    kept = []
    removed = 0
    header = None
    for row in rows:
        if not row:
            kept.append(row)
            continue
        first = str(row[0]).strip()
        if first == 'Дата':
            header = row
            kept.append(row)
            continue
        if first == 'Неделя' or not header:
            kept.append(row)
            continue
        padded = row + [''] * max(0, len(header) - len(row))
        item = {str(header[i]).strip(): padded[i] for i in range(min(len(header), len(padded)))}
        identity = _fixed416_norm_identity(
            item.get('ФИО') or item.get('Имя') or '',
            item.get('Возраст', ''),
            item.get('Пол', ''),
        )
        if identity in identities:
            removed += 1
            continue
        kept.append(row)
    if not removed:
        return 0
    try:
        temp = csv_path.with_suffix('.tmp')
        with open(temp, 'w', encoding='utf-8-sig', newline='') as f:
            writer = csv.writer(f, delimiter=';')
            writer.writerows(kept)
        temp.replace(csv_path)
    except Exception:
        return 0
    return removed


def _fixed265_open_calendar_picker(owner: tk.Widget, current_value: str, on_pick):
    import calendar as _calendar
    from datetime import date as _date, datetime as _dt

    try:
        base = _dt.strptime(str(current_value).strip(), '%Y-%m-%d').date()
    except Exception:
        base = _date.today()

    shown = {'y': int(base.year), 'm': int(base.month)}

    pop = tk.Toplevel(owner)
    pop.title('Выбор даты')
    pop.configure(bg='white')
    pop.transient(owner.winfo_toplevel())
    pop.resizable(False, False)
    pop.grab_set()

    head = tk.Frame(pop, bg='white')
    head.pack(fill='x', padx=8, pady=(8, 4))
    body = tk.Frame(pop, bg='white')
    body.pack(fill='both', expand=True, padx=8, pady=(0, 8))
    foot = tk.Frame(pop, bg='white')
    foot.pack(fill='x', padx=8, pady=(0, 8))

    month_label = tk.Label(head, text='', bg='white', fg='#102744', font=('Arial', 11, 'bold'))
    month_label.pack(side='left', expand=True)

    def _set_date(y: int, m: int, d: int):
        try:
            selected = f"{int(y):04d}-{int(m):02d}-{int(d):02d}"
            on_pick(selected)
        finally:
            try:
                pop.destroy()
            except Exception:
                pass

    def _shift_month(delta: int):
        y = shown['y']
        m = shown['m'] + delta
        if m < 1:
            m = 12
            y -= 1
        elif m > 12:
            m = 1
            y += 1
        shown['y'], shown['m'] = y, m
        _render()

    tk.Button(
        head, text='◀', command=lambda: _shift_month(-1),
        bg='#eef3f8', activebackground='#e2eaf3', fg='#102744',
        relief='raised', bd=1, font=('Arial', 10, 'bold'), padx=6
    ).pack(side='left')
    tk.Button(
        head, text='▶', command=lambda: _shift_month(1),
        bg='#eef3f8', activebackground='#e2eaf3', fg='#102744',
        relief='raised', bd=1, font=('Arial', 10, 'bold'), padx=6
    ).pack(side='right')

    def _render():
        for w in body.winfo_children():
            w.destroy()
        y = shown['y']
        m = shown['m']
        month_label.configure(text=f"{_calendar.month_name[m].capitalize()} {y}")
        names = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс']
        for c, nm in enumerate(names):
            tk.Label(body, text=nm, bg='white', fg='#42546c', font=('Arial', 9, 'bold'), width=4).grid(row=0, column=c, padx=1, pady=(0, 2))
        first_wday, days_count = _calendar.monthrange(y, m)  # Monday=0
        r, c = 1, 0
        for _ in range(first_wday):
            tk.Label(body, text=' ', bg='white', width=4).grid(row=r, column=c, padx=1, pady=1)
            c += 1
        for day in range(1, days_count + 1):
            is_today = (_date.today().year == y and _date.today().month == m and _date.today().day == day)
            tk.Button(
                body,
                text=str(day),
                command=lambda d=day: _set_date(y, m, d),
                bg=('#dff3e4' if is_today else '#ffffff'),
                activebackground='#d7e8fb',
                fg='#102744',
                relief='raised',
                bd=1,
                font=('Arial', 9, 'bold' if is_today else 'normal'),
                width=4,
                padx=0,
                pady=2,
            ).grid(row=r, column=c, padx=1, pady=1)
            c += 1
            if c > 6:
                c = 0
                r += 1

    tk.Button(
        foot,
        text='Сегодня',
        command=lambda: _set_date(_date.today().year, _date.today().month, _date.today().day),
        bg='#49d65b',
        activebackground='#39c84c',
        fg='#102744',
        relief='raised',
        bd=2,
        font=('Arial', 10, 'bold'),
        padx=10,
        pady=4,
    ).pack(side='left')
    tk.Button(
        foot,
        text='Закрыть',
        command=pop.destroy,
        bg='#eef3f8',
        activebackground='#e2eaf3',
        fg='#102744',
        relief='raised',
        bd=2,
        font=('Arial', 10, 'bold'),
        padx=10,
        pady=4,
    ).pack(side='right')

    _render()
    pop.update_idletasks()
    try:
        owner_top = owner.winfo_toplevel()
        x = owner_top.winfo_rootx() + 80
        y = owner_top.winfo_rooty() + 120
        pop.geometry(f"+{max(20, x)}+{max(20, y)}")
    except Exception:
        pass


