        def _confirm_delete():
            data = self.progress_store._load()
            if not isinstance(data, dict):
                data = {}
            removed = 0
            files_to_delete: set[Path] = set(delete_files)
            records_for_excel = []
            records_for_csv = []
            for key in keys:
                if isinstance(data.get(key), dict):
                    record = data.get(key, {})
                    files, _session_ids = _collect_record_delete_targets(record)
                    files_to_delete.update(files)
                    records_for_excel.append(record)
                    records_for_csv.append(record)
                elif isinstance(visible_records.get(key), dict):
                    records_for_excel.append(visible_records.get(key, {}))
                    records_for_csv.append(visible_records.get(key, {}))
                if key in data:
                    data.pop(key, None)
                    removed += 1
            if removed:
                self.progress_store._save(data)
            if records_for_excel:
                _fixed417_delete_records_from_integrated_excel(self.base_dir, records_for_excel)
            _fixed416_remove_participants_rows_for_records(self.base_dir, records_for_csv)
            deleted_files = 0
            for path in sorted(files_to_delete, key=lambda p: str(p).casefold()):
                try:
                    if path.exists() and path.is_file():
                        path.unlink()
                        deleted_files += 1
                except Exception:
                    pass
            selected_keys.clear()
            records_state['records'] = _fixed416_all_user_summaries(self.progress_store)
            confirm.destroy()
