# ====== FIXED268: optional joystick control for Method A (fallback to mouse) ======
_FIXED268_METHOD_A_JOYSTICK_VERSION = 'fixed268_method_a_joystick_optional_v1'
_fixed268_prev_method_a_init = MethodAApp.__init__
_fixed268_prev_read_runtime_events = MethodAApp.read_runtime_events
_fixed268_prev_handle_control = MethodAApp.handle_control


def _fixed268_joy_event_types() -> tuple[int, int]:
    return (getattr(pygame, 'JOYDEVICEADDED', -1), getattr(pygame, 'JOYDEVICEREMOVED', -1))


def _fixed268_joystick_instance_id(joy) -> int | None:
    if joy is None:
        return None
    for getter in ('get_instance_id', 'get_id'):
        fn = getattr(joy, getter, None)
        if callable(fn):
            try:
                return int(fn())
            except Exception:
                continue
    return None




def _fixed268_method_a_init(self, cfg: MethodAConfig, session: SessionInfo, logger: ParticipantsLogger, base_dir: Path):
    _fixed268_prev_method_a_init(self, cfg, session, logger, base_dir)
    self._joy_requested = _fixed275_to_bool(getattr(self.cfg, 'enable_joystick', False))
    self._joy = None
    self._joy_instance_id = None
    self._joy_name = ''
    self._joy_enabled = False
