# ====== FIXED292: Method A crash trigger for stages 2/3 uses circular XY boundary ======
_FIXED292_METHOD_A_CRASH_CIRCLE_VERSION = 'fixed292_method_a_crash_circle_xy_v1'


def _fixed292_method_a_in_crash_zone(self, state: DriftState, stage_no: int) -> bool:
    stage = self.stage_defs[int(stage_no)]
    use_x = bool(stage.get('x'))
    use_y = bool(stage.get('y'))
    use_z = bool(stage.get('z'))

    # Stage 2 and 3: XY crash check must match the drawn circle boundary.
    if use_x and use_y:
        hit_xy = math.hypot(float(getattr(state, 'x_px', 0.0)), float(getattr(state, 'y_px', 0.0))) > float(self.work_half_px)
    else:
        hit_x = use_x and abs(float(getattr(state, 'x_px', 0.0))) > float(self.work_half_px)
        hit_y = use_y and abs(float(getattr(state, 'y_px', 0.0))) > float(self.work_half_px)
        hit_xy = bool(hit_x or hit_y)

    if use_z:
        roll_crash_deg = max(1.0, float(getattr(self.cfg, 'work_roll_deg', 90.0) or 90.0))
        hit_z = abs(float(getattr(state, 'roll_deg', 0.0))) >= roll_crash_deg
        return bool(hit_xy or hit_z)
    return bool(hit_xy)


MethodAApp.in_crash_zone = _fixed292_method_a_in_crash_zone


# ====== FIXED293: safer circle crash-check (stages 2/3) with robust guards ======
_FIXED293_METHOD_A_CRASH_CIRCLE_VERSION = 'fixed293_method_a_crash_circle_xy_safe_v1'
_fixed293_prev_in_crash_zone = MethodAApp.in_crash_zone


def _fixed293_method_a_in_crash_zone(self, state: DriftState, stage_no: int) -> bool:
    try:
        stage_map = getattr(self, 'stage_defs', {}) or {}
        stage = stage_map.get(int(stage_no), {})
        use_x = bool(stage.get('x'))
        use_y = bool(stage.get('y'))
        use_z = bool(stage.get('z'))

        px_per_cm = max(1e-6, float(getattr(self.cfg, 'px_per_cm', 38.0) or 38.0))
        crash_x_px = max(1e-6, float(getattr(self.cfg, 'r_crash_x_cm', 18.0) or 18.0) * px_per_cm)
        crash_y_px = max(1e-6, float(getattr(self.cfg, 'r_crash_y_cm', 18.0) or 18.0) * px_per_cm)
        if crash_x_px <= 0.0 or crash_y_px <= 0.0:
            return bool(_fixed293_prev_in_crash_zone(self, state, stage_no))

        x_px = float(getattr(state, 'x_px', 0.0) or 0.0)
        y_px = float(getattr(state, 'y_px', 0.0) or 0.0)

        # Stage 2/3: an ellipse uses the independently configured X/Y crash
        # radii.  With equal radii this is the same circular boundary as drawn.
        if use_x and use_y:
            hit_xy = math.hypot(x_px / crash_x_px, y_px / crash_y_px) >= 1.0
        else:
            hit_x = use_x and abs(x_px) >= crash_x_px
            hit_y = use_y and abs(y_px) >= crash_y_px
            hit_xy = bool(hit_x or hit_y)

        hit_z = False
        if use_z:
            roll_crash_deg = max(1.0, float(getattr(self.cfg, 'work_roll_deg', 90.0) or 90.0))
            hit_z = abs(float(getattr(state, 'roll_deg', 0.0) or 0.0)) >= roll_crash_deg

        return bool(hit_xy or hit_z)
    except Exception:
        return bool(_fixed293_prev_in_crash_zone(self, state, stage_no))


MethodAApp.in_crash_zone = _fixed293_method_a_in_crash_zone


# ====== FIXED294: robust Method A start (no app drop on stage-1 startup errors) ======
_FIXED294_METHOD_A_START_GUARD_VERSION = 'fixed294_method_a_start_guard_v1'


def _fixed294_write_method_a_error(base_dir: Path, session: SessionInfo, caption: str, exc: Exception) -> Path | None:
    try:
        # Save near the running executable/script so logs exist on any PC.
        out_dir = _runtime_app_dir()
        out_dir.mkdir(parents=True, exist_ok=True)
        stamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        sid = str(getattr(session, 'session_id', 'unknown') or 'unknown')
        path = out_dir / f'method_a_start_error_{stamp}_{sid}.txt'
        body = [
            f'caption: {caption}',
            f'time: {datetime.now().isoformat()}',
            f'session_id: {sid}',
            f'error_type: {type(exc).__name__}',
            f'error: {exc}',
            '',
            traceback.format_exc(),
        ]
        path.write_text('\n'.join(body), encoding='utf-8')
        return path
    except Exception:
        return None


def _fixed294_run_method_a(self, session: SessionInfo) -> dict:
    try:
        _ensure_pygame()
    except Exception as exc:
        messagebox.showerror(
            'Тест A недоступен',
            'Не удалось загрузить модуль pygame.\n'
            'Остальные экраны программы работают, но Тест A сейчас запустить нельзя.\n\n'
            f'Ошибка: {exc}'
        )
        return {'completed': False, 'reports': []}

    result = {'completed': False, 'reports': []}
    self.set_enabled(False)
    self.root.update_idletasks()
    self.root.withdraw()

    fallback_used = False
    start_error_log: Path | None = None
    start_error_text = ''
    try:
        cfg = load_config(
            path=self.base_dir / 'method_a_config.json',
            screen_w=self.root.winfo_screenwidth(),
            screen_h=self.root.winfo_screenheight(),
        )

        try:
            result = MethodAApp(cfg, session, self.logger, self.base_dir).run()
        except Exception as exc_first:
            start_error_log = _fixed294_write_method_a_error(self.base_dir, session, 'primary_start', exc_first)
            # Safety fallback: some driver stacks crash on joystick path at stage start.
            if bool(getattr(cfg, 'enable_joystick', False)):
                try:
                    cfg.enable_joystick = False
                    result = MethodAApp(cfg, session, self.logger, self.base_dir).run()
                    fallback_used = True
                except Exception as exc_second:
                    start_error_log = _fixed294_write_method_a_error(self.base_dir, session, 'fallback_without_joystick', exc_second)
                    start_error_text = str(exc_second)
                    result = {'completed': False, 'reports': []}
            else:
                start_error_text = str(exc_first)
                result = {'completed': False, 'reports': []}
    finally:
        self.root.deiconify()
        self.open_fullscreen()
        self.root.update_idletasks()
        try:
            self.root.focus_force()
        except Exception:
            pass

    if result.get('reports'):
        payload = self.build_method_a_payload(session, result)
        payload['completed'] = bool(result.get('completed'))
        self.progress_store.save_test_result(self.current_profile, 'A', payload)

    if fallback_used:
        messagebox.showwarning(
            'Тест A: запуск с защитой',
            'Первичный запуск завершился ошибкой, тест автоматически перезапущен без джойстика.\n'
            'Проверка продолжена в режиме мыши.'
        )

    if result.get('completed'):
        self.logger.log_event(session, event_type='summary', screen='test_menu', test_name='method_a', action='session_finished', value=len(result.get('reports', [])), note='Методика А завершена, данные добавлены в participants.csv и user_progress.json')
        self.menu_status_var.set('Тест А завершён. Его результат можно открыть из меню.')
        messagebox.showinfo('Готово', f'Тест А завершён.\nОбщий файл: {self.logger.data_file}\nРезультат сохранён и доступен из меню.')
    else:
        if start_error_text:
            extra = f'\n\nТехническая ошибка: {start_error_text}'
            if start_error_log is not None:
                extra += f'\nЛог: {start_error_log}'
            messagebox.showerror('Тест A остановлен', 'Во время запуска/выполнения произошла ошибка.' + extra)
            self.menu_status_var.set('Тест А остановлен из-за ошибки запуска. Лог сохранён.')
        else:
            self.menu_status_var.set('Тест А был прерван. Уже выполненные этапы сохранены и доступны в результатах.')
            if result.get('reports'):
                messagebox.showwarning('Остановлено', 'Тест А был прерван.\nЧастично выполненные этапы сохранены и доступны в результатах.')
            else:
                messagebox.showwarning('Остановлено', 'Тест А был прерван до появления данных.')

    self.set_enabled(True)
    self.refresh_menu_state()
    return result


