def _fixed297_get_research_section_groups(code: str, cls):
    groups = _fixed297_prev_get_research_section_groups(code, cls)
    filtered = []
    for title, names in groups:
        cleaned = [name for name in names if name != 'enable_joystick']
        if cleaned:
            filtered.append((title, cleaned))
