# ====== FIXED298: hard mouse-only control path for Method A ======
_FIXED298_MOUSE_ONLY_VERSION = 'fixed298_method_a_hard_mouse_only_v1'


def _fixed298_method_a_init(self, cfg: MethodAConfig, session: SessionInfo, logger: ParticipantsLogger, base_dir: Path):
    try:
        cfg.enable_joystick = False
    except Exception:
        pass
    # Initialize from pre-joystick init chain to avoid joystick side effects.
    if '_fixed268_prev_method_a_init' in globals():
        _fixed268_prev_method_a_init(self, cfg, session, logger, base_dir)
    else:
        _fixed297_prev_method_a_init(self, cfg, session, logger, base_dir)
    self._joy_requested = False
    self._joy_enabled = False
    self._joy = None


def _fixed298_method_a_read_runtime_events(self) -> int:
    wheel_delta = 0
    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            raise MethodAAbort
        if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
            raise MethodAAbort
        if event.type == pygame.MOUSEWHEEL:
            wheel_delta += int(getattr(event, 'y', 0) or 0)
        elif event.type == pygame.MOUSEBUTTONDOWN:
            if int(getattr(event, 'button', 0) or 0) == 4:
                wheel_delta += 1
            elif int(getattr(event, 'button', 0) or 0) == 5:
                wheel_delta -= 1
    return wheel_delta


def _fixed298_method_a_handle_control(self, state: DriftState, stage_no: int, wheel_delta: int):
    stage = self.stage_defs[int(stage_no)]
    rel_x, rel_y = pygame.mouse.get_rel()
    if bool(stage.get('x')):
        state.x_px -= float(rel_x) * float(self.cfg.mouse_gain_px)
    if bool(stage.get('y')):
        state.y_px -= float(rel_y) * float(self.cfg.mouse_gain_px)
    if bool(stage.get('z')) and int(wheel_delta):
        state.roll_deg -= float(wheel_delta) * float(self.cfg.roll_step_per_wheel_notch_deg)


MethodAApp.__init__ = _fixed298_method_a_init
MethodAApp.read_runtime_events = _fixed298_method_a_read_runtime_events
MethodAApp.handle_control = _fixed298_method_a_handle_control


# ====== FIXED301: Method C screen changes only by pressing "Далее" ======
def _fixed301_method_c_set_controls(self, input_enabled: bool):
    answer_btn = getattr(self, 'answer_btn', None)
    clear_btn = getattr(self, 'clear_btn', None)
    keypad = getattr(self, '_method_c_keypad', None)
    place_cfg = getattr(self, '_method_c_keypad_place', None) or {}

    if answer_btn is not None:
        try:
            answer_btn.configure(text='Далее', state='normal')
        except Exception:
            pass

    if clear_btn is not None:
        try:
            clear_btn.configure(state='normal' if input_enabled else 'disabled')
        except Exception:
            pass

    for widget in getattr(self, '_method_c_input_widgets', []):
        if widget is None or widget is answer_btn or widget is clear_btn:
            continue
        try:
            widget.configure(state='normal' if input_enabled else 'disabled')
        except Exception:
            pass

    if keypad is not None:
        try:
            if input_enabled:
                keypad.place(
                    x=place_cfg.get('x', 0),
                    y=place_cfg.get('y', 0),
                    anchor=place_cfg.get('anchor', 'n')
                )
            else:
                keypad.place_forget()
        except Exception:
            pass

    try:
        if input_enabled:
            self.entry.configure(state='normal')
            self.entry.focus_set()
            self.entry.selection_range(0, tk.END)
        else:
            self.entry.configure(state='readonly')
    except Exception:
        pass


def _fixed301_method_c_fit_prompt(self):
    prompt_label = getattr(self, 'prompt_label', None)
    if prompt_label is None:
        return
    strip = getattr(prompt_label, 'master', None)
    if strip is None:
        return
    try:
        scale = float(_fixed88_screen_metrics(self.win)[2])
    except Exception:
        scale = 1.0
    text = ''
    try:
        text = str(self.prompt_var.get() or '')
    except Exception:
        text = ''
    long_text = ('\n' in text) or (len(text) >= 38)
    strip_h = max(96, int((138 if long_text else 104) * scale))
    try:
        strip.place_configure(height=strip_h)
    except Exception:
        pass
    try:
        strip.configure(height=strip_h)
    except Exception:
        pass
    try:
        prompt_label.configure(
            wraplength=max(420, int(getattr(self, '_display_wrap', 720) * 0.98)),
            anchor='center',
            justify='center',
        )
        prompt_label.pack_configure(pady=(6, 6))
    except Exception:
        pass
    try:
        if getattr(self, 'win', None) is not None:
            self.win.update_idletasks()
    except Exception:
        pass
    # Keep prompt block above and separated from the numeric display block.
    display_box = getattr(self, '_display_box', None)
    if display_box is not None:
        try:
            strip_y = int(strip.place_info().get('y', strip.winfo_y()))
        except Exception:
            strip_y = 0
        try:
            strip_h_now = int(strip.place_info().get('height', strip.winfo_height()))
        except Exception:
            strip_h_now = strip_h
        try:
            display_h = int(display_box.place_info().get('height', display_box.winfo_height()))
        except Exception:
            display_h = max(180, int(210 * scale))
        try:
            display_y = int(display_box.place_info().get('y', display_box.winfo_y()))
        except Exception:
            display_y = int(display_box.winfo_y() + display_h / 2)
        min_display_y = strip_y + strip_h_now + max(26, int(34 * scale)) + int(display_h / 2)
        if display_y < min_display_y:
            try:
                display_box.place_configure(y=min_display_y)
            except Exception:
                pass
    try:
        strip.lift()
        prompt_label.lift()
    except Exception:
        pass


def _fixed301_method_c_start_stage(self, stage_index: int):
    self._cancel_afters()
    self.stage_index = stage_index
    if stage_index > 3:
        self._finish()
        return
    lo, hi = self._stage_limits(stage_index)
    self.exp_s = float(self.cfg.exposure_start_s[self.stage_index - 1])
    self.input_s = float(self.cfg.input_start_s[self.stage_index - 1])
    self.current_value = random.randint(lo, hi)
    self.stage_start_at = time.perf_counter()
    self.stage_records[stage_index] = {'cycles': [], 'Gq': 0, 'Fq': 0}
    self.phase = 'stage_ready'
    self._fixed301_next_action = 'start_cycle'

    if '_fixed150_method_c_feedback_clear' in globals():
        try:
            _fixed150_method_c_feedback_clear(self)
        except Exception:
            pass

    self.prompt_var.set(f'Этап {stage_index}.')
    _fixed301_method_c_fit_prompt(self)
    self.big_var.set('')
    try:
        self.big_label.configure(fg='#228b22')
    except Exception:
        pass
    self.entry_var.set('')
    _fixed301_method_c_set_controls(self, False)
    self._tick_stage_clock()


def _fixed301_method_c_start_operation_cycle(self):
    self._cancel_afters()
    if hasattr(self, "_fixed193_total_time_left") and self._fixed193_total_time_left() <= 0.05:
        self._finish()
        return
    if hasattr(self, "_fixed193_should_advance_stage") and self._fixed193_should_advance_stage():
        self.phase = 'stage_done'
        self._fixed301_next_action = 'next_stage'
        self.prompt_var.set(f'Этап {self.stage_index} завершён. Нажмите «Далее» для перехода к следующему этапу.')
        _fixed301_method_c_fit_prompt(self)
        self.big_var.set(str(self.current_value))
        self.entry_var.set(str(self.current_value))
        _fixed301_method_c_set_controls(self, False)
        self._tick_stage_clock()
        return

    self.phase = 'show_operand'
    self.current_op, self.current_operand, self.current_correct = self._generate_operand(self.current_value, self.stage_index)
    self.current_cycle_started_at = time.perf_counter()
    self._fixed301_next_action = 'begin_input'

    if '_fixed150_method_c_feedback_clear' in globals():
        try:
            _fixed150_method_c_feedback_clear(self)
        except Exception:
            pass

    color = '#228b22' if self.current_op == '+' else '#c93232'
    action = 'прибавьте' if self.current_op == '+' else 'вычтите'
    self.prompt_var.set(
        f'Используйте текущее число {self.current_value} как исходный результат. '
        f'{action.capitalize()} показанное число и нажмите «Далее».'
    )
    _fixed301_method_c_fit_prompt(self)
    self.big_var.set(str(self.current_operand))
    try:
        self.big_label.configure(fg=color)
    except Exception:
        pass
    self.entry_var.set(str(self.current_operand))
    _fixed301_method_c_set_controls(self, False)
    self._tick_stage_clock()


def _fixed301_method_c_begin_input_phase(self):
    if hasattr(self, "_fixed193_total_time_left") and self._fixed193_total_time_left() <= 0.05:
        self._finish()
        return
    self._cancel_afters()
    self.phase = 'input'
    self._fixed301_next_action = None
    self.prompt_var.set('Введите новый результат вычисления и нажмите «Далее».')
    _fixed301_method_c_fit_prompt(self)
    self.entry_var.set('')
    self.big_var.set('')
    try:
        self.big_label.configure(fg='#163d7a')
    except Exception:
        pass
    _fixed301_method_c_set_controls(self, True)
    self.input_deadline = 0.0
    self._tick_stage_clock()






def _fixed301_method_c_tick_input_timeout(self):
    # In fixed301 all transitions in Method C happen only via "Далее".
    return


MethodCWindow._start_stage = _fixed301_method_c_start_stage
MethodCWindow._start_operation_cycle = _fixed301_method_c_start_operation_cycle
MethodCWindow._begin_input_phase = _fixed301_method_c_begin_input_phase
MethodCWindow._tick_input_timeout = _fixed301_method_c_tick_input_timeout


# ====== FIXED302: Method B aligned to memory doc (click-click flow, 5 min default, clean config) ======
_FIXED302_METHOD_B_CALC_VERSION = 'fixed302_method_b_doc_memory_v1'


def _fixed302_method_b_pick_shape(self, shape_id: int):
    if str(getattr(self, 'phase', '') or '') != 'reproduce':
        return 'break'
    if shape_id in _fixed414_method_b_used_shapes(self):
        return 'break'
    self.selected_shape = shape_id
    self._draw_tray(show=True)
    self.selection_var.set('Фигура выбрана. Теперь щёлкните по свободной ячейке матрицы.')
    return 'break'






def _fixed302_method_b_on_matrix_cell(self, idx: int):
    if str(getattr(self, 'phase', '') or '') != 'reproduce':
        return
    if idx in self.placements:
        self.selection_var.set('Эта ячейка уже занята. Выберите свободную ячейку или нажмите «Очистить».')
        return
    shape_id = getattr(self, 'selected_shape', None)
    if shape_id is None:
        self.selection_var.set('Сначала выберите фигуру в кассе, затем щёлкните по свободной ячейке матрицы.')
        return
    if shape_id in _fixed414_method_b_used_shapes(self):
        self.selected_shape = None
        self._draw_tray(show=True)
        self.selection_var.set('Эта фигура уже размещена. Выберите другую в кассе.')
        return

    self.placements[idx] = shape_id
    self.selected_shape = None
    self._draw_reproduction_matrix()
    self._draw_tray(show=True)
    total = len(getattr(self, 'current_shapes', []))
    placed = len(self.placements)
    if placed >= total:
        self.selection_var.set('Все фигуры размещены. Проверьте матрицу и нажмите «Далее».')
    else:
        self.selection_var.set('Фигура поставлена. Выберите следующую фигуру в кассе.')


def _fixed302_method_b_clear_placements(self):
    if str(getattr(self, 'phase', '') or '') != 'reproduce':
        return
    self.placements = {}
    self.selected_shape = None
    self.available_shapes = list(getattr(self, 'current_shapes', []))
    self._draw_reproduction_matrix()
    self._draw_tray(show=True)
    self.selection_var.set('Выберите фигуру в кассе и затем свободную ячейку матрицы.')


def _fixed302_method_b_finalize_cycle(self, success: bool | None, reason: str):
    if str(getattr(self, 'phase', '') or '') != 'reproduce':
        return
    self._cancel_afters()
    success_eval, correct, expected = self._evaluate_cycle()
    if success is None:
        success = success_eval

    elapsed = time.perf_counter() - self.cycle_started_at
    n = len(expected)
    cycle_info = {
        'n': n,
        'success': bool(success),
        'correct_count': int(correct),
        'elapsed_s': _round2(elapsed),
        'reason': reason,
        'positions': list(self.current_positions),
        'shapes': list(self.current_shapes),
    }
    self.result['cycles'].append(cycle_info)
    self.logger.log_event(
        self.session,
        event_type='method_cycle',
        screen='method_b',
        test_name='method_b',
        stage=f'n={n}',
        action='success' if success else 'error',
        elapsed_ms=int(elapsed * 1000),
        value=correct,
        note=f'reason={reason}; placed={len(self.placements)}',
    )

    if success:
        self.current_n = min(self.cfg.max_items, self.current_n + 1)
    else:
        self.current_n = max(1, self.current_n - 1)

    if self._time_left_total() <= 1.0:
        self._finish()
        return
    self._start_cycle()


def _fixed302_method_b_compute_summary(self):
    cycles = self.result.get('cycles', [])
    max_cycle_n = max((int(c.get('n', 0) or 0) for c in cycles if isinstance(c, dict)), default=0)
    stage_count = max(1, int(getattr(self.cfg, 'max_items', 0) or 0), max_cycle_n)
    norm_list = list(getattr(self.cfg, 'normative_times', []) or [])
    if not norm_list:
        norm_list = [1.0]
    while len(norm_list) < stage_count:
        norm_list.append(float(norm_list[-1]))

    grouped_total = {n: 0 for n in range(1, stage_count + 1)}
    grouped_success = {n: 0 for n in range(1, stage_count + 1)}
    cycle_times = {n: [] for n in range(1, stage_count + 1)}
    for cyc in cycles:
        n = int(cyc.get('n', 0))
        if 1 <= n <= stage_count:
            grouped_total[n] += 1
            cycle_times[n].append(float(cyc.get('elapsed_s', 0.0)))
            if cyc.get('success'):
                grouped_success[n] += 1

    t_values = {}
    by_n = {}
    y_norm = max(1e-6, float(getattr(self.cfg, 'normative_success_coef', 1.0) or 1.0))
    for n in range(1, stage_count + 1):
        k_obsh = int(grouped_total[n])
        if k_obsh <= 0:
            continue
        t_avg = sum(cycle_times[n]) / max(1, len(cycle_times[n]))
        k_usp = int(grouped_success[n])
        gamma_n = _safe_ratio(k_usp, k_obsh, 0.0)  # Y этапа
        t_norm = float(norm_list[n - 1])
        if gamma_n >= (1.0 - 1e-9):
            u_prived = ((1.0 / y_norm) * math.sqrt((float(t_norm) / float(t_avg)))) if t_avg > 0 else 0.0
            t_n_zap = u_prived
        else:
            u_prived = 1.0
            t_n_zap = (gamma_n / y_norm)
        t_values[str(n)] = _round2(t_n_zap)
        by_n[str(n)] = {
            'k_usp': k_usp,
            'k_obsh': k_obsh,
            'gamma_n': _round2(gamma_n),
            'gamma_norm': _round2(y_norm),
            't_avg_s': _round2(t_avg),
            't_norm_s': _round2(t_norm),
            'u_prived': _round2(u_prived),
            't_n_zap': _round2(t_n_zap),
        }

    success_count = sum(1 for c in cycles if c.get('success'))
    max_correct = max((int(c.get('correct_count', 0)) for c in cycles), default=0)
    summary = {
        'cycles_total': len(cycles),
        'successful_cycles': success_count,
        'accuracy_pct': _round2(100.0 * success_count / max(1, len(cycles))),
        'max_correct_count': max_correct,
        'calculation_version': _FIXED302_METHOD_B_CALC_VERSION,
        't_values': t_values,
        'by_n': by_n,
        'tmin_b': t_values.get('4', 0.0),
        'tmedio_b': t_values.get('5', 0.0),
        'tmax_b': t_values.get('6', 0.0),
    }
    try:
        summary['total_time_s'] = _round2(float(getattr(self, '_elapsed_total', lambda: 0.0)()))
    except Exception:
        summary['total_time_s'] = 0.0
    return summary


