# ====== FIXED303: Method C calculations aligned to "СЧЕТ В АВТОТЕМПЕ" doc ======
_FIXED303_METHOD_C_CALC_VERSION = 'fixed351_method_c_gamma_times_avg_div_norm_v1'


def _fixed303_method_c_resolve_cycle(self, success: bool, timeout: bool, given: int | None = None):
    if getattr(self, 'phase', '') not in ('input', 'show_operand'):
        return
    self._cancel_afters()
    stage = self.stage_records.setdefault(self.stage_index, {'cycles': [], 'Gq': 0, 'Fq': 0})
    elapsed = time.perf_counter() - self.current_cycle_started_at
    stage['Gq'] += 1
    cycle_item = {
        'operand': self.current_operand,
        'op': self.current_op,
        'start_value': self.current_value,
        'correct_value': self.current_correct,
        'given_value': given,
        'success': bool(success),
        'elapsed_s': _round2(elapsed),
        'exp_s': _round2(float(getattr(self, 'exp_s', 0.0) or 0.0)),
        'input_s': _round2(float(getattr(self, 'input_s', 0.0) or 0.0)),
        'timeout': bool(timeout),
    }
    if success:
        stage['Fq'] += 1
    stage['cycles'].append(cycle_item)

    self.logger.log_event(
        self.session,
        event_type='method_cycle',
        screen='method_c',
        test_name='method_c',
        stage=f'stage_{self.stage_index}',
        action='success' if success else 'error',
        elapsed_ms=int(elapsed * 1000),
        value=self.current_correct,
        note=f'given={given}; timeout={int(timeout)}; op={self.current_op}{self.current_operand}',
    )

    # AUTOTEMPO: no forced cycle-time adaptation after success/error.
    self.current_value = self.current_correct
    if success:
        self.prompt_var.set('Верно. Нажмите «Далее», чтобы продолжить.')
        _fixed301_method_c_fit_prompt(self)
        if '_fixed150_method_c_feedback_clear' in globals():
            try:
                _fixed150_method_c_feedback_clear(self)
            except Exception:
                pass
    else:
        self.prompt_var.set(f'Ошибка, правильный результат {self.current_correct}. Нажмите «Далее».')
        _fixed301_method_c_fit_prompt(self)
        if '_fixed150_method_c_feedback_clear' in globals():
            try:
                _fixed150_method_c_feedback_clear(self)
            except Exception:
                pass

    self.big_var.set(str(self.current_correct))
    try:
        self.big_label.configure(fg='#228b22')
    except Exception:
        pass
    self.entry_var.set(str(self.current_correct))
    self.phase = 'feedback'
    self._fixed301_next_action = 'next_cycle'
    _fixed301_method_c_set_controls(self, False)
    self._tick_stage_clock()


def _fixed303_method_c_compute_summary(self):
    stage_payload = {}
    y_norm = max(1e-6, float(getattr(self.cfg, 'normative_success_coef', 1.0) or 1.0))
    try:
        stage_error_norms = list(getattr(self.cfg, 'normative_stage_errors', []) or [])
    except Exception:
        stage_error_norms = []
    for stage_index in range(1, 4):
        rec = self.stage_records.get(stage_index, {'cycles': [], 'Gq': 0, 'Fq': 0})
        cycles = list(rec.get('cycles', []))
        cycle_times = [max(0.0, float(c.get('elapsed_s', 0.0) or 0.0)) for c in cycles]
        t_avg = (sum(cycle_times) / len(cycle_times)) if cycle_times else 0.0
        k_obsh = int(rec.get('Gq', 0) or 0)
        k_usp = int(rec.get('Fq', 0) or 0)
        gamma = _safe_ratio(k_usp, k_obsh, 0.0)  # Y этапа
        t_norm = max(0.0001, float(self.cfg.normative_cycle_times[stage_index - 1]))
        try:
            allowed_errors = max(0, int(stage_error_norms[stage_index - 1]))
        except Exception:
            allowed_errors = 0
        error_count = max(0, k_obsh - k_usp)
        errors_within_norm = k_obsh > 0 and error_count <= allowed_errors
        if errors_within_norm:
            t_base = _round2(((1.0 / y_norm) * math.sqrt((t_norm / t_avg))) if t_avg > 0 else 0.0)
            t_count = t_base
        else:
            t_base = 1.0
            t_count = _round2(gamma / y_norm)
        stage_payload[str(stage_index)] = {
            'digits': stage_index,
            'Gq': k_obsh,
            'Fq': k_usp,
            'Hq': _round2(gamma),
            'avg_cycle_time_s': _round2(t_avg),
            'k_obsh': k_obsh,
            'k_usp': k_usp,
            'gamma_count': _round2(gamma),
            'gamma_norm': _round2(y_norm),
            'errors_count': error_count,
            'normative_stage_errors': allowed_errors,
            'errors_within_norm': bool(errors_within_norm),
            't_avg_cycle_s': _round2(t_avg),
            't_norm_cycle_s': _round2(t_norm),
            't_base_value': t_base,
            't_value': t_count,
            'cycles': cycles,
        }

    summary = {
        'stages': stage_payload,
        'tmin_c': stage_payload['1']['t_value'],
        'tmedio_c': stage_payload['2']['t_value'],
        'tmax_c': stage_payload['3']['t_value'],
        'total_cycles': sum(stage_payload[s]['Gq'] for s in ('1', '2', '3')),
        'successful_cycles': sum(stage_payload[s]['Fq'] for s in ('1', '2', '3')),
        'calculation_version': _FIXED303_METHOD_C_CALC_VERSION,
    }
    try:
        total_cfg = float(getattr(self.cfg, 'total_test_s', 0.0) or 0.0)
        if total_cfg <= 0.0:
            total_cfg = float(sum(float(x) for x in (getattr(self.cfg, 'stage_time_s', [40.0, 40.0, 40.0]) or [40.0, 40.0, 40.0])))
        if hasattr(self, '_fixed193_total_time_left'):
            total_left = float(self._fixed193_total_time_left())
            summary['total_time_s'] = _round2(max(0.0, total_cfg - total_left))
        else:
            summary['total_time_s'] = _round2(float(getattr(self, 'total_time_s', 0.0) or 0.0))
    except Exception:
        summary['total_time_s'] = 0.0
    return summary








