# ====== FIXED308: Method C results table in Test-B style, 3 stage columns ======
def _fixed308_show_method_c_results(self, payload: dict):
    top, outer = _open_results_top(self, 'Результаты - Тест C. Счёт в заданном темпе')
    participant = payload.get('participant', {})
    summary = dict(payload.get('summary', {}) or {})
    stages = payload.get('stages') or summary.get('stages', {})

    completed_at = payload.get('completed_at', '')
    dt_label = completed_at.replace('T', ' ')[:19] if completed_at else 'не указано'

    def _stage(stage_key: str) -> dict:
        item = stages.get(stage_key, {}) if isinstance(stages, dict) else {}
        return item if isinstance(item, dict) else {}

    def _f4(v) -> str:
        try:
            return f"{float(v or 0.0):.4f}"
        except Exception:
            return "0.0000"

    def _f2(v) -> str:
        try:
            return f"{float(v or 0.0):.2f}"
        except Exception:
            return "0.00"

    def _i(v) -> str:
        try:
            return str(int(v or 0))
        except Exception:
            return "0"

    def _sec(v) -> str:
        try:
            return str(max(0, int(round(float(v or 0.0)))))
        except Exception:
            return "0"

    def _stage_elapsed_s(stage_item: dict) -> float:
        cycles = stage_item.get('cycles', [])
        if not isinstance(cycles, list):
            return 0.0
        return sum(max(0.0, float(c.get('elapsed_s', 0.0) or 0.0)) for c in cycles if isinstance(c, dict))

    def _draw_t_with_index(
        parent: tk.Widget,
        token: str,
        *,
        big_size: int,
        sub_size: int,
        fg: str = '#101010',
        bg: str = '#ffffff',
        centered: bool = False,
    ):
        txt = str(token or '')
        if not txt:
            tk.Label(parent, text='', bg=bg, fg=fg).pack()
            return
        first = txt[0]
        rest = txt[1:]
        row = tk.Frame(parent, bg=bg)
        if centered:
            row.pack(expand=True)
        else:
            row.pack(anchor='w')
        tk.Label(row, text=first, bg=bg, fg=fg, font=('Times New Roman', big_size, 'bold')).pack(side='left', anchor='n')
        if rest:
            tk.Label(row, text=rest, bg=bg, fg=fg, font=('Times New Roman', sub_size, 'bold')).pack(
                side='left', anchor='s', pady=(max(4, int(big_size * 0.36)), 0)
            )

    s1, s2, s3 = _stage('1'), _stage('2'), _stage('3')
    stage_items = [s1, s2, s3]
    stage_names = ['однозначные числа', 'двузначные числа', 'трехзначные числа']
    stage_colors = ['#67a9ff', '#53c26b', '#c98cff']
    stage_bottom_colors = ['#78d3e2', '#ffb35c', '#ef7070']

    # Normative cycle time must come from settings.
    norm_time_cfg = [None, None, None]
    try:
        cfg = load_method_c_config(self.base_dir)
        raw = list(getattr(cfg, 'normative_cycle_times', []) or [])
        while len(raw) < 3:
            raw.append(raw[-1] if raw else 0.0)
        norm_time_cfg = [float(raw[0]), float(raw[1]), float(raw[2])]
    except Exception:
        pass

    def _norm_time(stage_item: dict, idx1: int) -> float:
        cfg_val = norm_time_cfg[idx1 - 1] if 1 <= idx1 <= 3 else None
        if cfg_val is not None:
            return float(cfg_val)
        return float(stage_item.get('t_norm_cycle_s', 0.0) or 0.0)

    def _t_value(stage_item: dict, idx1: int) -> float:
        # Для совместимости со старыми сохранениями пересчитываем по формуле:
        # tприв = tнорм / tреал
        try:
            t_avg = float(stage_item.get('t_avg_cycle_s', stage_item.get('avg_cycle_time_s', 0.0)) or 0.0)
        except Exception:
            t_avg = 0.0
        t_norm = max(0.0001, _norm_time(stage_item, idx1))
        return (t_norm / t_avg) if t_avg > 0 else float(stage_item.get('t_base_value', 0.0) or 0.0)

    def _t_value_with_gamma(stage_item: dict, idx1: int) -> float:
        try:
            gamma = float(stage_item.get('gamma_count', 0.0) or 0.0)
        except Exception:
            gamma = 0.0
        return _t_value(stage_item, idx1) * gamma

    header = tk.Frame(outer, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec')
    header.pack(fill='x', padx=24, pady=(24, 10))
    tk.Frame(header, bg='#67a9ff', height=6).pack(fill='x')
    head_body = tk.Frame(header, bg='#ffffff')
    head_body.pack(fill='both', expand=True, padx=22, pady=(14, 12))
    tk.Label(head_body, text='Тест C   Счёт в автотемпе', bg='#ffffff', fg='#102744', font=('Times New Roman', 30, 'bold')).pack(anchor='w')
    subtitle = f"{participant.get('name', '')}, {participant.get('age', '')} лет, {participant.get('gender', '')}. Последнее завершение: {dt_label}."
    tk.Label(head_body, text=subtitle, bg='#ffffff', fg='#5a6678', font=('Arial', 10, 'bold'), wraplength=1160, justify='left').pack(anchor='w', pady=(4, 0))

    cards_row = tk.Frame(outer, bg='#eef3f8')
    cards_row.pack(fill='x', padx=24, pady=(0, 4))
    for idx in range(3):
        cards_row.grid_columnconfigure(idx, weight=1, uniform='c_fixed336_cards')
        card = tk.Frame(cards_row, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec')
        card.grid(row=0, column=idx, sticky='nsew', padx=(0 if idx == 0 else 2, 0))
        tk.Frame(card, bg=stage_colors[idx], height=4).pack(fill='x')
        body = tk.Frame(card, bg='#ffffff')
        body.pack(fill='both', expand=True, padx=10, pady=(8, 8))
        top_line = tk.Frame(body, bg='#ffffff')
        top_line.pack(fill='x')
        tk.Label(top_line, text=_f2(_t_value_with_gamma(stage_items[idx], idx + 1)), bg='#ffffff', fg='#102744', font=('Arial', 26, 'bold')).pack(side='left')
        t_wrap = tk.Frame(top_line, bg='#ffffff')
        t_wrap.pack(side='left', padx=(18, 0))
        _draw_t_with_index(t_wrap, f"tсчет {idx + 1}", big_size=42, sub_size=22, fg='#101010', bg='#ffffff')
        tk.Label(body, text=f"Этап {idx + 1}: {stage_names[idx]}", bg='#ffffff', fg='#5a6678', font=('Arial', 9)).pack(anchor='center', pady=(6, 0))

    stage_row = tk.Frame(outer, bg='#eef3f8')
    stage_row.pack(fill='x', padx=24, pady=(0, 12))
    for idx in range(3):
        stage_row.grid_columnconfigure(idx, weight=1, uniform='c_fixed336_stage')
        block = tk.Frame(stage_row, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec', height=116)
        block.grid(row=0, column=idx, sticky='nsew', padx=(0 if idx == 0 else 2, 0))
        block.grid_propagate(False)
        tk.Frame(block, bg=stage_bottom_colors[idx], height=3).pack(fill='x', side='top')
        center = tk.Frame(block, bg='#ffffff')
        center.pack(fill='both', expand=True)
        tk.Label(center, text=stage_names[idx], bg='#ffffff', fg='#111111', font=('Arial', 17, 'bold')).pack(
            expand=True, pady=(8, 8)
        )

    table_shell = tk.Frame(outer, bg='#eef3f8')
    table_shell.pack(fill='x', padx=24, pady=(0, 8))
    table = tk.Frame(table_shell, bg='white', highlightthickness=1, highlightbackground='#9c9c9c')
    table.pack(fill='x')

    for grp in range(3):
        base = grp * 3
        table.grid_columnconfigure(base + 0, weight=2, uniform='c_fixed336_tbl')
        table.grid_columnconfigure(base + 1, weight=1, uniform='c_fixed336_tbl')
        table.grid_columnconfigure(base + 2, weight=1, uniform='c_fixed336_tbl')

    yellow = '#ffd400'
    head_labels = ('НАЗВАНИЕ\nПАРАМЕТРА', 'ПАРАМЕТР\nразмерность', 'величина')
    for grp in range(3):
        base = grp * 3
        for j, htxt in enumerate(head_labels):
            tk.Label(
                table,
                text=htxt,
                bg=yellow,
                fg='#1a1a1a',
                font=('Arial', 10, 'bold'),
                bd=1,
                relief='solid',
                padx=4,
                pady=6,
                justify='left' if j == 0 else 'center',
                anchor='w' if j == 0 else 'center',
            ).grid(row=0, column=base + j, sticky='nsew')

    row_defs = [
        ('время этапа (сек)', lambda s, i: f"T{i}", lambda s, i: _sec(_stage_elapsed_s(s))),
        ('всего циклов', lambda s, i: f"kобщ {i}", lambda s, i: _i(s.get('k_obsh', 0))),
        ('из них верных', lambda s, i: f"kусп {i}", lambda s, i: _i(s.get('k_usp', 0))),
        ('коэффициент успешности', lambda s, i: f"γсчет {i}", lambda s, i: _f4(s.get('gamma_count', 0.0))),
        ('реальный темп', lambda s, i: f"tср {i}", lambda s, i: _f2(s.get('t_avg_cycle_s', 0.0))),
        ('нормативный темп', lambda s, i: f"tнорм {i}", lambda s, i: _sec(_norm_time(s, i))),
        ('приведенный темп', lambda s, i: f"t{i}", lambda s, i: _f2(_t_value(s, i))),
        (lambda s, i: f'темп счета этапа {i}', lambda s, i: f"tсчет {i}", lambda s, i: _f2(_t_value_with_gamma(s, i))),
    ]

    for r_idx, (name_fn, sym_fn, val_fn) in enumerate(row_defs, start=1):
        for grp, stage_item in enumerate(stage_items, start=1):
            base = (grp - 1) * 3
            name_text = name_fn(stage_item, grp) if callable(name_fn) else name_fn
            values = (
                name_text,
                sym_fn(stage_item, grp),
                val_fn(stage_item, grp),
            )
            for j, text in enumerate(values):
                bg = '#f8ffff' if j == 0 and r_idx % 2 == 0 else ('#effff4' if j == 0 else '#ffffff')
                # In parameter symbols: make the first 't' larger, everything after it as lowered index.
                if j == 1 and isinstance(text, str) and text and text[0].lower() == 't':
                    cell = tk.Frame(table, bg=bg, bd=1, relief='solid')
                    cell.grid(row=r_idx, column=base + j, sticky='nsew')
                    slot = tk.Frame(cell, bg=bg)
                    slot.pack(fill='both', expand=True, padx=4, pady=2)
                    _draw_t_with_index(slot, text, big_size=18, sub_size=11, fg='#20324d', bg=bg, centered=True)
                else:
                    tk.Label(
                        table,
                        text=text,
                        bg=bg,
                        fg='#102744' if j == 0 else '#20324d',
                        font=('Arial', 9, 'bold' if j != 2 else 'normal'),
                        bd=1,
                        relief='solid',
                        padx=4,
                        pady=4,
                        justify='left' if j == 0 else 'center',
                        anchor='w' if j == 0 else 'center',
                    ).grid(row=r_idx, column=base + j, sticky='nsew')


