@dataclass
class MethodCConfigFixed309:
    total_test_s: float = 120.0
    normative_success_coef: float = 1.0

    etap1_vremya_s: float = 40.0
    etap2_vremya_s: float = 40.0
    etap3_vremya_s: float = 40.0

    etap1_pokaz_s: float = 1.0
    etap2_pokaz_s: float = 2.0
    etap3_pokaz_s: float = 4.0

    etap1_vvod_s: float = 3.0
    etap2_vvod_s: float = 6.0
    etap3_vvod_s: float = 12.0

    etap1_norma_tempa_s: float = 4.0
    etap2_norma_tempa_s: float = 8.0
    etap3_norma_tempa_s: float = 16.0

    etap1_norma_oshibok: int = 2
    etap2_norma_oshibok: int = 2
    etap3_norma_oshibok: int = 2

    @property
    def stage_time_s(self) -> list[float]:
        return [float(self.etap1_vremya_s), float(self.etap2_vremya_s), float(self.etap3_vremya_s)]

    @stage_time_s.setter
    def stage_time_s(self, vals):
        arr = list(vals or [40.0, 40.0, 40.0])[:3]
        while len(arr) < 3:
            arr.append(arr[-1] if arr else 40.0)
        self.etap1_vremya_s, self.etap2_vremya_s, self.etap3_vremya_s = [float(x) for x in arr]

    @property
    def exposure_start_s(self) -> list[float]:
        return [float(self.etap1_pokaz_s), float(self.etap2_pokaz_s), float(self.etap3_pokaz_s)]

    @exposure_start_s.setter
    def exposure_start_s(self, vals):
        arr = list(vals or [1.0, 2.0, 4.0])[:3]
        while len(arr) < 3:
            arr.append(arr[-1] if arr else 1.0)
        self.etap1_pokaz_s, self.etap2_pokaz_s, self.etap3_pokaz_s = [float(x) for x in arr]

    @property
    def input_start_s(self) -> list[float]:
        return [float(self.etap1_vvod_s), float(self.etap2_vvod_s), float(self.etap3_vvod_s)]

    @input_start_s.setter
    def input_start_s(self, vals):
        arr = list(vals or [3.0, 6.0, 12.0])[:3]
        while len(arr) < 3:
            arr.append(arr[-1] if arr else 3.0)
        self.etap1_vvod_s, self.etap2_vvod_s, self.etap3_vvod_s = [float(x) for x in arr]

    @property
    def normative_cycle_times(self) -> list[float]:
        return [float(self.etap1_norma_tempa_s), float(self.etap2_norma_tempa_s), float(self.etap3_norma_tempa_s)]

    @normative_cycle_times.setter
    def normative_cycle_times(self, vals):
        arr = list(vals or [4.0, 8.0, 16.0])[:3]
        while len(arr) < 3:
            arr.append(arr[-1] if arr else 4.0)
        self.etap1_norma_tempa_s, self.etap2_norma_tempa_s, self.etap3_norma_tempa_s = [float(x) for x in arr]

    @property
    def normative_stage_errors(self) -> list[int]:
        return [int(self.etap1_norma_oshibok), int(self.etap2_norma_oshibok), int(self.etap3_norma_oshibok)]

    @normative_stage_errors.setter
    def normative_stage_errors(self, vals):
        arr = list(vals or [2, 2, 2])[:3]
        while len(arr) < 3:
            arr.append(arr[-1] if arr else 2)
        self.etap1_norma_oshibok, self.etap2_norma_oshibok, self.etap3_norma_oshibok = [int(x) for x in arr]

    @property
    def time_step_s(self) -> list[float]:
        return [0.0, 0.0, 0.0]

    @time_step_s.setter
    def time_step_s(self, _vals):
        return

    @property
    def normative_success(self) -> list[float]:
        return [1.0, 1.0, 1.0]

    @normative_success.setter
    def normative_success(self, _vals):
        return


MethodCConfig = MethodCConfigFixed309
globals()['MethodCConfig'] = MethodCConfigFixed309


def _fixed309_pick3(raw: dict, scalar_keys: tuple[str, str, str], list_key: str, defaults: tuple[float, float, float], cast=float):
    out = []
    src_list = raw.get(list_key, [])
    for i, k in enumerate(scalar_keys):
        if k in raw:
            try:
                out.append(cast(raw.get(k)))
                continue
            except Exception:
                pass
        try:
            if isinstance(src_list, list) and i < len(src_list):
                out.append(cast(src_list[i]))
                continue
        except Exception:
            pass
        out.append(cast(defaults[i]))
    return out


def load_method_c_config(base_dir: Path) -> MethodCConfig:
    path = base_dir / 'method_c_config.json'
    raw = {}
    if path.exists():
        try:
            loaded = json.loads(path.read_text(encoding='utf-8'))
            if isinstance(loaded, dict):
                raw = loaded
        except Exception:
            raw = {}
    cfg = MethodCConfig()
    cfg.total_test_s = float(raw.get('total_test_s', cfg.total_test_s) or cfg.total_test_s)
    cfg.normative_success_coef = max(1e-6, float(raw.get('normative_success_coef', getattr(cfg, 'normative_success_coef', 1.0)) or 1.0))

    cfg.stage_time_s = _fixed309_pick3(
        raw,
        ('etap1_vremya_s', 'etap2_vremya_s', 'etap3_vremya_s'),
        'stage_time_s',
        (40.0, 40.0, 40.0),
        cast=float,
    )
    cfg.exposure_start_s = _fixed309_pick3(
        raw,
        ('etap1_pokaz_s', 'etap2_pokaz_s', 'etap3_pokaz_s'),
        'exposure_start_s',
        (1.0, 2.0, 4.0),
        cast=float,
    )
    cfg.input_start_s = _fixed309_pick3(
        raw,
        ('etap1_vvod_s', 'etap2_vvod_s', 'etap3_vvod_s'),
        'input_start_s',
        (3.0, 6.0, 12.0),
        cast=float,
    )
    cfg.normative_cycle_times = _fixed309_pick3(
        raw,
        ('etap1_norma_tempa_s', 'etap2_norma_tempa_s', 'etap3_norma_tempa_s'),
        'normative_cycle_times',
        (4.0, 8.0, 16.0),
        cast=float,
    )
    cfg.normative_stage_errors = _fixed309_pick3(
        raw,
        ('etap1_norma_oshibok', 'etap2_norma_oshibok', 'etap3_norma_oshibok'),
        'normative_stage_errors',
        (2, 2, 2),
        cast=int,
    )
    return cfg


