# ====== FIXED304: Method B results in unified style (same visual shell as Test A) ======
def _fixed306_export_method_b_pdf_all_results(self, top: tk.Toplevel, payload: dict) -> str:
    try:
        from PIL import ImageGrab as _fixed306_imagegrab
    except Exception:
        return ''

    canvas = _fixed207_find_results_canvas(top)
    if canvas is None:
        return ''

    try:
        top.update_idletasks()
        top.update()
        body = next((w for w in canvas.winfo_children() if isinstance(w, tk.Frame)), None)
        hidden_scrollbars = _fixed207_hide_scrollbars_for_capture(top)
        top.update_idletasks()
        top.update()

        captured: list[tuple[int, Image.Image]] = []
        try:
            region = str(canvas.cget('scrollregion') or '').strip()
            if region:
                parts = region.split()
                if len(parts) == 4:
                    _, y1s, _, y2s = parts
                    total_h = max(1, int(float(y2s) - float(y1s)))
                else:
                    box = canvas.bbox('all')
                    total_h = max(1, int((box[3] - box[1]) if box else canvas.winfo_height()))
            else:
                box = canvas.bbox('all')
                total_h = max(1, int((box[3] - box[1]) if box else canvas.winfo_height()))

            vis_h = max(1, int(canvas.winfo_height()))
            max_offset = max(0, total_h - vis_h)

            offsets: list[int] = []
            current = 0
            while current < max_offset:
                offsets.append(current)
                current += vis_h
            offsets.append(max_offset)

            for off in offsets:
                frac = float(off) / float(max(1, max_offset))
                canvas.yview_moveto(frac)
                top.update_idletasks()
                top.update()

                x1 = int(canvas.winfo_rootx())
                y1 = int(canvas.winfo_rooty())
                x2 = x1 + int(canvas.winfo_width())
                y2 = y1 + int(canvas.winfo_height())
                if x2 <= x1 or y2 <= y1:
                    continue
                shot = _fixed306_imagegrab.grab(bbox=(x1, y1, x2, y2))
                if shot.mode != 'RGB':
                    shot = shot.convert('RGB')
                captured.append((int(off), shot))
        finally:
            canvas.yview_moveto(0.0)
            _fixed207_restore_scrollbars(hidden_scrollbars)
            top.update_idletasks()
            top.update()

        if not captured:
            return ''

        # Build one continuous image by absolute offsets.
        canvas_w = int(captured[0][1].width)
        strip_h = max(1, int(total_h))
        strip = Image.new('RGB', (canvas_w, strip_h), 'white')
        for off, shot in captured:
            if off >= strip_h:
                continue
            copy_h = min(int(shot.height), strip_h - off)
            if copy_h <= 0:
                continue
            part = shot if copy_h == int(shot.height) else shot.crop((0, 0, int(shot.width), copy_h))
            strip.paste(part, (0, int(off)))

        # Real content height: trim empty tail under the last widget.
        content_h = strip_h
        blocks: list[tuple[int, int]] = []
        if body is not None:
            try:
                top.update_idletasks()
                kids = [w for w in body.winfo_children() if int(w.winfo_height() or 0) > 0]
                for w in kids:
                    y1 = max(0, int(w.winfo_y()))
                    y2 = y1 + max(1, int(w.winfo_height()))
                    blocks.append((y1, y2))
                if blocks:
                    content_h = min(strip_h, max(y2 for _, y2 in blocks) + 6)
            except Exception:
                blocks = []
        strip = strip.crop((0, 0, canvas_w, max(1, int(content_h))))

        # Split into pages by block boundaries to avoid tearing sections.
        page_h = max(1, int(vis_h))
        pages: list[Image.Image] = []
        y = 0
        while y < int(content_h):
            hard_end = min(int(content_h), y + page_h)
            split_end = hard_end
            if blocks:
                ends = [b for (a, b) in blocks if y < b <= hard_end]
                if ends:
                    split_end = max(ends)
            if split_end <= y:
                split_end = hard_end
            page = strip.crop((0, y, canvas_w, split_end))
            pages.append(page)
            y = split_end
        if not pages:
            return ''

        session_id = str(payload.get('session_id', 'session') or 'session')
        ts = datetime.now().strftime('%Y%m%d_%H%M%S')
        pdf_path = _results_dir(self.base_dir) / f'method_b_all_results_{session_id}_{ts}.pdf'
        pages[0].save(str(pdf_path), format='PDF', save_all=True, append_images=pages[1:], resolution=150.0)
        return str(pdf_path)
    except Exception:
        return ''








# ====== FIXED305: route result opening via overridable bound handlers ======
def _fixed305_view_results(self, code: str):
    if not self.current_profile:
        return
    payload = self.progress_store.get_test_result(self.current_profile, code)
    if not payload:
        messagebox.showinfo('Результаты', f'Для {TEST_LABELS[code]} пока нет сохранённых результатов.')
        return
    if code == 'A':
        self.show_method_a_results(payload)
    elif code == 'B':
        self.show_method_b_results(payload)
    elif code == 'C':
        self.show_method_c_results(payload)
    elif code == 'D':
        self.show_method_d_results(payload)


StartPageApp.view_results = _fixed305_view_results


# ====== FIXED220: config schema versioning + auto-reset of legacy config files ======
_FIXED220_CONFIG_SCHEMA_VERSION = 'fixed261_config_schema_2026_05_08_v1'
_FIXED220_CONFIG_VERSION_FILE = 'config_schema_version.txt'
_FIXED220_CONFIG_FILES = (
    ('method_a_config.json', MethodAConfig),
    ('method_b_config.json', MethodBConfig),
    ('method_c_config.json', MethodCConfig),
    ('method_d_config.json', MethodDConfig),
)


def _fixed220_write_default_config(path: Path, cls):
    obj = cls()
    payload = asdict(obj)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')


def _fixed220_prepare_config_schema(base_dir: Path):
    try:
        base_dir = Path(base_dir)
        marker_path = base_dir / _FIXED220_CONFIG_VERSION_FILE
        current = ''
        if marker_path.exists():
            try:
                current = marker_path.read_text(encoding='utf-8').strip()
            except Exception:
                current = ''

        if current == _FIXED220_CONFIG_SCHEMA_VERSION:
            return

        ts = datetime.now().strftime('%Y%m%d_%H%M%S')
        backup_dir = base_dir / 'data' / 'config_backup' / ts
        backup_created = False

        for filename, cls in _FIXED220_CONFIG_FILES:
            cfg_path = base_dir / filename
            if cfg_path.exists():
                if not backup_created:
                    backup_dir.mkdir(parents=True, exist_ok=True)
                    backup_created = True
                shutil.copy2(str(cfg_path), str(backup_dir / filename))
            _fixed220_write_default_config(cfg_path, cls)

        marker_path.write_text(_FIXED220_CONFIG_SCHEMA_VERSION, encoding='utf-8')
    except Exception:
        # Do not block app startup if migration cannot be completed.
        pass


_fixed220_prev_run_app = _run_app


def _run_app():
    _fixed220_prepare_config_schema(_runtime_app_dir())
    _fixed220_prev_run_app()


