_FIXED310_PREV_METHOD_C_BUILD_UI = MethodCWindow._build_ui


def _fixed310_method_c_build_ui(self):
    _FIXED310_PREV_METHOD_C_BUILD_UI(self)
    if not (getattr(self, 'win', None) and self.win.winfo_exists()):
        return

    # Before pressing "Начать тестирование" no digit should be visible.
    self.phase = 'idle'
    self.big_var.set('')
    self.entry_var.set('')
    try:
        self.big_label.configure(fg='#228b22')
    except Exception:
        pass
    if '_fixed150_method_c_feedback_clear' in globals():
        try:
            _fixed150_method_c_feedback_clear(self)
        except Exception:
            pass


