# ====== FIXED311: Method C start screen and controls match required layout ======
_FIXED311_PREV_METHOD_C_BUILD_UI = MethodCWindow._build_ui
_FIXED311_PREV_METHOD_C_START_STAGE = MethodCWindow._start_stage
_FIXED311_PREV_METHOD_C_START_OPERATION_CYCLE = MethodCWindow._start_operation_cycle
_FIXED311_PREV_METHOD_C_BEGIN_INPUT_PHASE = MethodCWindow._begin_input_phase
_FIXED311_PREV_METHOD_C_RESOLVE_CYCLE = MethodCWindow._resolve_cycle


def _fixed311_method_c_stage_text(self) -> str:
    stage = int(getattr(self, 'stage_index', 0) or 0)
    if stage <= 0:
        return ''
    return f'Этап {stage}.'


def _fixed311_method_c_hide_cancel_button(self):
    btn = getattr(self, 'clear_btn', None)
    if btn is None:
        return
    try:
        btn.place_forget()
    except Exception:
        pass
    try:
        btn.configure(state='disabled')
    except Exception:
        pass


def _fixed311_method_c_hide_next_button_until_start(self):
    btn = getattr(self, 'answer_btn', None)
    if btn is None:
        return
    if not hasattr(self, '_fixed311_answer_place'):
        try:
            self._fixed311_answer_place = dict(btn.place_info())
        except Exception:
            self._fixed311_answer_place = {}
    try:
        btn.place_forget()
    except Exception:
        pass


def _fixed311_method_c_show_next_button_after_start(self):
    btn = getattr(self, 'answer_btn', None)
    if btn is None:
        return
    place_cfg = getattr(self, '_fixed311_answer_place', {}) or {}
    if place_cfg:
        try:
            btn.place(**place_cfg)
        except Exception:
            try:
                btn.place_configure(**place_cfg)
            except Exception:
                pass
    try:
        btn.configure(state='normal', text='Далее')
    except Exception:
        pass


def _fixed311_method_c_build_ui(self):
    _FIXED311_PREV_METHOD_C_BUILD_UI(self)
    if not (getattr(self, 'win', None) and self.win.winfo_exists()):
        return
    self._fixed311_started = False
    self.prompt_var.set('')
    _fixed311_method_c_hide_cancel_button(self)
    _fixed311_method_c_hide_next_button_until_start(self)




def _fixed311_method_c_start_stage(self, stage_index: int):
    result = _FIXED311_PREV_METHOD_C_START_STAGE(self, stage_index)
    _fixed311_method_c_hide_cancel_button(self)
    self.prompt_var.set(_fixed311_method_c_stage_text(self))
    return result


def _fixed311_method_c_start_operation_cycle(self):
    result = _FIXED311_PREV_METHOD_C_START_OPERATION_CYCLE(self)
    _fixed311_method_c_hide_cancel_button(self)
    self.prompt_var.set(_fixed311_method_c_stage_text(self))
    return result


def _fixed311_method_c_begin_input_phase(self):
    result = _FIXED311_PREV_METHOD_C_BEGIN_INPUT_PHASE(self)
    _fixed311_method_c_hide_cancel_button(self)
    self.prompt_var.set(_fixed311_method_c_stage_text(self))
    return result




