MethodCWindow._begin_input_phase = _fixed311_method_c_begin_input_phase


# ====== FIXED312: Method C "Далее" button vertical placement tuned to reference ======
_FIXED312_PREV_SHOW_NEXT_AFTER_START = _fixed311_method_c_show_next_button_after_start


def _fixed312_method_c_place_next_button(self):
    btn = getattr(self, 'answer_btn', None)
    if btn is None:
        return
    keypad_place = getattr(self, '_method_c_keypad_place', {}) or {}
    center_x = int(keypad_place.get('x', 0) or 0)
    keypad_top_y = int(keypad_place.get('y', 0) or 0)
    if center_x <= 0 or keypad_top_y <= 0:
        return
    try:
        self.win.update_idletasks()
    except Exception:
        pass
    try:
        btn_w = int(btn.winfo_reqwidth())
    except Exception:
        btn_w = int(btn.winfo_width() or 0)
    try:
        btn_h = int(btn.winfo_reqheight())
    except Exception:
        btn_h = int(btn.winfo_height() or 0)
    btn_w = max(80, btn_w)
    btn_h = max(36, btn_h)
    gap = max(20, int(btn_h * 0.55))
    new_x = max(6, center_x - btn_w // 2)
    new_y = max(6, keypad_top_y - btn_h - gap)
    try:
        btn.place_configure(x=new_x, y=new_y)
    except Exception:
        try:
            btn.place(x=new_x, y=new_y)
        except Exception:
            pass


def _fixed311_method_c_show_next_button_after_start(self):
    _FIXED312_PREV_SHOW_NEXT_AFTER_START(self)
    _fixed312_method_c_place_next_button(self)


# ====== FIXED313: Method C auto-submit input and context-aware "Далее" visibility ======
_FIXED313_PREV_METHOD_C_BUILD_UI = MethodCWindow._build_ui
_FIXED313_PREV_METHOD_C_START_STAGE = MethodCWindow._start_stage
_FIXED313_PREV_METHOD_C_START_OPERATION_CYCLE = MethodCWindow._start_operation_cycle
_FIXED313_PREV_METHOD_C_BEGIN_INPUT_PHASE = MethodCWindow._begin_input_phase
_FIXED313_PREV_METHOD_C_APPEND_DIGIT = MethodCWindow._append_digit
_FIXED313_BASE_METHOD_C_RESOLVE = _FIXED311_PREV_METHOD_C_RESOLVE_CYCLE






def _fixed313_method_c_hide_next(self):
    _fixed311_method_c_hide_next_button_until_start(self)








def _fixed313_method_c_build_ui(self):
    _FIXED313_PREV_METHOD_C_BUILD_UI(self)
    self._fixed313_last_cycle_success = False
    self._fixed313_submitting = False
    _fixed313_method_c_hide_next(self)












MethodCWindow._build_ui = _fixed313_method_c_build_ui


# ====== FIXED314: Method C layout and flow aligned to requested scenario ======
_FIXED314_PREV_METHOD_C_BUILD_UI = MethodCWindow._build_ui


def _fixed314_method_c_required_len(self) -> int:
    return max(1, min(3, int(getattr(self, 'stage_index', 1) or 1)))


def _fixed416_method_c_place_action_buttons(self):
    next_btn = getattr(self, 'answer_btn', None)
    if next_btn is None:
        return
    clear_btn = getattr(self, 'clear_btn', None)
    keypad_place = getattr(self, '_method_c_keypad_place', {}) or {}
    center_x = int(keypad_place.get('x', 0) or 0)
    keypad_top_y = int(keypad_place.get('y', 0) or 0)
    if center_x <= 0 or keypad_top_y <= 0:
        return
    try:
        self.win.update_idletasks()
    except Exception:
        pass
    try:
        host_w = int(next_btn.master.winfo_width() or 0)
    except Exception:
        host_w = 0
    try:
        next_w = max(92, int(next_btn.winfo_reqwidth()))
        next_h = max(36, int(next_btn.winfo_reqheight()))
    except Exception:
        next_w, next_h = 130, 44
    clear_visible = clear_btn is not None and str(getattr(self, '_fixed314_mode', '') or '') in ('stage_ready', 'input', 'error')
    if clear_visible:
        try:
            clear_w = max(92, int(clear_btn.winfo_reqwidth()))
            clear_h = max(36, int(clear_btn.winfo_reqheight()))
        except Exception:
            clear_w, clear_h = 130, 44
        btn_h = max(clear_h, next_h)
        gap_x = max(44, int(btn_h * 1.15))
        group_w = clear_w + gap_x + next_w
        left_x = center_x - group_w // 2
        if host_w > 0:
            left_x = min(max(6, left_x), max(6, host_w - group_w - 6))
        else:
            left_x = max(6, left_x)
        clear_x = left_x
        next_x = left_x + clear_w + gap_x
    else:
        btn_h = next_h
        clear_x = None
        next_x = center_x - next_w // 2
        if host_w > 0:
            next_x = min(max(6, next_x), max(6, host_w - next_w - 6))
        else:
            next_x = max(6, next_x)
    gap_y = max(18, int(btn_h * 0.55))
    y = max(6, keypad_top_y - btn_h - gap_y)
    try:
        next_btn.place_configure(x=int(next_x), y=int(y))
    except Exception:
        try:
            next_btn.place(x=int(next_x), y=int(y))
        except Exception:
            pass
    if clear_visible and clear_btn is not None and clear_x is not None:
        try:
            clear_btn.place(x=int(clear_x), y=int(y))
        except Exception:
            try:
                clear_btn.place_configure(x=int(clear_x), y=int(y))
            except Exception:
                pass


def _fixed314_method_c_hide_next(self):
    btn = getattr(self, 'answer_btn', None)
    if btn is None:
        return
    try:
        btn.place_forget()
    except Exception:
        pass


def _fixed314_method_c_show_next(self):
    btn = getattr(self, 'answer_btn', None)
    if btn is None:
        return
    _fixed312_method_c_place_next_button(self)
    try:
        btn.configure(state='normal', text='Далее')
    except Exception:
        pass
    _fixed416_method_c_place_action_buttons(self)


def _fixed314_method_c_show_cancel(self, show: bool):
    btn = getattr(self, 'clear_btn', None)
    if btn is None:
        return
    try:
        if show:
            btn.configure(state='normal')
            if btn.winfo_manager() == 'grid':
                btn.grid_forget()
            _fixed416_method_c_place_action_buttons(self)
        else:
            if btn.winfo_manager() == 'place':
                btn.place_forget()
            elif btn.winfo_manager() == 'grid':
                btn.grid_remove()
    except Exception:
        pass


def _fixed314_method_c_show_keypad(self, show: bool):
    keypad = getattr(self, '_method_c_keypad', None)
    if keypad is None:
        return
    place_cfg = getattr(self, '_method_c_keypad_place', {}) or {}
    try:
        if show:
            keypad.place(
                x=int(place_cfg.get('x', 0) or 0),
                y=int(place_cfg.get('y', 0) or 0),
                anchor=place_cfg.get('anchor', 'n')
            )
        else:
            keypad.place_forget()
    except Exception:
        pass


def _fixed314_method_c_digits_state(self, enabled: bool):
    state = 'normal' if enabled else 'disabled'
    for w in list(getattr(self, '_method_c_input_widgets', [])[2:]):
        try:
            w.configure(state=state)
        except Exception:
            pass


def _fixed314_method_c_set_mode(self, mode: str):
    self._fixed314_mode = mode
    if mode == 'prestart':
        _fixed314_method_c_show_keypad(self, False)
        _fixed314_method_c_digits_state(self, False)
        _fixed314_method_c_show_cancel(self, False)
        _fixed314_method_c_hide_next(self)
        try:
            self.entry.configure(state='readonly')
        except Exception:
            pass
        return

    if mode == 'stage_ready':
        # На экране первого (исходного) числа касса должна быть скрыта.
        _fixed314_method_c_show_keypad(self, False)
        _fixed314_method_c_digits_state(self, False)
        _fixed314_method_c_show_cancel(self, True)
        _fixed314_method_c_show_next(self)
        try:
            self.entry.configure(state='readonly')
        except Exception:
            pass
        return

    if mode in ('show_operand', 'stage_done', 'test_done'):
        _fixed314_method_c_show_keypad(self, True)
        _fixed314_method_c_digits_state(self, False)
        _fixed314_method_c_show_cancel(self, False)
        _fixed314_method_c_show_next(self)
        try:
            self.entry.configure(state='readonly')
        except Exception:
            pass
        return

    if mode == 'input':
        _fixed314_method_c_show_keypad(self, True)
        _fixed314_method_c_digits_state(self, True)
        _fixed314_method_c_show_cancel(self, True)
        _fixed314_method_c_show_next(self)
        try:
            self.entry.configure(state='normal')
            self.entry.focus_set()
            self.entry.selection_range(0, tk.END)
        except Exception:
            pass
        return

    if mode == 'error':
        _fixed314_method_c_show_keypad(self, True)
        _fixed314_method_c_digits_state(self, False)
        _fixed314_method_c_show_cancel(self, True)
        _fixed314_method_c_show_next(self)
        try:
            self.entry.configure(state='readonly')
        except Exception:
            pass


def _fixed314_method_c_build_ui(self):
    _FIXED314_PREV_METHOD_C_BUILD_UI(self)
    if not (getattr(self, 'win', None) and self.win.winfo_exists()):
        return

    # Force one-row keypad (0..9) within stage width (no clipping).
    keypad = getattr(self, '_method_c_keypad', None)
    digit_btns = list(getattr(self, '_method_c_input_widgets', [])[2:])
    if keypad is not None and digit_btns:
        base_font = getattr(self, '_fixed137_digit_font', ('Arial', 72, 'bold'))
        try:
            base_size = int(base_font[1])
        except Exception:
            base_size = 72
        # Match the reference look for keypad digits: serif, regular weight.
        font_name = 'Times New Roman'
        font_weight = 'normal'

        place_cfg = getattr(self, '_method_c_keypad_place', {}) or {}
        stage_w = int(place_cfg.get('x', 0) or 0) * 2
        if stage_w <= 0:
            try:
                stage_w = int(keypad.master.winfo_width() or 760)
            except Exception:
                stage_w = 760
        target_w = max(640, stage_w - 24)
        digit_cell_w = max(48, int(target_w / 10))
        # Reference-like balance: large digits, but with clear inner margins.
        cash_size = max(32, min(base_size, int(digit_cell_w * 0.72)))
        cash_font = (font_name, cash_size, font_weight)

        for w in digit_btns:
            try:
                w.grid_forget()
            except Exception:
                pass
        for i, w in enumerate(digit_btns):
            try:
                w.configure(
                    font=cash_font,
                    width=1,
                    padx=4,
                    pady=4,
                    bg='#ffffff',
                    activebackground='#f1f1f1',
                    fg='#000000',
                    activeforeground='#000000',
                    disabledforeground='#000000',
                    bd=1,
                    relief='solid',
                    highlightthickness=1,
                    highlightbackground='#000000',
                    highlightcolor='#000000',
                )
                w.grid(row=0, column=i, sticky='nsew', padx=2, pady=2)
            except Exception:
                pass
        for r in range(4):
            try:
                keypad.grid_rowconfigure(r, weight=0)
            except Exception:
                pass
        try:
            keypad.grid_rowconfigure(0, weight=1, uniform='method_c_row_1')
        except Exception:
            pass
        for c in range(max(10, len(digit_btns))):
            try:
                keypad.grid_columnconfigure(c, weight=1, uniform='method_c_cols_1')
            except Exception:
                pass
        try:
            target_h = max(90, int(cash_size * 1.50))
            for c in range(max(10, len(digit_btns))):
                try:
                    keypad.grid_columnconfigure(c, minsize=max(48, int(target_w / 10)))
                except Exception:
                    pass
            keypad.grid_propagate(False)
            self.win.update_idletasks()
            keypad.configure(
                width=target_w,
                height=target_h,
                bg='#ffffff',
                highlightbackground='#000000',
                highlightcolor='#000000',
            )
            try:
                place_cfg = dict(getattr(self, '_method_c_keypad_place', {}) or {})
                old_y = int(place_cfg.get('y', 0) or 0)
                host_h = int(keypad.master.winfo_height() or 0)
                if host_h > 0:
                    new_y = max(6, host_h - target_h - 20)
                    if old_y > 0:
                        new_y = max(old_y, new_y)
                    place_cfg['y'] = new_y
                    self._method_c_keypad_place = place_cfg
                    keypad.place_configure(y=new_y)
            except Exception:
                pass
        except Exception:
            pass

    # Keep the working-screen "Отмена" and "Далее" as one action row above the keypad.
    clear_btn = getattr(self, 'clear_btn', None)
    if clear_btn is not None:
        try:
            base_digit = int(getattr(self, '_fixed137_digit_font', ('Arial', 72, 'bold'))[1])
        except Exception:
            base_digit = 72
        try:
            clear_btn.configure(
                command=self._clear_input,
                font=('Arial', max(12, int(base_digit * 0.17)), 'bold'),
                width=12,
                padx=12,
                pady=7,
                bd=3,
                relief='raised',
                highlightthickness=1,
                highlightbackground='#000000',
                highlightcolor='#000000',
            )
        except Exception:
            pass

    # Shrink only the working-screen "Далее" button (start/instruction buttons are separate widgets).
    answer_btn = getattr(self, 'answer_btn', None)
    if answer_btn is not None:
        try:
            base_digit = int(getattr(self, '_fixed137_digit_font', ('Arial', 72, 'bold'))[1])
        except Exception:
            base_digit = 72
        try:
            answer_btn.configure(
                font=('Arial', max(12, int(base_digit * 0.17)), 'bold'),
                width=12,
                padx=12,
                pady=7,
            )
        except Exception:
            pass
    _fixed416_method_c_place_action_buttons(self)

    self._fixed314_started = False
    self._fixed314_next_action = ''
    self._fixed314_mode = 'prestart'
    self._fixed313_last_cycle_success = False
    self.prompt_var.set('')
    self.big_var.set('')
    self.entry_var.set('')
    _fixed314_method_c_set_mode(self, 'prestart')




def _fixed314_method_c_start_stage(self, stage_index: int):
    self._cancel_afters()
    self.stage_index = stage_index
    if stage_index > 3:
        self.phase = 'finished_notice'
        self._fixed314_next_action = 'finish'
        self.prompt_var.set('Тест завершен, для продолжения нажмите «Далее»')
        self.big_var.set('')
        _fixed314_method_c_set_mode(self, 'test_done')
        self._tick_stage_clock()
        return

    lo, hi = self._stage_limits(stage_index)
    self.exp_s = float(self.cfg.exposure_start_s[stage_index - 1])
    self.input_s = float(self.cfg.input_start_s[stage_index - 1])
    self.current_value = random.randint(lo, hi)
    self.stage_start_at = time.perf_counter()
    self.stage_records[stage_index] = {'cycles': [], 'Gq': 0, 'Fq': 0}
    self.phase = 'stage_ready'
    self._fixed314_next_action = 'start_cycle'

    if '_fixed150_method_c_feedback_clear' in globals():
        try:
            _fixed150_method_c_feedback_clear(self)
        except Exception:
            pass

    self.prompt_var.set(f'Этап {stage_index}.')
    self.big_var.set(str(self.current_value))
    try:
        self.big_label.configure(fg='#228b22')
    except Exception:
        pass
    self.entry_var.set('')
    _fixed314_method_c_set_mode(self, 'stage_ready')
    self._tick_stage_clock()


def _fixed314_method_c_start_operation_cycle(self):
    self._cancel_afters()
    if hasattr(self, "_fixed193_total_time_left") and self._fixed193_total_time_left() <= 0.05:
        self._finish()
        return
    if hasattr(self, "_fixed193_should_advance_stage") and self._fixed193_should_advance_stage():
        self.phase = 'stage_done'
        if int(getattr(self, 'stage_index', 1) or 1) >= 3:
            self._fixed314_next_action = 'finish'
            self.prompt_var.set('Тест завершен, для продолжения нажмите «Далее»')
        else:
            self._fixed314_next_action = 'next_stage'
            self.prompt_var.set('Этап завершен, для перехода к следующему этапу нажмите «Далее»')
        self.big_var.set('')
        self.entry_var.set('')
        _fixed314_method_c_set_mode(self, 'stage_done')
        self._tick_stage_clock()
        return

    self.phase = 'input'
    self.current_op, self.current_operand, self.current_correct = self._generate_operand(self.current_value, self.stage_index)
    self.current_cycle_started_at = time.perf_counter()
    self._fixed314_next_action = ''

    if '_fixed150_method_c_feedback_clear' in globals():
        try:
            _fixed150_method_c_feedback_clear(self)
        except Exception:
            pass

    self.prompt_var.set('')
    self.big_var.set(str(self.current_operand))
    try:
        self.big_label.configure(fg=('#228b22' if self.current_op == '+' else '#c93232'))
    except Exception:
        pass
    self.entry_var.set('')
    _fixed314_method_c_set_mode(self, 'input')
    self._tick_stage_clock()


def _fixed314_method_c_begin_input_phase(self):
    if hasattr(self, "_fixed193_total_time_left") and self._fixed193_total_time_left() <= 0.05:
        self._finish()
        return
    self._cancel_afters()
    self.phase = 'input'
    self._fixed314_next_action = ''
    self.prompt_var.set('')
    self.entry_var.set('')
    self.big_var.set('')
    try:
        self.big_label.configure(fg='#163d7a')
    except Exception:
        pass
    _fixed314_method_c_set_mode(self, 'input')
    self.input_deadline = 0.0
    self._tick_stage_clock()


def _fixed314_method_c_submit_answer(self):
    if not (getattr(self, 'win', None) and self.win.winfo_exists()):
        return

    phase = str(getattr(self, 'phase', '') or '')
    if phase == 'input':
        text = ''.join(ch for ch in self.entry_var.get().strip().replace('−', '-') if ch.isdigit())
        if not text:
            return
        need = _fixed314_method_c_required_len(self)
        if len(text) > need:
            text = text[:need]
        try:
            value = int(text)
        except Exception:
            return
        self.entry_var.set(text)
        self._resolve_cycle(success=(value == self.current_correct), timeout=False, given=value)
        return

    action = str(getattr(self, '_fixed314_next_action', '') or '')
    if action == 'start_cycle' or action == 'next_cycle':
        self._fixed314_next_action = ''
        self._start_operation_cycle()
    elif action == 'next_stage':
        self._fixed314_next_action = ''
        self._start_stage(int(getattr(self, 'stage_index', 1) or 1) + 1)
    elif action == 'finish':
        self._fixed314_next_action = ''
        self._finish()


def _fixed314_method_c_resolve_cycle(self, success: bool, timeout: bool, given: int | None = None):
    if getattr(self, 'phase', '') not in ('input', 'show_operand'):
        return
    self._cancel_afters()
    stage = self.stage_records.setdefault(self.stage_index, {'cycles': [], 'Gq': 0, 'Fq': 0})
    elapsed = time.perf_counter() - self.current_cycle_started_at
    stage['Gq'] += 1
    cycle_item = {
        'operand': self.current_operand,
        'op': self.current_op,
        'start_value': self.current_value,
        'correct_value': self.current_correct,
        'given_value': given,
        'success': bool(success),
        'elapsed_s': _round2(elapsed),
        'exp_s': _round2(self.exp_s),
        'input_s': _round2(self.input_s),
        'timeout': bool(timeout),
    }
    if success:
        stage['Fq'] += 1
    stage['cycles'].append(cycle_item)

    self.logger.log_event(
        self.session,
        event_type='method_cycle',
        screen='method_c',
        test_name='method_c',
        stage=f'stage_{self.stage_index}',
        action='success' if success else 'error',
        elapsed_ms=int(elapsed * 1000),
        value=self.current_correct,
        note=f'given={given}; timeout={int(timeout)}; op={self.current_op}{self.current_operand}',
    )

    self.current_value = self.current_correct
    self.entry_var.set(str(self.current_correct))
    self.big_var.set(str(self.current_correct))
    try:
        self.big_label.configure(fg='#228b22')
    except Exception:
        pass

    if success:
        self.phase = 'feedback'
        self._fixed314_next_action = 'next_cycle'
        self.prompt_var.set('')
        _fixed314_method_c_set_mode(self, 'show_operand')
        self._track_after(self.win.after(70, self._start_operation_cycle))
    else:
        self.phase = 'feedback'
        self._fixed314_next_action = 'next_cycle'
        self.prompt_var.set(f'Ошибка, правильный результат {self.current_correct}')
        _fixed314_method_c_set_mode(self, 'error')
    self._tick_stage_clock()


def _fixed137_method_c_normalize_entry(self):
    raw = ''.join(ch for ch in self.entry_var.get() if ch.isdigit())
    max_len = _fixed314_method_c_required_len(self)
    if len(raw) > max_len:
        raw = raw[:max_len]
    if raw != self.entry_var.get():
        self.entry_var.set(raw)
    _fixed137_method_c_sync_input_display(self)


def _fixed137_method_c_append_digit(self, digit: str):
    if getattr(self, 'phase', '') != 'input':
        return
    _fixed137_method_c_normalize_entry(self)
    current = self.entry_var.get()
    max_len = _fixed314_method_c_required_len(self)
    if len(current) >= max_len:
        return
    self.entry_var.set(f'{current}{digit}')
    _fixed137_method_c_sync_input_display(self)
    try:
        self.entry.focus_set()
        self.entry.icursor(tk.END)
    except Exception:
        pass


MethodCWindow._build_ui = _fixed314_method_c_build_ui
MethodCWindow._start_stage = _fixed314_method_c_start_stage
MethodCWindow._start_operation_cycle = _fixed314_method_c_start_operation_cycle
MethodCWindow._begin_input_phase = _fixed314_method_c_begin_input_phase
MethodCWindow._submit_answer = _fixed314_method_c_submit_answer
MethodCWindow._resolve_cycle = _fixed314_method_c_resolve_cycle
MethodCWindow._append_digit = _fixed137_method_c_append_digit


# ====== FIXED323: Method C stage-end text fit + timer freeze while waiting for "Далее" ======
_FIXED323_PREV_METHOD_C_START_STAGE = MethodCWindow._start_stage
_FIXED323_PREV_METHOD_C_START_OPERATION_CYCLE = MethodCWindow._start_operation_cycle
_FIXED323_PREV_METHOD_C_SUBMIT_ANSWER = MethodCWindow._submit_answer


def _fixed323_method_c_fit_prompt(self):
    if '_fixed301_method_c_fit_prompt' in globals():
        try:
            _fixed301_method_c_fit_prompt(self)
        except Exception:
            pass


def _fixed323_method_c_pause_on(self):
    if float(getattr(self, '_fixed323_pause_started_at', 0.0) or 0.0) > 0.0:
        return
    self._fixed323_pause_started_at = time.perf_counter()


def _fixed323_method_c_pause_off(self):
    started = float(getattr(self, '_fixed323_pause_started_at', 0.0) or 0.0)
    if started <= 0.0:
        return
    total = float(getattr(self, '_fixed323_pause_total_s', 0.0) or 0.0)
    total += max(0.0, time.perf_counter() - started)
    self._fixed323_pause_total_s = total
    self._fixed323_pause_started_at = 0.0


def _fixed323_method_c_total_time_left(self) -> float:
    total_cfg = float(getattr(self.cfg, 'total_test_s', 0.0) or 0.0)
    if total_cfg <= 0.0:
        stage_cfg = getattr(self.cfg, 'stage_time_s', [40.0, 40.0, 40.0]) or [40.0, 40.0, 40.0]
        total_cfg = float(sum(float(x) for x in stage_cfg))
    started = float(getattr(self, 'total_started_at', 0.0) or 0.0)
    if started <= 0.0:
        return total_cfg

    now = time.perf_counter()
    paused_total = float(getattr(self, '_fixed323_pause_total_s', 0.0) or 0.0)
    pause_started = float(getattr(self, '_fixed323_pause_started_at', 0.0) or 0.0)
    if pause_started > 0.0:
        paused_total += max(0.0, now - pause_started)

    elapsed = max(0.0, (now - started) - paused_total)
    return max(0.0, total_cfg - elapsed)


def _fixed323_method_c_start_stage(self, stage_index: int):
    _fixed323_method_c_pause_off(self)
    result = _FIXED323_PREV_METHOD_C_START_STAGE(self, stage_index)
    _fixed323_method_c_fit_prompt(self)

    phase = str(getattr(self, 'phase', '') or '')
    action = str(getattr(self, '_fixed314_next_action', '') or '')
    if phase in ('finished_notice', 'stage_done') or action in ('next_stage', 'finish'):
        _fixed323_method_c_pause_on(self)
    else:
        _fixed323_method_c_pause_off(self)
    return result


def _fixed323_method_c_start_operation_cycle(self):
    _fixed323_method_c_pause_off(self)
    result = _FIXED323_PREV_METHOD_C_START_OPERATION_CYCLE(self)
    _fixed323_method_c_fit_prompt(self)

    phase = str(getattr(self, 'phase', '') or '')
    action = str(getattr(self, '_fixed314_next_action', '') or '')
    if phase in ('stage_done', 'finished_notice') or action in ('next_stage', 'finish'):
        _fixed323_method_c_pause_on(self)
    else:
        _fixed323_method_c_pause_off(self)
    return result


def _fixed323_method_c_submit_answer(self):
    phase = str(getattr(self, 'phase', '') or '')
    action = str(getattr(self, '_fixed314_next_action', '') or '')
    if phase != 'input' and action in ('next_stage', 'finish'):
        _fixed323_method_c_pause_off(self)
    result = _FIXED323_PREV_METHOD_C_SUBMIT_ANSWER(self)
    _fixed323_method_c_fit_prompt(self)
    return result


MethodCWindow._fixed193_total_time_left = _fixed323_method_c_total_time_left
MethodCWindow._start_stage = _fixed323_method_c_start_stage
MethodCWindow._start_operation_cycle = _fixed323_method_c_start_operation_cycle
MethodCWindow._submit_answer = _fixed323_method_c_submit_answer


