# ====== FIXED341: Method B results in Method C-style stage columns (3 per row) ======
def _fixed341_show_method_b_results(self, payload: dict):
    top, outer = _open_results_top(self, 'Результаты - Тест B. Запоминание фигур в матрице')

    participant = payload.get('participant', {}) if isinstance(payload, dict) else {}
    summary = dict(payload.get('summary', {}) or {}) if isinstance(payload, dict) else {}
    by_n = summary.get('by_n', {}) if isinstance(summary.get('by_n'), dict) else {}
    cycles = payload.get('cycles', []) if isinstance(payload.get('cycles', []), list) else []

    completed_at = payload.get('completed_at', '') if isinstance(payload, dict) else ''
    dt_label = completed_at.replace('T', ' ')[:19] if completed_at else 'не указано'

    # Determine how many stage-columns to render (settings + real data).
    stage_count = 12
    norm_list = []
    cfg_stage_count = 12
    try:
        cfg = load_method_b_config(self.base_dir)
        cfg_stage_count = max(1, min(12, int(getattr(cfg, 'max_items', 12) or 12)))
        norm_list = list(getattr(cfg, 'normative_times', []) or [])
    except Exception:
        cfg_stage_count = 12
        norm_list = []

    max_n_cycles = max((int(c.get('n', 0) or 0) for c in cycles if isinstance(c, dict)), default=0)
    max_n_by_n = 0
    try:
        max_n_by_n = max((int(k) for k in by_n.keys() if str(k).isdigit()), default=0)
    except Exception:
        max_n_by_n = 0
    stage_count = max(1, min(12, max(cfg_stage_count, max_n_cycles, max_n_by_n)))

    while len(norm_list) < stage_count:
        norm_list.append(float(norm_list[-1]) if norm_list else 0.0)

    # Fallback for legacy payloads: recompute stage stats from raw cycles.
    agg = {n: {'k_obsh': 0, 'k_usp': 0, 'sum_t': 0.0} for n in range(1, stage_count + 1)}
    timeout_numbers = set()
    success_numbers = set()
    for cyc in cycles:
        if not isinstance(cyc, dict):
            continue
        n = int(cyc.get('n', 0) or 0)
        if not (1 <= n <= stage_count):
            continue
        agg[n]['k_obsh'] += 1
        agg[n]['sum_t'] += max(0.0, float(cyc.get('elapsed_s', 0.0) or 0.0))
        if bool(cyc.get('success')):
            agg[n]['k_usp'] += 1
            success_numbers.add(n)
        elif str(cyc.get('reason', '') or '').strip().lower() == 'timeout':
            timeout_numbers.add(n)

    def _f2(v) -> str:
        try:
            return f"{float(v):.2f}"
        except Exception:
            return '0.00'

    def _f4(v) -> str:
        try:
            return f"{float(v):.4f}"
        except Exception:
            return '0.0000'

    def _i(v) -> str:
        try:
            return str(int(v))
        except Exception:
            return '0'

    def _fig_word(n: int) -> str:
        n_abs = abs(int(n))
        n100 = n_abs % 100
        if 11 <= n100 <= 14:
            return 'фигур'
        n10 = n_abs % 10
        if n10 == 1:
            return 'фигура'
        if 2 <= n10 <= 4:
            return 'фигуры'
        return 'фигур'

    def _sec_int(v) -> str:
        try:
            return str(max(0, int(round(float(v)))))
        except Exception:
            return '0'

    def _stage_item(n: int) -> dict:
        key = str(n)
        src = by_n.get(key, {}) if isinstance(by_n, dict) else {}
        if not isinstance(src, dict):
            src = {}
        k_obsh = int(src.get('k_obsh', agg[n]['k_obsh']) or 0)
        k_usp = int(src.get('k_usp', agg[n]['k_usp']) or 0)
        t_sum = float(agg[n]['sum_t'])
        t_avg = float(src.get('t_avg_s', (t_sum / k_obsh if k_obsh > 0 else 0.0)) or 0.0)
        t_norm = float(src.get('t_norm_s', norm_list[n - 1] if 1 <= n <= len(norm_list) else 0.0) or 0.0)
        gamma = float(src.get('gamma_n', (_safe_ratio(k_usp, k_obsh, 0.0))) or 0.0)
        if 't_n_zap' in src:
            t_zap = float(src.get('t_n_zap', 0.0) or 0.0)
        else:
            den = max(0.0001, t_norm * max(1, k_obsh))
            t_zap = (t_avg * k_usp) / den if k_obsh > 0 else 0.0
        return {
            'has_data': k_obsh > 0,
            'timeout_only': k_obsh > 0 and n in timeout_numbers and n not in success_numbers,
            'k_obsh': k_obsh,
            'k_usp': k_usp,
            't_sum_s': t_sum,
            't_avg_s': t_avg,
            't_norm_s': t_norm,
            'gamma_n': gamma,
            't_n_zap': t_zap,
        }

    # Header (same visual language as test C result pages).
    header = tk.Frame(outer, bg='#ffffff', highlightthickness=1, highlightbackground='#d8e1ec')
    header.pack(fill='x', padx=24, pady=(24, 10))
    tk.Frame(header, bg='#67a9ff', height=6).pack(fill='x')
    head_body = tk.Frame(header, bg='#ffffff')
    head_body.pack(fill='both', expand=True, padx=22, pady=(14, 12))
    tk.Label(head_body, text='Тест B   Запоминание матриц', bg='#ffffff', fg='#102744', font=('Times New Roman', 30, 'bold')).pack(anchor='w')
    subtitle = f"{participant.get('name', '')}, {participant.get('age', '')} лет, {participant.get('gender', '')}. Последнее завершение: {dt_label}."
    tk.Label(head_body, text=subtitle, bg='#ffffff', fg='#5a6678', font=('Arial', 10, 'bold'), wraplength=1160, justify='left').pack(anchor='w', pady=(4, 0))

    # Верхние карточки: только "приведенный темп для ... фигур".
    palette = ['#67a9ff', '#53c26b', '#c98cff', '#ffb35c', '#78d3e2', '#ef7070']
    tempo_cards: list[tuple[str, str, str, str]] = []
    for n in range(1, stage_count + 1):
        stage = _stage_item(n)
        if not stage['has_data']:
            continue
        tempo_cards.append((
            f'Приведенный темп для {n} {_fig_word(n)}',
            _f4(stage['t_n_zap']),
            f'tзап {n}',
            '#ffffff' if stage.get('timeout_only') else palette[(len(tempo_cards)) % len(palette)],
        ))

    if not tempo_cards:
        tempo_cards = [('Приведенный темп', '—', 'Нет данных по завершенным циклам', '#67a9ff')]

    cards_host = tk.Frame(outer, bg='#eef3f8')
    cards_host.pack(anchor='center', padx=24, fill='x')

    if len(tempo_cards) <= 6:
        _draw_summary_cards(cards_host, tempo_cards).pack(anchor='center', fill='x')
    else:
        cards_grid = tk.Frame(cards_host, bg='#eef3f8')
        cards_grid.pack(fill='x')
        max_per_row = 6
        for c in range(max_per_row):
            cards_grid.grid_columnconfigure(c, weight=1, uniform='b_fixed347_cards')
        for i, (title, value, subtitle, accent) in enumerate(tempo_cards):
            r = i // max_per_row
            c = i % max_per_row
            card = tk.Frame(cards_grid, bg='white', bd=0, highlightbackground='#d8e1ec', highlightthickness=1)
            card.grid(row=r, column=c, padx=8, pady=8, sticky='nsew')
            tk.Frame(card, bg=accent, height=6).pack(fill='x')
            tk.Label(card, text=title, bg='white', fg='#425065', font=('Arial', 10, 'bold'), wraplength=220, justify='left').pack(anchor='w', padx=12, pady=(10, 4))
            tk.Label(card, text=value, bg='white', fg='#102744', font=('Arial', 20, 'bold')).pack(anchor='w', padx=12)
            tk.Label(card, text=subtitle, bg='white', fg='#657385', font=('Arial', 10), wraplength=220, justify='left').pack(anchor='w', padx=12, pady=(2, 10))

    info = (
        'Расчёт выполнен по документу: tзап(n) = tср(n) × kусп(n) / (tнорм(n) × kобщ(n)). '
        'Для каждого этапа (числа фигур n) показаны исходные параметры и приведённый темп.'
    )
    _add_info_box(outer, 'Формула расчёта', info, '#53a7ff').pack(anchor='center', padx=24, pady=(6, 12), fill='x')

    # Stage blocks: 3 per row (1..3, then 4..6, etc.).
    grid = tk.Frame(outer, bg='#eef3f8')
    grid.pack(fill='x', padx=24, pady=(0, 10))
    for c in range(3):
        grid.grid_columnconfigure(c, weight=1, uniform='b_fixed341_cols')

    yellow = '#ffd400'
    row_defs = [
        ('время этапа (сек)', lambda s, n: f'T{n}', lambda s: _sec_int(s['t_sum_s']), 0),
        ('всего циклов', lambda s, n: f'kобщ {n}', lambda s: _i(s['k_obsh']), 0),
        ('из них верных', lambda s, n: f'kусп {n}', lambda s: _i(s['k_usp']), 0),
        ('коэффициент успешности', lambda s, n: f'Yзап {n}', lambda s: _f4(s['gamma_n']), 4),
        ('реальный темп', lambda s, n: f'tср {n}', lambda s: _f2(s['t_avg_s']), 2),
        ('нормативный темп', lambda s, n: f'tнорм {n}', lambda s: _f2(s['t_norm_s']), 2),
        ('приведенный темп', lambda s, n: f'tзап {n}', lambda s: _f4(s['t_n_zap']), 4),
    ]

    for idx, n in enumerate(range(1, stage_count + 1)):
        row = idx // 3
        col = idx % 3
        stage = _stage_item(n)

        block = tk.Frame(grid, bg='white', highlightthickness=1, highlightbackground='#d8e1ec')
        block.grid(row=row, column=col, sticky='nsew', padx=4, pady=4)

        top_bar = '#ffffff' if stage.get('timeout_only') else ['#78d3e2', '#ffb35c', '#ef7070'][col]
        tk.Frame(block, bg=top_bar, height=3).pack(fill='x', side='top')
        tk.Label(
            block,
            text=f'{n} {_fig_word(n)}',
            bg='white',
            fg='#111111',
            font=('Arial', 15, 'bold')
        ).pack(pady=(8, 6))

        tbl = tk.Frame(block, bg='white', highlightthickness=1, highlightbackground='#9c9c9c')
        tbl.pack(fill='x', padx=6, pady=(0, 8))
        tbl.grid_columnconfigure(0, weight=2, uniform='b_fixed341_tbl')
        tbl.grid_columnconfigure(1, weight=1, uniform='b_fixed341_tbl')
        tbl.grid_columnconfigure(2, weight=1, uniform='b_fixed341_tbl')

        headers = ('НАЗВАНИЕ\nПАРАМЕТРА', 'ПАРАМЕТР\nразмерность', 'величина')
        for j, htxt in enumerate(headers):
            tk.Label(
                tbl,
                text=htxt,
                bg=yellow,
                fg='#1a1a1a',
                font=('Arial', 10, 'bold'),
                bd=1,
                relief='solid',
                padx=4,
                pady=6,
                justify='left' if j == 0 else 'center',
                anchor='w' if j == 0 else 'center',
            ).grid(row=0, column=j, sticky='nsew')

        for r_idx, (name_txt, sym_fn, val_fn, _digits) in enumerate(row_defs, start=1):
            values = (
                name_txt,
                sym_fn(stage, n),
                (val_fn(stage) if stage['has_data'] else '—'),
            )
            for j, text in enumerate(values):
                bg = '#f8ffff' if j == 0 and r_idx % 2 == 0 else ('#effff4' if j == 0 else '#ffffff')
                tk.Label(
                    tbl,
                    text=text,
                    bg=bg,
                    fg='#102744' if j == 0 else '#20324d',
                    font=('Arial', 9, 'bold' if j != 2 else 'normal'),
                    bd=1,
                    relief='solid',
                    padx=4,
                    pady=4,
                    justify='left' if j == 0 else 'center',
                    anchor='w' if j == 0 else 'center',
                ).grid(row=r_idx, column=j, sticky='nsew')

    pdf_path = _fixed306_export_method_b_pdf_all_results(self, top, payload)
    if pdf_path:
        payload['pdf_path'] = pdf_path
        if isinstance(payload.get('summary', None), dict):
            payload['summary']['pdf_path'] = pdf_path


