_FIXED342_PREV_EXPORT_METHOD_B_PDF = _fixed306_export_method_b_pdf_all_results


def _fixed342_method_b_fig_word(n: int) -> str:
    n_abs = abs(int(n))
    n100 = n_abs % 100
    if 11 <= n100 <= 14:
        return 'фигур'
    n10 = n_abs % 10
    if n10 == 1:
        return 'фигура'
    if 2 <= n10 <= 4:
        return 'фигуры'
    return 'фигур'


def _fixed342_export_method_b_pdf_from_payload(self, payload: dict, note: str = '') -> str:
    try:
        from PIL import Image as _PILImage
        from PIL import ImageDraw as _PILImageDraw
        from PIL import ImageFont as _PILImageFont
    except Exception:
        return ''

    try:
        summary = dict(payload.get('summary', {}) or {}) if isinstance(payload, dict) else {}
        participant = dict(payload.get('participant', {}) or {}) if isinstance(payload, dict) else {}
        by_n = summary.get('by_n', {}) if isinstance(summary.get('by_n'), dict) else {}
        cycles = payload.get('cycles', []) if isinstance(payload.get('cycles', []), list) else []

        stage_count = 12
        norm_list: list[float] = []
        cfg_stage_count = 12
        try:
            cfg = load_method_b_config(self.base_dir)
            cfg_stage_count = max(1, min(12, int(getattr(cfg, 'max_items', 12) or 12)))
            norm_list = list(getattr(cfg, 'normative_times', []) or [])
        except Exception:
            cfg_stage_count = 12
            norm_list = []
        max_n_cycles = max((int(c.get('n', 0) or 0) for c in cycles if isinstance(c, dict)), default=0)
        max_n_by_n = 0
        try:
            max_n_by_n = max((int(k) for k in by_n.keys() if str(k).isdigit()), default=0)
        except Exception:
            max_n_by_n = 0
        stage_count = max(1, min(12, max(cfg_stage_count, max_n_cycles, max_n_by_n)))
        while len(norm_list) < stage_count:
            norm_list.append(float(norm_list[-1]) if norm_list else 0.0)

        agg = {n: {'k_obsh': 0, 'k_usp': 0, 'sum_t': 0.0} for n in range(1, stage_count + 1)}
        for cyc in cycles:
            if not isinstance(cyc, dict):
                continue
            n = int(cyc.get('n', 0) or 0)
            if not (1 <= n <= stage_count):
                continue
            agg[n]['k_obsh'] += 1
            agg[n]['sum_t'] += max(0.0, float(cyc.get('elapsed_s', 0.0) or 0.0))
            if bool(cyc.get('success')):
                agg[n]['k_usp'] += 1

        def _f2(v) -> str:
            try:
                return f'{float(v):.2f}'
            except Exception:
                return '0.00'

        def _f4(v) -> str:
            try:
                return f'{float(v):.4f}'
            except Exception:
                return '0.0000'

        def _i(v) -> str:
            try:
                return str(int(v))
            except Exception:
                return '0'

        lines: list[str] = []
        completed_at = str(payload.get('completed_at', '') or '').replace('T', ' ')[:19]
        lines.append('Тест B · Запоминание фигур в матрице')
        lines.append(
            f"{participant.get('name', '')}, {participant.get('age', '')} лет, {participant.get('gender', '')}. "
            f"Последнее завершение: {completed_at or 'не указано'}."
        )
        lines.append('')
        lines.append(
            f"Всего циклов: {_i(summary.get('cycles_total', 0))}; "
            f"из них верных: {_i(summary.get('successful_cycles', 0))}; "
            f"точность: {float(summary.get('accuracy_pct', 0.0) or 0.0):.1f}%."
        )
        lines.append('Формула: tзап(n) = tср(n) × kусп(n) / (tнорм(n) × kобщ(n)).')
        if note:
            lines.append(f'Примечание экспорта: {note}')
        lines.append('')

        for n in range(1, stage_count + 1):
            src = by_n.get(str(n), {}) if isinstance(by_n, dict) else {}
            if not isinstance(src, dict):
                src = {}
            k_obsh = int(src.get('k_obsh', agg[n]['k_obsh']) or 0)
            k_usp = int(src.get('k_usp', agg[n]['k_usp']) or 0)
            t_avg = float(src.get('t_avg_s', (agg[n]['sum_t'] / k_obsh if k_obsh > 0 else 0.0)) or 0.0)
            t_norm = float(src.get('t_norm_s', norm_list[n - 1] if 1 <= n <= len(norm_list) else 0.0) or 0.0)
            gamma = float(src.get('gamma_n', _safe_ratio(k_usp, k_obsh, 0.0)) or 0.0)
            if 't_n_zap' in src:
                t_zap = float(src.get('t_n_zap', 0.0) or 0.0)
            else:
                den = max(0.0001, t_norm * max(1, k_obsh))
                t_zap = (t_avg * k_usp) / den if k_obsh > 0 else 0.0

            lines.append(f'{n} {_fixed342_method_b_fig_word(n)}')
            lines.append(
                f"  kобщ={_i(k_obsh)}; kусп={_i(k_usp)}; Yзап={_f4(gamma)}; "
                f"tср={_f2(t_avg)} c; tнорм={_f2(t_norm)} c; tзап={_f4(t_zap)}"
            )
            lines.append('')

        page_w, page_h = 1654, 2339  # A4 @150 dpi
        margin_x, margin_y = 80, 80
        line_h = 34

        font_path = Path('C:/Windows/Fonts/arial.ttf')
        if font_path.exists():
            font = _PILImageFont.truetype(str(font_path), 30)
            title_font = _PILImageFont.truetype(str(font_path), 38)
        else:
            font = _PILImageFont.load_default()
            title_font = font

        pages: list[_PILImage.Image] = []
        page = _PILImage.new('RGB', (page_w, page_h), 'white')
        draw = _PILImageDraw.Draw(page)
        y = margin_y

        for idx, ln in enumerate(lines):
            use_font = title_font if idx == 0 else font
            if y + line_h >= page_h - margin_y:
                pages.append(page)
                page = _PILImage.new('RGB', (page_w, page_h), 'white')
                draw = _PILImageDraw.Draw(page)
                y = margin_y
            draw.text((margin_x, y), ln, fill='#111111', font=use_font)
            y += (line_h + 6) if idx == 0 else line_h

        pages.append(page)

        session_id = str(payload.get('session_id', 'session') or 'session')
        ts = datetime.now().strftime('%Y%m%d_%H%M%S')
        pdf_path = _results_dir(self.base_dir) / f'method_b_all_results_{session_id}_{ts}.pdf'
        pages[0].save(str(pdf_path), format='PDF', save_all=True, append_images=pages[1:], resolution=150.0)
        return str(pdf_path)
    except Exception:
        return ''


def _fixed342_export_method_b_pdf_all_results(self, top: tk.Toplevel, payload: dict) -> str:
    pdf_path = ''
    err_note = ''
    try:
        pdf_path = _FIXED342_PREV_EXPORT_METHOD_B_PDF(self, top, payload)
    except Exception as exc:
        err_note = f'capture_exception={exc}'
        pdf_path = ''

    try:
        if pdf_path and Path(str(pdf_path)).exists():
            return str(pdf_path)
    except Exception:
        pass

    fallback = _fixed342_export_method_b_pdf_from_payload(self, payload, note='fallback_payload_export')
    if fallback:
        return fallback
    if err_note:
        try:
            log_path = _results_dir(self.base_dir) / f"method_b_pdf_error_{datetime.now().strftime('%Y%m%d_%H%M%S')}.txt"
            log_path.write_text(err_note, encoding='utf-8')
        except Exception:
            pass
    return ''


_fixed306_export_method_b_pdf_all_results = _fixed342_export_method_b_pdf_all_results


# ====== FIXED343: Memory tray one-row + Method C first-start guard + Method B time unlock ======


def load_method_b_config(base_dir: Path) -> MethodBConfig:
    """Method B config without forced 120-second clamp (keeps researcher settings)."""
    try:
        if callable(globals().get('_prev_load_method_b_config_fixed89', None)):
            cfg = _prev_load_method_b_config_fixed89(base_dir)
        else:
            cfg = _load_json_dataclass(base_dir / 'method_b_config.json', MethodBConfig)
    except Exception:
        cfg = _load_json_dataclass(base_dir / 'method_b_config.json', MethodBConfig)

    try:
        cfg.total_test_s = max(10.0, float(getattr(cfg, 'total_test_s', 300.0) or 300.0))
    except Exception:
        cfg.total_test_s = 300.0

    try:
        cfg.max_items = max(1, int(getattr(cfg, 'max_items', 16) or 16))
    except Exception:
        cfg.max_items = 16

    try:
        norms = list(getattr(cfg, 'normative_times', []) or [])
    except Exception:
        norms = []
    if not norms:
        norms = [5.0 + 3.0 * (i - 1) for i in range(1, cfg.max_items + 1)]
    while len(norms) < cfg.max_items:
        norms.append(float(norms[-1]) if norms else 5.0)
    cfg.normative_times = [float(v) for v in norms[:cfg.max_items]]
    try:
        cfg.normative_success_coef = max(1e-6, float(getattr(cfg, 'normative_success_coef', 1.0) or 1.0))
    except Exception:
        cfg.normative_success_coef = 1.0
    return cfg




_FIXED343_PREV_METHOD_C_START_OPERATION_CYCLE = MethodCWindow._start_operation_cycle


def _fixed343_method_c_start_operation_cycle(self):
    result = _FIXED343_PREV_METHOD_C_START_OPERATION_CYCLE(self)
    # First-run guard: ensure keypad really becomes interactive in input phase.
    if str(getattr(self, 'phase', '') or '') == 'input':
        try:
            _fixed314_method_c_set_mode(self, 'input')
        except Exception:
            pass
        try:
            for w in list(getattr(self, '_method_c_input_widgets', [])[2:]):
                try:
                    w.configure(state='normal')
                except Exception:
                    pass
        except Exception:
            pass
    return result


def _fixed343_method_c_run(self):
    # Keep current run flow but force deterministic first-stage kickoff.
    self._build_ui()
    self.total_started_at = 0.0

    def _start_main_test():
        if '_fixed330_method_c_hide_instruction' in globals():
            try:
                _fixed330_method_c_hide_instruction(self)
            except Exception:
                pass
        if '_fixed327_method_c_clear_start_labels' in globals():
            try:
                _fixed327_method_c_clear_start_labels(self)
            except Exception:
                pass
        try:
            btn = getattr(self, '_fixed327_start_center_btn', None)
            if btn is not None and btn.winfo_exists():
                btn.destroy()
        except Exception:
            pass
        try:
            btn = getattr(self, '_fixed327_start_cancel_btn', None)
            if btn is not None and btn.winfo_exists():
                btn.destroy()
        except Exception:
            pass
        try:
            self.start_btn.destroy()
        except Exception:
            pass
        try:
            self._time_col.grid()
        except Exception:
            pass
        try:
            self.clear_btn.configure(command=self._clear_input)
            self.clear_btn.place_forget()
        except Exception:
            pass

        self.total_started_at = time.perf_counter()
        self._fixed314_started = True
        self._fixed314_next_action = 'start_cycle'
        try:
            self.logger.log_event(
                self.session,
                event_type='method_session',
                screen='method_c',
                test_name='method_c',
                action='started',
                note='Запущена методика C: счет в заданном темпе'
            )
        except Exception:
            pass

        def _kickoff():
            try:
                self._start_stage(1)
                if str(getattr(self, 'phase', '') or '') == 'stage_ready':
                    try:
                        _fixed314_method_c_set_mode(self, 'stage_ready')
                    except Exception:
                        pass
            except Exception:
                pass

        try:
            self.win.after(30, _kickoff)
        except Exception:
            _kickoff()

    def _open_instruction():
        if '_fixed327_method_c_clear_start_labels' in globals():
            try:
                _fixed327_method_c_clear_start_labels(self)
            except Exception:
                pass
        try:
            btn = getattr(self, '_fixed327_start_center_btn', None)
            if btn is not None and btn.winfo_exists():
                btn.place_forget()
        except Exception:
            pass
        try:
            btn = getattr(self, '_fixed327_start_cancel_btn', None)
            if btn is not None and btn.winfo_exists():
                btn.place_forget()
        except Exception:
            pass
        if '_fixed330_method_c_show_instruction' in globals():
            _fixed330_method_c_show_instruction(self, _start_main_test)
        else:
            _start_main_test()

    btn = getattr(self, '_fixed327_start_center_btn', None)
    if btn is not None:
        try:
            btn.configure(command=_open_instruction)
        except Exception:
            pass
    else:
        try:
            self.start_btn.configure(command=_open_instruction)
        except Exception:
            pass

    self.parent.wait_window(self.win)
    return self.result


