# ====== FIXED344: Method A instruction page shows a single reference image ======
def _fixed344_show_method_a_instruction(self) -> str:
    root = getattr(self, 'root', None)
    if root is None or not root.winfo_exists():
        return 'cancel'

    top = tk.Toplevel(root)
    top.title('СПР - Тест A · Инструкция')
    top.configure(bg='#ececec')
    top.transient(root)
    top.grab_set()
    top.protocol('WM_DELETE_WINDOW', lambda: None)

    try:
        top.attributes('-fullscreen', True)
    except Exception:
        sw = int(root.winfo_screenwidth())
        sh = int(root.winfo_screenheight())
        top.geometry(f'{sw}x{sh}+0+0')

    try:
        top.lift()
        top.focus_force()
    except Exception:
        pass

    sw = int(root.winfo_screenwidth())
    sh = int(root.winfo_screenheight())

    result = {'action': 'cancel'}

    def _finish(action: str):
        result['action'] = str(action or 'cancel')
        try:
            top.grab_release()
        except Exception:
            pass
        try:
            top.destroy()
        except Exception:
            pass

    top.bind('<Escape>', lambda _e: _finish('cancel'))

    instr_bg = '#ececec'
    left_margin = max(20, int(sw * 0.03))
    right_margin = max(20, int(sw * 0.03))
    top_margin = max(18, int(sh * 0.03))
    bottom_margin = max(12, int(sh * 0.02))

    frame_w = max(980, sw - left_margin - right_margin)
    frame_h = max(620, sh - top_margin - bottom_margin)

    frame = tk.Frame(top, bg=instr_bg)
    frame.place(x=left_margin, y=top_margin, width=frame_w, height=frame_h)

    content = tk.Frame(frame, bg=instr_bg)
    content.pack(fill='both', expand=True, padx=(24, 24), pady=(20, 8))

    img_candidates = _instruction_image_candidates(
        self.base_dir,
        'method_a_instruction_slezh_page1_fixed412.png',
        extra_names=['method_a_instruction_slezh_page1.png', 'image1.png', 'image.png'],
    )

    image_photo = None
    image_widget = None
    for p in img_candidates:
        if not p.exists():
            continue
        try:
            with Image.open(p) as src:
                src = src.convert('RGBA')
                content_w = max(600, frame_w - 48)
                content_h = max(320, int(frame_h * 0.78))
                scale = min(
                    float(content_w) / float(max(1, src.width)),
                    float(content_h) / float(max(1, src.height)),
                    1.0
                )
                draw_w = max(1, int(round(src.width * scale)))
                draw_h = max(1, int(round(src.height * scale)))
                resized = src.resize((draw_w, draw_h), Image.LANCZOS)
            image_photo = ImageTk.PhotoImage(resized)
            image_widget = tk.Label(content, image=image_photo, bg=instr_bg, bd=0, highlightthickness=0)
            image_widget.image = image_photo
            image_widget.pack(anchor='n', pady=(0, 0))
            break
        except Exception:
            image_photo = None
            image_widget = None

    if image_widget is None:
        tk.Label(
            content,
            text='Не найден файл инструкции: assets/method_a_instruction_slezh_page1_fixed412.png',
            bg=instr_bg,
            fg='#2b2b2b',
            font=('Arial', 16, 'bold'),
            justify='center',
        ).pack(expand=True)

    btn_row = tk.Frame(frame, bg=instr_bg)
    btn_row.pack(side='bottom', pady=(0, 26))
    for c in range(3):
        btn_row.grid_columnconfigure(c, weight=1, uniform='fixed344_instr_btn')

    btn_font = ('Arial', 20, 'bold')
    tk.Button(
        btn_row,
        text='Тренировка',
        command=lambda: _finish('training'),
        bg='#ffee20',
        activebackground='#e3d600',
        fg='#1d1d1d',
        font=btn_font,
        width=14,
        bd=3,
        relief='raised',
        highlightthickness=1,
        highlightbackground='#000000',
        highlightcolor='#000000',
    ).grid(row=0, column=1, padx=18)

    tk.Button(
        btn_row,
        text='ДАЛЕЕ',
        command=lambda: _finish('continue'),
        bg='#8bcf4d',
        activebackground='#79bd3e',
        fg='#0a2a0a',
        font=btn_font,
        width=12,
        bd=3,
        relief='raised',
        highlightthickness=1,
        highlightbackground='#000000',
        highlightcolor='#000000',
    ).grid(row=0, column=2, padx=18)

    tk.Button(
        btn_row,
        text='Выход',
        command=lambda: _finish('exit'),
        bg='#e65050',
        activebackground='#cd3f3f',
        fg='white',
        font=btn_font,
        width=10,
        bd=3,
        relief='raised',
        highlightthickness=1,
        highlightbackground='#000000',
        highlightcolor='#000000',
    ).grid(row=0, column=0, padx=18)

    try:
        _fixed414_install_method_a_small_stick_continue(self, top, lambda: _finish('continue'))
    except Exception:
        pass

    root.wait_window(top)
    return str(result.get('action') or 'cancel')


_fixed341_show_method_a_instruction = _fixed344_show_method_a_instruction


# ====== FIXED345: Method A stage-end and test-end continue prompt with visible "Далее" ======
_FIXED345_PREV_METHOD_A_LOG_STAGE_REPORT = MethodAApp.log_stage_report
_FIXED345_PREV_METHOD_A_SHOW_MESSAGE = MethodAApp.show_message


def _fixed345_method_a_wrap_text(font, text: str, max_width: int) -> list[str]:
    words = str(text or '').split()
    if not words:
        return ['']
    lines: list[str] = []
    current = words[0]
    for word in words[1:]:
        test = f'{current} {word}'
        if font.size(test)[0] <= max_width:
            current = test
        else:
            lines.append(current)
            current = word
    lines.append(current)
    return lines


def _fixed345_method_a_wait_continue(self, message: str, button_text: str = 'Далее'):
    # Use the same geometry as standard Method A start/continue buttons.
    btn_w, btn_h = 360, 58
    btn_rect = pygame.Rect(
        (self.cfg.width - btn_w) // 2,
        int(self.cfg.height * 0.72),
        btn_w,
        btn_h,
    )

    msg_font = pygame.font.SysFont('Times New Roman', max(36, int(self.cfg.height * 0.048)), bold=True)
    btn_font = pygame.font.SysFont('arial', 22, bold=True)

    panel_w = min(self.cfg.width - 80, int(self.cfg.width * 0.86))
    text_max_w = panel_w - 80
    lines = _fixed345_method_a_wrap_text(msg_font, message, text_max_w)

    prev_grab = False
    prev_visible = True
    try:
        prev_grab = bool(pygame.event.get_grab())
    except Exception:
        prev_grab = False
    try:
        prev_visible = bool(pygame.mouse.get_visible())
    except Exception:
        prev_visible = True

    try:
        # Important: mouse must be visible/clickable on this screen.
        try:
            pygame.event.set_grab(False)
        except Exception:
            pass
        try:
            pygame.mouse.set_visible(True)
        except Exception:
            pass

        joy_continue_state = None
        try:
            joy_continue_state = _fixed414_init_small_stick_continue_state(self)
        except Exception:
            joy_continue_state = None

        while True:
            self.clock.tick(self.cfg.fps)
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    raise MethodAAbort
                if event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_ESCAPE:
                        raise MethodAAbort
                    if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
                        return
                if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                    if btn_rect.collidepoint(event.pos):
                        return

            try:
                if joy_continue_state and _fixed414_small_stick_forward_pushed(joy_continue_state):
                    return
            except Exception:
                pass

            self.draw_background()

            line_h = msg_font.get_linesize()
            panel_h = max(110, 36 + len(lines) * line_h + 24)
            panel = pygame.Surface((panel_w, panel_h), pygame.SRCALPHA)
            panel.fill((255, 255, 255, 230))
            panel_rect = panel.get_rect(center=(self.cfg.width // 2, int(self.cfg.height * 0.30)))
            self.screen.blit(panel, panel_rect)
            pygame.draw.rect(self.screen, self.cfg.grid_color, panel_rect, 2, border_radius=12)

            y = panel_rect.y + 18
            for line in lines:
                surf = msg_font.render(line, True, (12, 37, 74))
                x = panel_rect.centerx - surf.get_width() // 2
                self.screen.blit(surf, (x, y))
                y += line_h

            # Same visual style as standard Method A green buttons.
            pygame.draw.rect(self.screen, (88, 204, 99), btn_rect)
            pygame.draw.rect(self.screen, (23, 59, 26), btn_rect, 2)
            btn_caption = str(button_text or 'ДАЛЕЕ').upper()
            btn_surf = btn_font.render(btn_caption, True, (23, 59, 26))
            self.screen.blit(
                btn_surf,
                (btn_rect.centerx - btn_surf.get_width() // 2, btn_rect.centery - btn_surf.get_height() // 2)
            )

            pygame.display.flip()
    finally:
        try:
            pygame.event.set_grab(prev_grab)
        except Exception:
            pass
        try:
            pygame.mouse.set_visible(prev_visible)
        except Exception:
            pass


def _fixed345_method_a_log_stage_report(self, report: StageReport):
    result = _FIXED345_PREV_METHOD_A_LOG_STAGE_REPORT(self, report)
    try:
        total_stages = int(max(self.stage_defs.keys()))
    except Exception:
        total_stages = 3
    try:
        stage_no = int(getattr(report, 'stage_no', 0) or 0)
    except Exception:
        stage_no = 0

    if 0 < stage_no < total_stages:
        _fixed345_method_a_wait_continue(
            self,
            'Этап завершен. Для перехода к следующему этапу нажмите кнопку "Далее"',
            'Далее',
        )
    return result


def _fixed345_method_a_show_message(self, text: str, seconds: float = 1.0):
    normalized = str(text or '').strip().lower().replace('ё', 'е')
    if normalized == 'тест завершен':
        _fixed345_method_a_wait_continue(
            self,
            'Тест завершен. Для продолжения нажмите кнопку "Далее"',
            'Далее',
        )
        return
    return _FIXED345_PREV_METHOD_A_SHOW_MESSAGE(self, text, seconds)


MethodAApp.log_stage_report = _fixed345_method_a_log_stage_report
MethodAApp.show_message = _fixed345_method_a_show_message


