def _fixed346_method_b_run(self):
    self._build_ui()
    self._fixed197_smooth_after_id = None
    # До старта теста ничего не показываем в матрице.
    try:
        self.current_positions = []
        self.current_shapes = []
        self.all_tray_shapes = []
        self.placements = {}
        self.phase = 'preview'
        self.message_var.set('')
        self.selection_var.set('')
        self._draw_memory_matrix()
        self._draw_tray(show=False)
        _fixed414_method_b_hide_tray_panel(self)
    except Exception:
        pass

    def _start_main_test():
        _fixed346_method_b_hide_instruction_overlay(self)
        if '_fixed339_method_b_hide_start_screen' in globals():
            try:
                _fixed339_method_b_hide_start_screen(self)
            except Exception:
                pass
        try:
            self.start_btn.destroy()
        except Exception:
            pass
        try:
            self._time_col.grid()
        except Exception:
            pass
        self.total_start = time.perf_counter()
        self._method_b_started = True
        self.logger.log_event(
            self.session,
            event_type='method_session',
            screen='method_b',
            test_name='method_b',
            action='started',
            note='Запущена методика B: Memory 4x4'
        )
        # Важно: сразу подготовить первый цикл, иначе current_shapes остаётся пустым,
        # и касса на первом показе оказывается пустой.
        self._start_cycle()
        try:
            self._fixed197_smooth_timer_tick()
        except Exception:
            pass

    def _open_instruction():
        if '_fixed339_method_b_hide_start_screen' in globals():
            try:
                _fixed339_method_b_hide_start_screen(self)
            except Exception:
                pass
        _fixed346_method_b_show_instruction_overlay(self, _start_main_test)

    try:
        self.start_btn.configure(command=_open_instruction)
    except Exception:
        pass

    if '_fixed339_method_b_show_start_screen' in globals():
        _fixed339_method_b_show_start_screen(self, _open_instruction)
    else:
        _open_instruction()

    self.parent.wait_window(self.win)
    return self.result


MethodBWindow.run = _fixed346_method_b_run






