# ====== FIXED348: Method C stage-2/3 keep result digit length strictly by stage ======
def _fixed348_method_c_generate_operand(self, current: int, stage_index: int):
    lo, hi = self._stage_limits(stage_index)
    lo = max(1, int(lo))
    hi = int(hi)
    cur = int(current)

    # Required result range by stage:
    # stage 2 -> only 2-digit results, stage 3 -> only 3-digit results.
    if int(stage_index) == 2:
        target_lo, target_hi = 10, 99
    elif int(stage_index) >= 3:
        target_lo, target_hi = 100, 999
    else:
        target_lo, target_hi = 0, 9

    plus_range = None
    minus_range = None

    # '+' : target_lo <= cur + op <= target_hi
    plus_lo = max(lo, target_lo - cur)
    plus_hi = min(hi, target_hi - cur)
    if plus_lo <= plus_hi:
        plus_range = (plus_lo, plus_hi)

    # '-' : target_lo <= cur - op <= target_hi
    minus_lo = max(lo, cur - target_hi)
    minus_hi = min(hi, cur - target_lo)
    if minus_lo <= minus_hi:
        minus_range = (minus_lo, minus_hi)

    choices = []
    if plus_range is not None:
        choices.append('+')
    if minus_range is not None:
        choices.append('-')

    if not choices:
        # Fallback: keep legacy behavior if strict range is temporarily impossible.
        max_add = hi - cur
        max_sub = cur
        legacy = []
        if max_add >= lo:
            legacy.append('+')
        if max_sub >= lo:
            legacy.append('-')
        if not legacy:
            return '+', lo, cur
        op = random.choice(legacy)
        if op == '+':
            operand = random.randint(lo, max_add)
            correct = cur + operand
        else:
            operand = random.randint(lo, max_sub)
            correct = cur - operand
        if correct < 0:
            correct = 0
        return op, operand, correct

    op = random.choice(choices)
    if op == '+':
        a, b = plus_range
        operand = random.randint(int(a), int(b))
        correct = cur + operand
    else:
        a, b = minus_range
        operand = random.randint(int(a), int(b))
        correct = cur - operand

    return op, operand, int(correct)


MethodCWindow._generate_operand = _fixed348_method_c_generate_operand


# ====== FIXED349: Method D instruction page with single image testD_inst.png ======
def _fixed349_method_d_hide_instruction_overlay(self):
    overlay = getattr(self, '_fixed349_d_instr_overlay', None)
    if overlay is not None:
        try:
            overlay.destroy()
        except Exception:
            pass
    self._fixed349_d_instr_overlay = None

    frame = getattr(self, '_fixed349_d_instr_frame', None)
    if frame is not None:
        try:
            frame.destroy()
        except Exception:
            pass
    self._fixed349_d_instr_frame = None


def _fixed349_method_d_show_instruction_overlay(self, on_continue):
    if not (getattr(self, 'win', None) and self.win.winfo_exists()):
        return
    _fixed349_method_d_hide_instruction_overlay(self)

    # Full-screen overlay removes any underlying widgets (title/progress/bars),
    # and keeps background color uniform with no visible jumps.
    instr_bg = '#ececec'
    overlay = tk.Frame(self.win, bg=instr_bg, bd=0, highlightthickness=0)
    overlay.place(relx=0.0, rely=0.0, relwidth=1.0, relheight=1.0)
    try:
        overlay.lift()
    except Exception:
        pass
    self._fixed349_d_instr_overlay = overlay

    sw = int(self.win.winfo_screenwidth())
    sh = int(self.win.winfo_screenheight())

    try:
        extra_cm_px = int(round(float(self.win.winfo_fpixels('2c'))))
    except Exception:
        extra_cm_px = 76

    base_lr = max(20, int(sw * 0.02))
    base_tb = max(20, int(sh * 0.03))
    left_margin = base_lr + extra_cm_px
    right_margin = base_lr + extra_cm_px
    top_margin = base_tb + extra_cm_px
    bottom_margin = base_tb

    frame_w = max(980, sw - left_margin - right_margin)
    frame_h = max(620, sh - top_margin - bottom_margin)

    frame = tk.Frame(overlay, bg=instr_bg)
    frame.place(x=left_margin, y=top_margin, width=frame_w, height=frame_h)
    try:
        frame.lift()
    except Exception:
        pass
    self._fixed349_d_instr_frame = frame

    content = tk.Frame(frame, bg=instr_bg)
    content.pack(fill='both', expand=True, padx=(24, 24), pady=(20, 8))

    image_widget = None
    image_candidates = _instruction_image_candidates(self.base_dir, 'testD_inst.png')
    for img_path in image_candidates:
        try:
            if not img_path.exists():
                continue
            with Image.open(img_path) as src:
                src = src.convert('RGBA')
                content_w = max(800, frame_w - 48)
                content_h = max(420, int(frame_h * 0.80))
                scale = min(
                    float(content_w) / float(max(1, src.width)),
                    float(content_h) / float(max(1, src.height)),
                    1.0,
                )
                draw_w = max(1, int(round(src.width * scale)))
                draw_h = max(1, int(round(src.height * scale)))
                resized = src.resize((draw_w, draw_h), Image.LANCZOS)
            img = ImageTk.PhotoImage(resized)
            image_widget = tk.Label(content, image=img, bg=instr_bg, bd=0, highlightthickness=0)
            image_widget.image = img
            image_widget.pack(anchor='n')
            break
        except Exception:
            image_widget = None

    if image_widget is None:
        tk.Label(
            content,
            text='Не найден файл инструкции: testD_inst.png',
            bg=instr_bg,
            fg='#2b2b2b',
            font=('Arial', 16, 'bold'),
            justify='center',
        ).pack(expand=True)

    btn_row = tk.Frame(frame, bg=instr_bg)
    btn_row.pack(side='bottom', pady=(0, 26))
    for c in range(3):
        btn_row.grid_columnconfigure(c, weight=1, uniform='fixed349_instr_btn')

    btn_font = ('Arial', 20, 'bold')
    tk.Button(
        btn_row,
        text='Тренировка',
        command=lambda: _fixed418_run_training_d_from_instruction(self, on_continue),
        bg='#ffee20',
        activebackground='#e3d600',
        fg='#1d1d1d',
        font=btn_font,
        width=14,
        bd=3,
        relief='raised',
        highlightthickness=1,
        highlightbackground='#000000',
        highlightcolor='#000000',
    ).grid(row=0, column=1, padx=18)

    def _continue():
        _fixed349_method_d_hide_instruction_overlay(self)
        on_continue()

    tk.Button(
        btn_row,
        text='ДАЛЕЕ',
        command=_continue,
        bg='#8bcf4d',
        activebackground='#79bd3e',
        fg='#0a2a0a',
        font=btn_font,
        width=12,
        bd=3,
        relief='raised',
        highlightthickness=1,
        highlightbackground='#000000',
        highlightcolor='#000000',
    ).grid(row=0, column=2, padx=18)

    tk.Button(
        btn_row,
        text='Выход',
        command=self._abort,
        bg='#e65050',
        activebackground='#cd3f3f',
        fg='white',
        font=btn_font,
        width=10,
        bd=3,
        relief='raised',
        highlightthickness=1,
        highlightbackground='#000000',
        highlightcolor='#000000',
    ).grid(row=0, column=0, padx=18)


def _fixed349_method_d_run(self) -> dict:
    self._build_ui()

    def _start_main_test():
        _fixed349_method_d_hide_instruction_overlay(self)
        _fixed340_method_d_hide_start_screen(self)
        self.total_started_at = time.perf_counter()
        self.logger.log_event(
            self.session,
            event_type='method_session',
            screen='method_d',
            test_name='method_d',
            action='started',
            note=f'Запущен блок D{self.block_index}'
        )
        self._start_next_task()

    def _open_instruction():
        _fixed340_method_d_hide_start_screen(self)
        _fixed349_method_d_show_instruction_overlay(self, _start_main_test)

    _fixed340_method_d_show_start_screen(self, _open_instruction)
    self.parent.wait_window(self.win)
    return self.result


MethodDWindow.run = _fixed349_method_d_run


# ====== FIXED355: Method C harder tasks on stage 2/3 (no round numbers) ======
_FIXED355_PREV_METHOD_C_GENERATE_OPERAND = MethodCWindow._generate_operand
_FIXED355_PREV_METHOD_C_START_STAGE = MethodCWindow._start_stage


def _fixed355_is_round_number(value: int) -> bool:
    try:
        return (abs(int(value)) % 10) == 0
    except Exception:
        return False


def _fixed355_target_bounds(stage_index: int) -> tuple[int, int]:
    stage = int(stage_index or 1)
    if stage >= 3:
        return 100, 999
    if stage == 2:
        return 10, 99
    return 0, 9


def _fixed355_pick_non_round_in_range(lo: int, hi: int) -> int | None:
    lo = int(lo)
    hi = int(hi)
    if hi < lo:
        return None
    vals = [v for v in range(lo, hi + 1) if not _fixed355_is_round_number(v)]
    if not vals:
        return None
    return int(random.choice(vals))


def _fixed355_method_c_generate_operand(self, current: int, stage_index: int):
    stage = int(stage_index or 1)
    if stage < 2:
        return _FIXED355_PREV_METHOD_C_GENERATE_OPERAND(self, current, stage_index)

    lo, hi = self._stage_limits(stage)
    lo = max(1, int(lo))
    hi = int(hi)
    cur = int(current)
    target_lo, target_hi = _fixed355_target_bounds(stage)

    plus_range = None
    minus_range = None

    plus_lo = max(lo, target_lo - cur)
    plus_hi = min(hi, target_hi - cur)
    if plus_lo <= plus_hi:
        plus_range = (plus_lo, plus_hi)

    minus_lo = max(lo, cur - target_hi)
    minus_hi = min(hi, cur - target_lo)
    if minus_lo <= minus_hi:
        minus_range = (minus_lo, minus_hi)

    candidates: list[tuple[str, int, int]] = []
    if plus_range is not None:
        a, b = plus_range
        for operand in range(int(a), int(b) + 1):
            if _fixed355_is_round_number(operand):
                continue
            correct = cur + operand
            if not (target_lo <= correct <= target_hi):
                continue
            if _fixed355_is_round_number(correct):
                continue
            candidates.append(('+', int(operand), int(correct)))

    if minus_range is not None:
        a, b = minus_range
        for operand in range(int(a), int(b) + 1):
            if _fixed355_is_round_number(operand):
                continue
            correct = cur - operand
            if not (target_lo <= correct <= target_hi):
                continue
            if _fixed355_is_round_number(correct):
                continue
            candidates.append(('-', int(operand), int(correct)))

    if candidates:
        op, operand, correct = random.choice(candidates)
        return op, int(operand), int(correct)

    # Safety fallback: keep the app running even in pathological boundary states.
    op, operand, correct = _FIXED355_PREV_METHOD_C_GENERATE_OPERAND(self, current, stage_index)
    return op, int(operand), int(correct)


def _fixed355_method_c_start_stage(self, stage_index: int):
    result = _FIXED355_PREV_METHOD_C_START_STAGE(self, stage_index)
    stage = int(getattr(self, 'stage_index', stage_index) or stage_index or 1)
    if stage < 2:
        return result

    if str(getattr(self, 'phase', '') or '') != 'stage_ready':
        return result

    try:
        lo, hi = self._stage_limits(stage)
        target_lo, target_hi = _fixed355_target_bounds(stage)
        lo = max(int(lo), int(target_lo))
        hi = min(int(hi), int(target_hi))
        cur = int(getattr(self, 'current_value', lo) or lo)

        if cur < lo or cur > hi or _fixed355_is_round_number(cur):
            picked = _fixed355_pick_non_round_in_range(lo, hi)
            if picked is not None:
                self.current_value = int(picked)
                self.big_var.set(str(self.current_value))
    except Exception:
        pass
    return result


MethodCWindow._generate_operand = _fixed355_method_c_generate_operand
MethodCWindow._start_stage = _fixed355_method_c_start_stage


# ====== FIXED366: Method C operand rules by latest notes ======
_FIXED366_PREV_METHOD_C_GENERATE_OPERAND = MethodCWindow._generate_operand
_FIXED366_PREV_METHOD_C_START_STAGE = MethodCWindow._start_stage


def _fixed366_stage_target_bounds(stage_index: int) -> tuple[int, int]:
    stage = int(stage_index or 1)
    if stage >= 3:
        return 100, 999
    if stage == 2:
        return 10, 99
    return 0, 9


def _fixed366_is_all_same_digit(value: int, digit: str) -> bool:
    s = str(abs(int(value)))
    return bool(s) and all(ch == digit for ch in s)


def _fixed366_is_disallowed_later_number(value: int) -> bool:
    n = abs(int(value))
    s = str(n)
    if n % 10 == 0:
        return True
    if s.startswith('1'):
        return True
    if _fixed366_is_all_same_digit(n, '1') or _fixed366_is_all_same_digit(n, '9'):
        return True
    return False


def _fixed366_is_valid_stage_number(stage: int, value: int) -> bool:
    v = int(value)
    if stage <= 1:
        return v not in (0, 1)
    return not _fixed366_is_disallowed_later_number(v)


def _fixed366_candidates_for_current(stage: int, cur: int, lo: int, hi: int, target_lo: int, target_hi: int) -> list[tuple[str, int, int]]:
    candidates: list[tuple[str, int, int]] = []

    plus_lo = max(int(lo), int(target_lo) - int(cur))
    plus_hi = min(int(hi), int(target_hi) - int(cur))
    if plus_lo <= plus_hi:
        for operand in range(plus_lo, plus_hi + 1):
            correct = int(cur) + int(operand)
            if not (target_lo <= correct <= target_hi):
                continue
            if not _fixed366_is_valid_stage_number(stage, operand):
                continue
            if not _fixed366_is_valid_stage_number(stage, correct):
                continue
            if stage >= 2 and ((int(cur) % 10) + (int(operand) % 10) <= 10):
                continue
            candidates.append(('+', int(operand), int(correct)))

    minus_lo = max(int(lo), int(cur) - int(target_hi))
    minus_hi = min(int(hi), int(cur) - int(target_lo))
    if minus_lo <= minus_hi:
        for operand in range(minus_lo, minus_hi + 1):
            correct = int(cur) - int(operand)
            if not (target_lo <= correct <= target_hi):
                continue
            if not _fixed366_is_valid_stage_number(stage, operand):
                continue
            if not _fixed366_is_valid_stage_number(stage, correct):
                continue
            if stage >= 2 and not ((int(cur) % 10) < (int(operand) % 10)):
                continue
            candidates.append(('-', int(operand), int(correct)))

    return candidates


def _fixed366_pick_valid_current(stage: int, lo: int, hi: int, target_lo: int, target_hi: int) -> int | None:
    cur_lo = max(int(lo), int(target_lo))
    cur_hi = min(int(hi), int(target_hi))
    if cur_hi < cur_lo:
        return None

    pool = list(range(cur_lo, cur_hi + 1))
    random.shuffle(pool)
    for cur in pool:
        if not _fixed366_is_valid_stage_number(stage, cur):
            continue
        if _fixed366_candidates_for_current(stage, int(cur), int(lo), int(hi), int(target_lo), int(target_hi)):
            return int(cur)
    return None


def _fixed366_method_c_generate_operand(self, current: int, stage_index: int):
    stage = int(stage_index or 1)
    lo, hi = self._stage_limits(stage)
    lo = max(0, int(lo))
    hi = int(hi)
    target_lo, target_hi = _fixed366_stage_target_bounds(stage)

    cur = int(current)
    if not _fixed366_is_valid_stage_number(stage, cur):
        picked_cur = _fixed366_pick_valid_current(stage, lo, hi, target_lo, target_hi)
        if picked_cur is not None:
            cur = int(picked_cur)
            self.current_value = int(cur)
            try:
                self.big_var.set(str(cur))
            except Exception:
                pass

    candidates = _fixed366_candidates_for_current(stage, cur, lo, hi, target_lo, target_hi)
    if candidates:
        op, operand, correct = random.choice(candidates)
        return str(op), int(operand), int(correct)

    picked_cur = _fixed366_pick_valid_current(stage, lo, hi, target_lo, target_hi)
    if picked_cur is not None:
        cur = int(picked_cur)
        self.current_value = int(cur)
        try:
            self.big_var.set(str(cur))
        except Exception:
            pass
        candidates = _fixed366_candidates_for_current(stage, cur, lo, hi, target_lo, target_hi)
        if candidates:
            op, operand, correct = random.choice(candidates)
            return str(op), int(operand), int(correct)

    op, operand, correct = _FIXED366_PREV_METHOD_C_GENERATE_OPERAND(self, current, stage_index)
    return str(op), int(operand), int(correct)


def _fixed366_method_c_start_stage(self, stage_index: int):
    result = _FIXED366_PREV_METHOD_C_START_STAGE(self, stage_index)
    stage = int(getattr(self, 'stage_index', stage_index) or stage_index or 1)
    if str(getattr(self, 'phase', '') or '') != 'stage_ready':
        return result

    try:
        lo, hi = self._stage_limits(stage)
        lo = max(0, int(lo))
        hi = int(hi)
        target_lo, target_hi = _fixed366_stage_target_bounds(stage)
        cur = int(getattr(self, 'current_value', lo) or lo)

        if (not _fixed366_is_valid_stage_number(stage, cur)) or (
            not _fixed366_candidates_for_current(stage, cur, lo, hi, target_lo, target_hi)
        ):
            picked_cur = _fixed366_pick_valid_current(stage, lo, hi, target_lo, target_hi)
            if picked_cur is not None:
                self.current_value = int(picked_cur)
                self.big_var.set(str(self.current_value))
    except Exception:
        pass
    return result


MethodCWindow._generate_operand = _fixed366_method_c_generate_operand
MethodCWindow._start_stage = _fixed366_method_c_start_stage


# ====== FIXED356: Method A supports PXN-2113 Pro with mouse fallback ======
_FIXED356_METHOD_A_PXN_VERSION = 'fixed356_method_a_pxn_2113_pro_v1'
_fixed356_prev_method_a_init = MethodAApp.__init__
_fixed356_prev_read_runtime_events = MethodAApp.read_runtime_events
_fixed356_prev_handle_control = MethodAApp.handle_control


def _fixed356_norm_joy_name(name: str) -> str:
    s = str(name or '').strip().lower()
    for ch in (' ', '-', '_'):
        s = s.replace(ch, '')
    return s


def _fixed356_is_pxn_2113(joy_name: str) -> bool:
    norm = _fixed356_norm_joy_name(joy_name)
    return ('pxn' in norm) and ('2113' in norm)


def _fixed356_clear_joy_state(self):
    self._joy = None
    self._joy_enabled = False
    self._joy_instance_id = None
    self._joy_name = ''
    self._joy_axis_baseline = {}
    self._joy_axis_prev = {}


def _fixed356_connect_pxn_joystick(self):
    _fixed356_clear_joy_state(self)
    try:
        pygame.joystick.init()
    except Exception:
        return
    try:
        count = int(pygame.joystick.get_count())
    except Exception:
        count = 0
    for idx in range(max(0, count)):
        try:
            joy = pygame.joystick.Joystick(idx)
            joy.init()
            if not bool(joy.get_init()):
                continue
            try:
                joy_name = str(joy.get_name() or '')
            except Exception:
                joy_name = ''
            if not _fixed356_is_pxn_2113(joy_name):
                continue

            self._joy = joy
            self._joy_enabled = True
            self._joy_name = joy_name
            if '_fixed268_joystick_instance_id' in globals():
                self._joy_instance_id = _fixed268_joystick_instance_id(joy)
            else:
                try:
                    self._joy_instance_id = int(joy.get_instance_id())
                except Exception:
                    self._joy_instance_id = None
            self._joy_axis_baseline = {}
            self._joy_axis_prev = {}
            try:
                pygame.event.pump()
                num_axes = int(joy.get_numaxes())
            except Exception:
                num_axes = 0
            for aidx in range(max(0, num_axes)):
                try:
                    aval = float(joy.get_axis(aidx))
                except Exception:
                    aval = 0.0
                self._joy_axis_baseline[aidx] = aval
                self._joy_axis_prev[aidx] = aval
            return
        except Exception:
            continue


def _fixed356_method_a_init(self, cfg: MethodAConfig, session: SessionInfo, logger: ParticipantsLogger, base_dir: Path):
    _fixed356_prev_method_a_init(self, cfg, session, logger, base_dir)
    self._joy_requested = True
    self._joy_required_model = 'PXN-2113 Pro'
    self._joy_connect_retry_after_ms = 0
    self._joy_last_tick_ms = int(pygame.time.get_ticks())
    self._joy_axis_baseline = {}
    self._joy_axis_prev = {}
    _fixed356_clear_joy_state(self)


def _fixed356_method_a_read_runtime_events(self) -> int:
    wheel_delta = 0
    if '_fixed268_joy_event_types' in globals():
        ev_add, ev_remove = _fixed268_joy_event_types()
    else:
        ev_add = getattr(pygame, 'JOYDEVICEADDED', -1)
        ev_remove = getattr(pygame, 'JOYDEVICEREMOVED', -1)

    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            raise MethodAAbort
        if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
            raise MethodAAbort
        if event.type == pygame.MOUSEWHEEL:
            wheel_delta += int(getattr(event, 'y', 0) or 0)
        elif event.type == pygame.MOUSEBUTTONDOWN:
            btn = int(getattr(event, 'button', 0) or 0)
            if btn == 4:
                wheel_delta += 1
            elif btn == 5:
                wheel_delta -= 1
        elif event.type == ev_add:
            self._joy_connect_retry_after_ms = 0
        elif event.type == ev_remove:
            removed_id = getattr(event, 'instance_id', None)
            current_id = getattr(self, '_joy_instance_id', None)
            if current_id is None or removed_id is None or int(removed_id) == int(current_id):
                _fixed356_clear_joy_state(self)
                self._joy_connect_retry_after_ms = 0
    return wheel_delta


def _fixed356_axis(joy, axis_index: int, deadzone: float) -> float:
    try:
        if axis_index < 0 or axis_index >= int(joy.get_numaxes()):
            return 0.0
        raw = float(joy.get_axis(axis_index))
    except Exception:
        return 0.0
    if abs(raw) < deadzone:
        return 0.0
    return max(-1.0, min(1.0, raw))


def _fixed356_apply_pxn_control(self, state: DriftState, stage_no: int) -> bool:
    joy = getattr(self, '_joy', None)
    if not bool(getattr(self, '_joy_enabled', False)) or joy is None:
        return False
    try:
        if not bool(joy.get_init()):
            return False
    except Exception:
        return False

    now_ms = int(pygame.time.get_ticks())
    prev_ms = int(getattr(self, '_joy_last_tick_ms', now_ms))
    dt = max(1.0 / 240.0, min(0.2, float(now_ms - prev_ms) / 1000.0))
    self._joy_last_tick_ms = now_ms

    deadzone = max(0.01, float(getattr(self.cfg, 'joystick_deadzone', 0.12) or 0.12))
    gain_xy = max(1.0, float(getattr(self.cfg, 'joystick_xy_gain_px_s', 520.0) or 520.0))

    current_roll_speed = float(getattr(state, 'speed_z_deg_s', getattr(self.cfg, 'start_speed_z_deg_s', 10.0)) or 10.0)
    z_default_gain = float(getattr(self.cfg, 'joystick_roll_gain_deg_s', current_roll_speed) or current_roll_speed)
    gain_z = max(1.0, z_default_gain, current_roll_speed * 1.15)

    axis_big_x = int(getattr(self.cfg, 'joystick_axis_x', 0) or 0)
    axis_big_y = int(getattr(self.cfg, 'joystick_axis_y', 1) or 1)
    x_in = _fixed356_axis(joy, axis_big_x, deadzone)
    y_in = _fixed356_axis(joy, axis_big_y, deadzone)

    stage = self.stage_defs[int(stage_no)]
    if bool(stage.get('x')):
        state.x_px -= x_in * gain_xy * dt
    if bool(stage.get('y')):
        state.y_px -= y_in * gain_xy * dt

    # Stage 3 roll: small stick left-right.
    if bool(stage.get('z')) and int(stage_no) == 3:
        candidates = [
            int(getattr(self.cfg, 'joystick_small_x_axis', 3) or 3),
            int(getattr(self.cfg, 'joystick_axis_z', 2) or 2),
            int(getattr(self.cfg, 'joystick_axis_z_alt', 3) or 3),
            int(getattr(self.cfg, 'joystick_axis_z_alt2', 4) or 4),
            int(getattr(self.cfg, 'joystick_axis_z_alt3', 5) or 5),
        ]
        # Do not depend on legacy helpers from older fixes: some of them call
        # removed symbols (for example _fixed270_joy_axis) and can crash stage 3.
        z_in = 0.0
        seen = set()
        for idx in candidates:
            if idx in seen or idx in (axis_big_x, axis_big_y):
                continue
            seen.add(idx)
            cand = _fixed356_axis(joy, idx, deadzone)
            if abs(cand) > abs(z_in):
                z_in = cand
        if bool(getattr(self.cfg, 'joystick_invert_roll', False)):
            z_in = -z_in
        state.roll_deg -= z_in * gain_z * dt

    return True


def _fixed356_method_a_handle_control(self, state: DriftState, stage_no: int, wheel_delta: int):
    now_ms = int(pygame.time.get_ticks())
    retry_after = int(getattr(self, '_joy_connect_retry_after_ms', 0) or 0)
    if (not bool(getattr(self, '_joy_enabled', False)) or getattr(self, '_joy', None) is None) and now_ms >= retry_after:
        _fixed356_connect_pxn_joystick(self)
        self._joy_connect_retry_after_ms = now_ms + 1200

    # If required PXN joystick is connected, control test A by joystick only.
    if bool(getattr(self, '_joy_enabled', False)) and _fixed356_apply_pxn_control(self, state, stage_no):
        _ = pygame.mouse.get_rel()
        return

    # No supported joystick: keep legacy mouse behavior.
    _fixed356_prev_handle_control(self, state, stage_no, wheel_delta)


MethodAApp.__init__ = _fixed356_method_a_init
MethodAApp.read_runtime_events = _fixed356_method_a_read_runtime_events
MethodAApp.handle_control = _fixed356_method_a_handle_control


# ====== FIXED358: Method A stage-3 roll from PXN buttons 5/6 (axis fallback) ======
_FIXED358_METHOD_A_ROLL_BUTTONS_VERSION = 'fixed358_method_a_roll_buttons_5_6_v1'
_fixed358_prev_apply_pxn_control = _fixed356_apply_pxn_control


def _fixed358_joy_button(joy, button_index: int) -> bool:
    try:
        if button_index < 0 or button_index >= int(joy.get_numbuttons()):
            return False
        return bool(joy.get_button(button_index))
    except Exception:
        return False


def _fixed358_apply_pxn_control(self, state: DriftState, stage_no: int) -> bool:
    joy = getattr(self, '_joy', None)
    if not bool(getattr(self, '_joy_enabled', False)) or joy is None:
        return False
    try:
        if not bool(joy.get_init()):
            return False
    except Exception:
        return False

    now_ms = int(pygame.time.get_ticks())
    prev_ms = int(getattr(self, '_joy_last_tick_ms', now_ms))
    dt = max(1.0 / 240.0, min(0.2, float(now_ms - prev_ms) / 1000.0))
    self._joy_last_tick_ms = now_ms

    # Reuse previous implementation for non-stage-3 behavior.
    if int(stage_no) != 3:
        return _fixed358_prev_apply_pxn_control(self, state, stage_no)

    deadzone = max(0.01, float(getattr(self.cfg, 'joystick_deadzone', 0.12) or 0.12))
    gain_xy = max(1.0, float(getattr(self.cfg, 'joystick_xy_gain_px_s', 520.0) or 520.0))

    current_roll_speed = float(getattr(state, 'speed_z_deg_s', getattr(self.cfg, 'start_speed_z_deg_s', 10.0)) or 10.0)
    z_default_gain = float(getattr(self.cfg, 'joystick_roll_gain_deg_s', current_roll_speed) or current_roll_speed)
    gain_z = max(1.0, z_default_gain, current_roll_speed * 1.15)

    axis_big_x = int(getattr(self.cfg, 'joystick_axis_x', 0) or 0)
    axis_big_y = int(getattr(self.cfg, 'joystick_axis_y', 1) or 1)
    x_in = _fixed356_axis(joy, axis_big_x, deadzone)
    y_in = _fixed356_axis(joy, axis_big_y, deadzone)

    stage = self.stage_defs[int(stage_no)]
    applied = False
    if bool(stage.get('x')):
        state.x_px -= x_in * gain_xy * dt
        applied = applied or abs(x_in) > 0.0
    if bool(stage.get('y')):
        state.y_px -= y_in * gain_xy * dt
        applied = applied or abs(y_in) > 0.0
    if not bool(stage.get('z')):
        return applied

    # Priority: physical buttons 5/6.
    # Most drivers expose them as 0-based indices 4/5; some as 5/6.
    left0 = int(getattr(self.cfg, 'joystick_roll_left_button', 4) or 4)
    right0 = int(getattr(self.cfg, 'joystick_roll_right_button', 5) or 5)
    left_pressed = _fixed358_joy_button(joy, left0)
    right_pressed = _fixed358_joy_button(joy, right0)
    if not left_pressed and not right_pressed:
        left_pressed = _fixed358_joy_button(joy, left0 + 1)
        right_pressed = _fixed358_joy_button(joy, right0 + 1)

    z_in = 0.0
    if left_pressed and not right_pressed:
        z_in = -1.0
    elif right_pressed and not left_pressed:
        z_in = 1.0
    else:
        # Fallback to small-stick axes when roll buttons are neutral/ambiguous.
        candidates = [
            int(getattr(self.cfg, 'joystick_small_x_axis', 3) or 3),
            int(getattr(self.cfg, 'joystick_axis_z', 2) or 2),
            int(getattr(self.cfg, 'joystick_axis_z_alt', 3) or 3),
            int(getattr(self.cfg, 'joystick_axis_z_alt2', 4) or 4),
            int(getattr(self.cfg, 'joystick_axis_z_alt3', 5) or 5),
        ]
        seen = set()
        for idx in candidates:
            if idx in seen or idx in (axis_big_x, axis_big_y):
                continue
            seen.add(idx)
            cand = _fixed356_axis(joy, idx, deadzone)
            if abs(cand) > abs(z_in):
                z_in = cand

    if bool(getattr(self.cfg, 'joystick_invert_roll', False)):
        z_in = -z_in
    if abs(z_in) > 0.0:
        state.roll_deg -= z_in * gain_z * dt
        return True
    return applied


_fixed356_apply_pxn_control = _fixed358_apply_pxn_control


# ====== FIXED359: stabilize PXN input (no random drop, robust roll button state) ======
_FIXED359_METHOD_A_PXN_STABILITY_VERSION = 'fixed359_method_a_pxn_stability_v1'
_fixed359_prev_method_a_init = MethodAApp.__init__
_fixed359_prev_read_runtime_events = MethodAApp.read_runtime_events
_fixed359_prev_apply_pxn_control = _fixed356_apply_pxn_control


def _fixed359_method_a_init(self, cfg: MethodAConfig, session: SessionInfo, logger: ParticipantsLogger, base_dir: Path):
    _fixed359_prev_method_a_init(self, cfg, session, logger, base_dir)
    self._joy_button_state = {}


def _fixed359_button_pressed(self, joy, button_index: int) -> bool:
    try:
        if button_index < 0:
            return False
        by_event = bool((getattr(self, '_joy_button_state', {}) or {}).get(int(button_index), False))
    except Exception:
        by_event = False
    by_poll = False
    try:
        if joy is not None and bool(joy.get_init()) and button_index < int(joy.get_numbuttons()):
            by_poll = bool(joy.get_button(button_index))
    except Exception:
        by_poll = False
    return bool(by_event or by_poll)


def _fixed359_method_a_read_runtime_events(self) -> int:
    wheel_delta = 0
    if '_fixed268_joy_event_types' in globals():
        ev_add, ev_remove = _fixed268_joy_event_types()
    else:
        ev_add = getattr(pygame, 'JOYDEVICEADDED', -1)
        ev_remove = getattr(pygame, 'JOYDEVICEREMOVED', -1)
    ev_btn_down = getattr(pygame, 'JOYBUTTONDOWN', -1)
    ev_btn_up = getattr(pygame, 'JOYBUTTONUP', -1)

    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            raise MethodAAbort
        if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
            raise MethodAAbort
        if event.type == pygame.MOUSEWHEEL:
            wheel_delta += int(getattr(event, 'y', 0) or 0)
        elif event.type == pygame.MOUSEBUTTONDOWN:
            btn = int(getattr(event, 'button', 0) or 0)
            if btn == 4:
                wheel_delta += 1
            elif btn == 5:
                wheel_delta -= 1
        elif event.type == ev_btn_down:
            try:
                b = int(getattr(event, 'button', -1))
                if b >= 0:
                    self._joy_button_state[b] = True
            except Exception:
                pass
        elif event.type == ev_btn_up:
            try:
                b = int(getattr(event, 'button', -1))
                if b >= 0:
                    self._joy_button_state[b] = False
            except Exception:
                pass
        elif event.type == ev_add:
            self._joy_connect_retry_after_ms = 0
        elif event.type == ev_remove:
            removed_id = getattr(event, 'instance_id', None)
            current_id = getattr(self, '_joy_instance_id', None)
            # Ignore ambiguous remove events without instance id: they can be
            # emitted by some stacks and should not drop active control.
            if removed_id is None:
                continue
            if current_id is not None and int(removed_id) == int(current_id):
                _fixed356_clear_joy_state(self)
                self._joy_connect_retry_after_ms = 0
                self._joy_button_state = {}
    return wheel_delta


def _fixed359_apply_pxn_control(self, state: DriftState, stage_no: int) -> bool:
    joy = getattr(self, '_joy', None)
    if not bool(getattr(self, '_joy_enabled', False)) or joy is None:
        return False
    try:
        if not bool(joy.get_init()):
            return False
    except Exception:
        return False

    now_ms = int(pygame.time.get_ticks())
    prev_ms = int(getattr(self, '_joy_last_tick_ms', now_ms))
    dt = max(1.0 / 240.0, min(0.2, float(now_ms - prev_ms) / 1000.0))
    self._joy_last_tick_ms = now_ms

    stage = self.stage_defs[int(stage_no)]
    if int(stage_no) != 3 or not bool(stage.get('z')):
        return _fixed359_prev_apply_pxn_control(self, state, stage_no)

    # Stage 3: keep baseline XY from previous PXN logic.
    deadzone = max(0.01, float(getattr(self.cfg, 'joystick_deadzone', 0.08) or 0.08))
    gain_xy = max(1.0, float(getattr(self.cfg, 'joystick_xy_gain_px_s', 520.0) or 520.0))
    axis_big_x = int(getattr(self.cfg, 'joystick_axis_x', 0) or 0)
    axis_big_y = int(getattr(self.cfg, 'joystick_axis_y', 1) or 1)
    x_in = _fixed356_axis(joy, axis_big_x, deadzone)
    y_in = _fixed356_axis(joy, axis_big_y, deadzone)
    applied_xy = False
    if bool(stage.get('x')):
        state.x_px -= x_in * gain_xy * dt
        applied_xy = applied_xy or abs(x_in) > 0.0
    if bool(stage.get('y')):
        state.y_px -= y_in * gain_xy * dt
        applied_xy = applied_xy or abs(y_in) > 0.0

    current_roll_speed = float(getattr(state, 'speed_z_deg_s', getattr(self.cfg, 'start_speed_z_deg_s', 10.0)) or 10.0)
    z_default_gain = float(getattr(self.cfg, 'joystick_roll_gain_deg_s', current_roll_speed) or current_roll_speed)
    gain_z = max(1.0, z_default_gain, current_roll_speed * 1.15)

    # Prefer physical buttons 5/6:
    # common mapping -> 0-based indices 4/5; alternate mapping -> 5/6.
    left0 = int(getattr(self.cfg, 'joystick_roll_left_button', 4) or 4)
    right0 = int(getattr(self.cfg, 'joystick_roll_right_button', 5) or 5)
    left_pressed = _fixed359_button_pressed(self, joy, left0)
    right_pressed = _fixed359_button_pressed(self, joy, right0)
    if not left_pressed and not right_pressed:
        left_pressed = _fixed359_button_pressed(self, joy, left0 + 1)
        right_pressed = _fixed359_button_pressed(self, joy, right0 + 1)

    z_in = 0.0
    if left_pressed and not right_pressed:
        z_in = -1.0
    elif right_pressed and not left_pressed:
        z_in = 1.0
    else:
        # Axis fallback if roll buttons are neutral.
        candidates = [
            int(getattr(self.cfg, 'joystick_small_x_axis', 3) or 3),
            int(getattr(self.cfg, 'joystick_axis_z', 2) or 2),
            int(getattr(self.cfg, 'joystick_axis_z_alt', 3) or 3),
            int(getattr(self.cfg, 'joystick_axis_z_alt2', 4) or 4),
            int(getattr(self.cfg, 'joystick_axis_z_alt3', 5) or 5),
        ]
        seen = set()
        for idx in candidates:
            if idx in seen or idx in (axis_big_x, axis_big_y):
                continue
            seen.add(idx)
            cand = _fixed356_axis(joy, idx, deadzone)
            if abs(cand) > abs(z_in):
                z_in = cand

    if bool(getattr(self.cfg, 'joystick_invert_roll', False)):
        z_in = -z_in
    if abs(z_in) > 0.0:
        state.roll_deg -= z_in * gain_z * dt
        return True
    return bool(applied_xy)


MethodAApp.__init__ = _fixed359_method_a_init
MethodAApp.read_runtime_events = _fixed359_method_a_read_runtime_events
_fixed356_apply_pxn_control = _fixed359_apply_pxn_control


# ====== FIXED360: stronger/stable PXN control (anti-drop + adaptive authority) ======
_FIXED360_METHOD_A_PXN_STABILITY_VERSION = 'fixed360_method_a_pxn_stability_and_gain_v1'
_fixed360_prev_method_a_init = MethodAApp.__init__
_fixed360_prev_read_runtime_events = MethodAApp.read_runtime_events
_fixed360_prev_handle_control = MethodAApp.handle_control


def _fixed360_method_a_init(self, cfg: MethodAConfig, session: SessionInfo, logger: ParticipantsLogger, base_dir: Path):
    _fixed360_prev_method_a_init(self, cfg, session, logger, base_dir)
    now_ms = int(pygame.time.get_ticks())
    self._joy_refresh_after_ms = now_ms + 2500
    self._joy_last_axis_pump_ms = now_ms


def _fixed360_method_a_read_runtime_events(self) -> int:
    wheel_delta = _fixed360_prev_read_runtime_events(self)
    # Keep event subsystem alive even when queue is almost empty.
    try:
        pygame.event.pump()
    except Exception:
        pass
    return wheel_delta


def _fixed360_apply_pxn_control(self, state: DriftState, stage_no: int) -> bool:
    joy = getattr(self, '_joy', None)
    if not bool(getattr(self, '_joy_enabled', False)) or joy is None:
        return False
    try:
        if not bool(joy.get_init()):
            return False
    except Exception:
        return False

    try:
        pygame.event.pump()
    except Exception:
        pass

    now_ms = int(pygame.time.get_ticks())
    prev_ms = int(getattr(self, '_joy_last_tick_ms', now_ms))
    dt = max(1.0 / 240.0, min(0.2, float(now_ms - prev_ms) / 1000.0))
    self._joy_last_tick_ms = now_ms

    deadzone = max(0.01, min(0.35, float(getattr(self.cfg, 'joystick_deadzone', 0.08) or 0.08)))
    axis_big_x = int(getattr(self.cfg, 'joystick_axis_x', 0) or 0)
    axis_big_y = int(getattr(self.cfg, 'joystick_axis_y', 1) or 1)

    # Adaptive authority: keep pilot control comfortably above drift dynamics.
    drift_xy_px_s = abs(float(getattr(state, 'speed_xy_cm_s', getattr(self.cfg, 'start_speed_xy_cm_s', 3.0)) or 3.0)) * float(getattr(self.cfg, 'px_per_cm', 38.0) or 38.0)
    base_xy = max(1.0, float(getattr(self.cfg, 'joystick_xy_gain_px_s', 520.0) or 520.0))
    # Stronger authority so full-stick can hold course even after speed ramp-up.
    gain_xy = max(base_xy * 1.8, drift_xy_px_s * 6.0)
    work_xy = max(1.0, float(getattr(self, 'work_half_px', 1.0) or 1.0))
    xy_dev = max(abs(float(getattr(state, 'x_px', 0.0) or 0.0)), abs(float(getattr(state, 'y_px', 0.0) or 0.0))) / work_xy
    xy_boost = 1.0 + min(2.2, max(0.0, xy_dev) * 2.2)
    gain_xy *= xy_boost

    roll_speed = abs(float(getattr(state, 'speed_z_deg_s', getattr(self.cfg, 'start_speed_z_deg_s', 10.0)) or 10.0))
    base_z = max(1.0, float(getattr(self.cfg, 'joystick_roll_gain_deg_s', roll_speed) or roll_speed))
    gain_z = max(base_z, roll_speed * 2.8)

    x_in = _fixed356_axis(joy, axis_big_x, deadzone)
    y_in = _fixed356_axis(joy, axis_big_y, deadzone)
    # Slightly nonlinear response: better control authority before stick end-stop.
    if abs(x_in) > 0.0:
        x_in = math.copysign(abs(x_in) ** 0.75, x_in)
    if abs(y_in) > 0.0:
        y_in = math.copysign(abs(y_in) ** 0.75, y_in)

    stage = self.stage_defs[int(stage_no)]
    applied = False
    if bool(stage.get('x')):
        state.x_px -= x_in * gain_xy * dt
        applied = applied or abs(x_in) > 0.0
    if bool(stage.get('y')):
        y_delta = y_in * gain_xy * dt
        state.y_px += y_delta if int(stage_no) in (2, 3) else -y_delta
        applied = applied or abs(y_in) > 0.0

    if bool(stage.get('z')) and int(stage_no) == 3:
        left0 = int(getattr(self.cfg, 'joystick_roll_left_button', 4) or 4)
        right0 = int(getattr(self.cfg, 'joystick_roll_right_button', 5) or 5)
        left_pressed = _fixed359_button_pressed(self, joy, left0)
        right_pressed = _fixed359_button_pressed(self, joy, right0)
        if not left_pressed and not right_pressed:
            left_pressed = _fixed359_button_pressed(self, joy, left0 + 1)
            right_pressed = _fixed359_button_pressed(self, joy, right0 + 1)

        z_in = 0.0
        if left_pressed and not right_pressed:
            z_in = -1.0
        elif right_pressed and not left_pressed:
            z_in = 1.0
        else:
            candidates = [
                int(getattr(self.cfg, 'joystick_small_x_axis', 3) or 3),
                int(getattr(self.cfg, 'joystick_axis_z', 2) or 2),
                int(getattr(self.cfg, 'joystick_axis_z_alt', 3) or 3),
                int(getattr(self.cfg, 'joystick_axis_z_alt2', 4) or 4),
                int(getattr(self.cfg, 'joystick_axis_z_alt3', 5) or 5),
            ]
            seen = set()
            for idx in candidates:
                if idx in seen or idx in (axis_big_x, axis_big_y):
                    continue
                seen.add(idx)
                cand = _fixed356_axis(joy, idx, deadzone)
                if abs(cand) > abs(z_in):
                    z_in = cand
        if bool(getattr(self.cfg, 'joystick_invert_roll', False)):
            z_in = -z_in
        if abs(z_in) > 0.0:
            state.roll_deg -= z_in * gain_z * dt
            applied = True
    return applied


def _fixed360_method_a_handle_control(self, state: DriftState, stage_no: int, wheel_delta: int):
    now_ms = int(pygame.time.get_ticks())
    retry_after = int(getattr(self, '_joy_connect_retry_after_ms', 0) or 0)
    refresh_after = int(getattr(self, '_joy_refresh_after_ms', 0) or 0)

    need_connect = (not bool(getattr(self, '_joy_enabled', False))) or (getattr(self, '_joy', None) is None)
    if need_connect and now_ms >= retry_after:
        _fixed356_connect_pxn_joystick(self)
        self._joy_connect_retry_after_ms = now_ms + 700

    # Periodic soft refresh helps with driver stacks where joystick path "freezes".
    if now_ms >= refresh_after:
        _fixed356_connect_pxn_joystick(self)
        self._joy_refresh_after_ms = now_ms + 2500

    if bool(getattr(self, '_joy_enabled', False)) and _fixed360_apply_pxn_control(self, state, stage_no):
        _ = pygame.mouse.get_rel()
        return

    _fixed360_prev_handle_control(self, state, stage_no, wheel_delta)


MethodAApp.__init__ = _fixed360_method_a_init
MethodAApp.read_runtime_events = _fixed360_method_a_read_runtime_events
MethodAApp.handle_control = _fixed360_method_a_handle_control


# ====== FIXED361: stage-3 roll supports both PXN buttons and small stick ======
_FIXED361_METHOD_A_ROLL_MIX_VERSION = 'fixed361_method_a_roll_buttons_and_small_stick_v1'
_fixed361_prev_apply_pxn_control = _fixed360_apply_pxn_control


def _fixed362_axis_delta(self, joy, axis_index: int, deadzone: float) -> float:
    try:
        if axis_index < 0 or axis_index >= int(joy.get_numaxes()):
            return 0.0
        raw = float(joy.get_axis(axis_index))
    except Exception:
        return 0.0
    try:
        base = float((getattr(self, '_joy_axis_baseline', {}) or {}).get(int(axis_index), 0.0))
    except Exception:
        base = 0.0
    val = raw - base
    if abs(val) < deadzone:
        return 0.0
    return max(-1.0, min(1.0, val))


def _fixed362_pick_small_stick_roll(self, joy, axis_big_x: int, axis_big_y: int, deadzone: float) -> float:
    # 1) Preferred indices from config
    preferred = [
        int(getattr(self.cfg, 'joystick_small_x_axis', 3) or 3),
        int(getattr(self.cfg, 'joystick_axis_z', 2) or 2),
        int(getattr(self.cfg, 'joystick_axis_z_alt', 3) or 3),
        int(getattr(self.cfg, 'joystick_axis_z_alt2', 4) or 4),
        int(getattr(self.cfg, 'joystick_axis_z_alt3', 5) or 5),
    ]

    z_axis = 0.0
    seen = set()
    for idx in preferred:
        if idx in seen or idx in (axis_big_x, axis_big_y):
            continue
        seen.add(idx)
        cand_raw = _fixed356_axis(joy, idx, max(0.01, deadzone * 0.75))
        cand_delta = _fixed362_axis_delta(self, joy, idx, max(0.01, deadzone * 0.65))
        cand = cand_delta if abs(cand_delta) >= abs(cand_raw) else cand_raw
        if abs(cand) > abs(z_axis):
            z_axis = cand

    # 2) Auto-scan all other axes (helps with unknown PXN mapping)
    try:
        axis_count = int(joy.get_numaxes())
    except Exception:
        axis_count = 0
    for idx in range(max(0, axis_count)):
        if idx in seen or idx in (axis_big_x, axis_big_y):
            continue
        cand = _fixed362_axis_delta(self, joy, idx, max(0.01, deadzone * 0.55))
        if abs(cand) > abs(z_axis):
            z_axis = cand

    # 3) Hat fallback
    if abs(z_axis) < max(0.01, deadzone):
        try:
            hats = int(joy.get_numhats())
        except Exception:
            hats = 0
        for h in range(max(0, hats)):
            try:
                hx, _hy = joy.get_hat(h)
                if abs(float(hx)) > abs(z_axis):
                    z_axis = float(hx)
            except Exception:
                continue
    return max(-1.0, min(1.0, z_axis))


def _fixed361_apply_pxn_control(self, state: DriftState, stage_no: int) -> bool:
    joy = getattr(self, '_joy', None)
    if not bool(getattr(self, '_joy_enabled', False)) or joy is None:
        return False
    try:
        if not bool(joy.get_init()):
            return False
    except Exception:
        return False

    now_ms = int(pygame.time.get_ticks())
    prev_ms = int(getattr(self, '_joy_last_tick_ms', now_ms))
    dt = max(1.0 / 240.0, min(0.2, float(now_ms - prev_ms) / 1000.0))
    self._joy_last_tick_ms = now_ms

    stage = self.stage_defs[int(stage_no)]
    if int(stage_no) != 3 or not bool(stage.get('z')):
        return _fixed361_prev_apply_pxn_control(self, state, stage_no)

    try:
        pygame.event.pump()
    except Exception:
        pass

    deadzone = max(0.01, min(0.35, float(getattr(self.cfg, 'joystick_deadzone', 0.08) or 0.08)))
    axis_big_x = int(getattr(self.cfg, 'joystick_axis_x', 0) or 0)
    axis_big_y = int(getattr(self.cfg, 'joystick_axis_y', 1) or 1)

    # Keep stage-3 XY control from big stick.
    drift_xy_px_s = abs(float(getattr(state, 'speed_xy_cm_s', getattr(self.cfg, 'start_speed_xy_cm_s', 3.0)) or 3.0)) * float(getattr(self.cfg, 'px_per_cm', 38.0) or 38.0)
    base_xy = max(1.0, float(getattr(self.cfg, 'joystick_xy_gain_px_s', 520.0) or 520.0))
    gain_xy = max(base_xy, drift_xy_px_s * 3.2)
    x_in = _fixed356_axis(joy, axis_big_x, deadzone)
    y_in = _fixed356_axis(joy, axis_big_y, deadzone)
    applied = False
    if bool(stage.get('x')):
        state.x_px -= x_in * gain_xy * dt
        applied = applied or abs(x_in) > 0.0
    if bool(stage.get('y')):
        state.y_px -= y_in * gain_xy * dt
        applied = applied or abs(y_in) > 0.0

    # Roll authority.
    roll_speed = abs(float(getattr(state, 'speed_z_deg_s', getattr(self.cfg, 'start_speed_z_deg_s', 10.0)) or 10.0))
    base_z = max(1.0, float(getattr(self.cfg, 'joystick_roll_gain_deg_s', roll_speed) or roll_speed))
    # Boost roll authority as well (user request), especially near dangerous angles.
    gain_z = max(base_z * 1.8, roll_speed * 5.0)
    roll_lim = max(1.0, float(getattr(self.cfg, 'work_roll_deg', 90.0) or 90.0))
    roll_dev = abs(float(getattr(state, 'roll_deg', 0.0) or 0.0)) / roll_lim
    roll_boost = 1.0 + min(2.5, max(0.0, roll_dev) * 2.5)
    gain_z *= roll_boost

    # Source 1: buttons 5/6 (with alternate index scheme).
    left0 = int(getattr(self.cfg, 'joystick_roll_left_button', 4) or 4)
    right0 = int(getattr(self.cfg, 'joystick_roll_right_button', 5) or 5)
    left_pressed = _fixed359_button_pressed(self, joy, left0)
    right_pressed = _fixed359_button_pressed(self, joy, right0)
    if not left_pressed and not right_pressed:
        left_pressed = _fixed359_button_pressed(self, joy, left0 + 1)
        right_pressed = _fixed359_button_pressed(self, joy, right0 + 1)

    z_btn = 0.0
    if left_pressed and not right_pressed:
        z_btn = -1.0
    elif right_pressed and not left_pressed:
        z_btn = 1.0

    # Source 2: small stick left-right (preferred axes + full auto-scan fallback).
    z_axis = _fixed362_pick_small_stick_roll(self, joy, axis_big_x, axis_big_y, deadzone)

    # Use whichever source is currently stronger.
    z_in = z_btn if abs(z_btn) >= abs(z_axis) else z_axis
    if bool(getattr(self.cfg, 'joystick_invert_roll', False)):
        z_in = -z_in
    if abs(z_in) > 0.0:
        state.roll_deg -= z_in * gain_z * dt
        applied = True

    return bool(applied)


_fixed360_apply_pxn_control = _fixed361_apply_pxn_control


# ====== FIXED363: stage-3 roll by big-stick twist axis (with fallback) ======
_FIXED363_METHOD_A_TWIST_ROLL_VERSION = 'fixed363_method_a_twist_roll_priority_v1'
_fixed363_prev_apply_pxn_control = _fixed360_apply_pxn_control


def _fixed363_pick_twist_roll(self, joy, axis_big_x: int, axis_big_y: int, deadzone: float) -> float:
    # PXN usually exposes stick twist on axis 2 (sometimes 3).
    preferred = [
        int(getattr(self.cfg, 'joystick_twist_axis', 2) or 2),
        int(getattr(self.cfg, 'joystick_axis_z', 2) or 2),
        int(getattr(self.cfg, 'joystick_axis_z_alt', 3) or 3),
    ]
    z_twist = 0.0
    seen = set()
    for idx in preferred:
        if idx in seen or idx in (axis_big_x, axis_big_y):
            continue
        seen.add(idx)
        cand_raw = _fixed356_axis(joy, idx, max(0.01, deadzone * 0.75))
        cand_delta = _fixed362_axis_delta(self, joy, idx, max(0.01, deadzone * 0.65))
        cand = cand_delta if abs(cand_delta) >= abs(cand_raw) else cand_raw
        if abs(cand) > abs(z_twist):
            z_twist = cand
    return max(-1.0, min(1.0, z_twist))






# ====== FIXED365: Method D engine replaced by tensor_matrix_test_2026_04_23_v14 ======
_FIXED365_METHOD_D_ENGINE_VERSION = 'fixed365_method_d_tensor_engine_replace_v1'
_FIXED365_TENSOR_MODULE = None


def _fixed365_load_tensor_module(base_dir: Path):
    global _FIXED365_TENSOR_MODULE
    if _FIXED365_TENSOR_MODULE is not None:
        return _FIXED365_TENSOR_MODULE
    import sys as _sys
    file_name = 'tensor_matrix_test_2026_04_23_v14.py'
    candidates: list[Path] = []
    try:
        candidates.append(Path(base_dir) / file_name)
    except Exception:
        pass
    try:
        candidates.append(_runtime_app_dir() / file_name)
    except Exception:
        pass
    try:
        meipass = getattr(_sys, '_MEIPASS', None)
        if meipass:
            candidates.append(Path(str(meipass)) / file_name)
    except Exception:
        pass
    try:
        candidates.append(Path(__file__).resolve().parent / file_name)
    except Exception:
        pass

    path = next((p for p in candidates if p.exists()), None)
    if path is None:
        shown = ', '.join(str(p) for p in candidates)
        raise FileNotFoundError(f'Не найден файл движка теста D: {file_name}. Проверены пути: {shown}')
    import importlib.util as _importlib_util

    name = '_tensor_matrix_test_2026_04_23_v14_runtime'
    spec = _importlib_util.spec_from_file_location(name, str(path))
    if spec is None or spec.loader is None:
        raise RuntimeError(f'Не удалось загрузить модуль из {path}')
    mod = _importlib_util.module_from_spec(spec)
    _sys.modules[name] = mod
    spec.loader.exec_module(mod)
    _FIXED365_TENSOR_MODULE = mod
    return mod




def _fixed365_stage_key_by_l(l_value: int) -> str:
    try:
        lv = int(l_value or 2)
    except Exception:
        lv = 2
    if lv <= 2:
        return 'min'
    if lv == 3:
        return 'medio'
    return 'max'


