_FIXED390_PREV_METHOD_D_BUILD_UI = MethodDWindow._build_ui
_FIXED390_PREV_METHOD_D_TICK_CLOCK = MethodDWindow._tick_clock


def _fixed390_method_d_update_time_bar(self):
    canvas = getattr(self, 'time_bar_canvas', None)
    if canvas is None:
        return
    total = max(10.0, float(getattr(self.cfg, 'total_test_s', 540.0) or 540.0))
    started = float(getattr(self, 'total_started_at', 0.0) or 0.0)
    ratio = 0.0 if started <= 0.0 else min(1.0, max(0.0, (time.perf_counter() - started) / total))
    try:
        _fixed180_draw_vertical_time_bar(canvas, ratio)
    except Exception:
        pass


def _fixed390_method_d_build_ui(self):
    _FIXED390_PREV_METHOD_D_BUILD_UI(self)
    try:
        root = self.win.winfo_children()[0]
        root.grid_columnconfigure(0, weight=0)
        root.grid_columnconfigure(1, weight=1)
        for child in root.grid_slaves():
            info = child.grid_info()
            col = int(info.get('column', 0))
            if col == 0:
                child.grid_configure(column=1)
        side = tk.Frame(root, bg='#ffffff')
        side.grid(row=1, column=0, sticky='ns', padx=(24, 10), pady=(8, 8))
        self.time_bar_canvas = tk.Canvas(
            side,
            width=96,
            height=360,
            bg='#ffffff',
            highlightthickness=0,
            bd=0,
        )
        self.time_bar_canvas.pack(anchor='n')
        _fixed390_method_d_update_time_bar(self)
    except Exception:
        self.time_bar_canvas = None


def _fixed390_method_d_tick_clock(self):
    _fixed390_method_d_update_time_bar(self)
    return _FIXED390_PREV_METHOD_D_TICK_CLOCK(self)


def _fixed390_shield_layout(self, count: int, width: int = 180, height: int = 110):
    geom, regions = _fixed365_shield_layout(self, count, width, height)
    scale = max(0.1, min(float(width) / 300.0, float(height) / 380.0))
    line_w = max(float(geom.get('line_w', 1.0)), round(3.8 * scale, 2), 2.0)
    geom['line_w'] = line_w
    geom['select_w'] = max(line_w * 3.0, round(15.0 * scale, 2), 8.0)
    return geom, regions


def _fixed390_draw_shield_code(self, canvas: tk.Canvas, code_values, selected_idx=None):
    canvas.delete('all')
    width = int(canvas.cget('width'))
    height = int(canvas.cget('height'))
    count = max(2, min(4, len(code_values)))
    geom, regions = self._shield_layout(count, width, height)

    frame_color = '#000000'
    inner_bg = '#ffffff'
    outer = [
        (geom['x0'], geom['y0']),
        (geom['x1'], geom['y0']),
        (geom['x1'], geom['notch_y']),
        (geom['cx'], geom['y1']),
        (geom['x0'], geom['notch_y']),
    ]
    inner = [
        (geom['ix0'], geom['iy0']),
        (geom['ix1'], geom['iy0']),
        (geom['ix1'], geom['notch_y'] - geom['trim']),
        (geom['cx'], geom['tip_y']),
        (geom['ix0'], geom['notch_y'] - geom['trim']),
    ]
    canvas.create_polygon(outer, fill=frame_color, outline='#000000', width=geom['line_w'])
    canvas.create_polygon(inner, fill=inner_bg, outline='', width=0)

    for idx, poly in enumerate(regions):
        value = code_values[idx] if idx < len(code_values) else None
        fill = self._pocket_colors.get(value, '#ffffff') if value else '#ffffff'
        canvas.create_polygon(poly, fill=fill, outline='', width=0)

    for poly in regions:
        canvas.create_polygon(poly, fill='', outline='#000000', width=geom['line_w'])
    canvas.create_polygon(inner, fill='', outline='#000000', width=geom['line_w'])

    if selected_idx is not None and 0 <= int(selected_idx) < len(regions):
        poly = regions[int(selected_idx)]
        canvas.create_polygon(poly, fill='#e6e6e6', outline='', width=0)
        canvas.create_polygon(poly, fill='', outline='#ffffff', width=geom['select_w'])
        canvas.create_polygon(poly, fill='', outline='#003b73', width=max(float(geom['line_w']) * 3.0, int(float(geom['select_w']) * 0.72)))
    return regions


def _fixed394_apply_color(self, pocket: str):
    if not self.correct_answer:
        return
    if self.selected_slot is None:
        self.feedback_var.set('Сначала кликните по пустому карману на белом щите.')
        return
    self.user_answer[self.selected_slot] = pocket
    self.selected_slot = None
    self.feedback_var.set('')
    self._draw_missing_cell()


