def _fixed390_show_test_completed_dialog(self, code: str):
    if code != 'D':
        return _FIXED390_PREV_SHOW_TEST_COMPLETED_DIALOG(self, code)

    dialog = tk.Toplevel(self.root)
    dialog.title(f'{TEST_LABELS[code]} завершён')
    dialog.configure(bg=BG_COLOR)
    dialog.transient(self.root)
    dialog.grab_set()
    dialog.resizable(True, False)

    frame = tk.Frame(dialog, bg=PANEL_COLOR, bd=2, relief='groove')
    frame.pack(fill='both', expand=True, padx=18, pady=18)
    screen_w = int(dialog.winfo_screenwidth() or 1366)
    text_wrap = max(340, min(760, int(screen_w * 0.50)))

    tk.Label(
        frame,
        text=f'{TEST_LABELS[code]} завершён',
        bg=PANEL_COLOR,
        fg=TITLE_COLOR,
        font=('Arial', 20, 'bold'),
    ).pack(pady=(12, 10))
    tk.Label(
        frame,
        text='Сначала откройте результаты теста D. Общий профиль СПР доступен после просмотра или из меню.',
        bg=PANEL_COLOR,
        fg=TEXT_COLOR,
        justify='center',
        font=('Arial', 12, 'bold'),
        wraplength=text_wrap,
    ).pack(padx=18, pady=(0, 16))

    btns = tk.Frame(frame, bg=PANEL_COLOR)
    btns.pack(pady=(0, 14))
    tk.Button(
        btns,
        text='РЕЗУЛЬТАТЫ\nТЕСТА D',
        command=lambda: (dialog.destroy(), self.view_results(code)),
        bg=RESULT_BG,
        activebackground=RESULT_ACTIVE,
        relief='raised',
        bd=3,
        cursor='hand2',
        font=('Arial', 12, 'bold'),
        width=18,
        height=2,
    ).pack(side='left', padx=(0, 12))
    tk.Button(
        btns,
        text='В МЕНЮ',
        command=dialog.destroy,
        bg=NEXT_BG,
        activebackground=NEXT_ACTIVE,
        relief='raised',
        bd=3,
        cursor='hand2',
        font=('Arial', 12, 'bold'),
        width=12,
        height=2,
    ).pack(side='left')

    dialog.update_idletasks()
    x = max(0, self.root.winfo_rootx() + (self.root.winfo_width() - dialog.winfo_reqwidth()) // 2)
    y = max(0, self.root.winfo_rooty() + (self.root.winfo_height() - dialog.winfo_reqheight()) // 2)
    dialog.geometry(f'+{x}+{y}')


