def _fixed389_balanced_method_b_positions(grid_size: int, n: int) -> list[int]:
    grid_size = max(1, int(grid_size or 4))
    total = grid_size * grid_size
    n = max(1, min(total, int(n or 1)))
    cells = list(range(total))
    if n >= total:
        random.shuffle(cells)
        return sorted(cells)

    def _try_exact_non_line_selection() -> list[int] | None:
        selected: list[tuple[int, int]] = []
        used_rows: set[int] = set()
        used_cols: set[int] = set()
        used_diag_a: set[int] = set()
        used_diag_b: set[int] = set()

        def _search() -> bool:
            if len(selected) >= n:
                return True
            candidates = [(idx // grid_size, idx % grid_size) for idx in cells]
            random.shuffle(candidates)
            for row, col in candidates:
                if row in used_rows or col in used_cols:
                    continue
                diag_a = row - col
                diag_b = row + col
                if diag_a in used_diag_a or diag_b in used_diag_b:
                    continue
                selected.append((row, col))
                used_rows.add(row)
                used_cols.add(col)
                used_diag_a.add(diag_a)
                used_diag_b.add(diag_b)
                if _search():
                    return True
                selected.pop()
                used_rows.remove(row)
                used_cols.remove(col)
                used_diag_a.remove(diag_a)
                used_diag_b.remove(diag_b)
            return False

        return sorted(row * grid_size + col for row, col in selected) if _search() else None

    if n <= grid_size:
        exact = _try_exact_non_line_selection()
        if exact:
            return exact

    def _score(selection: list[int]) -> tuple:
        coords = [(idx // grid_size, idx % grid_size) for idx in selection]
        row_counts = [0] * grid_size
        col_counts = [0] * grid_size
        for row, col in coords:
            row_counts[row] += 1
            col_counts[col] += 1
        line_conflicts = 0
        for i, (r1, c1) in enumerate(coords):
            for r2, c2 in coords[i + 1:]:
                if r1 == r2:
                    line_conflicts += 1
                if c1 == c2:
                    line_conflicts += 1
                if abs(r1 - r2) == abs(c1 - c2):
                    line_conflicts += 1
        min_dist_sq = 0
        if len(coords) > 1:
            min_dist_sq = min(
                (r1 - r2) ** 2 + (c1 - c2) ** 2
                for i, (r1, c1) in enumerate(coords)
                for r2, c2 in coords[i + 1:]
            )
        row_span = max(row for row, _col in coords) - min(row for row, _col in coords)
        col_span = max(col for _row, col in coords) - min(col for _row, col in coords)
        row_overload = max(row_counts) - min(row_counts)
        col_overload = max(col_counts) - min(col_counts)
        spread = row_span + col_span
        center = (grid_size - 1) / 2.0
        center_penalty = sum(abs(row - center) + abs(col - center) for row, col in coords)
        return (
            line_conflicts,
            row_overload + col_overload,
            -min_dist_sq,
            -spread,
            center_penalty,
            random.random(),
        )

    best = None
    best_score = None
    attempts = 900 if n <= grid_size else 1400
    for _ in range(attempts):
        selection = random.sample(cells, n)
        score = _score(selection)
        if best_score is None or score < best_score:
            best = selection
            best_score = score
    return sorted(best or random.sample(cells, n))



# ====== FIXED400: matrix header spacing, gender shorthand, extra memory rows ======
def _fixed376_float(value, default: float = 0.0) -> float:
    try:
        return float(value or default)
    except Exception:
        return float(default)


def _fixed376_format_value(value, *, zero_as_empty: bool = True) -> str:
    val = _fixed376_float(value, 0.0)
    if abs(val) < 1e-12 and zero_as_empty:
        return ''
    if abs(val) < 1e-12:
        return '0'
    return f'{val:.2f}'.replace('.', ',')


def _fixed376_cell_color(value, *, force_white: bool = False) -> str:
    if force_white:
        return '#ffffff'
    val = _fixed376_float(value, 0.0)
    if val <= 0:
        return '#ff1717'
    if val > 1.5:
        return '#00b050'
    if val >= 1.0:
        return '#a8d18d'
    if val >= 0.65:
        return '#fff200'
    if val >= 0.5:
        return '#f8c85f'
    return '#ff1717'


def _fixed376_collect_workability_values(self, profile: UserProfile | None = None) -> dict:
    profile = profile or self.current_profile
    if not profile:
        return {}

    def _payload(code: str) -> dict:
        data = self.progress_store.get_test_result(profile, code)
        return data if isinstance(data, dict) else {}

    values = _collect_integral_values(self, profile)
    out = {
        'A': list(values.get('A', [0.0, 0.0, 0.0])),
        'B': {},
        'B_white': set(),
        'C': list(values.get('C', [0.0, 0.0, 0.0])),
        'D': list(values.get('D', [0.0, 0.0, 0.0])),
    }

    b_payload = _payload('B')
    b_summary = b_payload.get('summary', {}) if isinstance(b_payload.get('summary', {}), dict) else {}
    by_n = b_summary.get('by_n', {}) if isinstance(b_summary.get('by_n', {}), dict) else {}
    cycles = b_payload.get('cycles', []) if isinstance(b_payload.get('cycles', []), list) else []
    timeout_numbers = set()
    success_numbers = set()

    max_n = 0
    for key in by_n.keys():
        try:
            max_n = max(max_n, int(key))
        except Exception:
            pass
    for cycle in cycles:
        if isinstance(cycle, dict):
            try:
                cycle_n = int(cycle.get('n', 0) or 0)
            except Exception:
                cycle_n = 0
            max_n = max(max_n, cycle_n)
            reason = str(cycle.get('reason', '') or '').strip().lower()
            if cycle_n > 0 and reason == 'timeout' and not bool(cycle.get('success')):
                timeout_numbers.add(cycle_n)
            if cycle_n > 0 and bool(cycle.get('success')):
                success_numbers.add(cycle_n)

    for n in range(1, max_n + 1):
        item = by_n.get(str(n), {}) if isinstance(by_n, dict) else {}
        if isinstance(item, dict):
            val = _fixed376_float(item.get('t_n_zap', item.get('t_value', 0.0)), 0.0)
        else:
            val = 0.0
        out['B'][n] = val

    legacy_b = list(values.get('B', []) or [])
    for idx, val in enumerate(legacy_b, start=1):
        if _fixed376_float(out['B'].get(idx, 0.0), 0.0) <= 0 and _fixed376_float(val, 0.0) > 0:
            out['B'][idx] = _fixed376_float(val, 0.0)

    out['B_white'] = {n for n in timeout_numbers if n not in success_numbers}

    return out


def _fixed376_fig_word(n: int) -> str:
    n_abs = abs(int(n))
    n100 = n_abs % 100
    if 11 <= n100 <= 14:
        return 'фигур'
    n10 = n_abs % 10
    if n10 == 1:
        return 'фигуры'
    if 2 <= n10 <= 4:
        return 'фигур'
    return 'фигур'


def _fixed376_show_integral_results(self):
    if not self.current_profile:
        return
    values = _fixed376_collect_workability_values(self, self.current_profile)
    if not values:
        messagebox.showinfo('Интегральный результат', 'Пока нет сохранённых результатов для построения матрицы.')
        return

    top, outer = _open_results_top(self, 'Матрица психической работоспособности')
    bg = '#ffffff'
    aqua = '#c9ffff'
    line = '#123747'
    pale_line = '#b7c9df'
    outer.configure(bg=bg)

    a_vals = values.get('A', [0.0, 0.0, 0.0])
    c_vals = values.get('C', [0.0, 0.0, 0.0])
    d_vals = values.get('D', [0.0, 0.0, 0.0])
    b_vals = values.get('B', {}) if isinstance(values.get('B', {}), dict) else {}
    b_white_numbers = set()
    try:
        b_white_numbers = {int(n) for n in values.get('B_white', set())}
    except Exception:
        b_white_numbers = set()
    memory_numbers = sorted(int(n) for n in b_vals.keys() if int(n) > 0)
    extra_memory_numbers = [n for n in memory_numbers if n >= 8][:2]

    screen_w = max(1024, int(top.winfo_screenwidth() or 1366))
    canvas_w = min(max(screen_w - 90, 1320), 1600)

    x0 = 58
    y_title = 44
    y_info = 112
    y_top = 158
    y_grad = y_top + 70
    y_header = y_grad + 110

    left_w = 142
    level_w = 72
    grid_x = x0 + left_w + level_w
    usable_w = canvas_w - grid_x - 56
    col_w = usable_w / 4.0
    xs = [grid_x + i * col_w for i in range(5)]
    result_box_w = min(210, max(190, col_w - 44))

    memory_rows = [[1, 2, 3], [4, 5], [6, 7]]
    extra_memory_rows = [[n] for n in extra_memory_numbers]
    row_heights = [
        max(184, 62 * len(memory_rows[0])),
        max(150, 62 * len(memory_rows[1])),
        max(150, 62 * len(memory_rows[2])),
    ]
    y1 = y_header + row_heights[0]
    y2 = y1 + row_heights[1]
    y4 = y2 + row_heights[2]
    extra_row_h = 62
    y_memory_bottom = y4 + extra_row_h * len(extra_memory_rows)
    bottom_y = y_memory_bottom + 106
    canvas_h = bottom_y + 34

    canvas = tk.Canvas(outer, width=canvas_w, height=canvas_h, bg=bg, highlightthickness=0)
    canvas.pack(anchor='center', padx=18, pady=(18, 24))

    def _rect(x1, y1, x2, y2, *, outline=line, fill=bg, width=2):
        canvas.create_rectangle(x1, y1, x2, y2, outline=outline, fill=fill, width=width)

    def _line(x1, y1, x2, y2, *, fill=line, width=2):
        canvas.create_line(x1, y1, x2, y2, fill=fill, width=width)

    def _text(x, y, text, *, size=14, weight='bold', anchor='center', justify='center', angle=0, width=None):
        canvas.create_text(
            x,
            y,
            text=text,
            fill='#000000',
            font=('Arial', int(size), weight),
            anchor=anchor,
            justify=justify,
            angle=angle,
            width=width,
        )

    def _draw_t_token(cx: float, y: float, token: str, *, size: int = 30):
        token = str(token or '')
        if not token:
            return
        canvas.create_text(cx - 7, y, text=token[:1], fill='#000000', font=('Arial', size, 'bold'), anchor='e')
        if len(token) > 1:
            canvas.create_text(cx - 4, y + int(size * 0.22), text=token[1:], fill='#000000', font=('Arial', max(12, int(size * 0.48)), 'bold'), anchor='w')

    def _draw_value_box(cx: float, cy: float, token: str, value, *, force_white: bool = False, w: float = 170, h: float = 86, token_size: int = 26, value_size: int = 18):
        color = _fixed376_cell_color(value, force_white=force_white)
        x1 = cx - w / 2.0
        y1 = cy - h / 2.0
        x2 = cx + w / 2.0
        y2 = cy + h / 2.0
        _rect(x1, y1, x2, y2, fill=color, outline=pale_line, width=2)
        value_text = _fixed376_format_value(value, zero_as_empty=False)
        _text(cx, cy, f'{token} = {value_text}', size=value_size)

    def _draw_memory_box(cx: float, y: float, n: int, *, force_white: bool = False, w: float = 174, h: float = 34):
        val = _fixed376_float(b_vals.get(n, 0.0), 0.0)
        color = _fixed376_cell_color(val, force_white=force_white)
        _rect(cx - w / 2.0, y, cx + w / 2.0, y + h, fill=color, outline=pale_line, width=2)
        text = f't{n} = {_fixed376_format_value(val, zero_as_empty=False)}'
        _text(cx, y + h / 2.0, text, size=15)

    def _draw_memory_group(x1: float, y1: float, x2: float, y2: float, numbers: list[int]):
        cx = (x1 + x2) / 2.0
        count = max(1, len(numbers))
        slot_h = (y2 - y1) / count
        for idx, n in enumerate(numbers):
            slot_y1 = y1 + idx * slot_h
            slot_y2 = y1 + (idx + 1) * slot_h
            if idx:
                _line(x1, slot_y1, x2, slot_y1, fill=pale_line, width=2)
            _text(cx, slot_y1 + 12, f'Зап. {n} {_fixed376_fig_word(n)}', size=10)
            box_h = min(34, max(28, slot_h - 26))
            box_y = min(slot_y2 - box_h - 4, slot_y1 + 24)
            _draw_memory_box(cx, box_y, n, force_white=(n in b_white_numbers), w=result_box_w, h=box_h)

    def _value_at(vals: list, idx: int) -> float:
        return _fixed376_float(vals[idx], 0.0) if len(vals) > idx else 0.0

    def _gender_short(value) -> str:
        text = str(value or '').strip().lower()
        if text.startswith(('м', 'm')):
            return 'м'
        if text.startswith(('ж', 'f')):
            return 'ж'
        return str(value or '')

    _text(canvas_w / 2, y_title, 'Матрица психической работоспособности', size=27)
    _text(x0 + 12, y_info, 'ФИО', size=18, anchor='w')
    _line(x0 + 128, y_info + 12, x0 + 430, y_info + 12, fill='#333333', width=2)
    _text(x0 + 448, y_info, 'возраст', size=18, anchor='w')
    _line(x0 + 585, y_info + 12, x0 + 670, y_info + 12, fill='#333333', width=2)
    _text(x0 + 690, y_info, 'пол', size=18, anchor='w')
    _line(x0 + 775, y_info + 12, x0 + 840, y_info + 12, fill='#333333', width=2)
    _text(x0 + 862, y_info, 'проф.', size=18, anchor='w')
    _line(x0 + 950, y_info + 12, canvas_w - 70, y_info + 12, fill='#333333', width=2)

    try:
        profile = self.current_profile
        prof_value = (
            getattr(profile, 'profession', '')
            or getattr(profile, 'profession_name', '')
            or getattr(profile, 'prof', '')
        )
        _text(x0 + 138, y_info + 2, str(profile.name), size=11, weight='normal', anchor='w', width=286)
        _text(x0 + 596, y_info + 2, str(profile.age), size=11, weight='normal', anchor='w', width=70)
        _text(x0 + 790, y_info + 2, _gender_short(getattr(profile, 'gender', '')), size=11, weight='normal', anchor='w', width=42)
        if prof_value:
            _text(x0 + 960, y_info + 2, str(prof_value), size=11, weight='normal', anchor='w', width=int(canvas_w - x0 - 1030))
    except Exception:
        pass

    _rect(x0, y_top, canvas_w - 56, bottom_y, fill=bg, outline=line, width=2)
    _rect(x0, y_top, grid_x, bottom_y, fill=aqua, outline=line, width=2)
    _rect(grid_x, y_top, canvas_w - 56, y_grad, fill=aqua, outline=line, width=2)
    _text((grid_x + canvas_w - 56) / 2, y_top + 37, 'Градации сложности деятельности', size=30, weight='normal')

    _rect(grid_x, y_grad, canvas_w - 56, y_header, fill=aqua, outline=line, width=4)
    headers = [
        'сенсомоторная\nдеятельность',
        'мнестическая\nдеятельность',
        'счетно-\nлогическая\nдеятельность',
        'сложная\nлогическая\nдеятельность',
    ]
    for idx, header in enumerate(headers):
        _rect(xs[idx], y_grad, xs[idx + 1], y_header, fill=aqua, outline=line, width=4)
        _text((xs[idx] + xs[idx + 1]) / 2, y_grad + 54, header, size=16, width=int(col_w - 20))

    _text(x0 + left_w / 2, (y_header + y4) / 2, 'Градации числа\nэлементов деятельности', size=24, weight='normal', angle=90)
    _rect(x0 + left_w, y_header, grid_x, y4, fill=aqua, outline=line, width=4)
    for label, yc in [('Min', (y_header + y1) / 2), ('Med', (y1 + y2) / 2), ('Max', (y2 + y4) / 2)]:
        _text(x0 + left_w + level_w / 2, yc, label, size=25, weight='normal', angle=90)

    for x in xs:
        _line(x, y_header, x, y4, width=4)
    if extra_memory_rows:
        _line(xs[1], y4, xs[1], y_memory_bottom, width=4)
        _line(xs[2], y4, xs[2], y_memory_bottom, width=4)
        for idx in range(1, len(extra_memory_rows) + 1):
            y = y4 + extra_row_h * idx
            _line(xs[1], y, xs[2], y, width=4)
    for y in (y_header, y1, y2, y4):
        _line(x0 + left_w, y, canvas_w - 56, y, width=4)

    def _cell_bounds(col: int, row: int):
        y_starts = [y_header, y1, y2]
        y_ends = [y1, y2, y4]
        return xs[col], y_starts[row], xs[col + 1], y_ends[row]

    def _draw_standard_cell(col: int, row: int, title: str, token: str, value, *, box_h: float = 82, title_size: int = 10, token_size: int = 26, value_size: int = 18):
        x1, yy1, x2, yy2 = _cell_bounds(col, row)
        cx = (x1 + x2) / 2
        cell_h = yy2 - yy1
        _text(cx, yy1 + 19, title, size=title_size, width=int(x2 - x1 - 28))
        effective_h = min(box_h, max(58, cell_h - 68))
        box_cy = yy1 + 40 + (cell_h - 48) / 2
        box_cy = max(yy1 + 50 + effective_h / 2, min(yy2 - 10 - effective_h / 2, box_cy))
        _draw_value_box(cx, box_cy, token, value, w=result_box_w, h=effective_h, token_size=token_size, value_size=value_size)

    _draw_standard_cell(0, 0, 'Управление по\nX', 'tx', _value_at(a_vals, 0), box_h=84)
    _draw_standard_cell(0, 1, 'Управление по\nXY', 'txy', _value_at(a_vals, 1), box_h=78)
    _draw_standard_cell(0, 2, 'Управление по\nXYZ', 'txyz', _value_at(a_vals, 2), box_h=78)

    for row_idx, nums in enumerate(memory_rows):
        x1, yy1, x2, yy2 = _cell_bounds(1, row_idx)
        _draw_memory_group(x1, yy1, x2, yy2, nums)
    for extra_idx, nums in enumerate(extra_memory_rows):
        yy1 = y4 + extra_row_h * extra_idx
        yy2 = yy1 + extra_row_h
        _draw_memory_group(xs[1], yy1, xs[2], yy2, nums)

    _draw_standard_cell(2, 0, 'Однозначные\nцифры', 'tсчет1', _value_at(c_vals, 0), box_h=78, title_size=9, token_size=24, value_size=17)
    _draw_standard_cell(2, 1, 'Двузначные\nцифры', 'tсчет2', _value_at(c_vals, 1), box_h=76, title_size=9, token_size=24, value_size=17)
    _draw_standard_cell(2, 2, 'Трехзначные\nцифры', 'tсчет3', _value_at(c_vals, 2), box_h=76, title_size=9, token_size=24, value_size=17)

    _draw_standard_cell(3, 0, '2-позиционная\nзадача', 'tзак1', _value_at(d_vals, 0), box_h=78)
    _draw_standard_cell(3, 1, '3-позиционная\nзадача', 'tзак3', _value_at(d_vals, 1), box_h=74)
    _draw_standard_cell(3, 2, '4-позиционная\nзадача', 'tзак4', _value_at(d_vals, 2), box_h=74)

    legend_items = (
        ('#00b050', 'свыше 1,5', 220),
        ('#a8d18d', '1-1,5', 150),
        ('#fff200', '0,65-1', 155),
        ('#f8c85f', '0,5-0,65', 175),
        ('#ff1717', 'до 0,5', 145),
    )
    legend_y = y_memory_bottom + 44
    legend_total_w = sum(item_w for _color, _label, item_w in legend_items)
    legend_x = (grid_x + canvas_w - 56 - legend_total_w) / 2
    for color, label, item_w in legend_items:
        x = legend_x
        _rect(x, legend_y - 9, x + 76, legend_y + 9, fill=color, outline=line, width=1)
        _text(x + 92, legend_y, label, size=12, weight='normal', anchor='w')
        legend_x += item_w


_show_integral_results = _fixed376_show_integral_results
StartPageApp.show_integral_results = _fixed376_show_integral_results
StartPageApp.collect_integral_values = _fixed376_collect_workability_values


# ====== FIXED379: Method D normative cycle times in settings ======
_FIXED379_HIDDEN_D_SPEED_FIELDS = {'etap1_norm_speed', 'etap2_norm_speed', 'etap3_norm_speed'}

_fixed379_prev_get_research_section_groups = _get_research_section_groups


def _fixed379_get_research_section_groups(code: str, cls):
    if code != 'D':
        return _fixed379_prev_get_research_section_groups(code, cls)
    declared = [fld.name for fld in fields(cls) if fld.name not in _FIXED379_HIDDEN_D_SPEED_FIELDS]
    groups = [
        ('Структура теста', [name for name in ('total_test_s',) if name in declared]),
        ('Нормативы', [
            name for name in (
                'normative_success_coef',
                'etap1_norm_cycle_time_s',
                'etap2_norm_cycle_time_s',
                'etap3_norm_cycle_time_s',
            )
            if name in declared
        ]),
    ]
    used = {name for _title, names in groups for name in names}
    remaining = [name for name in declared if name not in used]
    result = [(title, names) for title, names in groups if names]
    if remaining:
        result.append(('Прочие параметры', remaining))
    return result


globals()['_get_research_section_groups'] = _fixed379_get_research_section_groups


_fixed379_prev_load_researcher_cfg = getattr(StartPageApp, 'load_researcher_cfg', None)






_fixed379_prev_collect_researcher_configs = StartPageApp.collect_researcher_configs


def _fixed379_collect_researcher_configs(self):
    collected = _fixed379_prev_collect_researcher_configs(self)
    for filename, cfg in collected:
        if str(filename).lower() != 'method_d_config.json':
            continue
        for time_attr, speed_attr, default_time in (
            ('etap1_norm_cycle_time_s', 'etap1_norm_speed', 6.25),
            ('etap2_norm_cycle_time_s', 'etap2_norm_speed', 8.75),
            ('etap3_norm_cycle_time_s', 'etap3_norm_speed', 11.25),
        ):
            try:
                time_value = float(getattr(cfg, time_attr, default_time) or default_time)
            except Exception:
                time_value = default_time
            if time_value <= 0:
                time_value = default_time
            setattr(cfg, time_attr, float(time_value))
            setattr(cfg, speed_attr, 1.0 / float(time_value))
    return collected


