# ====== FIXED407: Method A PXN forward stick moves aircraft down on stages 2 and 3 ======
_FIXED406_METHOD_A_STAGE23_JOYSTICK_Y_VERSION = 'fixed407_method_a_stage23_pxn_forward_down_v1'
_FIXED406_PXN_FORWARD_RAW_Y_SIGN = -1.0
_fixed406_prev_method_a_init = MethodAApp.__init__


def _fixed406_method_a_init(self, cfg: MethodAConfig, session: SessionInfo, logger: ParticipantsLogger, base_dir: Path):
    _fixed406_prev_method_a_init(self, cfg, session, logger, base_dir)
    try:
        pygame.display.set_caption('СПР - Тест А: слежение за объектом · fixed407')
    except Exception:
        pass


def _fixed406_stage23_y_delta(y_in: float, gain_xy: float, dt: float) -> float:
    return float(y_in) * float(_FIXED406_PXN_FORWARD_RAW_Y_SIGN) * float(gain_xy) * float(dt)


def _fixed406_apply_pxn_control(self, state: DriftState, stage_no: int) -> bool:
    joy = getattr(self, '_joy', None)
    if not bool(getattr(self, '_joy_enabled', False)) or joy is None:
        return False
    try:
        if not bool(joy.get_init()):
            return False
    except Exception:
        return False

    try:
        pygame.event.pump()
    except Exception:
        pass

    stage_no = int(stage_no)
    stage = self.stage_defs[int(stage_no)]
    now_ms = int(pygame.time.get_ticks())
    prev_ms = int(getattr(self, '_joy_last_tick_ms', now_ms))
    dt = max(1.0 / 240.0, min(0.2, float(now_ms - prev_ms) / 1000.0))
    self._joy_last_tick_ms = now_ms

    deadzone = max(0.01, min(0.35, float(getattr(self.cfg, 'joystick_deadzone', 0.08) or 0.08)))
    axis_big_x = int(getattr(self.cfg, 'joystick_axis_x', 0) or 0)
    axis_big_y = int(getattr(self.cfg, 'joystick_axis_y', 1) or 1)

    drift_xy_px_s = abs(float(getattr(state, 'speed_xy_cm_s', getattr(self.cfg, 'start_speed_xy_cm_s', 3.0)) or 3.0)) * float(getattr(self.cfg, 'px_per_cm', 38.0) or 38.0)
    base_xy = max(1.0, float(getattr(self.cfg, 'joystick_xy_gain_px_s', 520.0) or 520.0))
    gain_xy = max(base_xy * 1.8, drift_xy_px_s * 6.0) if stage_no != 3 else max(base_xy, drift_xy_px_s * 3.2)
    work_xy = max(1.0, float(getattr(self, 'work_half_px', 1.0) or 1.0))
    xy_dev = max(abs(float(getattr(state, 'x_px', 0.0) or 0.0)), abs(float(getattr(state, 'y_px', 0.0) or 0.0))) / work_xy
    if stage_no != 3:
        gain_xy *= 1.0 + min(2.2, max(0.0, xy_dev) * 2.2)

    x_in = _fixed356_axis(joy, axis_big_x, deadzone)
    y_in = _fixed356_axis(joy, axis_big_y, deadzone)
    if stage_no != 3:
        if abs(x_in) > 0.0:
            x_in = math.copysign(abs(x_in) ** 0.75, x_in)
        if abs(y_in) > 0.0:
            y_in = math.copysign(abs(y_in) ** 0.75, y_in)

    applied = False
    if bool(stage.get('x')):
        state.x_px -= x_in * gain_xy * dt
        applied = applied or abs(x_in) > 0.0
    if bool(stage.get('y')):
        if stage_no in (2, 3):
            state.y_px += _fixed406_stage23_y_delta(y_in, gain_xy, dt)
        else:
            state.y_px -= y_in * gain_xy * dt
        applied = applied or abs(y_in) > 0.0

    if bool(stage.get('z')) and stage_no == 3:
        roll_speed = abs(float(getattr(state, 'speed_z_deg_s', getattr(self.cfg, 'start_speed_z_deg_s', 10.0)) or 10.0))
        base_z = max(1.0, float(getattr(self.cfg, 'joystick_roll_gain_deg_s', roll_speed) or roll_speed))
        gain_z = max(base_z, roll_speed * 2.8)

        z_twist = _fixed363_pick_twist_roll(self, joy, axis_big_x, axis_big_y, deadzone)

        left0 = int(getattr(self.cfg, 'joystick_roll_left_button', 4) or 4)
        right0 = int(getattr(self.cfg, 'joystick_roll_right_button', 5) or 5)
        left_pressed = _fixed359_button_pressed(self, joy, left0)
        right_pressed = _fixed359_button_pressed(self, joy, right0)
        if not left_pressed and not right_pressed:
            left_pressed = _fixed359_button_pressed(self, joy, left0 + 1)
            right_pressed = _fixed359_button_pressed(self, joy, right0 + 1)

        z_btn = 0.0
        if left_pressed and not right_pressed:
            z_btn = -1.0
        elif right_pressed and not left_pressed:
            z_btn = 1.0

        z_small = _fixed362_pick_small_stick_roll(self, joy, axis_big_x, axis_big_y, deadzone)
        z_in = z_twist
        if abs(z_in) < deadzone:
            z_in = z_btn
        if abs(z_in) < deadzone:
            z_in = z_small
        if bool(getattr(self.cfg, 'joystick_invert_roll', False)):
            z_in = -z_in
        if abs(z_in) > 0.0:
            z_in = math.copysign(abs(z_in) ** 0.72, z_in)
            state.roll_deg -= z_in * gain_z * dt
            applied = True

    return bool(applied)


MethodAApp.__init__ = _fixed406_method_a_init
_fixed360_apply_pxn_control = _fixed406_apply_pxn_control


# ====== FIXED408: extended registration profile + FIO-prefixed data files ======
import re

_FIXED408_PROFILE_FIELDS_VERSION = 'fixed408_profile_fields_fio_data_files_v1'


@dataclass(frozen=True)
class UserProfile:
    name: str
    age: int
    gender: str
    flight_hours: str = ''
    aircraft_type: str = ''
    position: str = ''
    education: str = ''

    @property
    def key(self) -> str:
        return f"{self.name.strip().casefold()}|{self.age}|{self.gender.strip().casefold()}"


def _fixed416_find_progress_key_for_profile(data: dict, profile: UserProfile) -> str:
    if isinstance(data, dict) and profile.key in data:
        return profile.key
    target = _fixed416_norm_identity(profile.name, profile.age, profile.gender)
    if not isinstance(data, dict) or not target[0]:
        return profile.key
    for key, record in data.items():
        if isinstance(record, dict) and _fixed416_record_identity(record) == target:
            return str(key)
    return profile.key


_fixed416_prev_get_progress = UserProgressStore.get_progress
_fixed416_prev_get_test_result = UserProgressStore.get_test_result


def _fixed416_get_progress(self, profile: UserProfile) -> dict:
    data = self._load()
    key = _fixed416_find_progress_key_for_profile(data, profile)
    if key == profile.key:
        return _fixed416_prev_get_progress(self, profile)
    record = data.get(key)
    if not isinstance(record, dict):
        return _fixed416_prev_get_progress(self, profile)
    completed = []
    for code in record.get('completed_tests', []):
        if code in TEST_ORDER and code not in completed:
            completed.append(code)
    record['completed_tests'] = completed
    record.setdefault('name', profile.name)
    record.setdefault('age', profile.age)
    record.setdefault('gender', profile.gender)
    record.setdefault('created_at', datetime.now().isoformat(timespec='seconds'))
    record.setdefault('updated_at', datetime.now().isoformat(timespec='seconds'))
    record.setdefault('results', {})
    record.setdefault('history', [])
    return record


def _fixed416_get_test_result(self, profile: UserProfile, test_code: str) -> dict | None:
    data = self._load()
    key = _fixed416_find_progress_key_for_profile(data, profile)
    if key == profile.key:
        return _fixed416_prev_get_test_result(self, profile, test_code)
    record = data.get(key)
    if not isinstance(record, dict):
        return None
    results = record.get('results', {})
    if not isinstance(results, dict):
        return None
    item = results.get(test_code)
    if not isinstance(item, dict):
        return None
    return self._enrich_payload_for_storage(test_code, item)


UserProgressStore.get_progress = _fixed416_get_progress
UserProgressStore.get_test_result = _fixed416_get_test_result


CSV_HEADERS = [
    "Дата",
    "Время",
    "ФИО",
    "Возраст",
    "Пол",
    "Налет (ч)",
    "Тип ВС",
    "Должность",
    "Образование",
    "SessionID",
    "Событие",
    "Экран",
    "Тест",
    "Этап",
    "Действие",
    "Длительность_мс",
    "X",
    "Y",
    "Крен",
    "Значение",
    "Примечание",
]


def _fixed408_clean_text(value) -> str:
    return str(value or '').strip()


def _fixed408_filename_prefix(name: str) -> str:
    text = _fixed408_clean_text(name)
    text = re.sub(r'[<>:"/\\|?*\x00-\x1f]+', '_', text)
    text = re.sub(r'\s+', '_', text).strip('._ ')
    return text[:80] or 'Без_ФИО'


def _fixed408_participant_dict(source) -> dict:
    return {
        'name': _fixed408_clean_text(getattr(source, 'name', '')),
        'age': getattr(source, 'age', ''),
        'gender': _fixed408_clean_text(getattr(source, 'gender', '')),
        'flight_hours': _fixed408_clean_text(getattr(source, 'flight_hours', '')),
        'aircraft_type': _fixed408_clean_text(getattr(source, 'aircraft_type', '')),
        'position': _fixed408_clean_text(getattr(source, 'position', '')),
        'education': _fixed408_clean_text(getattr(source, 'education', '')),
    }


def _fixed408_legacy_csv_row_to_current(row: list[str]) -> list[str]:
    if len(row) == 17:
        return row[:5] + ['', '', '', ''] + row[5:]
    if len(row) == 21:
        return row
    if len(row) > 5 and len(row) < len(CSV_HEADERS):
        return row[:5] + [''] * (len(CSV_HEADERS) - len(row)) + row[5:]
    return row


def _fixed408_logger_ensure_file(self):
    self.rotate_weekly_file_if_needed()
    self.data_dir.mkdir(parents=True, exist_ok=True)

    now = datetime.now()
    current_year, current_week, _ = now.isocalendar()

    if not self.data_file.exists() or self.data_file.stat().st_size <= 0:
        with open(self.data_file, 'w', newline='', encoding='utf-8-sig') as f:
            writer = csv.writer(f, delimiter=';')
            writer.writerow(['Неделя', f'{current_year}-W{current_week:02d}'])
            writer.writerow(CSV_HEADERS)
        return

    try:
        with open(self.data_file, 'r', newline='', encoding='utf-8-sig') as f:
            rows = list(csv.reader(f, delimiter=';'))
    except Exception:
        return

    changed = False
    header_idx = None
    for idx, row in enumerate(rows):
        if row and row[0] == 'Дата':
            header_idx = idx
            break

    if header_idx is None:
        rows.insert(0, CSV_HEADERS)
        changed = True
    elif rows[header_idx] != CSV_HEADERS:
        rows[header_idx] = CSV_HEADERS
        changed = True

    start_idx = 0 if header_idx is None else header_idx + 1
    for idx in range(start_idx, len(rows)):
        row = rows[idx]
        if not row or row[0] in ('Неделя', 'Дата'):
            continue
        updated = _fixed408_legacy_csv_row_to_current(row)
        if updated != row:
            rows[idx] = updated
            changed = True

    if changed:
        with open(self.data_file, 'w', newline='', encoding='utf-8-sig') as f:
            writer = csv.writer(f, delimiter=';')
            writer.writerows(rows)


def _fixed408_logger_log_event(
    self,
    session: SessionInfo,
    event_type: str,
    screen: str = '',
    test_name: str = '',
    stage: str = '',
    action: str = '',
    elapsed_ms: str | int | float = '',
    x: str | int | float = '',
    y: str | int | float = '',
    angle: str | int | float = '',
    value: str | int | float = '',
    note: str = '',
):
    current_year, current_week, _ = datetime.now().isocalendar()
    prefix = _fixed408_filename_prefix(getattr(session, 'name', ''))
    self.data_file = self.data_dir / f'{prefix}_participants_{current_year}-W{current_week:02d}.csv'
    self._ensure_file()
    now = datetime.now()
    participant = _fixed408_participant_dict(session)
    row = [
        now.strftime('%d.%m.%Y'),
        now.strftime('%H:%M:%S'),
        participant['name'],
        participant['age'],
        participant['gender'],
        participant['flight_hours'],
        participant['aircraft_type'],
        participant['position'],
        participant['education'],
        session.session_id,
        event_type,
        screen,
        test_name,
        stage,
        action,
        elapsed_ms,
        x,
        y,
        angle,
        value,
        note,
    ]
    with open(self.data_file, 'a', newline='', encoding='utf-8-sig') as f:
        writer = csv.writer(f, delimiter=';')
        writer.writerow(row)


