def _fixed408_validate_form(self):
    name = self.name_var.get().strip()
    age_text = self.age_var.get().strip()
    gender = self.gender_var.get().strip()
    flight_hours = self.flight_hours_var.get().strip()
    aircraft_type = self.aircraft_type_var.get().strip()
    position = self.position_var.get().strip()
    education = self.education_var.get().strip()

    if not name:
        return False, 'Введите ФИО.'
    if not age_text:
        return False, 'Введите возраст.'
    if not age_text.isdigit():
        return False, 'Возраст должен быть целым числом лет.'

    age = int(age_text)
    if age < 1 or age > 120:
        return False, 'Возраст должен быть в диапазоне от 1 до 120 лет.'
    if gender not in ('Мужской', 'Женский'):
        return False, 'Выберите пол.'
    if not flight_hours:
        return False, 'Введите налет в часах.'
    try:
        flight_value = float(flight_hours.replace(',', '.'))
    except ValueError:
        return False, 'Налет должен быть числом часов.'
    if flight_value < 0:
        return False, 'Налет не может быть отрицательным.'
    if not aircraft_type:
        return False, 'Введите тип ВС.'
    if not position:
        return False, 'Введите должность.'
    if not education:
        return False, 'Введите образование.'

    return True, UserProfile(
        name=name,
        age=age,
        gender=gender,
        flight_hours=flight_hours,
        aircraft_type=aircraft_type,
        position=position,
        education=education,
    )


