def save_method_payload(base_dir: Path, code: str, session_id: str, payload: dict) -> str:
    ts = datetime.now().strftime('%Y%m%d_%H%M%S')
    participant = payload.get('participant', {}) if isinstance(payload, dict) else {}
    prefix = _fixed408_filename_prefix(participant.get('name', ''))
    p = _results_dir(base_dir) / f'{prefix}_method_{code.lower()}_{session_id}_{ts}.json'
    p.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
    return str(p)


