def _fixed408_method_a_run(self) -> dict:
    outcome = _fixed408_prev_method_a_run(self)
    try:
        result_path_raw = str(outcome.get('result_path', '') or '').strip()
        if not result_path_raw:
            return outcome
        result_path = Path(result_path_raw)
        if not result_path.is_absolute():
            result_path = self.base_dir / result_path
        if not result_path.exists() or not result_path.is_file():
            return outcome
        prefix = _fixed408_filename_prefix(getattr(self.session, 'name', ''))
        if result_path.name.startswith(prefix + '_'):
            outcome['result_path'] = str(result_path)
            return outcome
        target = result_path.with_name(f'{prefix}_{result_path.name}')
        if target.exists():
            target = result_path.with_name(f'{prefix}_{datetime.now().strftime("%Y%m%d_%H%M%S")}_{result_path.name}')
        result_path.replace(target)
        outcome['result_path'] = str(target)
    except Exception:
        pass
    return outcome


MethodAApp.run = _fixed408_method_a_run


def _fixed408_rewrite_payload_file(payload: dict):
    try:
        result_path_raw = str(payload.get('result_path', '') or '').strip()
        if not result_path_raw:
            return
        result_path = Path(result_path_raw)
        if result_path.exists() and result_path.is_file():
            result_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
    except Exception:
        pass


