# ====== FIXED409: Method A per-stage normative axis speeds ======
_FIXED409_METHOD_A_STAGE_NORM_SPEEDS_VERSION = 'fixed409_method_a_stage_axis_norm_speeds_v1'


@dataclass
class MethodAConfigFixed409(MethodAConfig):
    # Stage-specific normative control speeds. Defaults preserve the previous
    # common-axis values while allowing each stage to be tuned independently.
    stage1_v_norm_x_cm_s: float = 5.0
    stage2_v_norm_x_cm_s: float = 5.0
    stage2_v_norm_y_cm_s: float = 5.0
    stage3_v_norm_x_cm_s: float = 5.0
    stage3_v_norm_y_cm_s: float = 5.0
    stage3_v_norm_z_deg_s: float = 25.0


MethodAConfig = MethodAConfigFixed409
globals()['MethodAConfig'] = MethodAConfigFixed409

_fixed409_prev_load_config = load_config


def _fixed409_float(value, default: float) -> float:
    try:
        return float(value)
    except Exception:
        return float(default)


def _fixed409_stage_norms(cfg, stage_no: int) -> tuple[float, float, float]:
    fallback_x = _fixed409_float(getattr(cfg, 'v_norm_x_cm_s', 5.0), 5.0)
    fallback_y = _fixed409_float(getattr(cfg, 'v_norm_y_cm_s', 5.0), 5.0)
    fallback_z = _fixed409_float(getattr(cfg, 'v_norm_z_deg_s', 25.0), 25.0)
    st = int(stage_no)
    if st == 1:
        return (
            max(1e-6, _fixed409_float(getattr(cfg, 'stage1_v_norm_x_cm_s', fallback_x), fallback_x)),
            fallback_y,
            fallback_z,
        )
    if st == 2:
        return (
            max(1e-6, _fixed409_float(getattr(cfg, 'stage2_v_norm_x_cm_s', fallback_x), fallback_x)),
            max(1e-6, _fixed409_float(getattr(cfg, 'stage2_v_norm_y_cm_s', fallback_y), fallback_y)),
            fallback_z,
        )
    return (
        max(1e-6, _fixed409_float(getattr(cfg, 'stage3_v_norm_x_cm_s', fallback_x), fallback_x)),
        max(1e-6, _fixed409_float(getattr(cfg, 'stage3_v_norm_y_cm_s', fallback_y), fallback_y)),
        max(1e-6, _fixed409_float(getattr(cfg, 'stage3_v_norm_z_deg_s', fallback_z), fallback_z)),
    )


def _fixed409_clamp_cfg(cfg: MethodAConfigFixed409) -> MethodAConfigFixed409:
    cfg = _fixed260_clamp_cfg(cfg)
    cfg.stage1_v_norm_x_cm_s = max(1e-6, _fixed409_float(getattr(cfg, 'stage1_v_norm_x_cm_s', getattr(cfg, 'v_norm_x_cm_s', 5.0)), 5.0))
    cfg.stage2_v_norm_x_cm_s = max(1e-6, _fixed409_float(getattr(cfg, 'stage2_v_norm_x_cm_s', getattr(cfg, 'v_norm_x_cm_s', 5.0)), 5.0))
    cfg.stage2_v_norm_y_cm_s = max(1e-6, _fixed409_float(getattr(cfg, 'stage2_v_norm_y_cm_s', getattr(cfg, 'v_norm_y_cm_s', 5.0)), 5.0))
    cfg.stage3_v_norm_x_cm_s = max(1e-6, _fixed409_float(getattr(cfg, 'stage3_v_norm_x_cm_s', getattr(cfg, 'v_norm_x_cm_s', 5.0)), 5.0))
    cfg.stage3_v_norm_y_cm_s = max(1e-6, _fixed409_float(getattr(cfg, 'stage3_v_norm_y_cm_s', getattr(cfg, 'v_norm_y_cm_s', 5.0)), 5.0))
    cfg.stage3_v_norm_z_deg_s = max(1e-6, _fixed409_float(getattr(cfg, 'stage3_v_norm_z_deg_s', getattr(cfg, 'v_norm_z_deg_s', 25.0)), 25.0))
    return cfg


def load_config(path: str | Path = 'method_a_config.json', screen_w: int | None = None, screen_h: int | None = None) -> MethodAConfigFixed409:
    base_cfg = _fixed409_prev_load_config(path=path, screen_w=screen_w, screen_h=screen_h)
    raw = _fixed260_read_raw_json(path)

    inherited_kwargs = {}
    for fld in fields(MethodAConfigFixed409):
        if hasattr(base_cfg, fld.name):
            inherited_kwargs[fld.name] = getattr(base_cfg, fld.name)
        elif fld.name in raw:
            inherited_kwargs[fld.name] = raw.get(fld.name)

    cfg = MethodAConfigFixed409(**inherited_kwargs)
    for key in (
        'stage1_v_norm_x_cm_s',
        'stage2_v_norm_x_cm_s',
        'stage2_v_norm_y_cm_s',
        'stage3_v_norm_x_cm_s',
        'stage3_v_norm_y_cm_s',
        'stage3_v_norm_z_deg_s',
    ):
        if key in raw:
            try:
                setattr(cfg, key, float(raw.get(key)))
            except Exception:
                pass
    cfg = _fixed409_clamp_cfg(cfg)
    return cfg


globals()['load_config'] = load_config

