def _fixed409_get_research_section_groups(code: str, cls):
    groups = _fixed409_prev_get_research_section_groups(code, cls)
    if code != 'A':
        return groups
    hidden_fields = {'v_norm_x_cm_s', 'v_norm_y_cm_s', 'v_norm_z_deg_s'}
    cleaned_groups = []
    for title, field_names in groups:
        cleaned = [name for name in field_names if name not in hidden_fields]
        if cleaned:
            cleaned_groups.append((title, cleaned))
    return cleaned_groups


