def _fixed409_run_stage(self, stage_no: int) -> StageReport:
    cfg = self.cfg
    old_norms = (
        getattr(cfg, 'v_norm_x_cm_s', 5.0),
        getattr(cfg, 'v_norm_y_cm_s', 5.0),
        getattr(cfg, 'v_norm_z_deg_s', 25.0),
    )
    stage_norms = _fixed409_stage_norms(cfg, int(stage_no))
    cfg.v_norm_x_cm_s, cfg.v_norm_y_cm_s, cfg.v_norm_z_deg_s = stage_norms
    try:
        report = _fixed409_prev_run_stage(self, stage_no)
        report.v_norm_x_stage = float(stage_norms[0])
        report.v_norm_y_stage = float(stage_norms[1])
        report.v_norm_z_stage = float(stage_norms[2])
        report.stage_norm_speed_version = _FIXED409_METHOD_A_STAGE_NORM_SPEEDS_VERSION
        return report
    finally:
        cfg.v_norm_x_cm_s, cfg.v_norm_y_cm_s, cfg.v_norm_z_deg_s = old_norms


MethodAApp.run_stage = _fixed409_run_stage


