def _fixed411_make_radio_image(selected: bool, size: int = 26):
    img = Image.new('RGBA', (size, size), (0, 0, 0, 0))
    draw = ImageDraw.Draw(img)
    margin = max(2, int(size * 0.12))
    draw.ellipse(
        (margin, margin, size - margin - 1, size - margin - 1),
        fill=(255, 255, 255, 255),
        outline=(0, 0, 0, 255),
        width=max(2, size // 13),
    )
    if selected:
        dot_margin = max(7, int(size * 0.32))
        draw.ellipse(
            (dot_margin, dot_margin, size - dot_margin - 1, size - dot_margin - 1),
            fill=(0, 0, 0, 255),
        )
    return ImageTk.PhotoImage(img)


def _fixed411_refresh_gender_radio_images(self):
    images = getattr(self, '_fixed411_radio_images', None)
    if not images:
        return
    gender = self.gender_var.get()
    male = getattr(self, 'gender_male', None)
    female = getattr(self, 'gender_female', None)
    if male is not None:
        male.configure(image=images['on'] if gender == 'Мужской' else images['off'])
    if female is not None:
        female.configure(image=images['on'] if gender == 'Женский' else images['off'])


def _fixed411_make_gender_radio(self, text: str, value: str):
    return tk.Radiobutton(
        self.gender_frame,
        text=text,
        variable=self.gender_var,
        value=value,
        image=self._fixed411_radio_images['on'] if self.gender_var.get() == value else self._fixed411_radio_images['off'],
        compound='left',
        indicatoron=False,
        bg=PANEL_COLOR,
        activebackground=PANEL_COLOR,
        selectcolor=PANEL_COLOR,
        highlightthickness=0,
        bd=0,
        relief='flat',
        overrelief='flat',
        anchor='w',
        padx=0,
        pady=0,
        command=lambda: _fixed411_refresh_gender_radio_images(self),
    )


