# ====== FIXED412: suggest known FIOs without forced autofill ======
_FIXED412_LOGIN_FIO_SUGGESTIONS_VERSION = 'fixed412_login_fio_suggestions_manual_choice_v1'


def _fixed412_known_records_for_name(self, raw_name: str, limit: int = 6) -> list[dict]:
    query = _fixed410_norm_name(raw_name)
    if not query:
        return []

    records = []
    try:
        records = [
            record for _profile, record in self.progress_store.all_user_records()
            if isinstance(record, dict)
        ]
    except Exception:
        try:
            data = self.progress_store._load()
            if isinstance(data, dict):
                records = [record for record in data.values() if isinstance(record, dict)]
        except Exception:
            records = []

    by_name = {}
    for record in records:
        name = str(record.get('name', '') or '').strip()
        norm = _fixed410_norm_name(name)
        if not norm:
            continue
        if not norm.startswith(query) and query not in norm:
            continue
        old = by_name.get(norm)
        if old is None or _fixed410_record_stamp(record) > _fixed410_record_stamp(old):
            by_name[norm] = record

    found = list(by_name.values())
    found.sort(key=lambda record: (not _fixed410_norm_name(record.get('name', '')).startswith(query), str(record.get('name', '')).casefold()))
    return found[:max(1, int(limit))]




def _fixed412_show_suggestions(self):
    box = getattr(self, 'fio_suggestion_box', None)
    if box is None:
        return

    records = _fixed412_known_records_for_name(self, self.name_var.get())
    self._fixed412_suggestion_records = records
    box.delete(0, tk.END)
    if not records:
        _fixed412_hide_suggestions(self)
        return

    for record in records:
        name = str(record.get('name', '') or '').strip()
        age = str(record.get('age', '') or '').strip()
        aircraft = str(record.get('aircraft_type', '') or '').strip()
        position = str(record.get('position', '') or '').strip()
        details = ', '.join(part for part in (age + ' лет' if age else '', aircraft, position) if part)
        box.insert(tk.END, f'{name} — {details}' if details else name)

    visible_rows = min(5, max(1, len(records)))
    box.configure(height=visible_rows)
    box.grid()


def _fixed412_schedule_suggestions(self):
    after_id = getattr(self, '_fixed412_suggest_after_id', None)
    if after_id is not None:
        try:
            self.root.after_cancel(after_id)
        except Exception:
            pass
    self._fixed412_suggest_after_id = self.root.after(250, lambda: _fixed412_show_suggestions(self))






def _fixed412_shift_login_rows_for_suggestions(self):
    for widget in list(self.form_frame.winfo_children()):
        if widget in (getattr(self, 'name_label', None), getattr(self, 'name_entry', None)):
            continue
        try:
            info = widget.grid_info()
            row = int(info.get('row', 0))
        except Exception:
            continue
        if row >= 2:
            widget.grid_configure(row=row + 1)


def _fixed412_install_fio_suggestions(self):
    old_box = getattr(self, 'fio_suggestion_box', None)
    if getattr(self, '_fixed412_suggestions_installed', False) and old_box is not None:
        try:
            if old_box.winfo_exists():
                return
        except Exception:
            pass
    if getattr(self, '_fixed412_suggestions_installed', False):
        self._fixed412_suggestions_installed = False
    self._fixed412_suggestions_installed = True
    self._fixed412_suggestion_records = []

    _fixed412_shift_login_rows_for_suggestions(self)

    self.fio_suggestion_box = tk.Listbox(
        self.form_frame,
        exportselection=False,
        activestyle='dotbox',
        bg='#ffffff',
        fg=TEXT_COLOR,
        selectbackground='#dbeafe',
        selectforeground=TEXT_COLOR,
        bd=1,
        relief='solid',
        highlightthickness=1,
        highlightbackground='#9aa7b5',
    )
    self.fio_suggestion_box.grid(row=2, column=1, sticky='ew', padx=(0, 16), pady=(0, 6))
    self.fio_suggestion_box.grid_remove()

    self.name_entry.bind('<KeyRelease>', lambda _event: _fixed412_schedule_suggestions(self), add='+')
    self.name_entry.bind('<Down>', lambda _event: (_fixed412_show_suggestions(self), self.fio_suggestion_box.focus_set(), self.fio_suggestion_box.selection_set(0), 'break')[-1], add='+')
    self.fio_suggestion_box.bind('<Return>', lambda _event: (_fixed412_accept_selected_suggestion(self), 'break')[-1])
    self.fio_suggestion_box.bind('<Double-Button-1>', lambda _event: _fixed412_accept_selected_suggestion(self))
    self.fio_suggestion_box.bind('<ButtonRelease-1>', lambda _event: _fixed412_accept_selected_suggestion(self))
    self.fio_suggestion_box.bind('<Escape>', lambda _event: (_fixed412_hide_suggestions(self), self.name_entry.focus_set(), 'break')[-1])
    self.name_entry.bind('<Escape>', lambda _event: (_fixed412_hide_suggestions(self), 'break')[-1], add='+')
    self.name_entry.bind('<FocusOut>', lambda _event: self.root.after(200, lambda: _fixed412_hide_suggestions(self)), add='+')


