# ====== FIXED414: Method A accepts small-stick forward on pre-test buttons ======
_FIXED414_METHOD_A_SMALL_STICK_CONTINUE_VERSION = 'fixed414_method_a_small_stick_forward_continue_v1'


def _fixed414_float(value, default: float) -> float:
    try:
        return float(value)
    except Exception:
        return float(default)


def _fixed414_int(value, default: int) -> int:
    try:
        return int(value)
    except Exception:
        return int(default)


def _fixed414_method_a_cfg_for_owner(owner):
    try:
        cfg = getattr(owner, 'cfg', None)
        if cfg is not None:
            return cfg
    except Exception:
        pass
    try:
        base_dir = Path(getattr(owner, 'base_dir', Path.cwd()))
        return load_config(base_dir / 'method_a_config.json')
    except Exception:
        try:
            return MethodAConfig()
        except Exception:
            return None








def _fixed414_install_method_a_small_stick_continue(owner, top, continue_callback) -> None:
    state = _fixed414_init_small_stick_continue_state(owner)
    if not state:
        return

    def _poll():
        try:
            if not top.winfo_exists():
                return
            if _fixed414_small_stick_forward_pushed(state):
                continue_callback()
                return
            top.after(60, _poll)
        except Exception:
            return

    try:
        setattr(top, '_fixed414_small_stick_continue_state', state)
    except Exception:
        pass
    try:
        top.after(250, _poll)
    except Exception:
        pass


# ====== FIXED415: wider small-stick detection and Method A "Start test" button ======
_FIXED415_METHOD_A_SMALL_STICK_START_VERSION = 'fixed415_method_a_small_stick_start_and_continue_v1'


def _fixed415_method_a_big_axes(cfg) -> tuple[int, int]:
    return (
        _fixed414_int(getattr(cfg, 'joystick_axis_x', 0), 0),
        _fixed414_int(getattr(cfg, 'joystick_axis_y', 1), 1),
    )


def _fixed415_init_small_stick_continue_state(owner):
    try:
        pg = _ensure_pygame()
        try:
            pg.init()
        except Exception:
            pass
        try:
            pg.joystick.init()
        except Exception:
            return None
        count = int(pg.joystick.get_count())
        if count <= 0:
            return None

        cfg = _fixed414_method_a_cfg_for_owner(owner)
        joys = []
        for idx in range(count):
            try:
                joy = pg.joystick.Joystick(idx)
                if not joy.get_init():
                    joy.init()
                axis_count = int(joy.get_numaxes())
                baseline = {}
                for axis in range(max(0, axis_count)):
                    try:
                        baseline[axis] = float(joy.get_axis(axis))
                    except Exception:
                        baseline[axis] = 0.0
                joys.append({'joy': joy, 'baseline': baseline})
            except Exception:
                continue
        if not joys:
            return None
        try:
            pg.event.pump()
        except Exception:
            pass
        return {
            'pygame': pg,
            'cfg': cfg,
            'joys': joys,
            'last_accept_ms': -10000,
        }
    except Exception:
        return None


def _fixed415_threshold(cfg) -> float:
    threshold = _fixed414_float(getattr(cfg, 'joystick_small_forward_threshold', 0.28), 0.28)
    return max(0.12, min(0.95, threshold))


def _fixed415_axis_is_small_candidate(cfg, axis: int) -> bool:
    big_x, big_y = _fixed415_method_a_big_axes(cfg)
    return int(axis) not in (big_x, big_y)


def _fixed415_axis_moved_forward_enough(cfg, raw: float, baseline: float) -> bool:
    threshold = _fixed415_threshold(cfg)
    forward_sign = _fixed414_float(getattr(cfg, 'joystick_small_forward_sign', -1.0), -1.0)
    if forward_sign == 0:
        forward_sign = -1.0
    delta = float(raw) - float(baseline)
    if (delta * forward_sign) >= threshold:
        return True
    if abs(delta) >= threshold:
        return True
    # Some drivers report a centered stick around 0.0 and do not change the
    # stored baseline cleanly until the first motion event reaches the queue.
    return abs(float(baseline)) < 0.20 and abs(float(raw)) >= max(threshold, 0.35)


def _fixed415_event_pushed_small_stick(state, events) -> bool:
    cfg = state.get('cfg')
    joys = state.get('joys') or []
    by_instance = {}
    for item in joys:
        joy = item.get('joy')
        try:
            by_instance[int(joy.get_instance_id())] = item
        except Exception:
            continue

    for event in events or []:
        ev_type = getattr(event, 'type', None)
        if ev_type == getattr(pygame, 'JOYAXISMOTION', -1):
            axis = _fixed414_int(getattr(event, 'axis', -1), -1)
            if axis < 0 or not _fixed415_axis_is_small_candidate(cfg, axis):
                continue
            item = by_instance.get(_fixed414_int(getattr(event, 'instance_id', -999999), -999999))
            if item is None and joys:
                item = joys[0]
            baseline = 0.0
            try:
                baseline = float((item.get('baseline') or {}).get(axis, 0.0))
            except Exception:
                baseline = 0.0
            raw = _fixed414_float(getattr(event, 'value', 0.0), 0.0)
            if _fixed415_axis_moved_forward_enough(cfg, raw, baseline):
                return True
        elif ev_type == getattr(pygame, 'JOYHATMOTION', -1):
            try:
                _hx, hy = getattr(event, 'value', (0, 0))
                if int(hy) != 0:
                    return True
            except Exception:
                continue
    return False


def _fixed415_poll_small_stick_axes(state) -> bool:
    cfg = state.get('cfg')
    for item in state.get('joys') or []:
        joy = item.get('joy')
        baseline = item.get('baseline') or {}
        try:
            axis_count = int(joy.get_numaxes())
        except Exception:
            continue
        for axis in range(max(0, axis_count)):
            if not _fixed415_axis_is_small_candidate(cfg, axis):
                continue
            try:
                raw = float(joy.get_axis(axis))
                base = float(baseline.get(axis, 0.0))
            except Exception:
                continue
            if _fixed415_axis_moved_forward_enough(cfg, raw, base):
                return True
        try:
            hats = int(joy.get_numhats())
        except Exception:
            hats = 0
        for hat in range(max(0, hats)):
            try:
                _hx, hy = joy.get_hat(hat)
                if int(hy) != 0:
                    return True
            except Exception:
                continue
    return False


def _fixed415_small_stick_forward_pushed(state, events=None) -> bool:
    if not state:
        return False
    pg = state.get('pygame')
    if pg is None:
        return False
    try:
        now_ms = int(pg.time.get_ticks())
    except Exception:
        now_ms = 0
    if now_ms - int(state.get('last_accept_ms', -10000)) < 700:
        return False

    try:
        if events is None:
            pg.event.pump()
        if _fixed415_event_pushed_small_stick(state, events or []):
            state['last_accept_ms'] = now_ms
            return True
    except Exception:
        pass
    try:
        if _fixed415_poll_small_stick_axes(state):
            state['last_accept_ms'] = now_ms
            return True
    except Exception:
        pass
    return False


_fixed414_init_small_stick_continue_state = _fixed415_init_small_stick_continue_state
_fixed414_small_stick_forward_pushed = _fixed415_small_stick_forward_pushed






# ====== FIXED416: require a fresh small-stick push on Method A buttons ======
_FIXED416_METHOD_A_FRESH_SMALL_STICK_BUTTONS_VERSION = 'fixed416_method_a_fresh_small_stick_buttons_v1'


def _fixed416_axis_is_button_candidate(cfg, axis: int) -> bool:
    if bool(getattr(cfg, 'joystick_continue_accept_all_axes', False)):
        return True
    big_x, big_y = _fixed415_method_a_big_axes(cfg)
    return int(axis) not in (big_x, big_y)


def _fixed416_init_small_stick_continue_state(owner):
    try:
        pg = _ensure_pygame()
        try:
            pg.init()
        except Exception:
            pass
        try:
            pg.joystick.init()
        except Exception:
            return None
        count = int(pg.joystick.get_count())
        if count <= 0:
            return None

        cfg = _fixed414_method_a_cfg_for_owner(owner)
        joys = []
        for idx in range(count):
            try:
                joy = pg.joystick.Joystick(idx)
                if not joy.get_init():
                    joy.init()
                axis_count = int(joy.get_numaxes())
                hat_count = int(joy.get_numhats())
                joys.append({
                    'joy': joy,
                    'axis_count': max(0, axis_count),
                    'hat_count': max(0, hat_count),
                    'armed_axes': set(),
                    'armed_hats': set(),
                })
            except Exception:
                continue
        if not joys:
            return None
        try:
            pg.event.pump()
        except Exception:
            pass
        return {
            'pygame': pg,
            'cfg': cfg,
            'joys': joys,
            'last_accept_ms': -10000,
        }
    except Exception:
        return None


def _fixed416_small_stick_forward_pushed(state, events=None) -> bool:
    if not state:
        return False
    pg = state.get('pygame')
    cfg = state.get('cfg')
    if pg is None:
        return False

    try:
        pg.event.pump()
    except Exception:
        pass
    try:
        now_ms = int(pg.time.get_ticks())
    except Exception:
        now_ms = 0
    if now_ms - int(state.get('last_accept_ms', -10000)) < 700:
        return False

    threshold = max(0.25, min(0.95, _fixed414_float(getattr(cfg, 'joystick_small_forward_threshold', 0.45), 0.45)))
    neutral = max(0.08, min(0.40, _fixed414_float(getattr(cfg, 'joystick_small_neutral_threshold', 0.22), 0.22)))

    for item in state.get('joys') or []:
        joy = item.get('joy')
        armed_axes = item.setdefault('armed_axes', set())
        try:
            axis_count = int(item.get('axis_count', joy.get_numaxes()))
        except Exception:
            axis_count = 0
        for axis in range(max(0, axis_count)):
            if not _fixed416_axis_is_button_candidate(cfg, axis):
                continue
            try:
                raw = float(joy.get_axis(axis))
            except Exception:
                continue
            if abs(raw) <= neutral:
                armed_axes.add(axis)
                continue
            if axis in armed_axes and abs(raw) >= threshold:
                armed_axes.discard(axis)
                state['last_accept_ms'] = now_ms
                return True

        armed_hats = item.setdefault('armed_hats', set())
        try:
            hat_count = int(item.get('hat_count', joy.get_numhats()))
        except Exception:
            hat_count = 0
        for hat in range(max(0, hat_count)):
            try:
                hx, hy = joy.get_hat(hat)
            except Exception:
                continue
            if int(hx) == 0 and int(hy) == 0:
                armed_hats.add(hat)
                continue
            if hat in armed_hats and int(hy) != 0:
                armed_hats.discard(hat)
                state['last_accept_ms'] = now_ms
                return True
    return False


_fixed414_init_small_stick_continue_state = _fixed416_init_small_stick_continue_state
_fixed414_small_stick_forward_pushed = _fixed416_small_stick_forward_pushed


def _fixed416_wait_for_method_a_start(self) -> str:
    start_w, start_h = 360, 58
    exit_w, exit_h = 360, 58
    bottom_margin = 16
    side_margin = 16

    exit_rect = pygame.Rect(side_margin, self.cfg.height - bottom_margin - exit_h, exit_w, exit_h)
    start_rect = pygame.Rect(self.cfg.width - side_margin - start_w, self.cfg.height - bottom_margin - start_h, start_w, start_h)

    title_font = pygame.font.SysFont('arial', 22, bold=True)
    btn_font = pygame.font.SysFont('arial', 22, bold=True)
    joy_continue_state = _fixed414_init_small_stick_continue_state(self)

    try:
        joy_axis_event = getattr(pygame, 'JOYAXISMOTION', -1)
        joy_hat_event = getattr(pygame, 'JOYHATMOTION', -1)
        pygame.event.clear((joy_axis_event, joy_hat_event))
    except Exception:
        pass

    while True:
        events = pygame.event.get()
        for event in events:
            if event.type == pygame.QUIT:
                return 'exit'
            if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
                return 'exit'
            if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                if start_rect.collidepoint(event.pos):
                    return 'start'
                if exit_rect.collidepoint(event.pos):
                    return 'exit'

        try:
            if joy_continue_state and _fixed414_small_stick_forward_pushed(joy_continue_state):
                return 'start'
        except Exception:
            pass

        self.draw_background()
        try:
            self.draw_zones()
        except TypeError:
            try:
                self.draw_zones(1)
            except Exception:
                pass

        title = title_font.render('Нажмите кнопку, чтобы начать тестирование', True, self.cfg.text_color)
        self.screen.blit(title, (self.cfg.width // 2 - title.get_width() // 2, 34))

        pygame.draw.rect(self.screen, (88, 204, 99), start_rect)
        pygame.draw.rect(self.screen, (23, 59, 26), start_rect, 2)
        start_text = btn_font.render('Начать тестирование', True, (23, 59, 26))
        self.screen.blit(
            start_text,
            (start_rect.centerx - start_text.get_width() // 2, start_rect.centery - start_text.get_height() // 2)
        )

        pygame.draw.rect(self.screen, (217, 90, 90), exit_rect)
        pygame.draw.rect(self.screen, (255, 255, 255), exit_rect, 2)
        exit_text = btn_font.render('Выход', True, (255, 255, 255))
        self.screen.blit(
            exit_text,
            (exit_rect.centerx - exit_text.get_width() // 2, exit_rect.centery - exit_text.get_height() // 2)
        )

        pygame.display.flip()
        self.clock.tick(60)


_fixed121_wait_for_method_a_start = _fixed416_wait_for_method_a_start


# ====== FIXED417: append/update integrated Excel row after each finished test ======
_FIXED417_INTEGRATED_EXCEL_EXPORT_VERSION = 'fixed417_integrated_excel_login_and_total_rows_v1'
_FIXED417_INTEGRATED_XLSX = 'Integrated Data_methods_tracking_header_final.xlsx'
_FIXED417_DATA_START_ROW = 5


def _fixed417_log_excel_export(base_dir: Path | str, message: str) -> None:
    try:
        data_dir = Path(base_dir) / 'data'
        data_dir.mkdir(parents=True, exist_ok=True)
        log_path = data_dir / 'integrated_excel_export.log'
        stamp = datetime.now().isoformat(timespec='seconds')
        with log_path.open('a', encoding='utf-8') as fh:
            fh.write(f'[{stamp}] {message}\n')
    except Exception:
        pass


def _fixed417_norm_fio(value) -> str:
    return ' '.join(str(value or '').strip().casefold().split())


def _fixed417_float_or_none(value):
    if value in (None, ''):
        return None
    try:
        return float(value)
    except Exception:
        return None


def _fixed417_nested(source, *paths):
    for path in paths:
        cur = source
        ok = True
        for key in path:
            if isinstance(cur, dict) and key in cur:
                cur = cur.get(key)
            else:
                ok = False
                break
        if ok and cur not in (None, ''):
            return cur
    return None


def _fixed417_set_if_value(ws, row: int, col: int, value) -> None:
    if value not in (None, ''):
        ws.cell(row=row, column=col).value = value


def _fixed417_external_excel_path(base_dir: Path | str) -> Path:
    return Path(base_dir) / _FIXED417_INTEGRATED_XLSX


def _fixed417_prepare_excel_file(base_dir: Path | str) -> Path | None:
    path = _fixed417_external_excel_path(base_dir)
    if path.exists():
        return path
    try:
        meipass = getattr(sys, '_MEIPASS', None)
        if meipass:
            bundled = Path(meipass) / _FIXED417_INTEGRATED_XLSX
            if bundled.exists():
                shutil.copy2(bundled, path)
                return path
    except Exception as exc:
        _fixed417_log_excel_export(base_dir, f'Не удалось скопировать шаблон Excel: {exc}')
    return None


def _fixed417_find_or_create_participant_row(ws, fio: str) -> int:
    target = _fixed417_norm_fio(fio)
    for row in range(_FIXED417_DATA_START_ROW, max(ws.max_row, _FIXED417_DATA_START_ROW - 1) + 1):
        if _fixed417_norm_fio(ws.cell(row=row, column=2).value) == target and target:
            return row
    return max(ws.max_row + 1, _FIXED417_DATA_START_ROW)


def _fixed417_position_column(ws) -> int:
    for col in range(1, ws.max_column + 1):
        if _fixed417_norm_fio(ws.cell(row=4, column=col).value) == _fixed417_norm_fio('Должность'):
            return col
    col = ws.max_column + 1
    try:
        from copy import copy
        for row in (1, 2, 3, 4):
            src = ws.cell(row=row, column=7)
            dst = ws.cell(row=row, column=col)
            if src.has_style:
                dst._style = copy(src._style)
            if src.font:
                dst.font = copy(src.font)
            if src.fill:
                dst.fill = copy(src.fill)
            if src.border:
                dst.border = copy(src.border)
            if src.alignment:
                dst.alignment = copy(src.alignment)
    except Exception:
        pass
    ws.cell(row=1, column=col).value = 'Данные формы'
    ws.cell(row=4, column=col).value = 'Должность'
    try:
        ws.column_dimensions[ws.cell(row=1, column=col).column_letter].width = 16
    except Exception:
        pass
    return col


def _fixed417_write_login(ws, row: int, participant: dict) -> None:
    _fixed417_set_if_value(ws, row, 1, row - (_FIXED417_DATA_START_ROW - 1))
    _fixed417_set_if_value(ws, row, 2, participant.get('name'))
    _fixed417_set_if_value(ws, row, 3, participant.get('age'))
    _fixed417_set_if_value(ws, row, 4, participant.get('gender'))
    _fixed417_set_if_value(ws, row, 5, participant.get('flight_hours'))
    _fixed417_set_if_value(ws, row, 6, participant.get('aircraft_type'))
    _fixed417_set_if_value(ws, row, 7, participant.get('education'))
    position = str(participant.get('position', '') or '').strip()
    if position:
        _fixed417_set_if_value(ws, row, _fixed417_position_column(ws), position)


def _fixed417_stage_avg(report: dict) -> dict:
    avg = report.get('second_metrics_avg')
    return avg if isinstance(avg, dict) else {}


def _fixed417_stage_value(report: dict, avg: dict, key: str):
    mapping = {
        'r_x': ((avg, ('x_cm',)), (report, ('avg_abs_x_cm',)), (report, ('mean_abs_xy_cm',))),
        'r_y': ((avg, ('y_cm',)), (report, ('avg_abs_y_cm',))),
        'r_z': ((avg, ('z_deg',)), (report, ('avg_abs_z_deg',)), (report, ('mean_abs_roll_deg',))),
        'goal_x': ((avg, ('goal_x',)), (report, ('r_goal_x_cm',))),
        'goal_y': ((avg, ('goal_y',)), (report, ('r_goal_y_cm',))),
        'goal_z': ((avg, ('goal_z',)), (report, ('r_goal_z_deg',))),
        'crash_x': ((avg, ('crash_x',)), (report, ('r_crash_x_cm',))),
        'crash_y': ((avg, ('crash_y',)), (report, ('r_crash_y_cm',))),
        'crash_z': ((avg, ('crash_z',)), (report, ('r_crash_z_deg',))),
        'vx': ((avg, ('vx',)), (report, ('v_avg_x',))),
        'vy': ((avg, ('vy',)), (report, ('v_avg_y',))),
        'vz': ((avg, ('vz',)), (report, ('v_avg_z',))),
        'v_current': ((avg, ('v_current',)), (report, ('v_avg',))),
        'v_ctrl_x': ((avg, ('v_control_x',)),),
        'v_ctrl_y': ((avg, ('v_control_y',)),),
        'v_ctrl_z': ((avg, ('v_control_z',)),),
        'v_ctrl_total': ((avg, ('v_control_total',)),),
        'lambda_x': ((avg, ('lambda_x',)),),
        'lambda_y': ((avg, ('lambda_y',)),),
        'lambda_z': ((avg, ('lambda_z',)),),
        'lambda_total': ((avg, ('lambda_total',)), (avg, ('lambda_xyz',)), (report, ('_fixed209_lambda_sum',))),
        's_x': ((avg, ('s_x',)), (report, ('y_sigma_x',)), (report, ('_fixed203_y_sigma_x',))),
        's_y': ((avg, ('s_y',)), (report, ('y_sigma_y',)), (report, ('_fixed203_y_sigma_y',))),
        's_z': ((avg, ('s_z',)), (report, ('y_sigma_z',)), (report, ('_fixed203_y_sigma_z',))),
        'y_current': ((avg, ('h_current',)), (report, ('y_tek_window_avg',)), (report, ('y_tek_current',))),
        # Prefer the exact terminal accumulators stored in the stage report.
        # A stage can finish between 0.5-second table rows, so the last table
        # snapshot may lag behind the actual final gamma sum.
        'ys_x': ((report, ('y_sigma_x',)), (report, ('_fixed203_y_sigma_x',)), (avg, ('h_sigma_x',))),
        'ys_y': ((report, ('y_sigma_y',)), (report, ('_fixed203_y_sigma_y',)), (avg, ('h_sigma_y',))),
        'ys_z': ((report, ('y_sigma_z',)), (report, ('_fixed203_y_sigma_z',)), (avg, ('h_sigma_z',))),
        'ys_total': ((report, ('sum_error',)), (avg, ('h_sigma',)), (report, ('y_sigma',))),
        'n': ((report, ('n_real_doc',)), (avg, ('crashes',)), (report, ('crashes',))),
        'y_pred': ((avg, ('y_pred',)), (report, ('error_limit_value',)), (report, ('error_limit_formula_value',))),
        'n_dop': ((avg, ('n_dop_t',)), (report, ('crash_limit_doc',)), (report, ('crash_limit_doc_180',))),
    }
    for source, path in mapping.get(key, ()):
        value = _fixed417_nested(source, path)
        if value not in (None, ''):
            num = _fixed417_float_or_none(value)
            return num if num is not None else value
    return None


def _fixed417_write_method_a(ws, row: int, payload: dict) -> None:
    reports = payload.get('reports') if isinstance(payload.get('reports'), list) else []
    by_stage = {}
    for report in reports:
        if isinstance(report, dict):
            try:
                by_stage[int(report.get('stage_no', 0) or 0)] = report
            except Exception:
                pass
    keys = [
        'r_x', 'r_y', 'r_z', 'goal_x', 'goal_y', 'goal_z', 'crash_x', 'crash_y', 'crash_z',
        'vx', 'vy', 'vz', 'v_current', 'v_ctrl_x', 'v_ctrl_y', 'v_ctrl_z', 'v_ctrl_total',
        'lambda_x', 'lambda_y', 'lambda_z', 'lambda_total', 's_x', 's_y', 's_z',
        'y_current', 'ys_x', 'ys_y', 'ys_z', 'ys_total', 'n', 'y_pred', 'n_dop',
    ]
    for stage_no, start_col in ((1, 8), (2, 40), (3, 72)):
        report = by_stage.get(stage_no)
        if not report:
            continue
        avg = _fixed417_stage_avg(report)
        for offset, key in enumerate(keys):
            _fixed417_set_if_value(ws, row, start_col + offset, _fixed417_stage_value(report, avg, key))


def _fixed417_write_method_b(ws, row: int, payload: dict) -> None:
    summary = payload.get('summary') if isinstance(payload.get('summary'), dict) else {}
    t_values = summary.get('t_values') if isinstance(summary.get('t_values'), dict) else {}
    by_n = summary.get('by_n') if isinstance(summary.get('by_n'), dict) else {}
    for n in range(1, 17):
        value = t_values.get(str(n), t_values.get(n))
        if value in (None, '') and isinstance(by_n.get(str(n), by_n.get(n)), dict):
            item = by_n.get(str(n), by_n.get(n))
            value = item.get('t_value', item.get('t'))
        _fixed417_set_if_value(ws, row, 103 + n, _fixed417_float_or_none(value))


def _fixed417_write_method_c(ws, row: int, payload: dict) -> None:
    summary = payload.get('summary') if isinstance(payload.get('summary'), dict) else {}
    stages = summary.get('stages') if isinstance(summary.get('stages'), dict) else {}
    for idx, key in enumerate(('1', '2', '3'), start=120):
        value = None
        item = stages.get(key, stages.get(int(key)))
        if isinstance(item, dict):
            value = item.get('t_value')
        if value in (None, ''):
            value = summary.get({120: 'tmin_c', 121: 'tmedio_c', 122: 'tmax_c'}[idx])
        _fixed417_set_if_value(ws, row, idx, _fixed417_float_or_none(value))


def _fixed417_write_method_d(ws, row: int, payload: dict) -> None:
    summary = payload.get('summary') if isinstance(payload.get('summary'), dict) else {}
    groups = summary.get('groups') if isinstance(summary.get('groups'), dict) else {}
    for col, key, fallback in ((123, 'min', 'tmin_d'), (124, 'medio', 'tmedio_d'), (125, 'max', 'tmax_d')):
        value = None
        item = groups.get(key)
        if isinstance(item, dict):
            value = item.get('t_value')
        if value in (None, ''):
            value = summary.get(fallback)
        _fixed417_set_if_value(ws, row, col, _fixed417_float_or_none(value))


def _fixed417_export_payload_to_integrated_excel(base_dir: Path | str, payload: dict) -> None:
    if not isinstance(payload, dict):
        return
    participant = payload.get('participant') if isinstance(payload.get('participant'), dict) else {}
    fio = str(participant.get('name', '') or '').strip()
    if not fio:
        return
    path = _fixed417_prepare_excel_file(base_dir)
    if path is None:
        _fixed417_log_excel_export(base_dir, f'Excel-файл не найден: {_FIXED417_INTEGRATED_XLSX}')
        return

    try:
        import openpyxl
        wb = openpyxl.load_workbook(path)
        ws = wb.active
        row = _fixed417_find_or_create_participant_row(ws, fio)
        _fixed417_write_login(ws, row, participant)
        code = str(payload.get('test_code', '') or '').upper()
        if code == 'A':
            _fixed417_write_method_a(ws, row, payload)
        elif code == 'B':
            _fixed417_write_method_b(ws, row, payload)
        elif code == 'C':
            _fixed417_write_method_c(ws, row, payload)
        elif code == 'D':
            _fixed417_write_method_d(ws, row, payload)
        wb.save(path)
        _fixed417_log_excel_export(base_dir, f'OK: {fio}, тест {code}, строка {row}, файл {path.name}')
    except PermissionError:
        _fixed417_log_excel_export(base_dir, f'Ошибка: Excel-файл открыт или недоступен для записи: {path}')
    except Exception as exc:
        _fixed417_log_excel_export(base_dir, f'Ошибка экспорта Excel для {fio}: {type(exc).__name__}: {exc}')


def _fixed417_payloads_from_progress_record(record: dict) -> list[dict]:
    if not isinstance(record, dict):
        return []
    results = record.get('results') if isinstance(record.get('results'), dict) else {}
    payloads = []
    for code in TEST_ORDER:
        payload = results.get(code)
        if not isinstance(payload, dict):
            continue
        enriched = dict(payload)
        enriched['test_code'] = str(enriched.get('test_code') or code).upper()
        participant = dict(enriched.get('participant') if isinstance(enriched.get('participant'), dict) else {})
        for key in ('name', 'age', 'gender', 'flight_hours', 'aircraft_type', 'education', 'position'):
            if participant.get(key) in (None, '') and record.get(key) not in (None, ''):
                participant[key] = record.get(key)
        enriched['participant'] = participant
        payloads.append(enriched)
    return payloads


def _fixed417_delete_records_from_integrated_excel(base_dir: Path | str, records: list[dict]) -> int:
    identities = []
    for record in records or []:
        if not isinstance(record, dict):
            continue
        name = _fixed417_norm_fio(record.get('name'))
        age = str(record.get('age', '') or '').strip()
        gender = _fixed417_norm_fio(record.get('gender'))
        if name:
            identities.append((name, age, gender))
        for payload in _fixed417_payloads_from_progress_record(record):
            participant = payload.get('participant') if isinstance(payload.get('participant'), dict) else {}
            p_name = _fixed417_norm_fio(participant.get('name'))
            p_age = str(participant.get('age', '') or '').strip()
            p_gender = _fixed417_norm_fio(participant.get('gender'))
            if p_name:
                identities.append((p_name, p_age, p_gender))
    identities = list(dict.fromkeys(identities))
    if not identities:
        return 0

    path = _fixed417_external_excel_path(base_dir)
    if not path.exists():
        return 0
    try:
        import openpyxl
        wb = openpyxl.load_workbook(path)
        ws = wb.active
        rows_to_delete = []
        for row in range(_FIXED417_DATA_START_ROW, ws.max_row + 1):
            row_name = _fixed417_norm_fio(ws.cell(row=row, column=2).value)
            row_age = str(ws.cell(row=row, column=3).value or '').strip()
            row_gender = _fixed417_norm_fio(ws.cell(row=row, column=4).value)
            for name, age, gender in identities:
                if row_name != name:
                    continue
                if age and row_age and row_age != age:
                    continue
                if gender and row_gender and row_gender != gender:
                    continue
                rows_to_delete.append(row)
                break
        for row in sorted(set(rows_to_delete), reverse=True):
            ws.delete_rows(row, 1)
        if rows_to_delete:
            for row in range(_FIXED417_DATA_START_ROW, ws.max_row + 1):
                ws.cell(row=row, column=1).value = row - (_FIXED417_DATA_START_ROW - 1)
            wb.save(path)
            _fixed417_log_excel_export(base_dir, f'Удалено строк integrateddata: {len(set(rows_to_delete))}')
        return len(set(rows_to_delete))
    except PermissionError:
        _fixed417_log_excel_export(base_dir, f'Ошибка: Excel-файл открыт или недоступен для удаления строк: {path}')
    except Exception as exc:
        _fixed417_log_excel_export(base_dir, f'Ошибка удаления строк Excel: {type(exc).__name__}: {exc}')
    return 0


