# ====== FIXED414: Method B vector scene; matrix and tray drawn on one canvas ======
_FIXED414_METHOD_B_VECTOR_VERSION = 'fixed414_method_b_vector_scene_v1'


def _fixed416_method_b_random_tray_order(shapes) -> list[int]:
    items = list(shapes or [])
    if len(items) <= 1:
        return items
    original = list(items)
    for _ in range(12):
        random.shuffle(items)
        if items != original:
            return items
    return items[1:] + items[:1]


def _fixed414_method_b_make_button(parent, text, command, bg, active, fg, font, width, padx, pady):
    btn = tk.Button(
        parent,
        text=text,
        command=command,
        bg=bg,
        activebackground=active,
        fg=fg,
        font=font,
        width=width,
        padx=padx,
        pady=pady,
        bd=3,
        relief='raised',
        cursor='hand2',
        highlightthickness=1,
        highlightbackground='#000000',
        highlightcolor='#000000',
    )
    try:
        _fixed169_method_c_make_pressable(btn)
    except Exception:
        pass
    return btn


def _fixed414_method_b_refresh_controls(self):
    clear_btn = getattr(self, '_method_b_clear_btn', None)
    next_btn = getattr(self, '_method_b_next_btn', None)
    phase = str(getattr(self, 'phase', 'idle') or 'idle')
    started = bool(getattr(self, '_method_b_started', False))

    if clear_btn is not None:
        try:
            clear_btn.configure(
                state='normal' if phase == 'reproduce' else 'disabled',
                command=self._clear_placements,
            )
        except Exception:
            pass

    if next_btn is not None:
        state = 'normal' if started and phase in ('preview_wait_next', 'reproduce') else 'disabled'
        try:
            next_btn.configure(state=state, command=self._submit_cycle)
        except Exception:
            pass


def _fixed414_method_b_start_cycle(self):
    _fixed414_method_b_prepare_preview_cycle(self, started=bool(getattr(self, '_method_b_started', False)))


def _fixed414_method_b_used_shapes(self):
    placements = getattr(self, 'placements', {})
    return set(placements.values()) if isinstance(placements, dict) else set()


def _fixed414_method_b_build_ui(self):
    self.win = tk.Toplevel(self.parent)
    self.win.title('СПР - Тест B')
    self.win.configure(bg=PDF_TURQUOISE_BG)
    self.win.transient(self.parent)
    self.win.grab_set()
    try:
        self.win.attributes('-fullscreen', True)
    except tk.TclError:
        self.win.geometry(f"{self.parent.winfo_screenwidth()}x{self.parent.winfo_screenheight()}+0+0")
    self.win.bind('<Escape>', lambda _e: self._abort())
    self.win.protocol('WM_DELETE_WINDOW', self._abort)
    try:
        self.win.lift()
        self.win.focus_force()
    except Exception:
        pass

    sw, sh, scale = _fixed88_screen_metrics(self.win)
    self._method_b_started = False
    self._b414_tray_visible = False
    self._b414_geom = {}
    self.grid_cells = []
    self.tray_cells = []
    self.all_tray_shapes = []
    self.drag_shape = None
    self.drag_preview = None
    self._drag_motion_bind = None
    self._drag_release_bind = None

    self.win.grid_columnconfigure(0, weight=1)
    self.win.grid_rowconfigure(0, weight=1)

    shell = tk.Frame(self.win, bg=PDF_TURQUOISE_BG)
    shell.grid(row=0, column=0, sticky='nsew')
    shell.grid_columnconfigure(0, weight=0)
    shell.grid_columnconfigure(1, weight=1)
    shell.grid_columnconfigure(2, weight=0)
    shell.grid_columnconfigure(3, weight=1)
    shell.grid_rowconfigure(0, weight=1)
    shell.grid_rowconfigure(1, weight=0)

    time_w = max(96, int(104 * scale))
    time_gap = max(18, int(22 * scale))
    left_margin = max(8, int(12 * scale))

    self._time_col = tk.Frame(shell, bg=PDF_TURQUOISE_BG)
    self._time_col.grid(row=0, column=0, sticky='nw', padx=(left_margin, time_gap), pady=(max(12, int(18 * scale)), 0))
    self.time_bar_canvas = tk.Canvas(
        self._time_col,
        width=time_w,
        height=max(250, int(sh * 0.54)),
        bg=PDF_TURQUOISE_BG,
        highlightthickness=0,
        bd=0,
    )
    self.time_bar_canvas.pack(anchor='n')
    self.task_bar_canvas = None
    self._time_col.grid_remove()

    main = tk.Frame(shell, bg=PDF_TURQUOISE_BG)
    main.grid(row=0, column=2, sticky='n', pady=(max(28, int(48 * scale)), 0))

    self.method_b_scene = tk.Canvas(
        main,
        width=720,
        height=720,
        bg=PDF_TURQUOISE_BG,
        highlightthickness=0,
        bd=0,
        cursor='arrow',
    )
    self.method_b_scene.pack()
    self.method_b_scene.bind('<Button-1>', lambda event: _fixed414_method_b_on_scene_click(self, event))

    btn_font = ('Arial', max(14, int(17 * scale)), 'bold')
    shared_btn_w = 15
    side_btn_w = max(9, int(shared_btn_w * 0.58))
    shared_padx = max(12, int(14 * scale))
    shared_pady = max(7, int(8 * scale))

    action_row = tk.Frame(main, bg=PDF_TURQUOISE_BG)
    action_row.pack(pady=(max(8, int(10 * scale)), 0))
    action_row.grid_columnconfigure(0, weight=1, uniform='b414_actions')
    action_row.grid_columnconfigure(1, weight=1, uniform='b414_actions')
    self._method_b_action_row = action_row

    self._method_b_clear_btn = _fixed414_method_b_make_button(
        action_row,
        'Отмена',
        self._clear_placements,
        '#f2d64b',
        '#e3c12d',
        '#4f3900',
        btn_font,
        side_btn_w,
        shared_padx,
        shared_pady,
    )
    self._method_b_clear_btn.grid(row=0, column=0, sticky='w', padx=(0, max(22, int(26 * scale))), pady=4)

    self._method_b_next_btn = _fixed414_method_b_make_button(
        action_row,
        'Далее',
        self._submit_cycle,
        '#58cc63',
        '#43b84f',
        '#173b1a',
        btn_font,
        side_btn_w,
        shared_padx,
        shared_pady,
    )
    self._method_b_next_btn.grid(row=0, column=1, sticky='e', padx=(max(22, int(26 * scale)), 0), pady=4)

    footer = tk.Frame(shell, bg=PDF_TURQUOISE_BG)
    footer.grid(row=1, column=0, columnspan=4, sticky='ew', pady=(max(10, int(12 * scale)), max(18, int(24 * scale))))
    footer.grid_columnconfigure(0, weight=1)
    footer.grid_columnconfigure(1, weight=1)

    self.exit_btn = _fixed414_method_b_make_button(
        footer,
        'Выход',
        self._abort,
        '#d95a5a',
        '#c44d4d',
        'white',
        btn_font,
        shared_btn_w,
        shared_padx,
        shared_pady,
    )
    self.exit_btn.grid(row=0, column=0, sticky='w', padx=(16, 0))

    self.start_btn = _fixed414_method_b_make_button(
        footer,
        'Начать тестирование',
        lambda: None,
        '#58cc63',
        '#43b84f',
        '#173b1a',
        btn_font,
        shared_btn_w,
        shared_padx,
        shared_pady,
    )
    self.start_btn.grid(row=0, column=1, sticky='e', padx=(0, 16))

    self.win._tpr_footer_button_style = {
        'font': btn_font,
        'width': shared_btn_w,
        'padx': shared_padx,
        'pady': shared_pady,
    }

    self.message_var.set('')
    self.selection_var.set('')
    _fixed414_method_b_layout_scene(self)
    try:
        _fixed74_method_b_update_hud(self)
    except Exception:
        pass
    _fixed414_method_b_refresh_controls(self)


def _fixed414_method_b_layout_scene(self):
    canvas = getattr(self, 'method_b_scene', None)
    if canvas is None:
        return {}
    sw, sh, scale = _fixed88_screen_metrics(getattr(self, 'win', self.parent))
    time_w = max(96, int(104 * scale))
    usable_w = max(640, sw - time_w - max(190, int(sw * 0.18)))
    top_pad = max(28, int(48 * scale))
    grid_size = int(getattr(self.cfg, 'grid_size', 4) or 4)

    all_items = list(getattr(self, 'all_tray_shapes', []) or getattr(self, 'current_shapes', []))
    if not all_items:
        n = max(1, min(int(getattr(self.cfg, 'max_items', 5) or 5), int(getattr(self, 'current_n', 1) or 1)))
        ordered_shapes = [s for s in _FIXED71_SHAPE_ORDER if s < len(BASIC_SYMBOLS)]
        all_items = ordered_shapes[:n]
    action_h = 72
    footer_h = max(78, int(88 * scale))
    usable_h = max(330, sh - top_pad - action_h - footer_h - max(18, int(24 * scale)))
    tray_gap_y = max(14, int(18 * scale))

    cell_gap_ratio = 0.075
    tray_pad = max(12, int(16 * scale))
    slot_count = max(1, len(all_items))
    max_tray_items = max(slot_count, int(getattr(self.cfg, 'max_items', slot_count) or slot_count))
    layout_tray_rows = 2 if max_tray_items > 8 else 1
    layout_tray_cols = max(1, min(8, max_tray_items if layout_tray_rows == 1 else int(math.ceil(max_tray_items / 2))))
    layout_height_units = (
        grid_size
        + layout_tray_rows
        + (grid_size - 1 + max(0, layout_tray_rows - 1)) * cell_gap_ratio
    )
    cell_by_width = min(
        usable_w / max(1, grid_size + 1.4),
        (usable_w - 2 * tray_pad - max(0, layout_tray_cols - 1) * 8) / max(1, layout_tray_cols),
    )
    cell_by_height = (usable_h - tray_gap_y - 2 * tray_pad) / max(1.0, layout_height_units)
    cell = int(min(150, max(52, min(cell_by_width, cell_by_height))))
    gap = max(6, int(cell * cell_gap_ratio))

    tray_gap = gap
    tray_rows = 1 if slot_count <= 8 else 2
    tray_cols = slot_count if tray_rows == 1 else int(math.ceil(slot_count / 2))
    matrix_w = grid_size * cell + (grid_size - 1) * gap
    matrix_h = grid_size * cell + (grid_size - 1) * gap
    tray_slot = cell
    tray_w = tray_cols * tray_slot + max(0, tray_cols - 1) * tray_gap + 2 * tray_pad
    tray_h = tray_rows * tray_slot + max(0, tray_rows - 1) * tray_gap + 2 * tray_pad

    scene_w = max(matrix_w, tray_w) + max(30, int(36 * scale))
    scene_h = matrix_h + tray_gap_y + tray_h
    scene_w = int(min(max(scene_w, 450), max(500, usable_w)))
    scene_h = int(min(max(scene_h, 330), max(330, usable_h)))

    matrix_x = int((scene_w - matrix_w) / 2)
    matrix_y = max(4, int((scene_h - (matrix_h + tray_gap_y + tray_h)) / 2))
    tray_x = int((scene_w - tray_w) / 2)
    tray_y = matrix_y + matrix_h + tray_gap_y

    self._matrix_cell_size = cell
    self._tray_cell_size = tray_slot
    self._method_b_matrix_total_w = matrix_w
    self._matrix_symbol_scale = max(1.05, min(1.78, 1.56 * (cell / 156.0)))
    self._tray_symbol_scale = self._matrix_symbol_scale
    self._matrix_symbol_margin = max(7, int(cell * 0.09))
    self._tray_symbol_margin = max(7, int(tray_slot * 0.09))

    geom = {
        'cell': cell,
        'gap': gap,
        'grid_size': grid_size,
        'matrix_w': matrix_w,
        'matrix_h': matrix_h,
        'matrix_x': matrix_x,
        'matrix_y': matrix_y,
        'tray_slot': tray_slot,
        'tray_gap': tray_gap,
        'tray_gap_y': tray_gap_y,
        'tray_cols': tray_cols,
        'tray_rows': tray_rows,
        'tray_pad': tray_pad,
        'tray_w': tray_w,
        'tray_h': tray_h,
        'tray_x': tray_x,
        'tray_y': tray_y,
        'scene_w': scene_w,
        'scene_h': scene_h,
        'tray_items': list(all_items),
    }
    self._b414_geom = geom
    try:
        canvas.configure(width=scene_w, height=scene_h)
    except Exception:
        pass
    row = getattr(self, '_method_b_action_row', None)
    if row is not None:
        try:
            clear_btn = getattr(self, '_method_b_clear_btn', None)
            next_btn = getattr(self, '_method_b_next_btn', None)
            button_h = 72
            for btn in (clear_btn, next_btn):
                if btn is not None:
                    try:
                        button_h = max(button_h, int(btn.winfo_reqheight()) + 16)
                    except Exception:
                        pass
            row.configure(width=scene_w, height=button_h)
            row.grid_propagate(False)
            row.pack_propagate(False)
        except Exception:
            pass
    return geom


def _fixed414_method_b_cell_bbox(self, idx: int, geom: dict | None = None):
    geom = geom or getattr(self, '_b414_geom', {}) or _fixed414_method_b_layout_scene(self)
    grid_size = int(geom.get('grid_size', 4))
    cell = int(geom.get('cell', 100))
    gap = int(geom.get('gap', 8))
    row, col = divmod(int(idx), grid_size)
    x1 = int(geom.get('matrix_x', 0)) + col * (cell + gap)
    y1 = int(geom.get('matrix_y', 0)) + row * (cell + gap)
    return x1, y1, x1 + cell, y1 + cell


def _fixed414_method_b_find_cell(self, x: int, y: int):
    geom = getattr(self, '_b414_geom', {}) or _fixed414_method_b_layout_scene(self)
    grid_size = int(geom.get('grid_size', 4))
    for idx in range(grid_size * grid_size):
        x1, y1, x2, y2 = _fixed414_method_b_cell_bbox(self, idx, geom)
        if x1 <= x <= x2 and y1 <= y <= y2:
            return idx
    return None


def _fixed414_method_b_find_tray_shape(self, x: int, y: int):
    geom = getattr(self, '_b414_geom', {}) or _fixed414_method_b_layout_scene(self)
    if not getattr(self, '_b414_tray_visible', False):
        return None
    slot = int(geom.get('tray_slot', 72))
    gap = int(geom.get('tray_gap', 5))
    tray_pad = int(geom.get('tray_pad', 12))
    tray_cols = max(1, int(geom.get('tray_cols', 1)))
    tray_x = int(geom.get('tray_x', 0)) + tray_pad
    tray_y = int(geom.get('tray_y', 0)) + tray_pad
    used = _fixed414_method_b_used_shapes(self)
    tray_items = list(geom.get('tray_items', []))
    for pos, shape in enumerate(tray_items):
        row, col = divmod(pos, tray_cols)
        row_count = min(tray_cols, max(0, len(tray_items) - row * tray_cols))
        row_w = row_count * slot + max(0, row_count - 1) * gap
        row_x = tray_x + int((int(geom.get('tray_w', row_w + 2 * tray_pad)) - 2 * tray_pad - row_w) / 2)
        x1 = row_x + col * (slot + gap)
        y1 = tray_y + row * (slot + gap)
        if x1 <= x <= x1 + slot and y1 <= y <= y1 + slot and shape not in used:
            return shape
    return None


def _fixed414_method_b_on_scene_click(self, event):
    if str(getattr(self, 'phase', '') or '') != 'reproduce':
        return 'break'
    shape = _fixed414_method_b_find_tray_shape(self, int(event.x), int(event.y))
    if shape is not None:
        return _fixed302_method_b_pick_shape(self, shape)
    cell_idx = _fixed414_method_b_find_cell(self, int(event.x), int(event.y))
    if cell_idx is not None:
        self._on_matrix_cell(cell_idx)
        return 'break'
    return 'break'


def _fixed414_draw_method_b_symbol(canvas: tk.Canvas, x1: int, y1: int, x2: int, y2: int, shape_id: int,
                                   fill: str = '#5a2323', outline: str = '#5a2323',
                                   scale: float = 1.0, tag: str | None = None):
    sid = int(shape_id) % len(BASIC_SYMBOLS)
    tag = tag or f'b414_symbol_{shape_id}_{x1}_{y1}'
    cx = (x1 + x2) / 2
    cy = (y1 + y2) / 2
    if sid == 6:
        size = min(x2 - x1, y2 - y1) * 0.28 * float(scale)
        line_width = max(8, int(size * 0.34))
        cap = max(2, int(line_width * 0.38))
        canvas.create_line(cx - size, cy - size, cx + size, cy + size, fill=outline, width=line_width, tags=(tag, 'symbol'))
        canvas.create_line(cx - size, cy + size, cx + size, cy - size, fill=outline, width=line_width, tags=(tag, 'symbol'))
        for px, py in (
            (cx - size, cy - size), (cx + size, cy + size),
            (cx - size, cy + size), (cx + size, cy - size),
        ):
            canvas.create_oval(px - cap, py - cap, px + cap, py + cap, outline='', fill=outline, tags=(tag, 'symbol'))
        return

    draw_basic_symbol(canvas, x1, y1, x2, y2, shape_id, fill=fill, outline=outline, tag=tag)
    if abs(float(scale) - 1.0) > 1e-6:
        try:
            canvas.scale(tag, cx, cy, float(scale), float(scale))
        except Exception:
            pass
    try:
        canvas.addtag_withtag('symbol', tag)
    except Exception:
        pass


def _fixed414_method_b_draw_scene(self, mode: str, show_tray: bool | None = None):
    canvas = getattr(self, 'method_b_scene', None)
    if canvas is None:
        return
    if show_tray is not None:
        self._b414_tray_visible = bool(show_tray)
    geom = _fixed414_method_b_layout_scene(self)
    canvas.delete('all')

    grid_size = int(geom.get('grid_size', 4))
    cell = int(geom.get('cell', 100))
    pad = max(5, int(cell * 0.055))
    margin = max(8, int(geom.get('cell', 100) * 0.10))
    base_scale = float(getattr(self, '_matrix_symbol_scale', 1.36))

    for idx in range(grid_size * grid_size):
        x1, y1, x2, y2 = _fixed414_method_b_cell_bbox(self, idx, geom)
        canvas.create_rectangle(x1, y1, x2, y2, outline='#8f958f', fill='#f7f7f7', width=1)
        canvas.create_rectangle(x1 + pad, y1 + pad, x2 - pad, y2 - pad, outline='#2b2b2b', fill='#ffffff', width=2)
        shape = None
        if mode == 'memory' and idx in getattr(self, 'current_positions', []):
            shape = self.current_shapes[self.current_positions.index(idx)]
        elif mode == 'reproduce' and idx in getattr(self, 'placements', {}):
            shape = self.placements[idx]
        if shape is not None:
            _fixed414_draw_method_b_symbol(
                canvas,
                x1 + margin,
                y1 + margin,
                x2 - margin,
                y2 - margin,
                shape,
                fill='#5a2323',
                outline='#5a2323',
                scale=_fixed186_method_b_shape_scale(shape, base_scale),
                tag=f'b414_matrix_symbol_{idx}',
            )

    if not getattr(self, '_b414_tray_visible', False):
        return

    all_items = list(geom.get('tray_items', []))
    if not all_items:
        return
    used = _fixed414_method_b_used_shapes(self)
    slot = int(geom.get('tray_slot', 72))
    gap = int(geom.get('tray_gap', 5))
    tray_pad = int(geom.get('tray_pad', 12))
    tray_cols = max(1, int(geom.get('tray_cols', 1)))
    tray_x = int(geom.get('tray_x', 0))
    tray_y = int(geom.get('tray_y', 0))
    tray_w = int(geom.get('tray_w', slot + 20))
    tray_h = int(geom.get('tray_h', slot + 20))
    canvas.create_rectangle(tray_x, tray_y, tray_x + tray_w, tray_y + tray_h, outline='#aeb4bb', fill='#ffffff', width=2)

    margin = int(getattr(self, '_tray_symbol_margin', max(6, int(slot * 0.09))))
    base_scale = float(getattr(self, '_tray_symbol_scale', getattr(self, '_matrix_symbol_scale', 1.18)))
    visible_shapes = []
    for pos, shape in enumerate(all_items):
        row, col = divmod(pos, tray_cols)
        row_count = min(tray_cols, max(0, len(all_items) - row * tray_cols))
        row_w = row_count * slot + max(0, row_count - 1) * gap
        row_x = tray_x + tray_pad + int((tray_w - 2 * tray_pad - row_w) / 2)
        x1 = row_x + col * (slot + gap)
        y1 = tray_y + tray_pad + row * (slot + gap)
        shape_used = shape in used
        is_selected = (shape == getattr(self, 'selected_shape', None)) and not shape_used
        fill = '#fff5d7' if is_selected else ('#f7f9fb' if shape_used else '#ffffff')
        outline = '#000000' if is_selected else '#c5ced8'
        canvas.create_rectangle(x1, y1, x1 + slot, y1 + slot, outline=outline, fill=fill, width=2 if is_selected else 1)
        if shape_used:
            canvas.create_rectangle(
                x1 + margin,
                y1 + margin,
                x1 + slot - margin,
                y1 + slot - margin,
                outline='#e1e6ec',
                fill='#f7f9fb',
                width=1,
            )
            continue
        visible_shapes.append(shape)
        _fixed414_draw_method_b_symbol(
            canvas,
            x1 + margin,
            y1 + margin,
            x1 + slot - margin,
            y1 + slot - margin,
            shape,
            fill='#5a2323',
            outline='#5a2323',
            scale=_fixed186_method_b_shape_scale(shape, base_scale),
            tag=f'b414_tray_symbol_{shape}',
        )

    if getattr(self, 'phase', '') == 'reproduce':
        if self.selected_shape is not None and self.selected_shape in visible_shapes:
            self.selection_var.set('Выбрана фигура. Нажмите на нужную ячейку матрицы.')
        elif visible_shapes:
            self.selection_var.set('Выберите фигуру снизу и поставьте её в нужную ячейку.')
        else:
            self.selection_var.set('Все фигуры размещены. Нажмите «Далее».')


def _fixed414_method_b_draw_memory_matrix(self):
    self._b414_tray_visible = False
    _fixed414_method_b_draw_scene(self, 'memory', show_tray=False)


def _fixed414_method_b_draw_reproduction_matrix(self):
    _fixed414_method_b_draw_scene(self, 'reproduce')


def _fixed414_method_b_draw_tray(self, show=True):
    self._b414_tray_visible = bool(show)
    phase = str(getattr(self, 'phase', '') or '')
    if not show and phase in ('preview', 'preview_wait_next', 'memorize'):
        return
    mode = 'memory' if phase in ('preview', 'preview_wait_next', 'memorize') else 'reproduce'
    _fixed414_method_b_draw_scene(self, mode, show_tray=bool(show))


def _fixed414_method_b_hide_tray_panel(self):
    self._b414_tray_visible = False
    if getattr(self, 'phase', '') == 'reproduce':
        _fixed414_method_b_draw_scene(self, 'reproduce', show_tray=False)


def _fixed414_method_b_show_tray_panel(self):
    self._b414_tray_visible = True
    if getattr(self, 'phase', '') == 'reproduce':
        _fixed414_method_b_draw_scene(self, 'reproduce', show_tray=True)


def _fixed414_method_b_prepare_preview_cycle(self, started: bool):
    n = max(1, min(self.cfg.max_items, int(getattr(self, 'current_n', 1) or 1)))
    self.current_positions = _fixed389_balanced_method_b_positions(self.cfg.grid_size, n)
    ordered_shapes = [s for s in _FIXED71_SHAPE_ORDER if s < len(BASIC_SYMBOLS)]
    self.current_shapes = ordered_shapes[:n]
    self.all_tray_shapes = _fixed416_method_b_random_tray_order(self.current_shapes)
    self.placements = {}
    self.available_shapes = list(self.current_shapes)
    self.selected_shape = None
    self.phase = 'preview_wait_next' if started else 'preview'
    self.cycle_started_at = 0.0
    self.message_var.set('')
    self.selection_var.set('')
    self._draw_memory_matrix()
    self._draw_tray(show=False)
    _fixed414_method_b_hide_tray_panel(self)
    try:
        self._update_info_label()
    except Exception:
        pass
    _fixed414_method_b_refresh_controls(self)


def _fixed414_method_b_start_reproduction_phase(self):
    if not self.win or not self.win.winfo_exists():
        return
    self._cancel_afters()
    self.phase = 'reproduce'
    self.cycle_started_at = time.perf_counter()
    if sorted(getattr(self, 'all_tray_shapes', [])) != sorted(getattr(self, 'current_shapes', [])):
        self.all_tray_shapes = _fixed416_method_b_random_tray_order(self.current_shapes)
    self.available_shapes = list(self.current_shapes)
    self.selected_shape = None
    self.reproduction_deadline = 0.0
    self.message_var.set('')
    self.selection_var.set('Сначала кликните фигуру в кассе, затем кликните по свободной ячейке матрицы.')
    _fixed414_method_b_show_tray_panel(self)
    self._draw_reproduction_matrix()
    self._draw_tray(show=True)
    _fixed414_method_b_refresh_controls(self)
    if self._time_left_total() <= 0.05:
        self._finish()
        return
    self._track_after(self.win.after(120, self._fixed193_total_guard_tick))


