def _fixed416_method_b_total_guard_tick(self):
    if not self.win or not self.win.winfo_exists():
        return
    if self._time_left_total() <= 0.05:
        self._finish()
        return
    try:
        _fixed74_method_b_update_hud(self)
    except Exception:
        pass
    self._track_after(self.win.after(200, self._fixed193_total_guard_tick))


def _fixed416_method_b_smooth_timer_tick(self):
    if not self.win or not self.win.winfo_exists():
        return
    if bool(getattr(self, '_method_b_started', False)) and self._time_left_total() <= 0.05:
        self._fixed197_smooth_after_id = None
        self._finish()
        return
    try:
        _fixed74_method_b_update_hud(self)
    except Exception:
        pass
    if str(getattr(self, 'phase', '') or '') == 'finished':
        self._fixed197_smooth_after_id = None
        return
    try:
        self._fixed197_smooth_after_id = self.win.after(100, self._fixed197_smooth_timer_tick)
    except Exception:
        self._fixed197_smooth_after_id = None


