# ====== FIXED416: research tabs match the current visual style ======
def _fixed416_research_tab_scale(self):
    try:
        width = max(int(self.root.winfo_width() or self.root.winfo_screenwidth()), 960)
        height = max(int(self.root.winfo_height() or self.root.winfo_screenheight()), 680)
        return max(0.70, min(min(width / BASE_W, height / BASE_H), 1.15))
    except Exception:
        return 1.0


def _fixed416_sync_research_custom_tabs(self):
    tabs = getattr(self, 'research_tabs', None)
    items = getattr(self, '_fixed416_research_tab_items', [])
    if tabs is None or not items:
        return
    try:
        tab_ids = list(tabs.tabs())
        selected_id = tabs.select()
        selected_index = tab_ids.index(selected_id) if selected_id in tab_ids else 0
        scale = _fixed416_research_tab_scale(self)
        active_font = ('Arial', max(12, int(14 * scale)), 'bold')
        inactive_font = ('Arial', max(11, int(13 * scale)), 'bold')
        active_bg = '#d9d2a9'
        inactive_bg = PANEL_COLOR
        active_border = '#776f4d'
        inactive_border = '#9f9873'

        for index, item in enumerate(items):
            active = index == selected_index
            item['wrap'].pack_configure(
                anchor='s',
                pady=(0, 0) if active else (max(5, int(7 * scale)), 0),
            )
            item['label'].configure(
                bg=active_bg if active else inactive_bg,
                fg=TITLE_COLOR if active else TEXT_COLOR,
                font=active_font if active else inactive_font,
                padx=max(20, int((24 if active else 20) * scale)),
                pady=max(8, int((10 if active else 7) * scale)),
                bd=2 if active else 1,
                highlightbackground=active_border if active else inactive_border,
                highlightcolor=active_border if active else inactive_border,
                relief='raised' if active else 'solid',
            )
    except Exception:
        pass


def _fixed416_style_research_tabs(self):
    tabs = getattr(self, 'research_tabs', None)
    if tabs is None:
        return
    try:
        scale = _fixed416_research_tab_scale(self)
        style = ttk.Style(self.root)
        try:
            if style.theme_use() != 'clam':
                style.theme_use('clam')
        except Exception:
            pass
        style.configure(
            'ResearchHidden.TNotebook',
            background=BG_COLOR,
            borderwidth=0,
            tabmargins=(0, 0, 0, 0),
        )
        try:
            style.layout('ResearchHidden.TNotebook.Tab', [])
        except Exception:
            pass
        tabs.configure(style='ResearchHidden.TNotebook')

        parent = tabs.master
        parent.grid_columnconfigure(0, weight=1)
        parent.grid_rowconfigure(0, weight=0)
        parent.grid_rowconfigure(1, weight=1)
        if tabs.winfo_manager() == 'grid':
            tabs.grid_configure(row=1, column=0, sticky='nsew', padx=10, pady=(0, 10))

        tab_ids = list(tabs.tabs())
        tab_texts = tuple(tabs.tab(tab_id, 'text') for tab_id in tab_ids)
        bar = getattr(self, '_fixed416_research_tab_bar', None)
        old_texts = getattr(self, '_fixed416_research_tab_texts', None)
        if bar is None or not bar.winfo_exists() or old_texts != tab_texts:
            if bar is not None:
                try:
                    bar.destroy()
                except Exception:
                    pass
            bar_height = max(42, int(48 * scale))
            bar = tk.Frame(parent, bg=BG_COLOR, height=bar_height)
            bar.grid(row=0, column=0, sticky='ew', padx=10, pady=(10, 0))
            bar.grid_propagate(False)
            self._fixed416_research_tab_bar = bar
            self._fixed416_research_tab_texts = tab_texts
            self._fixed416_research_tab_items = []

            for index, (tab_id, text) in enumerate(zip(tab_ids, tab_texts)):
                wrap = tk.Frame(bar, bg=BG_COLOR)
                wrap.pack(side='left', anchor='s', padx=(0, max(3, int(4 * scale))), pady=(0, 0))
                label = tk.Label(
                    wrap,
                    text=text,
                    bg=PANEL_COLOR,
                    fg=TEXT_COLOR,
                    cursor='hand2',
                    borderwidth=1,
                    relief='solid',
                    highlightthickness=1,
                )
                label.pack(anchor='s')
                label.bind('<Button-1>', lambda _event, _tab_id=tab_id: tabs.select(_tab_id))
                self._fixed416_research_tab_items.append({'wrap': wrap, 'label': label})

        try:
            tabs.unbind('<<NotebookTabChanged>>', getattr(self, '_fixed416_research_tab_bind_id', ''))
        except Exception:
            pass
        self._fixed416_research_tab_bind_id = tabs.bind(
            '<<NotebookTabChanged>>',
            lambda _event: _fixed416_sync_research_custom_tabs(self),
            add='+',
        )
        _fixed416_sync_research_custom_tabs(self)
    except Exception:
        pass


