class _Fixed418NoResultLogger:
    data_file = ''

    def log_event(self, *args, **kwargs):
        return None


def _fixed418_clone_config(cfg):
    try:
        kwargs = {}
        for fld in fields(cfg.__class__):
            if getattr(fld, 'init', True) and hasattr(cfg, fld.name):
                kwargs[fld.name] = getattr(cfg, fld.name)
        return cfg.__class__(**kwargs)
    except Exception:
        try:
            kwargs = dict(getattr(cfg, '__dict__', {}) or {})
            return cfg.__class__(**kwargs)
        except Exception:
            return cfg


def _fixed418_training_session(owner, suffix: str = 'training') -> SessionInfo:
    base = getattr(owner, 'current_session', None)
    if base is None:
        return SessionInfo(
            session_id=f'training_{datetime.now().strftime("%Y%m%d_%H%M%S")}',
            name='Тренировка',
            age=0,
            gender='',
            started_at=datetime.now(),
        )
    try:
        return SessionInfo(
            session_id=f'{getattr(base, "session_id", "session")}_{suffix}_{datetime.now().strftime("%H%M%S")}',
            name=getattr(base, 'name', ''),
            age=getattr(base, 'age', 0),
            gender=getattr(base, 'gender', ''),
            started_at=getattr(base, 'started_at', datetime.now()),
        )
    except Exception:
        return base


def _fixed418_cfg_method_a_training(cfg):
    cfg = _fixed418_clone_config(cfg)
    training_stage_s = max(0.1, float(getattr(cfg, 'training_time_s', 10.0) or 10.0))
    for attr in (
        'stage_time_limit_s',
        'stage_time_limit_stage_1_s',
        'stage_time_limit_stage_2_s',
        'stage_time_limit_stage_3_s',
    ):
        try:
            setattr(cfg, attr, training_stage_s)
        except Exception:
            pass
    return cfg


def _fixed418_cfg_total_training(cfg):
    cfg = _fixed418_clone_config(cfg)
    try:
        cfg.total_test_s = max(0.1, float(getattr(cfg, 'training_time_s', 10.0) or 10.0))
    except Exception:
        pass
    return cfg


def _fixed418_cfg_method_c_training(cfg):
    cfg = _fixed418_cfg_total_training(cfg)
    try:
        stage_s = float(cfg.total_test_s) / 3.0
        cfg.stage_time_s = [stage_s, stage_s, stage_s]
    except Exception:
        pass
    return cfg


_FIXED418_PREV_METHOD_A_RUN = MethodAApp.run


def _fixed418_method_a_run(self) -> dict:
    if not bool(getattr(self, '_fixed418_training_mode', False)):
        return _FIXED418_PREV_METHOD_A_RUN(self)
    outcome = {'completed': False, 'training': True, 'reports': [], 'result_path': ''}
    try:
        for stage_no in (1, 2, 3):
            self.show_message(f'Тренировка. Этап {stage_no}', seconds=0.5)
            report = self.run_stage(stage_no)
            try:
                report.training_mode = True
            except Exception:
                pass
            self.reports.append(report)
        self.show_message('Тренировка завершена', seconds=0.8)
        outcome = {
            'completed': False,
            'training': True,
            'reports': [r.to_dict() for r in self.reports],
            'result_path': '',
        }
    except MethodAAbort:
        outcome = {
            'completed': False,
            'training': True,
            'reports': [r.to_dict() for r in self.reports],
            'result_path': '',
        }
    finally:
        try:
            pygame.event.set_grab(False)
        except Exception:
            pass
        try:
            pygame.mouse.set_visible(True)
        except Exception:
            pass
        try:
            pygame.quit()
        except Exception:
            pass
    return outcome


MethodAApp.run = _fixed418_method_a_run


