def _fixed418_run_training_a(owner, session: SessionInfo) -> dict:
    result = {'completed': False, 'training': True, 'reports': [], 'result_path': ''}
    try:
        owner.set_enabled(False)
    except Exception:
        pass
    try:
        owner.root.update_idletasks()
        owner.root.withdraw()
    except Exception:
        pass
    try:
        cfg = load_config(
            path=owner.base_dir / 'method_a_config.json',
            screen_w=owner.root.winfo_screenwidth(),
            screen_h=owner.root.winfo_screenheight(),
        )
        cfg = _fixed418_cfg_method_a_training(cfg)
        app = MethodAApp(cfg, _fixed418_training_session(owner, 'training_a'), _Fixed418NoResultLogger(), owner.base_dir)
        app._fixed418_training_mode = True
        result = app.run()
    finally:
        try:
            owner.root.deiconify()
            owner.open_fullscreen()
            owner.root.update_idletasks()
            owner.root.focus_force()
        except Exception:
            pass
        try:
            owner.set_enabled(True)
        except Exception:
            pass
    return result


def _fixed418_run_method_a(self, session: SessionInfo) -> dict:
    start_action = _fixed338_show_method_a_start_screen(self) if '_fixed338_show_method_a_start_screen' in globals() else 'continue'
    if start_action == 'exit':
        try:
            self.exit_app()
        except Exception:
            pass
        return {'completed': False, 'reports': []}
    if start_action != 'continue':
        try:
            self.menu_status_var.set('Запуск Теста A отменён до начала.')
        except Exception:
            pass
        return {'completed': False, 'reports': []}

    while True:
        instr_action = _fixed341_show_method_a_instruction(self)
        if instr_action == 'training':
            _fixed418_run_training_a(self, session)
            continue
        if instr_action == 'continue':
            return _FIXED341_BASE_RUN_METHOD_A(self, session)
        if instr_action == 'exit':
            try:
                self.exit_app()
            except Exception:
                pass
            return {'completed': False, 'reports': []}
        try:
            self.menu_status_var.set('Запуск Теста A отменён на экране инструкции.')
        except Exception:
            pass
        return {'completed': False, 'reports': []}


