# ====== FIXED419: integral Test C values match final C results; joystick cannot press navigation buttons ======
_FIXED419_INTEGRAL_C_AND_JOY_NAV_VERSION = 'fixed419_integral_c_same_as_results_joystick_nav_off_v1'


def _fixed419_method_c_stage_items(payload: dict) -> dict:
    summary = payload.get('summary', {}) if isinstance(payload.get('summary', {}), dict) else {}
    stages = payload.get('stages', None)
    if not isinstance(stages, dict):
        stages = summary.get('stages', {})
    return stages if isinstance(stages, dict) else {}


def _fixed419_method_c_norm_times(owner) -> list[float | None]:
    norm_times: list[float | None] = [None, None, None]
    try:
        cfg = load_method_c_config(Path(getattr(owner, 'base_dir', Path.cwd())))
        raw = list(getattr(cfg, 'normative_cycle_times', []) or [])
        while len(raw) < 3:
            raw.append(raw[-1] if raw else 0.0)
        norm_times = [float(raw[0]), float(raw[1]), float(raw[2])]
    except Exception:
        pass
    return norm_times


def _fixed419_float(value, default: float = 0.0) -> float:
    try:
        return float(value)
    except Exception:
        return float(default)


def _fixed419_method_c_result_values(owner, payload: dict) -> list[float]:
    stages = _fixed419_method_c_stage_items(payload)
    if not stages:
        return []

    norm_times = _fixed419_method_c_norm_times(owner)
    values: list[float] = []
    for idx in range(1, 4):
        stage_item = stages.get(str(idx), stages.get(idx, {}))
        if not isinstance(stage_item, dict):
            values.append(0.0)
            continue

        t_avg = _fixed419_float(stage_item.get('t_avg_cycle_s', stage_item.get('avg_cycle_time_s', 0.0)), 0.0)
        cfg_norm = norm_times[idx - 1] if idx - 1 < len(norm_times) else None
        if cfg_norm is None:
            t_norm = _fixed419_float(stage_item.get('t_norm_cycle_s', 0.0), 0.0)
        else:
            t_norm = _fixed419_float(cfg_norm, 0.0)
        t_norm = max(0.0001, t_norm)

        if t_avg > 0.0:
            t_base = t_norm / t_avg
        else:
            t_base = _fixed419_float(stage_item.get('t_base_value', stage_item.get('t_value', 0.0)), 0.0)

        gamma = _fixed419_float(stage_item.get('gamma_count', stage_item.get('Hq', 0.0)), 0.0)
        values.append(t_base * gamma)
    return values


_FIXED419_PREV_COLLECT_WORKABILITY_VALUES = _fixed376_collect_workability_values


def _fixed419_collect_workability_values(self, profile: UserProfile | None = None) -> dict:
    out = _FIXED419_PREV_COLLECT_WORKABILITY_VALUES(self, profile)
    profile = profile or self.current_profile
    if not profile:
        return out
    try:
        payload = self.progress_store.get_test_result(profile, 'C')
        if isinstance(payload, dict):
            c_values = _fixed419_method_c_result_values(self, payload)
            if len(c_values) == 3:
                out['C'] = c_values
    except Exception:
        pass
    return out


