def _fixed419_method_a_wait_continue(self, message: str, button_text: str = 'Далее'):
    btn_w, btn_h = 360, 58
    btn_rect = pygame.Rect((self.cfg.width - btn_w) // 2, int(self.cfg.height * 0.72), btn_w, btn_h)
    msg_font = pygame.font.SysFont('Times New Roman', max(36, int(self.cfg.height * 0.048)), bold=True)
    btn_font = pygame.font.SysFont('arial', 22, bold=True)
    panel_w = min(self.cfg.width - 80, int(self.cfg.width * 0.86))
    text_max_w = panel_w - 80
    lines = _fixed345_method_a_wrap_text(msg_font, message, text_max_w)

    prev_grab = False
    prev_visible = True
    try:
        prev_grab = bool(pygame.event.get_grab())
    except Exception:
        pass
    try:
        prev_visible = bool(pygame.mouse.get_visible())
    except Exception:
        pass

    try:
        try:
            pygame.event.set_grab(False)
        except Exception:
            pass
        try:
            pygame.mouse.set_visible(True)
        except Exception:
            pass

        while True:
            self.clock.tick(self.cfg.fps)
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    raise MethodAAbort
                if event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_ESCAPE:
                        raise MethodAAbort
                    if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER, pygame.K_SPACE):
                        return
                if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1 and btn_rect.collidepoint(event.pos):
                    return

            self.draw_background()
            line_h = msg_font.get_linesize()
            panel_h = max(110, 36 + len(lines) * line_h + 24)
            panel = pygame.Surface((panel_w, panel_h), pygame.SRCALPHA)
            panel.fill((255, 255, 255, 230))
            panel_rect = panel.get_rect(center=(self.cfg.width // 2, int(self.cfg.height * 0.30)))
            self.screen.blit(panel, panel_rect)
            pygame.draw.rect(self.screen, self.cfg.grid_color, panel_rect, 2, border_radius=12)

            y = panel_rect.y + 18
            for line in lines:
                surf = msg_font.render(line, True, (12, 37, 74))
                self.screen.blit(surf, (panel_rect.centerx - surf.get_width() // 2, y))
                y += line_h

            pygame.draw.rect(self.screen, (88, 204, 99), btn_rect)
            pygame.draw.rect(self.screen, (23, 59, 26), btn_rect, 2)
            btn_surf = btn_font.render(str(button_text or 'ДАЛЕЕ').upper(), True, (23, 59, 26))
            self.screen.blit(btn_surf, (btn_rect.centerx - btn_surf.get_width() // 2, btn_rect.centery - btn_surf.get_height() // 2))
            pygame.display.flip()
    finally:
        try:
            pygame.event.set_grab(prev_grab)
        except Exception:
            pass
        try:
            pygame.mouse.set_visible(prev_visible)
        except Exception:
            pass


globals()['_fixed345_method_a_wait_continue'] = _fixed419_method_a_wait_continue


def _fixed419_wait_for_method_a_start(self) -> str:
    start_w, start_h = 360, 58
    exit_w, exit_h = 360, 58
    bottom_margin = 16
    side_margin = 16

    exit_rect = pygame.Rect(side_margin, self.cfg.height - bottom_margin - exit_h, exit_w, exit_h)
    start_rect = pygame.Rect(self.cfg.width - side_margin - start_w, self.cfg.height - bottom_margin - start_h, start_w, start_h)
    title_font = pygame.font.SysFont('arial', 22, bold=True)
    btn_font = pygame.font.SysFont('arial', 22, bold=True)

    while True:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                return 'exit'
            if event.type == pygame.KEYDOWN and event.key == pygame.K_ESCAPE:
                return 'exit'
            if event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
                if start_rect.collidepoint(event.pos):
                    return 'start'
                if exit_rect.collidepoint(event.pos):
                    return 'exit'

        self.draw_background()
        try:
            self.draw_zones()
        except TypeError:
            try:
                self.draw_zones(1)
            except Exception:
                pass

        title = title_font.render('Нажмите кнопку, чтобы начать тестирование', True, self.cfg.text_color)
        self.screen.blit(title, (self.cfg.width // 2 - title.get_width() // 2, 34))

        pygame.draw.rect(self.screen, (88, 204, 99), start_rect)
        pygame.draw.rect(self.screen, (23, 59, 26), start_rect, 2)
        start_text = btn_font.render('Начать тестирование', True, (23, 59, 26))
        self.screen.blit(start_text, (start_rect.centerx - start_text.get_width() // 2, start_rect.centery - start_text.get_height() // 2))

        pygame.draw.rect(self.screen, (217, 90, 90), exit_rect)
        pygame.draw.rect(self.screen, (255, 255, 255), exit_rect, 2)
        exit_text = btn_font.render('Выход', True, (255, 255, 255))
        self.screen.blit(exit_text, (exit_rect.centerx - exit_text.get_width() // 2, exit_rect.centery - exit_text.get_height() // 2))

        pygame.display.flip()
        self.clock.tick(60)


_fixed121_wait_for_method_a_start = _fixed419_wait_for_method_a_start
globals()['_fixed121_wait_for_method_a_start'] = _fixed419_wait_for_method_a_start


