def _fixed420_style_research_section_tabs(self):
    try:
        scale = _fixed416_research_tab_scale(self) if '_fixed416_research_tab_scale' in globals() else 1.0
        style = ttk.Style(self.root)
        try:
            if style.theme_use() != 'clam':
                style.theme_use('clam')
        except Exception:
            pass
        style.configure(
            'ResearchSection.TNotebook',
            background=BG_COLOR,
            borderwidth=0,
            tabmargins=(0, max(4, int(5 * scale)), 0, 0),
        )
        style.configure(
            'ResearchSection.TNotebook.Tab',
            background=PANEL_COLOR,
            foreground=TEXT_COLOR,
            bordercolor='#9f9873',
            lightcolor=PANEL_COLOR,
            darkcolor='#9f9873',
            padding=(max(10, int(14 * scale)), max(5, int(7 * scale)), max(10, int(14 * scale)), max(5, int(7 * scale))),
            font=('Arial', max(10, int(12 * scale)), 'bold'),
        )
        style.map(
            'ResearchSection.TNotebook.Tab',
            background=[('selected', '#d9d2a9'), ('active', '#eee8c7')],
            foreground=[('selected', TITLE_COLOR), ('active', TITLE_COLOR)],
            padding=[('selected', (max(12, int(16 * scale)), max(8, int(10 * scale)), max(12, int(16 * scale)), max(8, int(10 * scale))))],
        )
    except Exception:
        pass


def _fixed420_short_tab_title(title: str) -> str:
    text = ' '.join(str(title or '').split())
    replacements = {
        'Окно и обновление': 'Окно',
        'Rцели и Rавар': 'Rцели/Rавар',
        'Нормативные скорости': 'Vнорм',
        'Нормативные скорости: этап 2': 'Vнорм этап 2',
        'Нормативные скорости: этап 3': 'Vнорм этап 3',
        'Sнорм (по этапам)': 'Sнорм',
        'Nдоп за 180с': 'Nдоп',
        'Динамика объекта': 'Динамика',
        'Управление и оформление': 'Управление',
        'Этапы и оценка': 'Этапы',
        'Подстройка под экран': 'Экран',
        'Структура теста': 'Структура',
        'Этапы и время': 'Время',
        'Прочие параметры': 'Прочие',
    }
    return replacements.get(text, text)


def _fixed420_make_research_field(self, code, cls, cfg, section, widgets, field_name, row):
    fld = next((item for item in fields(cls) if item.name == field_name), None)
    if fld is None:
        return row

    meta = _get_research_field_meta(code, fld.name)
    default_value = getattr(cfg, fld.name)

    label_box = tk.Frame(section, bg=PANEL_COLOR)
    label_box.grid(row=row, column=0, sticky='nw', padx=(8, 16), pady=6)

    label = tk.Label(
        label_box,
        text=meta.get('label', fld.name),
        bg=PANEL_COLOR,
        fg=TITLE_COLOR,
        anchor='w',
        justify='left',
        font=('Segoe UI', 10, 'bold'),
        wraplength=280,
    )
    label.pack(anchor='w')

    help_text = meta.get('help', '')
    if help_text:
        help_label = tk.Label(
            label_box,
            text=help_text,
            bg=PANEL_COLOR,
            fg='#5a5a5a',
            anchor='w',
            justify='left',
            wraplength=280,
        )
        help_label.pack(anchor='w', pady=(2, 0))

    template_value = getattr(cls(), fld.name)
    is_bool_field = isinstance(template_value, bool)
    serialized = _serialize_config_value(default_value)
    is_multiline = (not is_bool_field) and (isinstance(default_value, (list, dict, tuple)) or len(serialized) > 52)

    widget_box = tk.Frame(section, bg=PANEL_COLOR)
    widget_box.grid(row=row, column=1, sticky='ew', padx=(0, 8), pady=6)
    widget_box.grid_columnconfigure(0, weight=1)

    bool_var = None
    if is_bool_field:
        bool_var = tk.BooleanVar(value=_fixed275_to_bool(default_value))
        bool_text_var = tk.StringVar()

        def _sync_bool_caption(*_args, _var=bool_var, _text_var=bool_text_var):
            _text_var.set('Включено' if bool(_var.get()) else 'Выключено')

        _sync_bool_caption()
        bool_var.trace_add('write', _sync_bool_caption)
        widget = tk.Checkbutton(
            widget_box,
            textvariable=bool_text_var,
            variable=bool_var,
            onvalue=True,
            offvalue=False,
            bg=PANEL_COLOR,
            activebackground=PANEL_COLOR,
            fg=TITLE_COLOR,
            selectcolor=FIELD_BG,
            anchor='w',
            justify='left',
            font=('Segoe UI', 13, 'bold'),
            indicatoron=False,
            relief='raised',
            padx=10,
            pady=6,
            width=12,
            bd=2,
            highlightthickness=0,
        )
        widget.grid(row=0, column=0, sticky='w')
    elif is_multiline:
        widget = tk.Text(widget_box, height=max(3, min(6, serialized.count('\n') + 2)), wrap='word', bg=FIELD_BG, relief='sunken', bd=1)
        widget.insert('1.0', serialized)
        widget.grid(row=0, column=0, sticky='ew')
    else:
        widget = tk.Entry(widget_box, bg=FIELD_BG)
        widget.insert(0, serialized)
        widget.grid(row=0, column=0, sticky='ew', ipady=4)

    if not is_bool_field:
        default_hint = tk.Label(
            widget_box,
            text=f'По умолчанию: {serialized}',
            bg=PANEL_COLOR,
            fg='#6b7280',
            anchor='w',
            justify='left',
            wraplength=620,
        )
        default_hint.grid(row=1, column=0, sticky='w', pady=(3, 0))

    widgets[fld.name] = {
        'widget': widget,
        'template': template_value,
        'is_multiline': is_multiline,
        'is_bool': is_bool_field,
        'bool_var': bool_var,
    }
    return row + 1


def _fixed420_populate_researcher_fields(self):
    for child in self.research_content.winfo_children():
        child.destroy()
    self.research_widgets = {}
    self.research_sections = {}
    self._fixed420_research_block_tabs = {}

    self.research_content.grid_columnconfigure(0, weight=1)
    self.research_content.grid_rowconfigure(0, weight=1)

    self.research_tabs = ttk.Notebook(self.research_content)
    self.research_tabs.grid(row=0, column=0, sticky='nsew', padx=10, pady=10)

    for code, title, cls, filename in RESEARCH_CONFIG_SPECS:
        tab = tk.Frame(self.research_tabs, bg=BG_COLOR)
        tab.grid_columnconfigure(0, weight=1)
        tab.grid_rowconfigure(1, weight=1)
        self.research_tabs.add(tab, text=f'Тест {code}')

        intro = tk.Label(
            tab,
            text=title,
            bg=BG_COLOR,
            fg=TITLE_COLOR,
            anchor='center',
            justify='center',
        )
        intro.grid(row=0, column=0, sticky='ew', padx=10, pady=(8, 6))

        block_tabs = ttk.Notebook(tab, style='ResearchSection.TNotebook')
        block_tabs.grid(row=1, column=0, sticky='nsew', padx=10, pady=(0, 10))
        self._fixed420_research_block_tabs[code] = block_tabs

        cfg = _fixed73d_load_cfg(self, cls, filename)
        widgets = {}
        section_frames = []
        section_groups = _get_research_section_groups(code, cls)

        for section_title, field_names in section_groups:
            section_tab = tk.Frame(block_tabs, bg=PANEL_COLOR)
            section_tab.grid_columnconfigure(0, weight=1)
            block_tabs.add(section_tab, text=_fixed420_short_tab_title(section_title))

            section = tk.Frame(section_tab, bg=PANEL_COLOR, padx=10, pady=10, bd=2, relief='groove')
            section.grid(row=0, column=0, sticky='nsew', padx=10, pady=10)
            section.grid_columnconfigure(0, weight=0, minsize=300)
            section.grid_columnconfigure(1, weight=1)
            section_frames.append(section)

            header = tk.Label(
                section,
                text=section_title,
                bg=PANEL_COLOR,
                fg=TITLE_COLOR,
                anchor='w',
                justify='left',
                font=('Arial', 15, 'bold'),
            )
            header.grid(row=0, column=0, columnspan=2, sticky='ew', padx=8, pady=(0, 8))

            row = 1
            for field_name in field_names:
                row = _fixed420_make_research_field(self, code, cls, cfg, section, widgets, field_name, row)

        self.research_widgets[code] = widgets
        self.research_sections[code] = section_frames

    _fixed420_style_research_section_tabs(self)
    if '_fixed416_style_research_tabs' in globals():
        _fixed416_style_research_tabs(self)
    try:
        _bind_mousewheel_to_canvas(self.research_canvas, self.research_content, self.research_tabs, *getattr(self, '_fixed420_research_block_tabs', {}).values())
    except Exception:
        pass
    self._on_research_canvas_configure()
    self._on_research_content_configure()


