# ====== FIXED421: inner researcher block tabs are vertical ======
_FIXED421_RESEARCH_VERTICAL_BLOCK_TABS_VERSION = 'fixed421_research_vertical_block_tabs_v1'


def _fixed421_select_research_block(self, code: str, selected_index: int):
    groups = getattr(self, '_fixed421_research_block_tabs', {})
    state = groups.get(code, {}) if isinstance(groups, dict) else {}
    buttons = state.get('buttons', [])
    pages = state.get('pages', [])
    if not buttons or not pages:
        return
    for index, page in enumerate(pages):
        try:
            if index == selected_index:
                page.grid(row=0, column=0, sticky='nsew')
            else:
                page.grid_remove()
        except Exception:
            pass
    for index, btn in enumerate(buttons):
        try:
            active = index == selected_index
            btn.configure(
                bg='#d9d2a9' if active else PANEL_COLOR,
                activebackground='#d9d2a9' if active else '#eee8c7',
                fg=TITLE_COLOR if active else TEXT_COLOR,
                relief='raised' if active else 'solid',
                bd=2 if active else 1,
            )
        except Exception:
            pass


