# ====== FIXED422: stretch researcher settings down and reduce need for scrolling ======
_FIXED422_RESEARCH_USE_FULL_HEIGHT_VERSION = 'fixed422_research_settings_use_full_height_v1'


def _fixed422_on_research_canvas_configure(self, event=None):
    if not hasattr(self, 'research_canvas_window'):
        return
    try:
        width = event.width if event else self.research_canvas.winfo_width()
        height = event.height if event else self.research_canvas.winfo_height()
        self.research_canvas.itemconfigure(self.research_canvas_window, width=max(1, width), height=max(1, height))
        try:
            tabs = getattr(self, 'research_tabs', None)
            content = getattr(self, 'research_content', None)
            if tabs is not None and content is not None:
                tab_row = int(tabs.grid_info().get('row', 0) or 0)
                reserved = 0
                for child in content.grid_slaves():
                    if child is tabs:
                        continue
                    info = child.grid_info()
                    try:
                        child_row = int(info.get('row', -1))
                    except Exception:
                        child_row = -1
                    if child_row >= 0 and child_row != tab_row:
                        reserved += max(0, child.winfo_reqheight())
                content.grid_rowconfigure(tab_row, weight=1, minsize=max(360, int(height) - reserved - 18))
                tabs.grid_configure(sticky='nsew')
        except Exception:
            pass
        self.research_canvas.configure(scrollregion=self.research_canvas.bbox('all'))
    except Exception:
        try:
            width = event.width if event else self.research_canvas.winfo_width()
            self.research_canvas.itemconfigure(self.research_canvas_window, width=max(1, width))
        except Exception:
            pass


def _fixed422_on_research_content_configure(self, _event=None):
    if hasattr(self, 'research_canvas') and self.research_canvas.winfo_exists():
        try:
            self.research_canvas.configure(scrollregion=self.research_canvas.bbox('all'))
        except Exception:
            pass


_FIXED422_PREV_APPLY_RESEARCHER_LAYOUT = StartPageApp.apply_researcher_layout


def _fixed422_apply_researcher_layout(self):
    _FIXED422_PREV_APPLY_RESEARCHER_LAYOUT(self)
    width = max(self.root.winfo_width(), 1100)
    height = max(self.root.winfo_height(), 760)
    scale = max(0.75, min(min(width / BASE_W, height / BASE_H), 1.25))

    try:
        self.main.pack_configure(padx=max(10, int(14 * scale)), pady=max(6, int(8 * scale)))
    except Exception:
        pass
    for widget_name, pady in (
        ('research_header', (0, max(3, int(4 * scale)))),
        ('research_subtitle', (0, max(3, int(4 * scale)))),
        ('research_actions_top', (0, max(4, int(5 * scale)))),
        ('research_status', (0, max(3, int(4 * scale)))),
    ):
        try:
            getattr(self, widget_name).grid_configure(pady=pady)
        except Exception:
            pass

    try:
        self.research_tabs.grid_configure(padx=6, pady=(4, 0), sticky='nsew')
    except Exception:
        pass
    try:
        self.research_content.grid_rowconfigure(0, weight=1)
        self.research_content.grid_columnconfigure(0, weight=1)
    except Exception:
        pass

    nav_font = ('Arial', max(9, int(11 * scale)), 'bold')
    nav_width = max(168, int(205 * scale))
    for state in getattr(self, '_fixed421_research_block_tabs', {}).values():
        nav_outer = state.get('nav_outer')
        nav_canvas = state.get('nav_canvas')
        if nav_outer is not None:
            try:
                nav_outer.configure(width=nav_width)
                nav_outer.grid_propagate(False)
            except Exception:
                pass
        if nav_canvas is not None:
            try:
                nav_canvas.configure(width=max(145, nav_width - 16))
            except Exception:
                pass
        for btn in state.get('buttons', []):
            try:
                btn.configure(
                    font=nav_font,
                    padx=max(5, int(6 * scale)),
                    pady=max(1, int(2 * scale)),
                    wraplength=max(130, nav_width - 30),
                )
                btn.grid_configure(pady=(0, 2), ipady=max(2, int(3 * scale)))
            except Exception:
                pass
        for page in state.get('pages', []):
            try:
                page.grid_columnconfigure(0, weight=1)
                page.grid_rowconfigure(0, weight=1)
            except Exception:
                pass
        page_host = state.get('page_host')
        if page_host is not None:
            try:
                page_host.grid_configure(sticky='nsew')
            except Exception:
                pass

    _fixed422_on_research_canvas_configure(self)


StartPageApp._on_research_canvas_configure = _fixed422_on_research_canvas_configure
StartPageApp._on_research_content_configure = _fixed422_on_research_content_configure
StartPageApp.apply_researcher_layout = _fixed422_apply_researcher_layout


# ====== FIXED423: create/update integrated Excel and export full C/D result columns ======
_FIXED423_INTEGRATED_EXCEL_HEADERS_VERSION = 'fixed423_integrated_excel_create_full_cd_headers_v1'
_FIXED423_C_DETAIL_START_COL = 127
_FIXED423_D_DETAIL_START_COL = 151


def _fixed423_excel_headers() -> dict[int, tuple[str, str, str, str]]:
    headers: dict[int, tuple[str, str, str, str]] = {
        1: ('Данные формы', '', '', '№'),
        2: ('Данные формы', '', '', 'ФИО'),
        3: ('Данные формы', '', '', 'Возраст'),
        4: ('Данные формы', '', '', 'Пол'),
        5: ('Данные формы', '', '', 'Налет[ч]'),
        6: ('Данные формы', '', '', 'Тип ВС'),
        7: ('Данные формы', '', '', 'Образование'),
    }
    a_keys = [
        'Rтек.X', 'Rтек.Y', 'Rтек.Z', 'Rцели.X', 'Rцели.Y', 'Rцели.Z', 'Rавар.X', 'Rавар.Y', 'Rавар.Z',
        'Vx', 'Vy', 'Vz', 'Vтек', 'Vтек.упр.X', 'Vтек.упр.Y', 'Vтек.упр.Z', 'Vтек.упр.Σ',
        'λx', 'λy', 'λz', 'λтек', 'Sx', 'Sy', 'Sz', 'Yтек', 'YΣx', 'YΣy', 'YΣz', 'YΣ',
        'N', 'Yпред', 'Nдоп',
    ]
    for stage_index, start_col in enumerate((8, 40, 72), start=1):
        stage_label = ('Этап 1 · X', 'Этап 2 · X+Y', 'Этап 3 · X+Y+крен')[stage_index - 1]
        for offset, label in enumerate(a_keys):
            headers[start_col + offset] = ('Тест A', stage_label, str(stage_index), label)
    for n in range(1, 17):
        headers[103 + n] = ('Тест B', 'Память', str(n), f'tпамять {n}')
    for idx, label in enumerate(('tсчет 1', 'tсчет 2', 'tсчет 3'), start=120):
        headers[idx] = ('Тест C', 'Счет', str(idx - 119), label)
    for col, label, sub in ((123, 'tзакон 1', '2-поз.'), (124, 'tзакон 3', '3-поз.'), (125, 'tзакон 4', '4-поз.')):
        headers[col] = ('Тест D', 'Закономерности', sub, label)
    headers[126] = ('Данные формы', '', '', 'Должность')

    c_fields = [
        ('T', 'время этапа, с'),
        ('kобщ', 'всего циклов'),
        ('kусп', 'верных циклов'),
        ('γсчет', 'коэфф. успешности'),
        ('tср', 'реальный темп'),
        ('tнорм', 'нормативный темп'),
        ('tприв', 'приведенный темп'),
        ('tсчет', 'темп счета'),
    ]
    for stage_idx in range(1, 4):
        stage_name = ('Однозначные', 'Двузначные', 'Трехзначные')[stage_idx - 1]
        base = _FIXED423_C_DETAIL_START_COL + (stage_idx - 1) * len(c_fields)
        for offset, (symbol, title) in enumerate(c_fields):
            headers[base + offset] = ('Тест C · подробно', stage_name, str(stage_idx), f'{symbol} · {title}')

    d_fields = [
        ('Nпред', 'предъявлено'),
        ('Nотв', 'ответов'),
        ('Nверн', 'верных'),
        ('γзак', 'коэфф. успешности'),
        ('γнорм', 'норматив успешности'),
        ('T', 'время этапа, с'),
        ('tфакт', 'среднее время цикла'),
        ('tнорм', 'нормативное время цикла'),
        ('Vреал', 'реальная скорость'),
        ('Vнорм', 'нормативная скорость'),
        ('tприв', 'приведенный темп'),
        ('tзакон', 'темп закономерности'),
    ]
    for stage_idx, (key, stage_name) in enumerate((('min', '2-позиционная'), ('medio', '3-позиционная'), ('max', '4-позиционная')), start=1):
        base = _FIXED423_D_DETAIL_START_COL + (stage_idx - 1) * len(d_fields)
        for offset, (symbol, title) in enumerate(d_fields):
            headers[base + offset] = ('Тест D · подробно', stage_name, key, f'{symbol} · {title}')
    return headers


def _fixed423_style_header_cell(ws, col: int) -> None:
    try:
        from copy import copy
        src_col = 8 if col >= 8 else 2
        for row in (1, 2, 3, 4):
            src = ws.cell(row=row, column=src_col)
            dst = ws.cell(row=row, column=col)
            if src.has_style:
                dst._style = copy(src._style)
            if src.font:
                dst.font = copy(src.font)
            if src.fill:
                dst.fill = copy(src.fill)
            if src.border:
                dst.border = copy(src.border)
            if src.alignment:
                dst.alignment = copy(src.alignment)
    except Exception:
        pass


def _fixed423_ensure_integrated_excel_headers(ws) -> None:
    try:
        for merged_range in list(ws.merged_cells.ranges):
            if int(merged_range.min_row) <= 4 and int(merged_range.max_row) >= 1:
                ws.unmerge_cells(str(merged_range))
    except Exception:
        pass
    headers = _fixed423_excel_headers()
    for col, values in headers.items():
        _fixed423_style_header_cell(ws, col)
        for row, value in enumerate(values, start=1):
            if value not in (None, ''):
                ws.cell(row=row, column=col).value = value
        try:
            letter = ws.cell(row=1, column=col).column_letter
            if col >= _FIXED423_C_DETAIL_START_COL:
                ws.column_dimensions[letter].width = 15
            elif col >= 104:
                ws.column_dimensions[letter].width = 12
        except Exception:
            pass
    try:
        ws.freeze_panes = 'A5'
    except Exception:
        pass


def _fixed423_create_integrated_excel_file(path: Path) -> None:
    import openpyxl
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'Лист1'
    _fixed423_ensure_integrated_excel_headers(ws)
    path.parent.mkdir(parents=True, exist_ok=True)
    wb.save(path)


def _fixed423_prepare_excel_file(base_dir: Path | str) -> Path | None:
    path = _fixed417_external_excel_path(base_dir)
    if not path.exists():
        copied = False
        try:
            meipass = getattr(sys, '_MEIPASS', None)
            if meipass:
                bundled = Path(meipass) / _FIXED417_INTEGRATED_XLSX
                if bundled.exists():
                    shutil.copy2(bundled, path)
                    copied = True
        except Exception as exc:
            _fixed417_log_excel_export(base_dir, f'Не удалось скопировать шаблон Excel: {exc}')
        if not copied:
            try:
                _fixed423_create_integrated_excel_file(path)
            except Exception as exc:
                _fixed417_log_excel_export(base_dir, f'Не удалось создать Excel-файл: {type(exc).__name__}: {exc}')
                return None
    try:
        import openpyxl
        wb = openpyxl.load_workbook(path)
        ws = wb.active
        _fixed423_ensure_integrated_excel_headers(ws)
        wb.save(path)
    except PermissionError:
        _fixed417_log_excel_export(base_dir, f'Excel-файл открыт, заголовки не обновлены: {path}')
    except Exception as exc:
        _fixed417_log_excel_export(base_dir, f'Не удалось обновить заголовки Excel: {type(exc).__name__}: {exc}')
    return path


def _fixed423_float(value):
    return _fixed417_float_or_none(value)


def _fixed423_method_c_stage(payload: dict, stage_idx: int) -> dict:
    summary = payload.get('summary') if isinstance(payload.get('summary'), dict) else {}
    stages = payload.get('stages') if isinstance(payload.get('stages'), dict) else None
    if not isinstance(stages, dict):
        stages = summary.get('stages') if isinstance(summary.get('stages'), dict) else {}
    item = stages.get(str(stage_idx), stages.get(stage_idx, {}))
    return item if isinstance(item, dict) else {}


def _fixed423_stage_elapsed_s(stage_item: dict) -> float:
    cycles = stage_item.get('cycles', [])
    if not isinstance(cycles, list):
        return 0.0
    total = 0.0
    for cycle in cycles:
        if isinstance(cycle, dict):
            total += max(0.0, float(cycle.get('elapsed_s', 0.0) or 0.0))
    return total


def _fixed423_method_c_values(payload: dict) -> list[float]:
    if '_fixed419_method_c_result_values' in globals():
        try:
            class _Owner:
                base_dir = _runtime_app_dir()
            values = _fixed419_method_c_result_values(_Owner(), payload)
            if len(values) == 3:
                return values
        except Exception:
            pass
    summary = payload.get('summary') if isinstance(payload.get('summary'), dict) else {}
    return [
        _fixed423_float(summary.get('tmin_c')) or 0.0,
        _fixed423_float(summary.get('tmedio_c')) or 0.0,
        _fixed423_float(summary.get('tmax_c')) or 0.0,
    ]


def _fixed423_write_method_c(ws, row: int, payload: dict) -> None:
    c_values = _fixed423_method_c_values(payload)
    for col, value in zip((120, 121, 122), c_values):
        _fixed417_set_if_value(ws, row, col, _fixed423_float(value))

    c_fields = ('elapsed', 'k_obsh', 'k_usp', 'gamma_count', 't_avg_cycle_s', 't_norm_cycle_s', 't_base_value', 't_count')
    for stage_idx in range(1, 4):
        item = _fixed423_method_c_stage(payload, stage_idx)
        base = _FIXED423_C_DETAIL_START_COL + (stage_idx - 1) * len(c_fields)
        values = {
            'elapsed': _fixed423_stage_elapsed_s(item),
            'k_obsh': item.get('k_obsh', item.get('Gq')),
            'k_usp': item.get('k_usp', item.get('Fq')),
            'gamma_count': item.get('gamma_count', item.get('Hq')),
            't_avg_cycle_s': item.get('t_avg_cycle_s', item.get('avg_cycle_time_s')),
            't_norm_cycle_s': item.get('t_norm_cycle_s'),
            't_base_value': item.get('t_base_value', item.get('t_value')),
            't_count': c_values[stage_idx - 1] if stage_idx - 1 < len(c_values) else None,
        }
        for offset, key in enumerate(c_fields):
            _fixed417_set_if_value(ws, row, base + offset, _fixed423_float(values.get(key)))


def _fixed423_method_d_group(payload: dict, key: str) -> dict:
    summary = payload.get('summary') if isinstance(payload.get('summary'), dict) else {}
    groups = summary.get('groups') if isinstance(summary.get('groups'), dict) else {}
    item = groups.get(key, {})
    return item if isinstance(item, dict) else {}


def _fixed423_write_method_d(ws, row: int, payload: dict) -> None:
    summary = payload.get('summary') if isinstance(payload.get('summary'), dict) else {}
    for col, key, fallback in ((123, 'min', 'tmin_d'), (124, 'medio', 'tmedio_d'), (125, 'max', 'tmax_d')):
        item = _fixed423_method_d_group(payload, key)
        value = item.get('t_value') if item else None
        if value in (None, ''):
            value = summary.get(fallback)
        _fixed417_set_if_value(ws, row, col, _fixed423_float(value))

    d_fields = (
        'presented_count', 'answered_count', 'correct_count', 'success_ratio', 'gamma_norm', 'stage_elapsed_s',
        't_fact_avg_s', 't_norm_avg_s', 'real_speed', 'normative_speed', 't_reduced', 't_value',
    )
    for stage_idx, key in enumerate(('min', 'medio', 'max'), start=1):
        item = _fixed423_method_d_group(payload, key)
        base = _FIXED423_D_DETAIL_START_COL + (stage_idx - 1) * len(d_fields)
        for offset, field_name in enumerate(d_fields):
            _fixed417_set_if_value(ws, row, base + offset, _fixed423_float(item.get(field_name)))


def _fixed423_export_payload_to_integrated_excel(base_dir: Path | str, payload: dict) -> None:
    if not isinstance(payload, dict):
        return
    participant = payload.get('participant') if isinstance(payload.get('participant'), dict) else {}
    fio = str(participant.get('name', '') or '').strip()
    if not fio:
        return
    path = _fixed423_prepare_excel_file(base_dir)
    if path is None:
        _fixed417_log_excel_export(base_dir, f'Excel-файл не создан: {_FIXED417_INTEGRATED_XLSX}')
        return
    try:
        import openpyxl
        wb = openpyxl.load_workbook(path)
        ws = wb.active
        _fixed423_ensure_integrated_excel_headers(ws)
        row = _fixed417_find_or_create_participant_row(ws, fio)
        _fixed417_write_login(ws, row, participant)
        code = str(payload.get('test_code', '') or '').upper()
        if code == 'A':
            _fixed417_write_method_a(ws, row, payload)
        elif code == 'B':
            _fixed417_write_method_b(ws, row, payload)
        elif code == 'C':
            _fixed423_write_method_c(ws, row, payload)
        elif code == 'D':
            _fixed423_write_method_d(ws, row, payload)
        wb.save(path)
        _fixed417_log_excel_export(base_dir, f'OK: {fio}, тест {code}, строка {row}, файл {path.name}, headers={_FIXED423_INTEGRATED_EXCEL_HEADERS_VERSION}')
    except PermissionError:
        _fixed417_log_excel_export(base_dir, f'Ошибка: Excel-файл открыт или недоступен для записи: {path}')
    except Exception as exc:
        _fixed417_log_excel_export(base_dir, f'Ошибка экспорта Excel для {fio}: {type(exc).__name__}: {exc}')


globals()['_fixed417_prepare_excel_file'] = _fixed423_prepare_excel_file
globals()['_fixed417_export_payload_to_integrated_excel'] = _fixed423_export_payload_to_integrated_excel


_FIXED423_PREV_STARTPAGE_INIT = StartPageApp.__init__


