_FIXED424_PREV_LOAD_C = load_method_c_config
_FIXED424_PREV_LOAD_D = load_method_d_config


def _fixed424_upgrade_config(base_cfg, target_cls, raw: dict):
    kwargs = {}
    for fld in fields(target_cls):
        if fld.name in raw:
            kwargs[fld.name] = raw[fld.name]
        elif hasattr(base_cfg, fld.name):
            kwargs[fld.name] = getattr(base_cfg, fld.name)
    cfg = target_cls(**kwargs)
    try:
        cfg.training_time_s = max(0.1, float(getattr(cfg, 'training_time_s', 10.0) or 10.0))
    except Exception:
        cfg.training_time_s = 10.0
    return cfg


def _fixed424_read_config(path: Path | str) -> dict:
    try:
        raw = json.loads(Path(path).read_text(encoding='utf-8'))
        return raw if isinstance(raw, dict) else {}
    except Exception:
        return {}


def load_config(path: str | Path = 'method_a_config.json', screen_w: int | None = None, screen_h: int | None = None) -> MethodAConfigFixed424:
    base_cfg = _FIXED424_PREV_LOAD_CONFIG(path=path, screen_w=screen_w, screen_h=screen_h)
    return _fixed424_upgrade_config(base_cfg, MethodAConfigFixed424, _fixed424_read_config(path))


def load_method_b_config(base_dir: Path) -> MethodBConfigFixed424:
    path = Path(base_dir) / 'method_b_config.json'
    return _fixed424_upgrade_config(_FIXED424_PREV_LOAD_B(base_dir), MethodBConfigFixed424, _fixed424_read_config(path))


def load_method_c_config(base_dir: Path) -> MethodCConfigFixed424:
    path = Path(base_dir) / 'method_c_config.json'
    return _fixed424_upgrade_config(_FIXED424_PREV_LOAD_C(base_dir), MethodCConfigFixed424, _fixed424_read_config(path))


def load_method_d_config(base_dir: Path) -> MethodDConfigFixed424:
    path = Path(base_dir) / 'method_d_config.json'
    return _fixed424_upgrade_config(_FIXED424_PREV_LOAD_D(base_dir), MethodDConfigFixed424, _fixed424_read_config(path))


MethodAConfig = MethodAConfigFixed424
