# ====== FIXED425: persistent researcher settings ======
_FIXED425_PERSISTENT_SETTINGS_VERSION = 'fixed425_persistent_researcher_settings_v1'


def save_config_dataclass(base_dir: Path, filename: str, obj):
    """Persist a complete config atomically beside the source file / portable EXE."""
    base_dir = Path(base_dir)
    base_dir.mkdir(parents=True, exist_ok=True)
    path = base_dir / filename
    temp_path = path.with_name(f'{path.name}.tmp')
    payload = json.dumps(asdict(obj), ensure_ascii=False, indent=2)
    temp_path.write_text(payload, encoding='utf-8')
    temp_path.replace(path)


def _fixed425_load_researcher_cfg(self, cls, filename):
    """Always populate the settings editor from the last saved values."""
    path = Path(self.base_dir) / filename
    if str(filename).lower() == 'method_a_config.json':
        try:
            # Use the complete Method A compatibility loader, but do not replace
            # persisted window values with the current monitor dimensions here.
            return load_config(path=path, screen_w=None, screen_h=None)
        except Exception:
            pass
    return _load_json_dataclass(path, cls)


# The final FIXED421 settings renderer resolves this helper at call time.
globals()['_fixed73d_load_cfg'] = _fixed425_load_researcher_cfg
StartPageApp.load_researcher_cfg = _fixed425_load_researcher_cfg


def _fixed425_save_open_settings(self, show_error: bool = True) -> bool:
    """Save edits that are currently visible on the researcher settings page."""
    if getattr(self, 'view_mode', '') != 'researcher' or not getattr(self, 'research_widgets', None):
        return True
    try:
        for filename, cfg in self.collect_researcher_configs():
            save_config_dataclass(self.base_dir, filename, cfg)
        if '_fixed425_set_settings_dirty' in globals():
            _fixed425_set_settings_dirty(self, False)
        return True
    except Exception as exc:
        message = f'Не удалось сохранить настройки: {exc}'
        if getattr(self, 'research_status_var', None) is not None:
            self.research_status_var.set(message)
        if show_error:
            try:
                messagebox.showerror('Сохранение настроек', message)
            except Exception:
                pass
        return False


def _fixed425_set_settings_dirty(self, dirty: bool):
    self._fixed425_settings_dirty = bool(dirty)
    button = getattr(self, 'research_save_btn', None)
    actions = getattr(self, 'research_actions_top', None)
    next_button = getattr(self, 'research_next_btn', None)
    if button is None or actions is None or next_button is None:
        return
    try:
        if dirty:
            for column in range(5):
                actions.grid_columnconfigure(column, weight=1)
            button.grid(row=0, column=3, sticky='ew')
            next_button.grid_configure(row=0, column=4, sticky='ew')
            if getattr(self, 'research_status_var', None) is not None:
                self.research_status_var.set('Есть несохранённые изменения.')
        else:
            button.grid_remove()
            next_button.grid_configure(row=0, column=3, sticky='ew')
            for column in range(4):
                actions.grid_columnconfigure(column, weight=1)
            actions.grid_columnconfigure(4, weight=0)
    except Exception:
        pass


def _fixed425_schedule_settings_save(self, _event=None):
    """Mark the editor dirty as soon as any setting is changed."""
    if getattr(self, 'view_mode', '') != 'researcher':
        return
    _fixed425_set_settings_dirty(self, True)


def _fixed425_bind_settings_autosave(self):
    for field_map in getattr(self, 'research_widgets', {}).values():
        for info in field_map.values():
            widget = info.get('widget')
            if widget is not None and not getattr(widget, '_fixed425_autosave_bound', False):
                try:
                    widget.bind('<KeyRelease>', self._fixed425_schedule_settings_save, add='+')
                    widget.bind('<FocusOut>', self._fixed425_schedule_settings_save, add='+')
                    if isinstance(widget, tk.Entry) and not info.get('is_bool'):
                        edit_var = tk.StringVar(master=widget, value=widget.get())
                        widget.configure(textvariable=edit_var)
                        edit_var.trace_add(
                            'write',
                            lambda *_args, _self=self: _self._fixed425_schedule_settings_save(),
                        )
                        info['_fixed425_edit_var'] = edit_var
                    elif isinstance(widget, tk.Text):
                        widget.edit_modified(False)

                        def _text_modified(_event=None, _widget=widget, _self=self):
                            try:
                                if _widget.edit_modified():
                                    _widget.edit_modified(False)
                                    _self._fixed425_schedule_settings_save()
                            except Exception:
                                pass

                        widget.bind('<<Modified>>', _text_modified, add='+')
                    widget._fixed425_autosave_bound = True
                except Exception:
                    pass
            variable = info.get('bool_var')
            if variable is not None and not getattr(variable, '_fixed425_autosave_bound', False):
                try:
                    variable.trace_add('write', lambda *_args, _self=self: _self._fixed425_schedule_settings_save())
                    variable._fixed425_autosave_bound = True
                except Exception:
                    pass


