def _fixed425_apply_researcher_layout(self):
    _FIXED425_PREV_APPLY_RESEARCHER_LAYOUT(self)
    button = getattr(self, 'research_save_btn', None)
    if button is not None:
        width = max(self.root.winfo_width(), 1100)
        height = max(self.root.winfo_height(), 760)
        scale = max(0.75, min(min(width / BASE_W, height / BASE_H), 1.25))
        button.configure(font=('Arial', max(10, int(13 * scale)), 'bold'))
        if bool(getattr(self, '_fixed425_settings_dirty', False)):
            button.grid_configure(padx=(0, max(5, int(10 * scale))))


