_FIXED425_PREV_EXIT_APP = StartPageApp.exit_app


def _fixed425_exit_app(self):
    # Closing the application from the settings page must not discard valid edits.
    pending = getattr(self, '_fixed425_settings_save_after_id', None)
    if pending is not None:
        try:
            self.root.after_cancel(pending)
        except Exception:
            pass
        self._fixed425_settings_save_after_id = None
    if not _fixed425_save_open_settings(self, show_error=True):
        return
    _FIXED425_PREV_EXIT_APP(self)


StartPageApp.exit_app = _fixed425_exit_app


