_FIXED425_PREV_PREPARE_CONFIG_SCHEMA = _fixed220_prepare_config_schema


def _fixed220_prepare_config_schema(base_dir: Path):
    """Create missing configs without ever replacing an existing user config."""
    try:
        base_dir = Path(base_dir)
        base_dir.mkdir(parents=True, exist_ok=True)
        current_specs = {
            'method_a_config.json': MethodAConfig,
            'method_b_config.json': MethodBConfig,
            'method_c_config.json': MethodCConfig,
            'method_d_config.json': MethodDConfig,
        }
        for filename, cls in current_specs.items():
            path = base_dir / filename
            if not path.exists():
                save_config_dataclass(base_dir, filename, cls())
        marker_path = base_dir / _FIXED220_CONFIG_VERSION_FILE
        marker_path.write_text(_FIXED220_CONFIG_SCHEMA_VERSION, encoding='utf-8')
    except Exception:
        # A read-only location is reported when the user actually tries to save;
        # it must not prevent the application from starting.
        pass


