_fixed427_prev_get_research_section_groups = _get_research_section_groups


def _fixed427_get_research_section_groups(code: str, cls):
    if code != 'A':
        return _fixed427_prev_get_research_section_groups(code, cls)
    declared = {fld.name for fld in fields(cls)}
    return [
        (title, [name for name in names if name in declared])
        for title, names in RESEARCH_SECTION_META['A']
        if any(name in declared for name in names)
    ]


