def _fixed409_stage_norms(cfg, stage_no: int) -> tuple[float, float, float]:
    """The PDF defines one Vнорм per axis, not separate names per stage."""
    return (
        max(1e-6, _fixed409_float(getattr(cfg, 'v_norm_x_cm_s', 5.0), 5.0)),
        max(1e-6, _fixed409_float(getattr(cfg, 'v_norm_y_cm_s', 5.0), 5.0)),
        max(1e-6, _fixed409_float(getattr(cfg, 'v_norm_z_deg_s', 25.0), 25.0)),
    )


# ====== FIXED428: canonical PDF setting names with legacy JSON compatibility ======
@dataclass
class MethodAConfigFixed428(MethodAConfig):
    y_lim_xy_per_sec: float = 0.7
    y_lim_xyz_per_sec: float = 0.7
    n_dop_x_for_150s: float = 30.0
    n_dop_xy_for_150s: float = 40.0
    n_dop_xyz_for_150s: float = 40.0


_fixed428_prev_load_config = load_config


def load_config(path: str | Path = 'method_a_config.json', screen_w: int | None = None, screen_h: int | None = None) -> MethodAConfigFixed428:
    base_cfg = _fixed428_prev_load_config(path=path, screen_w=screen_w, screen_h=screen_h)
    raw = _fixed260_read_raw_json(path)
    kwargs = {}
    for fld in fields(MethodAConfigFixed428):
        if hasattr(base_cfg, fld.name):
            kwargs[fld.name] = getattr(base_cfg, fld.name)
        elif fld.name in raw:
            kwargs[fld.name] = raw[fld.name]
    cfg = MethodAConfigFixed428(**kwargs)

    aliases = (
        ('y_lim_xy_per_sec', 'y_lim_y_per_sec', 0.7),
        ('y_lim_xyz_per_sec', 'y_lim_z_per_sec', 0.7),
        ('n_dop_x_for_150s', 'n_dop_x_for_180s', 30.0),
        ('n_dop_xy_for_150s', 'n_dop_xy_for_180s', 40.0),
        ('n_dop_xyz_for_150s', 'n_dop_xyz_for_180s', 40.0),
    )
    for canonical, legacy, default in aliases:
        try:
            value = float(raw.get(canonical, raw.get(legacy, getattr(base_cfg, legacy, default))))
        except Exception:
            value = float(default)
        value = max(1e-6, value)
        setattr(cfg, canonical, value)

    return _fixed409_clamp_cfg(cfg)


MethodAConfig = MethodAConfigFixed428
globals()['MethodAConfig'] = MethodAConfigFixed428
globals()['load_config'] = load_config
